            application.setActivationPolicy(.accessory)
            do {
                let artifact = try GhosttyTerminalRuntime.runTerminalFillsTileSelfCheck()
                print("ContinuumRevivedTerminalFillsTileChecks passed: \(artifact.path)")
                Foundation.exit(0)
            } catch {
                fputs("FAIL: \(error)\n", stderr)
                Foundation.exit(1)
            }
        }

        if CommandLine.arguments.contains("--terminal-default-readability-check") {
            let application = NSApplication.shared
            application.setActivationPolicy(.accessory)
            do {
                let artifact = try TileSpawner.runTerminalDefaultReadabilitySelfCheck()
                print("ContinuumRevivedTerminalDefaultReadabilityChecks passed: \(artifact.path)")
                Foundation.exit(0)
            } catch {
                fputs("FAIL: \(error)\n", stderr)
                Foundation.exit(1)
            }
        }

        if CommandLine.arguments.contains("--terminal-zoom-pan-stability-check") {
            let application = NSApplication.shared
            application.setActivationPolicy(.accessory)
            do {
                let artifact = try GhosttyTerminalRuntime.runTerminalZoomPanStabilitySelfCheck()
                print("ContinuumRevivedTerminalZoomPanStabilityChecks passed: \(artifact.path)")
                Foundation.exit(0)
            } catch {
                fputs("FAIL: \(error)\n", stderr)
                Foundation.exit(1)
            }
        }

        if CommandLine.arguments.contains("--terminal-theme-fidelity-check") {
            let application = NSApplication.shared
            application.setActivationPolicy(.accessory)
            do {
                let artifact = try TileSpawner.runTerminalThemeFidelitySelfCheck()
                print("ContinuumRevivedTerminalThemeFidelityChecks passed: \(artifact.path)")
                Foundation.exit(0)
            } catch {
                fputs("FAIL: \(error)\n", stderr)
                Foundation.exit(1)
            }
        }

        if CommandLine.arguments.contains("--stray-window-audit-check") {
            let application = NSApplication.shared
            application.setActivationPolicy(.accessory)
            do {
                let artifact = try GhosttyTerminalRuntime.runStrayWindowAuditSelfCheck()
                print("ContinuumRevivedStrayWindowAuditChecks passed: \(artifact.path)")
                Foundation.exit(0)
            } catch {
                fputs("FAIL: \(error)\n", stderr)
                Foundation.exit(1)
            }
        }

        if CommandLine.arguments.contains("--session-resume-check") {
            let application = NSApplication.shared
            application.setActivationPolicy(.accessory)
            do {
                let artifact = try AppDelegate.runSessionResumeSelfCheck()
                print("ContinuumRevivedSessionResumeChecks passed: \(artifact.path)")
                Foundation.exit(0)
            } catch {
                fputs("FAIL: \(error)\n", stderr)
                Foundation.exit(1)
            }
        }

        if CommandLine.arguments.contains("--workspace-profile-check") {
            do {
                try AppDelegate.runWorkspaceProfileSelfCheck()
                print("ContinuumRevivedWorkspaceProfileChecks passed")
                Foundation.exit(0)
            } catch {
                fputs("FAIL: \(error)\n", stderr)
                Foundation.exit(1)
            }
        }

        // PATH augmentation must precede the first ProcessInfo.environment
        // read (NSProcessInfo caches on first access) — AppDelegate's
        // initializers already read it. See ToolEnvironment.
        ToolEnvironment.shared.bootstrap()
        ToolEnvironment.shared.startLoginShellUpgrade()
        // Live model catalogue: opt in to bounded `pi --list-models` probes
        // (startup + throttled re-probes on picker open / onboarding
        // re-check) so the picker offers whatever providers the user has
        // authed in pi. QA never enables this and keeps the frozen fallback.
        AgentModelCatalog.shared.enableLiveRefresh()

        // Every `--*-check` flag is handled above and exits. Reaching here with
        // one still on the command line means it was MISSPELLED or belongs to a
        // different binary — and falling through booted the FULL app instead.
        //
        // That is not a harmless no-op. A bare `swift build` binary launched this
        // way reads real state: it prompted for, and disturbed, the production
        // keychain item the installed app depends on, leaving the user's copy
        // asking for their keychain password on every companion sync. It also
        // hangs the caller, because a check runner waits for an exit that a
        // running app never produces. Both happened during this program, twice
        // in one session, to someone who knew the hazard.
        //
        // Refuse instead, and name the two mistakes that actually get made:
        // a typo, and running a CoreChecks flag against the app binary.
        // These eight are handled in `applicationDidFinishLaunching`, not here:
        // they are LIVE checks that need a booted app, so reaching this line is
        // correct for them and only for them. Keep this list in step with that
        // method BY HAND. NOTHING GATES IT: an earlier draft of this comment
        // named a `--live-check-flag-inventory-check` that was never written.
        // Omit a new live flag here and the guard below rejects it — which the
        // matrix does catch, because every live leg runs through this path.
        let flagsHandledAfterLaunch: Set<String> = [
            "--agent-location-live-check",
            "--claude-agent-live-check",
            "--codex-agent-live-check",
            "--managed-agent-live-check",
            "--palette-captures-keys-over-browser-check",
            "--previous-focus-navigation-check",
            "--sidebar-live-capture-check",
            "--terminal-scroll-ergonomics-check",
        ]
        let unhandledCheckFlags = CommandLine.arguments.filter { argument in
            argument.hasPrefix("--") && argument.hasSuffix("-check")
                && !flagsHandledAfterLaunch.contains(argument)
        }
        if !unhandledCheckFlags.isEmpty {
            fputs("""
            FAIL: unknown check flag(s): \(unhandledCheckFlags.joined(separator: ", "))

            This flag is not handled by the Array binary, so it would have fallen
            through and booted the full app against real state. Refusing.

              * Check the spelling. The app's flags are:
                  grep -oE '\\-\\-[a-z0-9-]+-check' \\
                    Sources/ContinuumRevived/App/ContinuumApp.swift | sort -u
              * Check the BINARY. Some legs belong to ContinuumRevivedCoreChecks,
                not to Array. scripts/run-matrix.sh names the binary for each leg.

            """, stderr)
            Foundation.exit(1)
        }

        let application = NSApplication.shared
        let delegate = AppDelegate()
        Self.delegate = delegate

        application.delegate = delegate
        application.setActivationPolicy(.regular)
        if updaterPermitted() {
            updaterController = SPUStandardUpdaterController(startingUpdater: true, updaterDelegate: nil, userDriverDelegate: nil)
        }
        installMainMenu()
        application.run()
    }

    // Go-live Phase 2 (docs/38-tickets/95-go-live.md): the auto-updater may only
    // start inside the real distributed bundle. The QA matrix runs the bare
    // binary (bundleIdentifier == nil), self-check legs pass `--*-check` flags,
    // and isolated QA runs of the bundle mark themselves with CONTINUUM_* env —
    // in all of those the updater must stay inert: no network, no prompts.
    @MainActor
    private static var updaterController: SPUStandardUpdaterController?

    private static func updaterPermitted() -> Bool {
        guard Bundle.main.bundleIdentifier == "dev.arrayapp.macos" else { return false }
        let environment = ProcessInfo.processInfo.environment
        if environment["CONTINUUM_APP_SUPPORT"] != nil { return false }
        if environment["CONTINUUM_SMOKE_TEST"] == "1" { return false }
        if environment["CONTINUUM_QA_FLOW"] != nil { return false }
        if environment["CONTINUUM_COMPONENT_SNAPSHOT"] != nil { return false }
        if CommandLine.arguments.contains(where: { $0.hasPrefix("--") }) { return false }
        return true
    }

