    private static let smokeNoteId = UUID(uuidString: "00000000-0000-0000-0000-000000000001")!
    private static let smokeNoteTileId = UUID(uuidString: "00000000-0000-0000-0000-000000000010")!
    private static let smokeFileTileId = UUID(uuidString: "00000000-0000-0000-0000-000000000011")!
    private static let smokeFileTreeTileId = UUID(uuidString: "00000000-0000-0000-0000-000000000012")!
    private static let workspaceDeleteSemanticsCopy = "Deletes only the workspace entry and workspace layout document. Projects, project folders, and project tile data are not deleted."
    private static let smokeNoteBody = "smoke-note-ok"
    private static let smokeFileBody = "smoke-file-ok"
    private static let smokeFileLongBody: String = {
        let longLine = "let unwrappedSourceLine = \"" + String(repeating: "0123456789", count: 36) + "\""
        let lines = (1...90).map { idx in
            "\(String(format: "%03d", idx)) \(idx == 1 ? smokeFileBody : "smoke-file-line") \(longLine)"
        }
        return lines.joined(separator: "\n") + "\n"
    }()
    static let topologyMigrationNoteShownKey = "continuum.topology.migrationNoteShown"
    static let onboardingShownKey = "continuum.onboarding.shown"
    static let topologyMigrationInformativeText = """
    Continuum now groups terminal tiles by project, so your terminals share one tmux session per project. Your terminal tiles will restart once. Any running agents will need to be re-launched - they are still alive in tmux and can be found with `tmux ls` if needed.
    """

    func applicationDidFinishLaunching(_ notification: Notification) {
        // Continuum's canvas is a dark surface: every tile/card fill is a dark
        // literal. The text, however, used dynamic system colors, which resolve
        // to BLACK under light appearance — that is the "black text on dark
        // blue" bug. Pin dark so the whole app matches its own surfaces
        // regardless of the user's system setting. Measured: labelColor goes
        // black@85% in Aqua, white@85% in DarkAqua.
        NSApp.appearance = NSAppearance(named: .darkAqua)

        // Ticket 87: headless component snapshot for Layer-2 vision QA. Renders
        // a Component Lab gallery to a PNG and exits, with zero project/boot
        // machinery — the reusable primitive for automated visual review.
        //   CONTINUUM_COMPONENT_SNAPSHOT=<name> CONTINUUM_SNAPSHOT_OUT=<path> Array
        if let snapshot = ProcessInfo.processInfo.environment["CONTINUUM_COMPONENT_SNAPSHOT"] {
            let out = ProcessInfo.processInfo.environment["CONTINUUM_SNAPSHOT_OUT"] ?? "component-snapshot.png"
            let ok = Self.renderComponentSnapshot(named: snapshot, to: out)
            NSApp.setActivationPolicy(.prohibited)
            exit(ok ? 0 : 1)
        }
        // Transcript motion is enabled here and nowhere else: this line runs only
        // on the interactive launch path, after the whole `--*-check` cascade and
        // after the component-snapshot early exit above. Every self-check leg,
        // pixel baseline and tour render therefore photographs a motionless
        // transcript — a frame captured mid-fade would be a flapping baseline.
        AgentTranscriptMotion.isEnabled = { true }
        // C3: adopt any pre-2026-08-24 per-tile transcript directory under the
        // agent-stable key. Detached and non-blocking because it only ever moves
        // history the app is not yet reading, and idempotent, so a crash halfway
        // through costs the next launch one more pass and nothing else. Runs on
        // the interactive path only, for the same reason motion does.
        Task.detached { [store = agentTranscriptStore] in
            _ = try? await store.migrateLegacySessionDirectories()
        }
        // C8's fourth blocker was that nothing ever installed the extension, so
        // the whole pi spawn path shipped unreachable. This is that call site,
        // and it is HERE rather than beside `ToolEnvironment.bootstrap()`
        // deliberately: `applicationDidFinishLaunching` runs only on the
        // interactive path, after the entire `--*-check` cascade, so no self-check
        // leg can write into the developer's real `~/.pi/agent/extensions`.
        // The installer never overwrites a copy whose bytes are not ours.
        Task.detached {
            let result = PiExtensionInstaller.install()
            if case .leftUserModifiedCopy = result {
                FileHandle.standardError.write(Data(
                    "PiExtensionInstaller: left a modified continuum-spawn-agent.ts in place\n".utf8))
            }
        }
        launchStartTime = QAPerf.timestamp()
        qaPerf = QAPerf()
        navKeymap = NavKeymap.resolve()
        focusBroker.navKeymap = navKeymap
        do {
            let appSupportDir = Self.resolveAppSupportDir(smokeTest: smokeTestEnabled)
            let registryStore = RegistryStore(applicationSupportDirectory: appSupportDir)
            companionAuthService = try CompanionAuthService(
                authDirectory: Self.resolveAuthDirectory(applicationSupportDirectory: appSupportDir),
                instanceDisplayName: Host.current().localizedName ?? "Continuum"
            )
            let registry = try registryStore.loadOrEmpty()
            // Go-live Phase 4: an empty registry is the "no prior state"
            // signal the first-run onboarding gate consumes after boot.
            let registryWasEmpty = registry.projects.isEmpty
            let projectRoot = try Self.resolveProjectRoot(smokeTest: smokeTestEnabled, registry: registry)
            let bootController = try presentLockContentionUXIfNeeded(projectRoot: projectRoot, registry: registry)
            self.registryStore = registryStore

            let projectStore = bootController.projectStore
            let project = bootController.project
            try Self.recordProjectInRegistry(project: project, in: registryStore, preferredWorkspaceId: ProjectLaunchCoordinator.consumePendingWorkspaceSelection())
            let updatedRegistry = try registryStore.loadOrEmpty()

            // P3.1/P3.2: a record on disk proves something happened, never that
            // something is happening. Sweep every root the registry knows about
            // BEFORE anything can read one — `attachUI`, `agentSupervisor.restore()`,
            // the tile walk and the first `agentRowStatus` read are all below this
            // line — and ARM the listing gate while we are here: until this returns,
            // `currentManagedAgentActivities()` REFUSES rather than answering off
            // unswept files. Idempotent per root and per record, so a launch with
            // nothing to fix writes nothing at all; a graceful quit stamps
            // `.continuumQuit` from `applicationWillTerminate` (which deliberately
            // uses the reconciler directly — this source is once-per-root, so a quit
            // routed through it would sweep nothing). A root that appears LATER, when
            // a workspace switch opens another project's controller, is swept on the
            // way in by the same source; that is why this is not the only sweep.
            let launchSweep = try reconciledManagedSessionSource.reconcile(
                registry: updatedRegistry,
                reason: .continuumRestarted,
                now: Date()
            )
            if launchSweep.terminalized > 0 {
                fputs("managed-session reconcile: terminalized \(launchSweep.terminalized) of \(launchSweep.scanned) persisted record(s) that still claimed liveness, across \(launchSweep.sweptRoots) project root(s)\n", stderr)
            }

            let activeWorkspace = try Self.loadActiveWorkspaceDocument(from: registryStore)
            let zoneRenderModels = Self.zoneRenderModels(from: activeWorkspace?.document, registry: updatedRegistry)
            let activeZone = zoneRenderModels.first(where: { $0.placement.projectId == project.id })?.placement
            let bootProjectBelongsToSelectedWorkspace = Self.selectedWorkspaceOwnsBootProject(
                project.id,
                selectedWorkspaceId: activeWorkspace?.workspaceId,
                registry: updatedRegistry
            )

            let ghostty = try GhosttyRuntimeContext()
            let browserEngine = BrowserEngineContext()
            let seededSmokeTiles = smokeTestEnabled
                ? try Self.seedSmokeTestTiles(in: projectStore, projectRoot: projectRoot)
                : []

            var canvasState: CanvasState
            let existingCanvasResult = try projectStore.tryLoadCanvasWithSanitizationResult()
            let selectedProjectHadCanvasState = existingCanvasResult != nil
            if let existing = existingCanvasResult {
                canvasState = existing.canvas
                if existing.recenteredViewport {
                    for note in existing.notes {
                        fputs("viewport sanitation: \(note)\n", stderr)
                    }
                }
            } else {
                canvasState = Self.defaultCanvasState()
            }
            for seededTile in seededSmokeTiles {
                if let index = canvasState.tiles.firstIndex(where: { $0.id == seededTile.id }) {
                    canvasState.tiles[index] = seededTile
                } else {
                    canvasState.tiles.append(seededTile)
                }
            }
            if smokeTestEnabled,
               !canvasState.tiles.contains(where: { $0.kind == .terminal }) {
                canvasState.tiles.append(Self.defaultTerminalTile())
            }
            if let queueConfig = registry.projects.first(where: { $0.id == project.id })?.linearTicketQueue {
                Self.materializeTicketQueueTile(in: &canvasState, config: queueConfig)
            }
            try Self.applyTopologyMigrationIfNeeded(
                projectStore: projectStore,
                canvas: canvasState,
                workspace: activeWorkspace?.document,
                defaults: UserDefaults.standard,
                presentAlert: Self.presentTopologyMigrationAlert
            )
            canvasState = Self.isolatedBootCanvasState(
                projectCanvas: canvasState,
                bootProjectId: project.id,
                selectedWorkspaceId: activeWorkspace?.workspaceId,
                selectedViewport: activeWorkspace?.document.viewport,
                registry: updatedRegistry
            )

            let canvasView = CanvasNSView(canvasState: canvasState, activeZone: activeZone, zoneRenderModels: zoneRenderModels)
            canvasView.delegate = self
            canvasView.onTileCloseRequested = { [weak self] tileId in
                self?.deleteTile(id: tileId)
            }
            canvasView.onTileStopRunRequested = { [weak self] tileId in
                self?.stopHarnessRun(tileId: tileId)
            }
            canvasView.onZoneCreated = { [weak self] placement in
                self?.persistCreatedGroupZone(placement)
            }
            canvasView.onZoneMoved = { [weak self] placement in
                self?.persistMovedZone(placement)
            }
            canvasView.onZoneCloseRequested = { [weak self] zoneId in
                self?.presentZoneCloseConfirm(zoneId)
            }
            canvasView.onZoneClosed = { [weak self] zoneId in
                self?.persistClosedZone(zoneId)
            }
            canvasView.onZoneRenamed = { [weak self] zoneId, name in
                self?.persistRenamedZone(zoneId, name: name)
                self?.demonstrateOnboarding(.zoneRenamed)
            }
            canvasView.onZoneColorChanged = { [weak self] _, _ in self?.demonstrateOnboarding(.zoneColorSelected) }
            canvasView.filesystemScopeForTile = { [weak self] tileId in
                self?.filesystemScopeEvidence(forTile: tileId)
            }
            canvasView.scopeLabelForZoneScope = { [weak self] scope in
                self?.zoneScopeLabel(scope) ?? "Needs Project"
            }
            canvasView.onZoneScopeRequired = { [weak self] placement, anchor in
                self?.presentProjectHomePicker(for: placement, anchor: anchor, isNewZone: true)
            }
            canvasView.onZoneScopeChangeRequested = { [weak self] placement, anchor in
                self?.presentProjectHomePicker(for: placement, anchor: anchor, isNewZone: false)
            }

            self.ghostty = ghostty
            self.browserEngine = browserEngine
            self.canvasView = canvasView

            // Wrap the boot controller in WorkspaceRuntime (T06).
            let bootRegistry = ZoneRuntimeRegistry(closeOnZero: true, makeController: { [weak self] projectId in
                guard let self else {
                    throw NSError(domain: "WorkspaceRuntime", code: 1,
                                  userInfo: [NSLocalizedDescriptionKey: "Array closed while opening a workspace project."])
                }
                let liveRegistry = try registryStore.loadOrEmpty()
                guard let entry = liveRegistry.projects.first(where: { $0.id == projectId && !$0.missing }) else {
                    throw NSError(domain: "WorkspaceRuntime", code: 2,
                                  userInfo: [NSLocalizedDescriptionKey: "That workspace's project is no longer registered."])
                }
                return try self.presentLockContentionUXIfNeeded(
                    projectRoot: URL(fileURLWithPath: entry.rootPath, isDirectory: true),
                    registry: liveRegistry
                )
            })
            if let activeWorkspace, bootProjectBelongsToSelectedWorkspace {
                self.workspaceRuntime = WorkspaceRuntime(
                    boot: bootController,
                    workspaceId: activeWorkspace.workspaceId,
                    document: activeWorkspace.document,
                    registry: bootRegistry,
                    focusBroker: focusBroker,
                    registryStore: registryStore,
                    ghostty: ghostty,
                    browserEngine: browserEngine
                )
            } else if let activeWorkspace {
                // An empty workspace has no controller of its own. Keep the
                // compatibility boot controller out of the runtime entirely so
                // its tiles, zone, persistence hooks and creation scope cannot
                // become part of the selected workspace by accident.
                self.workspaceRuntime = WorkspaceRuntime(
                    workspaceId: activeWorkspace.workspaceId,
                    document: activeWorkspace.document,
                    registry: bootRegistry,
                    focusBroker: focusBroker,
                    registryStore: registryStore,
                    ghostty: ghostty,
                    browserEngine: browserEngine
                )
            } else {
                self.workspaceRuntime = WorkspaceRuntime(
                    boot: bootController,
                    registry: bootRegistry,
                    focusBroker: focusBroker,
                    registryStore: registryStore,
                    ghostty: ghostty,
                    browserEngine: browserEngine
                )
            }

            let spawner = TileSpawner(
                canvasView: canvasView,
                ghostty: ghostty,
                browserEngine: browserEngine,
                projectStore: projectStore,
                project: project,
                browserProfiles: registry.settings.browserProfiles
            )
            spawner.browserPersistenceHandler = { [weak self] in
                self?.scheduleBrowserSave()
            }
            spawner.notePersistenceHandler = { [weak self] in
                self?.scheduleNoteSave()
            }
            spawner.fileTreePersistenceHandler = { [weak self] in
                self?.scheduleFileTreeSave()
            }
            spawner.reservedShortcutHandler = { [weak self] event in
                self?.handleReservedShortcut(event) ?? false
            }
            spawner.browserProfileMenuProvider = { [weak self] in
                (try? self?.registryStore?.loadOrEmpty().settings.browserProfiles) ?? registry.settings.browserProfiles
            }
            spawner.terminalProjectContextProvider = { [weak self] in
                self?.activeZoneProjectEntry()
            }
            spawner.terminalSessionTargetProvider = { [weak self] in
                guard let self else { return nil }
                if let projectId = activeZoneProjectEntry()?.id {
                    return .project(projectId: projectId)
                }
                if let workspaceId = workspaceRuntime?.workspaceId {
                    return .ambient(workspaceId: workspaceId)
                }
                return nil
            }
            spawner.terminalFocusedPaneTargetProvider = { [weak self] in
                guard let self,
                      let tileId = canvasView.canvasState.lastActiveTileId,
                      let record = self.managedSessionRecord(forTileId: tileId)
                else { return nil }
                return record.tmuxWindowTarget()
            }
            spawner.focusedTerminalCwdProvider = { [weak canvasView] in
                guard let canvasView,
                      let tileId = canvasView.canvasState.lastActiveTileId,
                      let tileView = canvasView.tileView(for: tileId) as? TerminalTileNSView
                else { return nil }
                return tileView.runtime.capturedCwd
            }
            spawner.browserProfileSwitchHandler = { [weak self] tileId, profileId in
                self?.switchBrowserTileProfile(tileId: tileId, profileId: profileId)
            }
            spawner.browserProfileCreateHandler = { [weak self] tileId in
                self?.createBrowserProfile(for: tileId)
            }
            spawner.browserProfileRenameHandler = { [weak self] tileId, profileId in
                self?.renameBrowserProfile(tileId: tileId, profileId: profileId)
            }
            spawner.browserProfileDeleteHandler = { [weak self] tileId, profileId in
                self?.deleteBrowserProfile(tileId: tileId, profileId: profileId)
            }
            try mountWorkspaceSceneAtBoot(
                canvasView: canvasView,
                spawner: spawner,
                projectStore: projectStore,
                canvasState: canvasState)
            refreshAgentSurfaces(notify: false)

            let window = NSWindow(
                contentRect: NSRect(x: 0, y: 0, width: 1280, height: 800),
                styleMask: [.titled, .closable, .miniaturizable, .resizable],
                backing: .buffered,
                defer: false
            )
            window.title = Self.mainWindowTitle(for: project, registry: updatedRegistry)
            window.center()
            let contentFrame = window.contentRect(forFrameRect: window.frame)
            window.contentView = makeWorkspaceContentView(canvasView: canvasView, frame: NSRect(origin: .zero, size: contentFrame.size))
            window.delegate = self
            window.makeKeyAndOrderFront(nil)
            window.makeFirstResponder(canvasView)
            self.window = window

            // Activate after runtimes are wired up: NSApp.activate can fire
            // applicationDidBecomeActive synchronously, and the focus path needs
            // a non-nil ghostty to forward set_focus into the surface.
            NSApp.activate(ignoringOtherApps: true)

            // P5.5 boot regression probe (display-dependent; belongs to the
            // supervised surface legs, never the headless matrix). Offscreen
            // cacheDisplay renders cannot witness a live display-transaction
            // feedback loop — the class of failure that killed the first v2
            // installed-candidate boot — so this runs the REAL window display
            // cycle for two seconds and reports only if the process survives it.
            if CommandLine.arguments.contains("--agent-tile-v2-boot-probe") {
                let usesV2Shell = true  // P5.5: v2 is the only shell; the launch flag is gone
                DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
                    guard let window = self.window, window.isVisible else {
                        fputs("FAIL: v2 boot probe: no visible window after the first display cycles\n", stderr)
                        Foundation.exit(1)
                    }
                    print("AgentTileV2BootProbe passed: live window displayed and stable (v2Shell=\(usesV2Shell))")
                    Foundation.exit(0)
                }
            }

            if CommandLine.arguments.contains("--sidebar-live-capture-check") {
                runSidebarLiveCaptureCheck(window: window)
            } else if CommandLine.arguments.contains("--agent-location-live-check") {
                runAgentLocationLiveCheck(window: window)
            } else if CommandLine.arguments.contains("--managed-agent-live-check") {
                runManagedAgentLiveCheck(window: window)
            } else if CommandLine.arguments.contains("--claude-agent-live-check") {
                runClaudeAgentLiveCheck(window: window)
            } else if CommandLine.arguments.contains("--codex-agent-live-check") {
                runCodexAgentLiveCheck(window: window)
            } else if CommandLine.arguments.contains("--palette-captures-keys-over-browser-check") {
                runPaletteCapturesKeysOverBrowserCheck(window: window)
            } else if CommandLine.arguments.contains("--terminal-scroll-ergonomics-check") {
                runTerminalScrollErgonomicsCheck(window: window, runtime: runtimes.first)
            } else if CommandLine.arguments.contains("--previous-focus-navigation-check") {
                runPreviousFocusNavigationCheck(window: window)
            } else if smokeTestEnabled {
                runSmokeTest(window: window, runtime: runtimes.first)
            } else {
                startDesktopCompanionSyncService()
                presentOnboardingIfFirstRun(
                    registryWasEmpty: registryWasEmpty,
                    selectedProjectHadCanvasState: selectedProjectHadCanvasState,
                    firstProjectId: project.id
                )
                if ProcessInfo.processInfo.environment["CONTINUUM_AUTO_PAIR_PHONE"] == "1" {
                    DispatchQueue.main.async { [weak self] in
                        self?.issueObserverPairingTokenFromMenu(nil)
                    }
                }
            }
        } catch {
            presentFatalError(error)
        }
    }

    /// Queue 91 P3 supervised gate: run one real Pi turn through the production
    /// supervisor/tile path and preserve the live Home/Where/What transitions as
    /// window captures plus a local JSON manifest. The fixture paths must be
    /// supplied by the isolated launch environment; this check never targets the
    /// owner's project or Application Support store.
    /// Program 96/P0.2 — the LIVE half of the screenshot harness, and the source of
    /// gate S0's red baseline.
    ///
    /// The offscreen leg is a geometry gate (§3.3); this is the shipped product, in a
    /// real window, composited by the WindowServer. It drives the same production
    /// writers the corpus does — so the rows are production rows and the
    /// `reloadWorkspaceSidebar`-overwrite hazard never arises — then captures the
    /// window twice: once through the WindowServer and once through the sidebar view's
    /// own `cacheDisplay`. Both are recorded with distinct `captureType`s because a
    /// view render is not evidence about the live window, and conflating them is
    /// exactly what §3.3 forbids.
    ///
    /// Not a matrix leg: it needs a WindowServer and Screen Recording permission.
    private func runSidebarLiveCaptureCheck(window: NSWindow) {
        let report: @MainActor @Sendable (String) -> Void = { line in
            FileHandle.standardError.write(Data("[sidebar-96-live] \(line)\n".utf8))
        }
        guard let output = ProcessInfo.processInfo.environment["CONTINUUM_QA_CAPTURE"],
              !output.isEmpty else {
            report("FAIL: CONTINUUM_QA_CAPTURE must name an output directory")
            Foundation.exit(2)
        }
        let directory = URL(fileURLWithPath: output, isDirectory: true)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        // This check MINTS five durable `AgentRecord`s and never deletes them, so it
        // must be impossible to point at real state. A project-root check alone was not
        // enough: run from the prod bundle against any other root it would have written
        // junk agents into Dylan's own agent store (AGENTS.md non-negotiable #1).
        guard ProcessInfo.processInfo.environment["CONTINUUM_APP_SUPPORT"] != nil else {
            report("FAIL: refusing to run without CONTINUUM_APP_SUPPORT — this check "
                   + "creates durable agent records and must never write a real store")
            Foundation.exit(2)
        }
        guard Bundle.main.bundleIdentifier != AppChannel.prodBundleIdentifier else {
            report("FAIL: refusing to run from the PROD bundle "
                   + "(\(AppChannel.prodBundleIdentifier)) — dev channel only")
            Foundation.exit(2)
        }
        guard let projectRoot = activeProject?.rootPath else {
            report("FAIL: no active project — refusing to capture an unknown root")
            Foundation.exit(2)
        }
        // Never Dylan's workspace, whatever the caller passed.
        guard !projectRoot.contains("/Documents/personal") else {
            report("FAIL: refusing to run against \(projectRoot)")
            Foundation.exit(2)
        }
        let requestedWidth = WorkspaceSidebarConfig.resolveWidth(defaults: .standard)

        // A Task rather than a fixed delay: the app is still finishing its own boot at
        // one second, and the FIRST version of this check captured a sidebar reading
        // "No agents yet" while reporting PASS — the app's later mount reloaded the
        // list out from under the push. Now the rows are waited for and their absence
        // is a FAILURE, because a green check over an empty screenshot is the exact
        // false evidence this program exists to prevent.
        Task { @MainActor [weak self] in
            guard let self else { Foundation.exit(3) }
            let root = URL(fileURLWithPath: projectRoot, isDirectory: true)
            // Let the workspace mount settle before driving anything.
            try? await Task.sleep(nanoseconds: 2_000_000_000)

            // The same writers P0.1 drives: three untouched ⌘K drafts, one renamed, and
            // one that finished a turn. Enough for the owner-screenshot row shape and
            // one completion to be visible in the same frame.
            for _ in 0..<3 {
                _ = self.agentSupervisor.spawn(
                    role: nil, prompt: nil, cwd: root,
                    model: "openai-codex/gpt-5.6-sol", thinking: "medium",
                    projectId: self.activeProject?.id, tileId: UUID())
            }
            let named = self.agentSupervisor.spawn(
                role: nil, prompt: nil, cwd: root,
                model: "anthropic/claude-opus-5", thinking: "medium",
                projectId: self.activeProject?.id, tileId: UUID())
            _ = self.agentSupervisor.rename(
                agentID: named, to: "Replace sidebar identity and completion UX")
            let finished = self.agentSupervisor.spawn(
                role: nil, prompt: nil, cwd: root,
                model: "openai-codex/gpt-5.6-sol", thinking: "medium",
                projectId: self.activeProject?.id, tileId: UUID())
            _ = self.agentSupervisor.rename(agentID: finished, to: "Stop the camera resizing tiles")
            let turnEvents: [AgentRuntimeEvent] = [
                .turnStarted(threadId: "s0", turnId: "s0-1"),
                .turnCompleted(threadId: "s0", turnId: "s0-1", outcome: .completed, errorMessage: nil),
            ]
            for (index, event) in turnEvents.enumerated() {
                // Both owners, as production wires them: `deliver` updates the turn
                // facts the row's state reads, the bridge records the activity draft.
                self.recordManagedActivity(
                    agentId: finished, tileId: nil, event: event,
                    status: index == turnEvents.count - 1 ? .done : .working)
                self.agentSupervisor.qaDeliver(event, to: finished)
            }
            self.refreshAgentSurfaces(notify: false)

            guard let sidebar = self.workspaceSidebarView else {
                report("FAIL: no workspace sidebar view")
                Foundation.exit(1)
            }

            // Poll for the rows to actually be on screen. Re-push each tick, because
            // the app's own boot can reload the list after ours.
            let expectedRows = 5
            var settled = false
            for _ in 0..<40 {
                self.refreshAgentSurfaces(notify: false)
                sidebar.layoutSubtreeIfNeeded()
                sidebar.inboxForQA.layoutForQA()
                let modelRows = sidebar.inboxForQA.rowIdsForQA.count
                let painted = sidebar.inboxForQA.qaMaterializedRowCells
                    .filter { $0.qaAgentID != nil }.count
                if modelRows >= expectedRows, painted >= expectedRows,
                   !sidebar.inboxForQA.isEmptyMessageVisibleForQA {
                    settled = true
                    break
                }
                try? await Task.sleep(nanoseconds: 250_000_000)
            }
            guard settled else {
                report("FAIL: the sidebar never showed \(expectedRows) rows "
                       + "(model \(sidebar.inboxForQA.rowIdsForQA.count), painted "
                       + "\(sidebar.inboxForQA.qaMaterializedRowCells.filter { $0.qaAgentID != nil }.count), "
                       + "empty-state visible "
                       + "\(sidebar.inboxForQA.isEmptyMessageVisibleForQA)) — refusing to "
                       + "capture an empty sidebar and call it a baseline")
                Foundation.exit(1)
            }
            window.display()
            window.flush()
            // One more beat so the WindowServer has the composited frame.
            try? await Task.sleep(nanoseconds: 400_000_000)

            var entries: [SidebarScreenshotChecks.Entry] = []
            let measuredWidth = Double(sidebar.bounds.width)
            let appearance = window.effectiveAppearance.name == .aqua ? "aqua" : "darkAqua"
            let workspace = NSWorkspace.shared
            let reduceMotion = workspace.accessibilityDisplayShouldReduceMotion
                ? "system-on" : "system-off"
            let increaseContrast = workspace.accessibilityDisplayShouldIncreaseContrast
                ? "system-on" : "system-off"
            // Painted AGENT cells only. A bare tree walk also finds views AppKit has
            // not yet removed, which is how the first version reported five rows over a
            // screenshot of the empty state.
            let rowCount = sidebar.inboxForQA.qaMaterializedRowCells
                .filter { $0.qaAgentID != nil }.count

            func record(_ png: String, captureType: String, scale: Double) {
                entries.append(SidebarScreenshotChecks.Entry(
                    png: png, fixture: "s0-red-baseline",
                    widthRequestedPt: Double(requestedWidth),
                    widthMeasuredPt: measuredWidth,
                    heightPt: Double(sidebar.bounds.height),
                    appearance: appearance,
                    reduceMotion: reduceMotion, increaseContrast: increaseContrast,
                    scale: scale, captureType: captureType,
                    checkFlag: SidebarScreenshotChecks.liveFlag,
                    digest: "n/a (live capture)",
                    rowsRendered: rowCount,
                    completeRowsIn662pt: nil, cardHeightPt: nil, pitchPt: nil))
            }

            // 1 — the WindowServer's own picture of the live window.
            let windowName = "live-window-\(Int(requestedWidth))pt.png"
            if let image = CGWindowListCreateImage(
                .null, .optionIncludingWindow, CGWindowID(window.windowNumber),
                [.boundsIgnoreFraming]) {
                let rep = NSBitmapImageRep(cgImage: image)
                // The offscreen leg applies a non-blank floor to every image; this one
                // used to apply none, so a valid-but-empty WindowServer image would have
                // been written and PASSed. `CGWindowListCreateImage` returning non-nil is
                // not evidence that anything was composited.
                let metrics = VisualSnapshot.metrics(of: rep)
                if metrics.isBlank {
                    report("FAIL: the window capture is blank "
                           + "(\(metrics.distinctSampledColors) distinct colours) — "
                           + "refusing to file an empty image as a baseline")
                    Foundation.exit(1)
                }
                if let data = rep.representation(using: .png, properties: [:]) {
                    try? data.write(
                        to: directory.appendingPathComponent(windowName), options: .atomic)
                    record(windowName, captureType: "live-window",
                           scale: Double(image.width) / max(Double(window.frame.width), 1))
                }
            } else {
                report("WARN: CGWindowListCreateImage returned nothing — Screen Recording "
                       + "permission is probably not granted for this bundle")
            }

            // 2 — the sidebar view's own render. Not a substitute for the above; it is
            // the exact subtree state at this instant, labelled as a view render.
            let viewName = "live-view-cache-\(Int(requestedWidth))pt.png"
            if let rep = sidebar.bitmapImageRepForCachingDisplay(in: sidebar.bounds) {
                sidebar.cacheDisplay(in: sidebar.bounds, to: rep)
                if let data = rep.representation(using: .png, properties: [:]) {
                    try? data.write(
                        to: directory.appendingPathComponent(viewName), options: .atomic)
                    record(viewName, captureType: "live-view-cache",
                           scale: Double(rep.pixelsWide) / max(measuredWidth, 1))
                }
            }

            // A width recorded is not a width applied: `constrainedWidth` vetoes growth
            // against a 640 pt content floor, so a 360 pt request in a narrow window is
            // silently clamped. Without this the manifest would say 360 requested / 280
            // measured and still call itself PASS.
            let widthApplied = abs(measuredWidth - Double(requestedWidth)) <= 0.5
            if !widthApplied {
                report("FAIL: requested \(requestedWidth)pt but the sidebar measured "
                       + "\(measuredWidth)pt — the width was clamped, so this capture is "
                       + "not the width it claims")
            }
            let verdict = (widthApplied && entries.contains { $0.captureType == "live-window" })
                ? "PASS" : "FAIL"
            let payload: [String: Any] = [
                "check": SidebarScreenshotChecks.liveCheckName,
                "verdict": verdict,
                "program": "96-P0.2",
                "appearance": appearance,
                "widthRequestedPt": requestedWidth,
                "widthMeasuredPt": measuredWidth,
                "rowsRendered": rowCount,
                "reduceMotion": reduceMotion,
                "increaseContrast": increaseContrast,
                "scratchProjectRoot": projectRoot,
                "bundlePath": Bundle.main.bundlePath,
                "bundleVersion": Bundle.main.infoDictionary?["CFBundleVersion"] as? String ?? "",
                "captures": entries.map {
                    ["png": $0.png, "captureType": $0.captureType, "scale": $0.scale]
                },
            ]
            try? JSONSerialization.data(
                withJSONObject: payload, options: [.prettyPrinted, .sortedKeys]
            ).write(to: directory.appendingPathComponent("manifest.json"), options: .atomic)

            report("\(verdict): \(entries.count) capture(s), \(rowCount) rows at "
                   + "\(Int(requestedWidth))pt (\(appearance)) -> \(directory.path)")
            Foundation.exit(verdict == "PASS" ? 0 : 1)
        }
    }

    private func runAgentLocationLiveCheck(window: NSWindow) {
        let report: @MainActor @Sendable (String) -> Void = { line in
            FileHandle.standardError.write(Data("[agent-location-live] \(line)\n".utf8))
        }
        guard let externalPath = ProcessInfo.processInfo.environment["CONTINUUM_LOCATION_LIVE_EXTERNAL"],
              (externalPath as NSString).isAbsolutePath,
              FileManager.default.fileExists(atPath: externalPath),
              let projectRoot = activeProject?.rootPath else {
            report("FAIL: isolated project root/external fixture missing")
            Foundation.exit(2)
        }
        let insidePath = URL(fileURLWithPath: projectRoot, isDirectory: true)
            .appendingPathComponent("inside.txt").path
        guard FileManager.default.fileExists(atPath: insidePath) else {
            report("FAIL: isolated inside fixture missing")
            Foundation.exit(2)
        }

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            guard let self, let spawner = self.tileSpawner, let canvasView = self.canvasView else {
                report("FAIL: no spawner/canvas")
                Foundation.exit(2)
            }
            guard case let .spawned(tileId) = spawner.spawnManagedAgent() else {
                report("FAIL: spawnManagedAgent did not spawn")
                Foundation.exit(2)
            }
            self.wireManagedAgentTile(tileId)
            self.focusSpawnedTile(tileId)
            guard let view = canvasView.tileView(for: tileId) as? ManagedAgentTileNSView else {
                report("FAIL: spawned tile is not a ManagedAgentTileNSView")
                Foundation.exit(2)
            }

            let qaCapture = QACapture()
            var samples: [[String: Any]] = []
            var seenStates = Set<String>()
            let sample: @MainActor @Sendable (String) -> Void = { phase in
                view.layoutSubtreeIfNeeded()
                window.displayIfNeeded()
                let row: [String: Any] = [
                    "phase": phase,
                    "location": view.qaLocationText,
                    "what": view.qaWhatText,
                    "locationAX": view.qaLocationAccessibilityValue,
                    "whatAX": view.qaWhatAccessibilityValue,
                    "detail": view.qaLocationDetail,
                    "whereExternalMarker": view.qaWhereOutboundMarkerVisible,
                    "whatExternalMarker": view.qaWhatOutboundMarkerVisible,
                ]
                samples.append(row)
                report("\(phase): \(view.qaLocationText) | \(view.qaWhatText) | external=\(view.qaWhatOutboundMarkerVisible)")
                let stateKey = "\(view.qaLocationText)|\(view.qaWhatText)|\(view.qaWhereOutboundMarkerVisible)|\(view.qaWhatOutboundMarkerVisible)"
                if seenStates.insert(stateKey).inserted {
                    // Hold this exact streamed state for one compositor flush. Pi's
                    // read/edit tools can start and finish inside one display tick;
                    // without the flush a CGWindow capture truthfully samples the
                    // live window but only after it has already advanced to Thinking.
                    window.display()
                    window.flush()
                    Thread.sleep(forTimeInterval: 0.05)
                    qaCapture?.capture(
                        step: phase,
                        tSec: Date().timeIntervalSince1970,
                        window: window,
                        canvasState: canvasView.canvasState)
                    // Also snapshot the installed live tile synchronously. The
                    // WindowServer capture above proves real-window context, while
                    // this cacheDisplay sample preserves the exact streamed state
                    // before a millisecond read/edit tool can complete.
                    if let output = ProcessInfo.processInfo.environment["CONTINUUM_QA_CAPTURE"],
                       let rep = view.bitmapImageRepForCachingDisplay(in: view.bounds) {
                        view.cacheDisplay(in: view.bounds, to: rep)
                        let safePhase = phase.map { character in
                            character.isLetter || character.isNumber || character == "-"
                                ? character : "-"
                        }
                        let name = String(format: "exact-%02d-%@.png", seenStates.count, String(safePhase))
                        if let data = rep.representation(using: .png, properties: [:]) {
                            try? data.write(
                                to: URL(fileURLWithPath: output, isDirectory: true)
                                    .appendingPathComponent(name),
                                options: .atomic)
                        }
                    }
                }
            }

            let productionIngest = view.onIngestedEvent
            view.onIngestedEvent = { event in
                productionIngest?(event)
                switch event {
                case .itemStarted(_, _, _, let title):
                    sample("item-start-\(title ?? "unknown")")
                case .itemCompleted(_, _, _, let status):
                    sample("item-end-\(status)")
                case .sessionStateChanged(let state):
                    sample("session-\(state)")
                case .turnCompleted:
                    sample("turn-completed")
                default:
                    break
                }
            }

            sample("spawned")
            let prompt = """
            This is a supervised UI validation using disposable files. Perform exactly these actions in order:
            1. Use the read tool on \(insidePath).
            2. Use the edit tool on \(insidePath), replacing LIVE_ALPHA with LIVE_BETA.
            3. Use the bash tool to run exactly: sleep 2
            4. Use the read tool on \(externalPath).
            Then reply with exactly LOCATION_LIVE_DONE. Do not perform any other action.
            """
            view.qaSubmitPrompt(prompt)
            sample("submitted")

            Task { @MainActor in
                @MainActor func fail(_ message: String) -> Never {
                    sample("failure")
                    qaCapture?.writeManifest()
                    if let output = ProcessInfo.processInfo.environment["CONTINUUM_QA_CAPTURE"] {
                        try? JSONSerialization.data(
                            withJSONObject: ["verdict": "FAIL", "message": message, "samples": samples],
                            options: [.prettyPrinted, .sortedKeys]
                        ).write(to: URL(fileURLWithPath: output, isDirectory: true)
                            .appendingPathComponent("location-live.json"), options: .atomic)
                    }
                    report("transcript:\n\(view.qaTranscriptText)")
                    report("FAIL: \(message)")
                    Foundation.exit(1)
                }

                guard await waitUntil(timeout: 180, {
                    view.qaLastAssistantCardBody?.contains("LOCATION_LIVE_DONE") == true
                        && view.qaV2CanSend
                        && view.qaV2ActionTitle == "Send"
                }) else { fail("timed out waiting for the real Pi turn to finish") }
                sample("turn-settled")

                let insideRead = samples.contains {
                    ($0["what"] as? String)?.contains("Reading inside.txt") == true
                        && ($0["whatExternalMarker"] as? Bool) == false
                }
                let insideEdit = samples.contains {
                    ($0["what"] as? String)?.contains("Editing inside.txt") == true
                        && ($0["whatExternalMarker"] as? Bool) == false
                }
                let bashRun = samples.contains {
                    ($0["what"] as? String) == "What Running"
                }
                let externalRead = samples.contains {
                    ($0["what"] as? String)?.contains("Reading") == true
                        && ($0["what"] as? String)?.contains("external.txt") == true
                        && ($0["whatExternalMarker"] as? Bool) == true
                        && ($0["detail"] as? String)?.contains("outside Home") == true
                }
                let homeStayedAuthoritative = samples.allSatisfy {
                    ($0["location"] as? String) == "Home project"
                        && ($0["whereExternalMarker"] as? Bool) == false
                }
                let accessibilityStayedSemantic = samples.allSatisfy {
                    (($0["locationAX"] as? String)?.isEmpty == false)
                        && (($0["whatAX"] as? String)?.isEmpty == false)
                }
                let edited = (try? String(contentsOfFile: insidePath, encoding: .utf8))?
                    .contains("LIVE_BETA") == true
                guard insideRead, insideEdit, bashRun, externalRead, homeStayedAuthoritative,
                      accessibilityStayedSemantic, edited else {
                    fail("missing live transition: read=\(insideRead) edit=\(insideEdit) bash=\(bashRun) external=\(externalRead) home=\(homeStayedAuthoritative) ax=\(accessibilityStayedSemantic) edited=\(edited)")
                }

                guard await waitUntil(timeout: 35, {
                    view.qaWhatText.hasPrefix("Last Read")
                        && view.qaWhatOutboundMarkerVisible
                }) else { fail("live stale timer did not demote current What to recent external activity") }
                sample("stale-to-recent")
                if let rawHold = ProcessInfo.processInfo.environment["CONTINUUM_LOCATION_LIVE_HOLD_SECONDS"],
                   let requestedHold = UInt64(rawHold), requestedHold > 0 {
                    let holdSeconds = min(requestedHold, 60)
                    report("VOICEOVER_READY: holding stale external activity for \(holdSeconds)s")
                    try? await Task.sleep(nanoseconds: holdSeconds * 1_000_000_000)
                }

                qaCapture?.writeManifest()
                if let output = ProcessInfo.processInfo.environment["CONTINUUM_QA_CAPTURE"] {
                    let result: [String: Any] = [
                        "verdict": "PASS",
                        "homeStayedAuthoritative": homeStayedAuthoritative,
                        "insideReadObserved": insideRead,
                        "insideEditObserved": insideEdit,
                        "bashRunObserved": bashRun,
                        "externalReadObserved": externalRead,
                        "staleRecentObserved": true,
                        "accessibilityValuesNonempty": accessibilityStayedSemantic,
                        "samples": samples,
                    ]
                    do {
                        let url = URL(fileURLWithPath: output, isDirectory: true)
                            .appendingPathComponent("location-live.json")
                        try JSONSerialization.data(
                            withJSONObject: result,
                            options: [.prettyPrinted, .sortedKeys]
                        ).write(to: url, options: .atomic)
                        report("artifact: \(url.path)")
                    } catch {
                        fail("could not write location-live.json: \(error)")
                    }
                }
                report("PASS: real Pi produced inside read/edit, Bash, external read, waiting, and stale-to-recent UI evidence while Home remained authoritative")
                Foundation.exit(0)
            }
        }
    }

    /// End-to-end sanity check for the managed-agent tile (88.4b/88.5): spawn a
    /// tile through the real palette path, then drive TWO prompts through the
    /// tile's real Run action — turn 1 plants a codeword, turn 2 asks for it
    /// back. Passing proves the click path streams live GPT-5.6 into the tile
    /// AND that the session continues across prompts (memory). Exercises the
    /// exact path in-process; waits via the shared `waitUntil` (UITestSupport),
    /// which suspends rather than spinning a nested RunLoop, so the normal event
    /// loop drains the tile's main-queue ingests. Gated on
    /// `--managed-agent-live-check`.
    private func runManagedAgentLiveCheck(window: NSWindow) {
        func report(_ line: String) { FileHandle.standardError.write(Data("[managed-agent-live] \(line)\n".utf8)) }
        let codeword = "BANANA73"
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            guard let self, let spawner = self.tileSpawner, let canvasView = self.canvasView else {
                report("FAIL: no spawner/canvas"); Foundation.exit(2)
            }
            guard case let .spawned(tileId) = spawner.spawnManagedAgent() else {
                report("FAIL: spawnManagedAgent did not spawn"); Foundation.exit(2)
            }
            self.wireManagedAgentTile(tileId)
            self.focusSpawnedTile(tileId)
            guard let view = canvasView.tileView(for: tileId) as? ManagedAgentTileNSView else {
                report("FAIL: spawned tile is not a ManagedAgentTileNSView"); Foundation.exit(2)
            }
            report("spawned tile \(tileId)")

            // One budget for both turns, as before: each wait gets whatever is
            // left of the original 180s.
            let deadline = Date().addingTimeInterval(180)
            view.qaSubmitPrompt("Remember this codeword: \(codeword). Reply with just: OK")
            // Cards present right after the (synchronous) prompt echo — turn 1's
            // reply is done once a NEW card appears beyond this and it settles.
            let cardsAfterTurn1Submit = view.transcriptCardCount
            report("turn 1 submitted (plant codeword); baseCards=\(cardsAfterTurn1Submit)…")

            Task { @MainActor in
                @MainActor func timedOut(_ stage: String) -> Never {
                    report("transcript:\n\(view.qaTranscriptText)")
                    report("FAIL: timed out (\(stage))")
                    Foundation.exit(1)
                }

                // Turn 1 done: a reply card appeared past the echo and the agent
                // settled (not working). Then ask for recall.
                guard await waitUntil(timeout: deadline.timeIntervalSinceNow, {
                    view.transcriptCardCount > cardsAfterTurn1Submit
                        && view.qaV2CanSend
                        && view.qaV2ActionTitle == "Send"
                        && view.currentAgentStatus != .working
                }) else { timedOut("waiting for turn 1 reply") }

                report("turn 1 done; submitting turn 2 (recall) in a fresh Pi process, same session")
                view.qaSubmitPrompt("What was the codeword? Reply with only the codeword.")

                // Continuity proof: turn 2's reply (a NEW assistant card, since
                // 88.5 splits per turn) recalls the codeword planted in turn 1 —
                // impossible without a continued session.
                guard await waitUntil(timeout: deadline.timeIntervalSinceNow, {
                    view.qaLastAssistantCardBody?.contains(codeword) == true
                        && view.currentAgentStatus != .working
                }) else { timedOut("waiting for turn 2 recall") }

                report("transcript:\n\(view.qaTranscriptText)")
                // 88.4c: confirm the syncable activity timeline (what the phone
                // would receive) was populated in-app by the runner.
                let agentKey = self.agentSupervisor.agent(forTile: tileId)?.rawValue
                let kinds = agentKey.flatMap { self.managedAgentActivityByAgent[$0]?.map(\.kind) } ?? []
                report("sync activity timeline recorded (88.4c): \(kinds)")
                report("PASS: turn 2 recalled '\(codeword)' — session continuity works in-app")
                Foundation.exit(0)
            }
        }
    }

    /// The claude-backend twin of `runManagedAgentLiveCheck`: same two-turn
    /// codeword continuity proof through the real tile, but on an anthropic
    /// model so `productionRunner` routes to `ClaudeAgentRunner`. Proves the
    /// full path live: routing, the resume-first/--session-id-retry dance
    /// (turn 1 IS the retry; turn 2 resumes), stream-json translation into
    /// the tile, and cross-process session memory on the user's own claude
    /// login. Supervised only (spends real subscription usage, needs claude
    /// installed + signed in) — not a default matrix leg, like the pi twin.
    /// Gated on `--claude-agent-live-check`.
    private func runClaudeAgentLiveCheck(window: NSWindow) {
        func report(_ line: String) { FileHandle.standardError.write(Data("[claude-agent-live] \(line)\n".utf8)) }
        let codeword = "CANTALOUPE41"
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            guard let self, let spawner = self.tileSpawner, let canvasView = self.canvasView else {
                report("FAIL: no spawner/canvas"); Foundation.exit(2)
            }
            guard ClaudeAgentRunner.liveCLIAvailable() else {
                report("FAIL: no claude CLI on this machine — this leg is supervised and needs one"); Foundation.exit(2)
            }
            guard case let .spawned(tileId) = spawner.spawnManagedAgent() else {
                report("FAIL: spawnManagedAgent did not spawn"); Foundation.exit(2)
            }
            self.wireManagedAgentTile(tileId)
            self.focusSpawnedTile(tileId)
            guard let view = canvasView.tileView(for: tileId) as? ManagedAgentTileNSView else {
                report("FAIL: spawned tile is not a ManagedAgentTileNSView"); Foundation.exit(2)
            }
            // Move the agent onto an anthropic model so routing picks claude.
            // The check run never enables live catalogue refresh, so seed the
            // claude union the probe would have applied, then go through the
            // real validated setter.
            AgentModelCatalog.shared.apply(claudeBackendAvailable: true)
            guard let agentId = self.agentSupervisor.agent(forTile: tileId),
                  self.agentSupervisor.setProviderSettings(agentID: agentId, model: "anthropic/haiku", thinking: "low")
            else {
                report("FAIL: could not move the spawned agent onto anthropic/haiku"); Foundation.exit(2)
            }
            guard let record = self.agentSupervisor.records[agentId],
                  AgentSupervisor.productionRunner(for: AgentRunnerLaunch(record: record, spawnDepth: 0)) is ClaudeAgentRunner
            else {
                report("FAIL: anthropic/haiku did not route to ClaudeAgentRunner"); Foundation.exit(2)
            }
            report("spawned tile \(tileId), routed to claude (model anthropic/haiku)")

            let deadline = Date().addingTimeInterval(180)
            view.qaSubmitPrompt("Remember this codeword: \(codeword). Reply with just: OK")
            let cardsAfterTurn1Submit = view.transcriptCardCount
            report("turn 1 submitted (plant codeword, --session-id retry path); baseCards=\(cardsAfterTurn1Submit)…")

            Task { @MainActor in
                @MainActor func timedOut(_ stage: String) -> Never {
                    report("transcript:\n\(view.qaTranscriptText)")
                    report("FAIL: timed out (\(stage))")
                    Foundation.exit(1)
                }

                guard await waitUntil(timeout: deadline.timeIntervalSinceNow, {
                    view.transcriptCardCount > cardsAfterTurn1Submit
                        && view.qaV2CanSend
                        && view.qaV2ActionTitle == "Send"
                        && view.currentAgentStatus != .working
                }) else { timedOut("waiting for turn 1 reply") }

                report("turn 1 done; submitting turn 2 (recall) in a fresh claude process, same session via --resume")
                view.qaSubmitPrompt("What was the codeword? Reply with only the codeword.")

                guard await waitUntil(timeout: deadline.timeIntervalSinceNow, {
                    view.qaLastAssistantCardBody?.contains(codeword) == true
                        && view.currentAgentStatus != .working
                }) else { timedOut("waiting for turn 2 recall") }

                report("transcript:\n\(view.qaTranscriptText)")
                report("PASS: turn 2 recalled '\(codeword)' — claude-backed session continuity works in-app")
                Foundation.exit(0)
            }
        }
    }

    /// Twin of `runClaudeAgentLiveCheck` for the codex backend. Proves the one
    /// hard difference: codex continuity is STORED. Turn 1 (a fresh `codex exec`)
    /// plants a codeword and captures + PERSISTS the minted `thread_id` to
    /// `record.codexThreadId`; turn 2 (`codex exec resume` in a fresh process)
    /// recalls it. Supervised only (spends real subscription usage, needs codex
    /// installed + signed in) — not a default matrix leg, like the claude/pi
    /// twins. Gated on `--codex-agent-live-check`.
    private func runCodexAgentLiveCheck(window: NSWindow) {
        func report(_ line: String) { FileHandle.standardError.write(Data("[codex-agent-live] \(line)\n".utf8)) }
        let codeword = "PLATYPUS42"
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            guard let self, let spawner = self.tileSpawner, let canvasView = self.canvasView else {
                report("FAIL: no spawner/canvas"); Foundation.exit(2)
            }
            guard CodexAgentRunner.liveCLIAvailable() else {
                report("FAIL: no codex CLI on this machine — this leg is supervised and needs one"); Foundation.exit(2)
            }
            guard case let .spawned(tileId) = spawner.spawnManagedAgent() else {
                report("FAIL: spawnManagedAgent did not spawn"); Foundation.exit(2)
            }
            self.wireManagedAgentTile(tileId)
            self.focusSpawnedTile(tileId)
            guard let view = canvasView.tileView(for: tileId) as? ManagedAgentTileNSView else {
                report("FAIL: spawned tile is not a ManagedAgentTileNSView"); Foundation.exit(2)
            }
            // Move the agent onto an openai-codex model so routing picks codex.
            // The check run never enables live catalogue refresh, so seed the
            // codex union the probe would have applied, then go through the real
            // validated setter. The DEFAULT backend (.pi) already routes
            // openai-codex/* → codex when codex is available, so no backend
            // preference is written (never pollute the real defaults domain).
            AgentModelCatalog.shared.apply(codexBackendAvailable: true)
            guard let agentId = self.agentSupervisor.agent(forTile: tileId),
                  self.agentSupervisor.setProviderSettings(agentID: agentId, model: "openai-codex/gpt-5.4-mini", thinking: "low")
            else {
                report("FAIL: could not move the spawned agent onto openai-codex/gpt-5.4-mini"); Foundation.exit(2)
            }
            guard let record = self.agentSupervisor.records[agentId],
                  AgentSupervisor.productionRunner(for: AgentRunnerLaunch(record: record, spawnDepth: 0)) is CodexAgentRunner
            else {
                report("FAIL: openai-codex/gpt-5.4-mini did not route to CodexAgentRunner"); Foundation.exit(2)
            }
            report("spawned tile \(tileId), routed to codex (model openai-codex/gpt-5.4-mini)")

            let deadline = Date().addingTimeInterval(240)
            view.qaSubmitPrompt("Remember this codeword: \(codeword). Reply with just: OK")
            let cardsAfterTurn1Submit = view.transcriptCardCount
            report("turn 1 submitted (plant codeword, fresh codex exec); baseCards=\(cardsAfterTurn1Submit)…")

            Task { @MainActor in
                @MainActor func timedOut(_ stage: String) -> Never {
                    report("transcript:\n\(view.qaTranscriptText)")
                    report("FAIL: timed out (\(stage))")
                    Foundation.exit(1)
                }

                guard await waitUntil(timeout: deadline.timeIntervalSinceNow, {
                    view.transcriptCardCount > cardsAfterTurn1Submit
                        && view.qaV2CanSend
                        && view.qaV2ActionTitle == "Send"
                        && view.currentAgentStatus != .working
                }) else { timedOut("waiting for turn 1 reply") }

                // The STORED-continuity witness: turn 1's thread.started must
                // have been captured off the observation side channel and
                // persisted to the record before turn 2 can resume it.
                guard let persisted = self.agentSupervisor.records[agentId]?.codexThreadId, !persisted.isEmpty else {
                    report("transcript:\n\(view.qaTranscriptText)")
                    report("FAIL: turn 1 did not persist record.codexThreadId (stored continuity broke)")
                    Foundation.exit(1)
                }
                report("turn 1 done; persisted codexThreadId=\(persisted); submitting turn 2 (recall) via codex exec resume in a fresh process")
                view.qaSubmitPrompt("What was the codeword? Reply with only the codeword.")

                guard await waitUntil(timeout: deadline.timeIntervalSinceNow, {
                    view.qaLastAssistantCardBody?.contains(codeword) == true
                        && view.currentAgentStatus != .working
                }) else { timedOut("waiting for turn 2 recall") }

                report("transcript:\n\(view.qaTranscriptText)")
                report("PASS: turn 2 recalled '\(codeword)' and record.codexThreadId persisted (\(persisted)) — codex STORED continuity works in-app")
                Foundation.exit(0)
            }
        }
    }

    private func runTerminalScrollErgonomicsCheck(window: NSWindow, runtime: GhosttyTerminalRuntime?) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            guard let self else { return }
            func waitUntil(_ timeout: TimeInterval = 5, _ condition: () -> Bool) -> Bool {
                let deadline = Date().addingTimeInterval(timeout)
                while Date() < deadline {
                    if condition() { return true }
                    RunLoop.current.run(mode: .default, before: Date().addingTimeInterval(0.03))
                }
                return condition()
            }

            do {
                guard let runtime, let canvasView = self.canvasView else {
                    throw NSError(domain: "TerminalScrollErgonomics", code: 1, userInfo: [NSLocalizedDescriptionKey: "missing terminal runtime or canvas"])
                }
                guard let terminalView = runtime.qaTerminalView, let terminalWindow = terminalView.window else {
                    throw NSError(domain: "TerminalScrollErgonomics", code: 2, userInfo: [NSLocalizedDescriptionKey: "missing terminal view/window"])
                }
                let terminalCenterInWindow = terminalView.convert(
                    NSPoint(x: terminalView.bounds.midX, y: terminalView.bounds.midY),
                    to: nil
                )
                let terminalPointTargetsScrollableContent = self.pointTargetsScrollableTileContent(terminalCenterInWindow, in: terminalWindow)
                let startViewport = canvasView.viewport
                let defaults = UserDefaults.standard
                let oldPrecise = defaults.object(forKey: TerminalScrollConfig.preciseMultiplierKey)
                defer {
                    if let oldPrecise { defaults.set(oldPrecise, forKey: TerminalScrollConfig.preciseMultiplierKey) } else { defaults.removeObject(forKey: TerminalScrollConfig.preciseMultiplierKey) }
                }

                defaults.removeObject(forKey: TerminalScrollConfig.preciseMultiplierKey)
                let defaultSample = runtime.dispatchScrollWheel(deltaX: 0, deltaY: -3, precise: true)
                defaults.set("0.5", forKey: TerminalScrollConfig.preciseMultiplierKey)
                let tunedSample = runtime.dispatchScrollWheel(deltaX: 0, deltaY: -3, precise: true)
                let inputMarker = "terminal_scroll_ergonomics_\(UUID().uuidString.prefix(8))"
                let insertedInput = runtime.dispatchInsertedText("printf '\(inputMarker)\\n'\n")
                let inputAfterScrollWorked = insertedInput && waitUntil {
                    runtime.visibleText().contains(inputMarker)
                }
                let callCount = runtime.qaTerminalView?.qaGhosttyScrollCallCount ?? 0
                let viewportChanged = canvasView.viewport != startViewport

                guard let defaultSample, let tunedSample else { throw NSError(domain: "TerminalScrollErgonomics", code: 3) }
                guard terminalPointTargetsScrollableContent else { throw NSError(domain: "TerminalScrollErgonomics", code: 4) }
                guard defaultSample.deliveredViaProductionScrollWheel, tunedSample.deliveredViaProductionScrollWheel else { throw NSError(domain: "TerminalScrollErgonomics", code: 5) }
                guard abs(defaultSample.rawDeltaY - -3) < 0.001, abs(defaultSample.normalizedDeltaY - -3) < 0.001 else { throw NSError(domain: "TerminalScrollErgonomics", code: 6) }
                guard abs(tunedSample.rawDeltaY - -3) < 0.001, abs(tunedSample.normalizedDeltaY - -1.5) < 0.001 else { throw NSError(domain: "TerminalScrollErgonomics", code: 7) }
                guard callCount == 2 else { throw NSError(domain: "TerminalScrollErgonomics", code: 8) }
                guard !viewportChanged else { throw NSError(domain: "TerminalScrollErgonomics", code: 9) }
                guard inputAfterScrollWorked else { throw NSError(domain: "TerminalScrollErgonomics", code: 10) }

                let timestamp = Self.qaTimestamp()
                let dir = URL(fileURLWithPath: "qa-runs/\(timestamp)/terminal-scroll-ergonomics", isDirectory: true)
                try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
                let manifest: [String: Any] = [
                    "check": "terminal-scroll-ergonomics",
                    "settings": ["preciseMultiplier": 1.0, "lineMultiplier": 1.0, "maxAbsDeltaPerEvent": NSNull()],
                    "samples": [try Self.jsonObject(defaultSample), try Self.jsonObject(tunedSample)],
                    "ghosttyScrollCallCount": callCount,
                    "terminalPointTargetsScrollableTileContent": terminalPointTargetsScrollableContent,
                    "canvasViewportChanged": viewportChanged,
                    "inputMarker": inputMarker,
                    "inputAfterScrollWorked": inputAfterScrollWorked,
                    "manualMatrixPending": true
                ]
                let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
                try data.write(to: dir.appendingPathComponent("manifest.json"), options: .atomic)
                print("terminal-scroll-ergonomics artifact: \(dir.path)/manifest.json")
                NSApp.terminate(nil)
            } catch {
                fputs("terminal-scroll-ergonomics check failed: \(error)\n", stderr)
                self.smokeTestExitCode = 1
                NSApp.terminate(nil)
            }
        }
    }

    // MARK: - WS4 · completion awareness

    /// Whether Array is the active application, maintained by AppKit's own
    /// activation callbacks.
    ///
    /// This is a fact, not a flag a check can poke: `applicationDidBecomeActive`
    /// and `applicationDidResignActive` are the only writers, and they are the
    /// real delegate methods AppKit calls. A fixture proves the resign behaviour
    /// by delivering those notifications, which is the same path the window
    /// server drives — it does NOT get a setter, because a settable "pretend the
    /// app resigned" is not evidence that resigning does anything.
    ///
    /// Seeded from `NSApp.isActive` so a delegate built mid-session starts honest.
    private(set) lazy var applicationIsActiveForAwareness: Bool = NSApplication.shared.isActive

    /// Reduce Motion, read once per acknowledgment. Injectable for the same reason
    /// `CanvasNSView.occlusionVisibilityProvider` is: a check must be able to
    /// exercise both accessibility branches without changing a system setting on
    /// the machine it runs on. Production leaves it nil and reads `NSWorkspace`.
    var reduceMotionProvider: (() -> Bool)?

    /// Terminal arrivals the supervisor judged watched, stamped at arrival and
    /// consumed when the matching signal reaches `recordManagedActivity`.
    ///
    /// A stamp exists because the two halves arrive on different turns: the
    /// durable half runs inside `AgentSupervisor.deliver`, while the live signal
    /// is published later, from the TILE's stream subscription. Clearing at
    /// arrival would clear a signal that has not been published yet, and the
    /// stale success badge would then sit on the tile forever.
    /// The DECISION is stamped, not the arrival kind. Stamping the kind and
    /// re-deriving "is this a success" here would make
    /// `AgentAwarenessTransition` two owners of one rule, and the second one
    /// silently wins.
    private var pendingWatchedArrivalsByTile: [UUID: AgentAwarenessDecision] = [:]
    /// Acknowledgments actually played. Positive control for the visual half.
    private(set) var qaCompletionAcknowledgmentCount = 0
    /// Stamps consumed by the live half. Positive control for the hand-off.
    private(set) var qaWatchedArrivalStampsConsumed = 0
    /// Accepted-tile-focus callbacks refused as restoration rather than a visit.
    /// Positive control for "restoration did not mark it read": without it, a
    /// witness cannot tell a refused restore from a restore that never happened.
    private(set) var qaNonDeliberateFocusCount = 0

    /// The one place the app answers "is a human looking at this agent".
    ///
    /// Every answer is read from live state at the moment of the call. Nothing is
    /// remembered, so there is no value here that can go stale across a
    /// resignation, a window ordering change, a Space switch or a modal.
    func activeViewFacts(forAgent id: AgentID) -> AgentActiveViewFacts {
        guard let tileId = agentSupervisor.records[id]?.tileId,
              let canvasView,
              let tileView = canvasView.tileView(for: tileId) else { return .away }
        let window = tileView.window
        var facts = AgentActiveViewFacts()
        facts.tileMounted = true
        facts.appActive = applicationIsActiveForAwareness
        facts.focusScopeIsTile = focusBroker.activeSurface == .tile(tileId)
        guard let window else { return facts }
        // "Not upstaged", not `isKeyWindow` — see `AgentActiveViewFacts`.
        facts.windowNotUpstaged = NSApplication.shared.keyWindow.map { $0 === window } ?? true
        facts.windowVisible = window.isVisible && !window.isMiniaturized
        facts.windowOcclusionVisible = canvasView.awarenessWindowVisibility()
        facts.modalPresented = NSApplication.shared.modalWindow != nil
            || window.attachedSheet != nil
        if let responder = window.firstResponder as? NSView {
            facts.responderInTile = responder === tileView || responder.isDescendant(of: tileView)
        } else {
            facts.responderInTile = false
        }
        return facts
    }

    /// Wires the supervisor's awareness seams. Folded into
    /// `installAcceptedTileFocusHook` so no boot path or fixture can wire the
    /// focus bridge and forget the awareness one.
    func installAgentAwarenessHooks() {
        agentSupervisor.activeViewFactsProvider = { [weak self] agentID in
            self?.activeViewFacts(forAgent: agentID) ?? .away
        }
        agentSupervisor.onWatchedTerminalArrival = { [weak self] _, tileID, _, decision in
            guard let self, let tileID else { return }
            guard decision.clearsLiveSignal || decision.acknowledgesVisually else { return }
            self.pendingWatchedArrivalsByTile[tileID] = decision
        }
    }

    /// The live half, run once the signal for a watched arrival has been
    /// published. Only an ordinary success is retired and acknowledged; a failure
    /// keeps its signal, and `acknowledgeWatchedCompletion` refuses anything that
    /// is not a live `.completed`, so an action request that outranks it is safe.
    private func applyPendingWatchedArrival(tileID: UUID) {
        guard let decision = pendingWatchedArrivalsByTile.removeValue(forKey: tileID) else { return }
        qaWatchedArrivalStampsConsumed += 1
        guard decision.clearsLiveSignal else { return }
        // Refuses unless the live signal really is an ordinary success — which is
        // how a completion arriving behind an open action request leaves the
        // stronger state alone.
        guard agentSignalCenter.acknowledgeWatchedCompletion(tileID: tileID) else { return }
        guard decision.acknowledgesVisually else { return }
        let reduceMotion = reduceMotionProvider?()
            ?? NSWorkspace.shared.accessibilityDisplayShouldReduceMotion
        let plan = AgentCompletionAcknowledgmentPlan.plan(reduceMotion: reduceMotion)
        (canvasView?.tileView(for: tileID) as? ManagedAgentTileNSView)?
            .beginCompletionAcknowledgment(plan)
        qaCompletionAcknowledgmentCount += 1
    }

    func installAcceptedTileFocusHook() {
        installAgentAwarenessHooks()
        // M1.10: the APP's field, not the broker's composite one. Assigning
        // `onAcceptedTileFocusWithReason` here overwrote the controller's
        // composite — which is why `recoverManagedSessionOnFocus` never ran at
        // boot — and would have been overwritten right back on every switch.
        focusBroker.appAcceptedTileFocusWithReason = { [weak self] tileId, reason in
            guard let self else { return }
            // WS4: restoration is not a visit. App activation, modal dismissal and
            // recovery all arrive here looking exactly like a click, which is how
            // simply returning to Array cleared every completion that had landed
            // while it was in the background. The scope, lineage, history and zone
            // arming below still run — only the READ-STATE half is withheld.
            let deliberate = reason.isDeliberateVisit
            if !deliberate { self.qaNonDeliberateFocusCount += 1 }
            self.synchronizeAgentFocus(to: tileId, deliberate: deliberate)
            if deliberate { self.agentSignalCenter.markViewed(tileID: tileId) }
            self.updateContextualAgentLineage(forFocusedTile: tileId)
            self.recordAcceptedTileFocusInHistory(tileId, reason: reason)
            self.armZoneForFocusedTile(tileId, reason: reason)
        }
    }

    /// Focus owns the ephemeral lineage presentation. A child resolves upward
    /// to its parent; a parent stays itself; both show the same bounded visible
    /// direct-child fan. Non-agent focus clears the contextual overlay.
    private func updateContextualAgentLineage(forFocusedTile tileId: UUID) {
        guard let canvasView,
              let focusedAgent = agentSupervisor.agent(forTile: tileId),
              let focusedRecord = agentSupervisor.records[focusedAgent]
        else {
            self.canvasView?.clearContextualAgentLineage()
            return
        }
        let parentID = focusedRecord.parentAgentID ?? focusedAgent
        guard let parentTileID = agentSupervisor.records[parentID]?.tileId else {
            canvasView.clearContextualAgentLineage()
            return
        }
        let edges = agentSupervisor.children(of: parentID)
            .sorted { $0.rawValue.uuidString < $1.rawValue.uuidString }
            .compactMap { childID -> (parentTileID: UUID, childTileID: UUID)? in
                guard let childTileID = agentSupervisor.records[childID]?.tileId,
                      canvasView.tileView(for: childTileID) != nil else { return nil }
                return (parentTileID, childTileID)
            }
        canvasView.showContextualAgentLineage(edges: edges)
    }

    /// T2 (`.plans/47`): working in a tile arms its zone, so the next thing you
    /// create lands beside what you were just doing.
    ///
    /// `.userClick` ONLY. Every other reason is a restore or a side effect —
    /// `appActivated`, `modalDismissed` and `recovery` all replay a focus the user
    /// did not just perform, and `switchWorkspace`'s own `restoreFocus` runs
    /// through them. Arming on those would let a workspace switch's tail end
    /// re-point the zone the switch had just deliberately set.
    private func armZoneForFocusedTile(_ tileId: UUID, reason: FocusRequest) {
        guard reason == .userClick,
              let zoneId = canvasView?.zoneId(containing: tileId) else { return }
        workspaceRuntime?.setActiveZone(zoneId, reason: .focus)
    }

    /// Keep the supervisor's read watermark on the same tile focus the canvas
    /// already accepted. Sidebar reveal used to call `focus(agentID:)` explicitly,
    /// but a direct click in a tile and work-oriented keyboard navigation stopped
    /// at FocusBroker/CanvasState, leaving a Done row unread until its sidebar card
    /// was clicked. This is the shared bridge for those routes.
    ///
    /// Rebuild only when the focused agent or its attention actually changed. The
    /// window-level click monitor reports every click inside an already-focused
    /// transcript/composer; reloading the whole sidebar for each one would turn a
    /// read-watermark fix into an interaction performance regression.
    private func synchronizeAgentFocus(to tileId: UUID?, deliberate: Bool = true) {
        let previousAgent = agentSupervisor.focusedAgentID
        let nextAgent = tileId.flatMap { agentSupervisor.agent(forTile: $0) }
        let previousAttention = nextAgent.map { agentSupervisor.attention(for: $0) }
        agentSupervisor.focusTile(tileId, deliberate: deliberate)
        let attentionChanged = nextAgent.map {
            previousAttention != agentSupervisor.attention(for: $0)
        } ?? false
        guard previousAgent != agentSupervisor.focusedAgentID || attentionChanged else { return }
        reloadWorkspaceSidebar(rebuildAgentActivity: false)
    }

    private func recordAcceptedTileFocusInHistory(_ tileId: UUID, reason: FocusRequest) {
        guard reason == .userClick else { return }
        focusHistory.recordTileFocus(tileId, zoneId: zoneContainingTile(tileId), reason: .directTileActivation)
    }

    private func runPreviousFocusNavigationCheck(window: NSWindow) {
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            do {
                let artifact = try self.performPreviousFocusNavigationCheck(window: window)
                print("previous-focus-navigation artifact: \(artifact.path)")
                self.smokeTestExitCode = 0
                NSApp.terminate(nil)
            } catch {
                fputs("previous-focus-navigation check failed: \(error)\n", stderr)
                self.smokeTestExitCode = 1
                NSApp.terminate(nil)
            }
        }
    }

    private func performPreviousFocusNavigationCheck(window: NSWindow) throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String { if case let .failed(message) = self { return message }; return "failed" }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }
        func viewportErrorScreenPx(_ lhs: CanvasViewport, _ rhs: CanvasViewport) -> Double {
            let zoom = max(max(abs(lhs.zoom), abs(rhs.zoom)), CameraFraming.minJumpZoom)
            return max(abs(lhs.x - rhs.x) * zoom, abs(lhs.y - rhs.y) * zoom, abs(lhs.zoom - rhs.zoom) * 1000)
        }
        func paletteAction(named displayName: String, in rows: [LaunchPaletteRow]) throws -> LaunchPaletteAction {
            for row in rows {
                switch row {
                case let .action(action) where action.displayName == displayName:
                    return action
                case let .jumpToTile(tile) where "Jump to \(tile.title)" == displayName:
                    return .jumpToTile(tile.id)
                case let .jumpToZone(zone) where "Jump to \(zone.title)" == displayName:
                    return .jumpToZone(zone.id)
                default:
                    continue
                }
            }
            throw CheckError.failed("missing palette row \(displayName)")
        }

        let a = UUID(uuidString: "A0000000-0000-4000-8000-000000000801")!
        let b = UUID(uuidString: "A0000000-0000-4000-8000-000000000802")!
        let z1 = UUID(uuidString: "A0000000-0000-4000-8000-000000000811")!
        let z2 = UUID(uuidString: "A0000000-0000-4000-8000-000000000812")!
        let tileA = Tile(id: a, kind: .note, title: "A", frame: TileFrame(x: 80, y: 120, width: 320, height: 220), zPosition: .fromLegacyRank(0), runtimeRef: nil, metadata: TileMetadata())
        let tileB = Tile(id: b, kind: .note, title: "B", frame: TileFrame(x: 2_520, y: 140, width: 320, height: 220), zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata())
        let zoneA = ZonePlacement(zoneId: z1, projectId: nil, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 700, height: 520), color: "blue", collapsed: false, hydrationPolicy: .automatic, name: "Z1", navKey: "a")
        let zoneB = ZonePlacement(zoneId: z2, projectId: nil, origin: ZonePoint(x: 2_320, y: 0), size: ZoneSize(width: 700, height: 520), color: "mint", collapsed: false, hydrationPolicy: .automatic, name: "Z2", navKey: "b")
        let canvas = CanvasNSView(
            canvasState: CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [tileA, tileB], groups: [], lastActiveTileId: nil),
            zoneRenderModels: [CanvasNSView.ZoneRenderModel(placement: zoneA, displayName: "Z1"), CanvasNSView.ZoneRenderModel(placement: zoneB, displayName: "Z2")]
        )
        canvas.frame = window.contentView?.bounds ?? NSRect(x: 0, y: 0, width: 900, height: 620)
        canvas.autoresizingMask = [.width, .height]
        self.canvasView?.detachFocusBroker()
        self.canvasView = canvas
        window.contentView = canvas
        canvas.focusBroker = focusBroker
        focusBroker.onAcceptedTileFocus = { [weak canvas] tileId in canvas?.markActive(tileId: tileId) }
        focusBroker.onAcceptedCanvasScope = { [weak canvas] in canvas?.clearFocusBorder() }
        installAcceptedTileFocusHook()
        let viewA = DescriptorTileNSView(tile: tileA)
        let viewB = DescriptorTileNSView(tile: tileB)
        canvas.install(tileView: viewA, for: tileA)
        canvas.install(tileView: viewB, for: tileB)
        window.makeFirstResponder(canvas)
        canvas.layoutSubtreeIfNeeded()
        viewA.layoutSubtreeIfNeeded()
        viewB.layoutSubtreeIfNeeded()

        let rows = LaunchPaletteModel.makeRows(
            profiles: [],
            jumpTiles: canvas.navigationTileSnapshots().map { JumpTileRow(id: $0.tileId, title: $0.title) },
            jumpZones: [JumpZoneRow(id: z1, title: "Z1"), JumpZoneRow(id: z2, title: "Z2")]
        )
        let previousRows = LaunchPaletteModel.filterRows(rows, query: "previous").map(\.displayName)
        try expect(previousRows.contains("Back to Previous View") && previousRows.contains("Go to Previous Tile") && previousRows.contains("Go to Previous Zone"), "previous commands must be discoverable through LaunchPaletteModel")
        let previousViewAction = try paletteAction(named: "Back to Previous View", in: rows)
        let previousTileAction = try paletteAction(named: "Go to Previous Tile", in: rows)
        let previousZoneAction = try paletteAction(named: "Go to Previous Zone", in: rows)
        let jumpBAction = try paletteAction(named: "Jump to B", in: rows)
        let jumpZ1Action = try paletteAction(named: "Jump to Z1", in: rows)
        let jumpZ2Action = try paletteAction(named: "Jump to Z2", in: rows)

        func routeClick(_ tileView: TileNSView) throws {
            let point = tileView.convert(NSPoint(x: tileView.bounds.midX, y: TileNSView.titleBarHeight / 2), to: nil)
            AppDelegate.routeTileClickFocus(at: point, in: canvas, focusBroker: focusBroker)
        }

        focusHistory = FocusHistory()
        navSelectedZoneId = nil
        try routeClick(viewA)
        try routeClick(viewB)
        performPaletteAction(previousTileAction)
        let previousTileFirst = canvas.canvasState.lastActiveTileId
        performPaletteAction(previousTileAction)
        let previousTileSecond = canvas.canvasState.lastActiveTileId
        performPaletteAction(previousTileAction)
        let previousTileThird = canvas.canvasState.lastActiveTileId
        try expect([previousTileFirst, previousTileSecond, previousTileThird] == [a, b, a], "previous tile must toggle A/B/A after real user-click focus")

        focusHistory = FocusHistory()
        navSelectedZoneId = nil
        let startViewport = CanvasViewport(x: 0, y: 0, zoom: 1)
        canvas.setViewport(startViewport)
        try routeClick(viewA)
        performPaletteAction(jumpBAction)
        let jumpedToBViewport = canvas.canvasState.viewport
        try expect(Self.viewportChangeExceedsJumpEpsilon(from: startViewport, to: jumpedToBViewport), "jump-to-B precondition should move the camera")
        performPaletteAction(previousViewAction)
        let restoredViewport = canvas.canvasState.viewport
        try expect(restoredViewport == startViewport, "previous view must restore the exact pre-jump viewport")
        let finalViewportErrorScreenPx = viewportErrorScreenPx(restoredViewport, startViewport)

        focusHistory = FocusHistory()
        navSelectedZoneId = nil
        canvas.setViewport(startViewport)
        try routeClick(viewA)
        performPaletteAction(jumpBAction)
        let viewBeforePreviousTile = canvas.canvasState.viewport
        performPaletteAction(previousTileAction)
        try expect(canvas.canvasState.lastActiveTileId == a, "previousTile should return to A before previous-view undo")
        performPaletteAction(previousViewAction)
        try expect(canvas.canvasState.viewport == viewBeforePreviousTile, "previous view after previousTile should restore the view previousTile left")

        focusHistory = FocusHistory()
        navSelectedZoneId = nil
        canvas.setViewport(startViewport)
        try routeClick(viewA)
        performPaletteAction(jumpZ1Action)
        performPaletteAction(jumpZ2Action)
        performPaletteAction(previousZoneAction)
        let previousZoneFirst = navSelectedZoneId
        let previousZoneFirstTile = canvas.canvasState.lastActiveTileId
        performPaletteAction(previousZoneAction)
        let previousZoneSecond = navSelectedZoneId
        performPaletteAction(previousZoneAction)
        let previousZoneThird = navSelectedZoneId
        try expect(previousZoneFirst == z1 && previousZoneFirstTile == a && previousZoneSecond == z2 && previousZoneThird == z1, "previous zone must toggle Z1/Z2/Z1 and restore Z1's last tile")

        focusHistory = FocusHistory()
        navSelectedZoneId = nil
        try routeClick(viewA)
        try routeClick(viewB)
        let beforeMissingTargetHistory = focusHistory
        let beforeMissingTargetViewport = canvas.canvasState.viewport
        canvas.removeTile(id: a)
        performPaletteAction(previousTileAction)
        let deletedTargetsSkipped = canvas.canvasState.lastActiveTileId == b && canvas.canvasState.viewport == beforeMissingTargetViewport && focusHistory != beforeMissingTargetHistory
        try expect(deletedTargetsSkipped, "deleted previous tile should be skipped without moving the camera")

        let beforeModalHistory = focusHistory
        focusBroker.openModal(.palette)
        focusBroker.closeModal(.palette)
        let modalRestorePollutedHistory = focusHistory != beforeModalHistory
        try expect(!modalRestorePollutedHistory, "palette modal restore must not pollute focus history")

        let timestamp = Self.qaTimestamp()
        let dir = URL(fileURLWithPath: "qa-runs/\(timestamp)/previous-focus-navigation", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let artifact = dir.appendingPathComponent("manifest.json")
        let manifest: [String: Any] = [
            "check": "previous-focus-navigation",
            "events": [
                ["reason": "directTileActivation", "target": "tile:A", "path": "routeTileClickFocus/userClick"],
                ["reason": "directTileActivation", "target": "tile:B", "path": "routeTileClickFocus/userClick"],
                ["reason": "previousNavigation", "target": "tile:A", "path": "LaunchPaletteModel row -> performPaletteAction"]
            ],
            "paletteRows": previousRows,
            "previousTileToggleSequence": ["A", "B", "A"],
            "previousZoneToggleSequence": ["Z1", "Z2", "Z1"],
            "previousZoneRestoredLastTile": previousZoneFirstTile == a,
            "deletedTargetsSkipped": deletedTargetsSkipped,
            "modalRestorePollutedHistory": modalRestorePollutedHistory,
            "cancelledTransitionRecorded": false,
            "finalViewportErrorScreenPx": finalViewportErrorScreenPx,
            "usedProductionClickRouter": true,
            "usedLaunchPaletteModelRows": true
        ]
        try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys]).write(to: artifact, options: .atomic)
        return artifact
    }

    private static func jsonObject<T: Encodable>(_ value: T) throws -> Any {
        let data = try JSONEncoder().encode(value)
        return try JSONSerialization.jsonObject(with: data)
    }

    private static func qaTimestamp() -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyyMMdd-HHmmss"
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        return formatter.string(from: Date())
    }

    private func installInitialTerminalTile(_ tile: Tile, in canvasView: CanvasNSView, via spawner: TileSpawner) {
        switch spawner.restartTerminalTile(tileId: tile.id) {
        case let .restarted(runtime):
            wireRuntimeExitHandler(runtime)
            runtimes.append(runtime)
        case let .missingCommand(executable):
            installRestartPlaceholder(
                for: tile,
                statusText: "\(executable) not found on $PATH",
                restartable: true,
                in: canvasView
            )
        case let .notConfigured(profileId):
            installRestartPlaceholder(
                for: tile,
                statusText: "Profile '\(profileId)' is not configured",
                restartable: false,
                in: canvasView
            )
        case let .unknownProfile(id):
            installRestartPlaceholder(
                for: tile,
                statusText: "Profile '\(id)' is missing",
                restartable: false,
                in: canvasView
            )
        case .tileNotFound:
            installRestartPlaceholder(
                for: tile,
                statusText: "Tile not found in canvas state",
                restartable: false,
                in: canvasView
            )
        case let .failure(error):
            fputs("Boot terminal install failed: \(error)\n", stderr)
            installRestartPlaceholder(
                for: tile,
                statusText: "Failed to start terminal",
                restartable: true,
                in: canvasView
            )
        }
    }

    private func installRestartPlaceholder(
        for tile: Tile,
        statusText: String,
        restartable: Bool,
        in canvasView: CanvasNSView
    ) {
        let onRestart: (() -> Void)?
        if restartable {
            let tileId = tile.id
            onRestart = { [weak self] in self?.restartTile(tileId: tileId) }
        } else {
            onRestart = nil
        }
        let view = TerminalRestartTileNSView(tile: tile, statusText: statusText, onRestart: onRestart)
        canvasView.install(tileView: view, for: tile)
    }

    private func wireRuntimeExitHandler(_ runtime: GhosttyTerminalRuntime) {
        runtime.onRuntimeExited = { [weak self] runtimeId, exitCode in
            self?.handleRuntimeExited(runtimeId: runtimeId, exitCode: exitCode)
        }
    }

    private func wireContentProcessTerminationHandler(_ runtime: WKWebViewBrowserRuntime) {
        runtime.onContentProcessTerminated = { [weak self] runtimeId in
            self?.handleBrowserContentProcessTerminated(runtimeId: runtimeId)
        }
    }

    /// A target=_blank popup creates its runtime inside TileSpawner and hands
    /// the WKWebView straight back to WebKit — no caller ever sees the runtime,
    /// so without this seam it skipped `browserRuntimes`, the live-browser
    /// registry, budget enforcement, and every teardown path. Same registration
    /// the hydration seam (`onBrowserRuntimeHydrated`) performs.
    private func wireBrowserRuntimeRegistration(on spawner: TileSpawner) {
        spawner.browserRuntimeSpawnedHandler = { [weak self] runtime in
            guard let self else { return }
            self.wireContentProcessTerminationHandler(runtime)
            self.browserRuntimes.append(runtime)
            self.workspaceRuntime?.registerLiveBrowser(tileId: runtime.tileId)
            self.workspaceRuntime?.enforceBrowserRuntimeBudget()
        }
    }

    private func handleBrowserContentProcessTerminated(runtimeId: BrowserRuntimeID) {
        guard let runtime = browserRuntimes.first(where: { $0.id == runtimeId }) else { return }
        let tileId = runtime.tileId

        tileSpawner?.writeBrowserTileSnapshot(for: runtime)

        browserRuntimes.removeAll { $0.id == runtimeId }
        runtime.terminate(policy: .force)

        guard let canvasView,
              let tile = canvasView.tileRecord(for: tileId)
        else {
            fputs("Browser content-process terminated: tile \(tileId) not found in canvas\n", stderr)
            return
        }

        installBrowserRestartPlaceholder(
            for: tile,
            statusText: "Web content process terminated",
            restartable: true,
            in: canvasView
        )
        focusBroker.enterScope(.tile(tileId), reason: .runtimeExited)
    }

    private func handleRuntimeExited(runtimeId: TerminalSessionID, exitCode: Int32?) {
        // Late .exited after windowWillClose teardown -- already handled there.
        guard let runtime = runtimes.first(where: { $0.id == runtimeId }) else { return }
        let tileId = runtime.tileId

        if let projectStore, var descriptor = try? projectStore.loadSession(id: runtimeId) {
            descriptor.lastExit = TerminalLastExit(exitCode: exitCode, signal: nil, at: Date())
            try? projectStore.saveSession(descriptor)
        }

        runtimes.removeAll { $0.id == runtimeId }
        runtime.terminate(policy: .force)
        // C2 (round-3 continuation): an exited runtime must tear down its
        // observation/watcher BEFORE the restart placeholder goes in, same as
        // the deliberate-delete path below — otherwise a stale observation
        // survives the exit and the observer keeps issuing writes against a
        // tile that no longer has a live runtime.
        workspaceRuntime?.activeController?.sessionObserverTileDidClose(tileId: tileId)

        guard let canvasView,
              let tile = canvasView.tileRecord(for: tileId)
        else { return }

        let statusText: String
        if let exitCode {
            statusText = "Shell exited (code \(exitCode))"
        } else {
            statusText = "Shell exited"
        }
        installRestartPlaceholder(for: tile, statusText: statusText, restartable: true, in: canvasView)
        focusBroker.enterScope(.tile(tileId), reason: .runtimeExited)
    }

    private func recoverFocusAfterTileRemoval(deletedTileId: UUID, in canvasView: CanvasNSView) {
        let fallbackTiles = canvasView.allWorkspaceTiles()
            .filter { $0.id != deletedTileId }
            .sorted { lhs, rhs in
                if lhs.zPosition == rhs.zPosition {
                    return lhs.id.uuidString < rhs.id.uuidString
                }
                return lhs.zPosition > rhs.zPosition
            }
            .map { FocusSurfaceID.tile($0.id) }
        _ = focusBroker.recoverFocus(candidates: fallbackTiles, reason: .tileClosed)
    }

    /// Tile-delete orchestrator. Per-kind cleanup mirrors the
    /// `handleRuntimeExited` shape but with kill+forget semantics: descriptors
    /// and snapshots are purged so the boot loop won't resurrect the tile next
    /// launch. Confirmation policy is read from `DeleteConfirmPolicy.current`
    /// which honors the `continuum.deleteConfirmPolicy` UserDefaults key.
    enum ReviewFlybackError: Error, CustomStringConvertible {
        case missingProjectStore
        case missingReviewTile
        case reviewTileHasNoReviewId
        case missingTargetAgentSession
        case missingLiveAgentEndpoint

        var description: String {
            switch self {
            case .missingProjectStore: return "missing project store"
            case .missingReviewTile: return "missing diff review tile"
            case .reviewTileHasNoReviewId: return "diff review tile has no review id"
            case .missingTargetAgentSession: return "target tile has no persisted agent session"
            case .missingLiveAgentEndpoint: return "target agent tile is not live"
            }
        }
    }

    private func sendReviewCommentsFromMenu(reviewTileId: UUID) {
        do {
            guard let target = try firstEligibleAgentTileIdForReviewFlyback() else {
                NSSound.beep()
                return
            }
            let sourceDescription = canvasView?.canvasState.tiles.first(where: { $0.id == reviewTileId }).map { DiffReviewSource(metadata: $0.metadata).displayName } ?? "working tree vs HEAD"
            _ = try sendReviewCommentsToAgent(reviewTileId: reviewTileId, targetAgentTileId: target, diffSourceDescription: sourceDescription)
        } catch {
            fputs("sendReviewCommentsFromMenu failed: \(error)\n", stderr)
            NSSound.beep()
        }
    }

    private func firstEligibleAgentTileIdForReviewFlyback() throws -> UUID? {
        guard let projectStore else { throw ReviewFlybackError.missingProjectStore }
        let sessions = try projectStore.listSessions()
        return sessions.first { session in
            guard var descriptor = session.agentDescriptor else { return false }
            if let liveStatus = canvasView?.agentStatus(for: session.tileId) { descriptor.status = liveStatus }
            guard AgentTileInput.canSend(to: descriptor.status) else { return false }
            return runtimes.contains(where: { $0.tileId == session.tileId })
        }?.tileId
    }

    @discardableResult
    func sendReviewCommentsToAgent(reviewTileId: UUID, targetAgentTileId: UUID, diffSourceDescription: String) throws -> ReviewFlybackPrompt {
        guard let projectStore else { throw ReviewFlybackError.missingProjectStore }
        guard let reviewTile = canvasView?.canvasState.tiles.first(where: { $0.id == reviewTileId && $0.kind == .diffReview }) else { throw ReviewFlybackError.missingReviewTile }
        guard let reviewId = reviewTile.metadata.reviewId else { throw ReviewFlybackError.reviewTileHasNoReviewId }
        guard let session = try projectStore.listSessions().first(where: { $0.tileId == targetAgentTileId && $0.agentDescriptor != nil }) else { throw ReviewFlybackError.missingTargetAgentSession }
        guard let runtime = runtimes.first(where: { $0.tileId == targetAgentTileId }) else { throw ReviewFlybackError.missingLiveAgentEndpoint }

        var descriptor = session.agentDescriptor
        if let liveStatus = canvasView?.agentStatus(for: targetAgentTileId) { descriptor?.status = liveStatus }
        let state = try projectStore.loadReviewCommentState(reviewId: reviewId)
        let prompt = ReviewFlybackPromptComposer.compose(state: state, diffSourceDescription: diffSourceDescription)
        try AgentTileInput.send(prompt: prompt.text, descriptor: descriptor, to: runtime)
        return prompt
    }

    func deleteTile(id: UUID) {
        guard let canvasView else { return }
        // `projectTiles()`, not the flat collection: once the active project's tiles
        // live in a ZoneLayer, looking a tile up here found nothing and deleteTile
        // returned silently — closing an agent tile did nothing at all, and the
        // agent it belonged to was never archived out of the inbox.
        guard let tile = canvasView.projectTiles().first(where: { $0.id == id })
            ?? canvasView.canvasState.tiles.first(where: { $0.id == id }) else { return }

        fputs("deleteTile entry kind=\(tile.kind.rawValue) id=\(id.uuidString)\n", stderr)
        var deleteOutcome = "deleted"
        defer {
            fputs("deleteTile exit kind=\(tile.kind.rawValue) id=\(id.uuidString) outcome=\(deleteOutcome)\n", stderr)
        }

        if tile.kind == .file,
           let fileView = canvasView.tileView(for: id) as? FileTileNSView,
           fileView.isDirty {
            let alert = NSAlert()
            alert.messageText = "Save changes before closing?"
            alert.informativeText = "This Markdown file has an unsaved draft."
            alert.alertStyle = .warning
            alert.addButton(withTitle: "Save")
            alert.addButton(withTitle: "Discard")
            alert.addButton(withTitle: "Cancel")
            switch alert.runModal() {
            case .alertFirstButtonReturn:
                guard fileView.saveInteractively() else {
                    deleteOutcome = "kept-open-save-failed-or-cancelled"
                    return
                }
            case .alertSecondButtonReturn:
                fileView.discardUnsavedChanges()
            default:
                deleteOutcome = "cancelled-dirty-file"
                return
            }
        }

        let policy = DeleteConfirmPolicy.current
        if policy.requiresConfirmation(for: tile.kind) {
            let configuration = policy.alertConfiguration(for: tile.kind)
            let alert = NSAlert()
            alert.messageText = configuration.message
            alert.informativeText = configuration.informative
            alert.alertStyle = .warning
            let cancel = alert.addButton(withTitle: configuration.buttonTitles[0])
            let delete = alert.addButton(withTitle: configuration.buttonTitles[1])
            delete.hasDestructiveAction = true
            delete.keyEquivalent = configuration.destructiveKeyEquivalent
            cancel.keyEquivalent = configuration.cancelKeyEquivalent
            if alert.runModal() != .alertSecondButtonReturn {
                deleteOutcome = "skipped"
                return
            }
        }

        switch tile.kind {
        case .terminal:
            // Deliberate user tile deletion is the only path that may issue a tmux kill.
            // Project release flows through ZoneRuntimeRegistry.release -> close(), which
            // has no tmux surface and must remain detach-only.
            killTmuxWindowForDeletedTerminalTile(tileId: id)
            if let runtime = runtimes.first(where: { $0.tileId == id }) {
                if let projectStore, var descriptor = try? projectStore.loadSession(id: runtime.id) {
                    descriptor.lastExit = TerminalLastExit(exitCode: nil, signal: nil, at: Date())
                    try? projectStore.saveSession(descriptor)
                }
                runtimes.removeAll { $0.id == runtime.id }
                runtime.terminate(policy: .force)
                try? projectStore?.deleteSession(id: runtime.id)
            }
            // C2 (round-3 continuation): unconditional, not just the
            // live-runtime branch above — a tile deleted while it has no live
            // `GhosttyTerminalRuntime` entry (e.g. a restart placeholder after
            // `handleRuntimeExited`) must still drop its observation/watcher.
            // `tileDidClose` is idempotent, so calling it again in the
            // live-runtime case above is harmless.
            workspaceRuntime?.activeController?.sessionObserverTileDidClose(tileId: id)
        case .browser:
            if let runtime = browserRuntimes.first(where: { $0.tileId == id }) {
                browserRuntimes.removeAll { $0.id == runtime.id }
                runtime.terminate(policy: .force)
            }
            _ = tileSpawner?.deleteBrowserInspectors(inspecting: id, in: canvasView)
            // Drop the persisted browser tile snapshot so the boot loop won't
            // try to resurrect this tile from BrowserState on next launch.
            if let projectStore,
               var browserState = try? projectStore.tryLoadBrowserState() {
                browserState.tiles.removeAll { $0.tileId == id }
                browserState.inspectorStates.removeAll { $0.inspectedBrowserTileId == id }
                try? projectStore.saveBrowserState(browserState)
            }
        case .browserInspector:
            tileSpawner?.deleteBrowserInspector(tileId: id)
        case .note:
            if let noteId = tile.metadata.noteId {
                noteViews.removeValue(forKey: noteId)
                if let projectStore {
                    if var noteState = try? projectStore.tryLoadNoteState() {
                        noteState.tiles.removeAll { $0.id == noteId || $0.tileId == id }
                        try? projectStore.saveNoteState(noteState)
                    }
                    try? projectStore.deleteNoteBody(id: noteId)
                }
            }
        case .file:
            // No on-disk descriptor to purge — file tiles only carry metadata.
            try? workspaceRuntime?.removeDocumentLinks(tileId: id)
        case .fileTree:
            fileTreeViews.removeValue(forKey: id)
            if let projectStore,
               var fileTreeState = try? projectStore.tryLoadFileTreeState() {
                fileTreeState.tiles.removeAll { $0.tileId == id }
                try? projectStore.saveFileTreeState(fileTreeState)
            }
        case .ticketQueue:
            ticketQueueViews.removeValue(forKey: id)
        case .conductorQueue:
            break
        case .diffReview:
            if let reviewId = tile.metadata.reviewId,
               let projectStore {
                try? projectStore.deleteReviewCommentState(reviewId: reviewId)
            }
        case .runArtifacts:
            // Run artifact viewer tiles are read-only; retain the run directory.
            break
        case .managedAgent:
            // CLOSING A TILE IS CLOSING A WINDOW, NOT ENDING THE WORK (P2A.5, locked
            // decision). Four things happen here and a fifth deliberately does not:
            // the tile-keyed `ManagedAgentSessionRecord` goes (view state, the same
            // class as canvas persistence dropping the tile — its `tileId` is a
            // `let`, so it cannot outlive the tile it is keyed on); the agent's VIEW
            // BINDING is cleared, so it is listed as running-and-unattached rather
            // than claiming a tile that no longer exists; the agent is PARKED IN
            // HISTORY unless it is busy; the tile cancels its own subscription
            // (P2A.4). What is NOT called is `agentSupervisor.stop` — the runner
            // keeps running and `AgentRecord` stays in `AgentStore`.
            // Stopping is a separate deliberate action (Phase 3's row context menu).
            // `--agent-supervisor-check` scans this branch to hold that.
            //
            // THE PARK IS WHY THE SIDEBAR STOPS FILLING UP (.plans/05-close-to-history.md).
            // Before it, a closed tile left its record in the live list with no tile
            // and no runner — unobservable, so the row froze at "Unconfirmed" and
            // stayed there forever. `close` refuses a busy agent, so a tile closed
            // mid-turn still leaves its row where you can see the work finish.
            try? workspaceRuntime?.activeController?.managedSessionStore.delete(tileId: id)
            if let agentId = agentSupervisor.agent(forTile: id) {
                agentSupervisor.close(agentID: agentId)
                agentSupervisor.detachView(agentID: agentId)
            }
            (canvasView.tileView(for: id) as? ManagedAgentTileNSView)?.detach()
        }

        canvasView.removeTile(id: id)
        recoverFocusAfterTileRemoval(deletedTileId: id, in: canvasView)
        flushCanvasSave()
        refreshAgentSurfaces()
    }

    private func killTmuxWindowForDeletedTerminalTile(tileId: UUID) {
        // LIFECYCLE INVARIANT: this is the only site that may issue a tmux kill
        // for terminal-tile removal. It is reached from deleteTile(_:) on a
        // .terminal tile, a deliberate user action. Project release must never call
        // this function; adding a tmux path to ZoneRuntimeRegistry.release or
        // ZoneRuntimeController.close violates D16.
        guard TmuxPersistenceConfig.enabled(defaults: tmuxDefaults),
              let tmuxPath = tmuxPathResolver(tmuxDefaults) else {
            return
        }
        let reach = workspaceRuntime?.activeController?.project.remoteEnvironment?.reach ?? .localhost
        let control = makeTmuxControl(tmuxPath: tmuxPath, reach: reach)

        let target = managedSessionRecord(forTileId: tileId)?.tmuxWindowTarget()
        if let target, TmuxSession.isValidPaneId(target) {
            if let error = Self.runTmuxControlOperationSync({ try await control.killWindow(target: target) }) {
                fputs("tmux kill-window failed for tile=\(tileId.uuidString) target=\(target): \(error)\n", stderr)
            }
            let viewSessionName = TmuxSession.viewSessionName(tileId: tileId)
            if let error = Self.runTmuxControlOperationSync({ try await control.killSession(name: viewSessionName) }) {
                fputs("tmux kill-session (view) failed for tile=\(tileId.uuidString): \(error)\n", stderr)
            }
            return
        }

        let sessionName = TmuxSession.sessionName(tileId: tileId)
        if let error = Self.runTmuxControlOperationSync({ try await control.killSession(name: sessionName) }) {
            fputs("tmux kill-session fallback failed for tile=\(tileId.uuidString): \(error)\n", stderr)
        }
    }

    private func terminalSessionDescriptor(forTileId tileId: UUID) -> TerminalSessionDescriptor? {
        guard let projectStore else { return nil }
        if let runtime = runtimes.first(where: { $0.tileId == tileId }),
           let descriptor = try? projectStore.loadSession(id: runtime.id) {
            return descriptor
        }
        return try? projectStore.listSessions().first(where: { $0.tileId == tileId })
    }

    private func managedSessionRecord(forTileId tileId: UUID) -> ManagedAgentSessionRecord? {
        try? workspaceRuntime?.activeController?.managedSessionStore.load(tileId: tileId)
    }

    /// What `currentManagedAgentActivities()` found, plus WHICH of those agents
    /// something live reported (P2B.8).
    ///
    /// An agent is OBSERVED here under exactly one rule: its status below came from
    /// a live source (a rendering `ManagedAgentTileNSView`, or a running supervised
    /// agent) rather than from a file. Held together with the activities so a caller
    /// cannot pair a fresh listing with a stale idea of who is being watched — the
    /// same reason `AgentActivitySurface` holds `agentIdentities`.
    struct ManagedAgentActivityScan {
        var activities: [DesktopManagedAgentActivity] = []
        var observedAgentIds: Set<UUID> = []
    }

    private func currentManagedAgentActivities() throws -> ManagedAgentActivityScan {
        // P2B.2: an inbox lists agents from EVERY project, not just the active
        // one. Two sources, in precedence order:
        //   1. the active project's live store — it is the writer, so it can
        //      never be staler than the files on disk;
        //   2. `CrossProjectManagedSessionWalk` over every registry project
        //      root, which reads the persisted records directly (no
        //      `ZoneRuntimeController` is opened just to list agents).
        // Deduped by tile id, active-first, because the walk covers the active
        // project's root too.
        //
        // The old "tile is on the active canvas" filter is GONE, not relaxed: a
        // record in another project has no tile here by definition, so the
        // filter was exactly what made those agents invisible. What it was
        // otherwise carrying, stated exactly: closing a managed tile deletes
        // that tile's LEGACY RECORD (see `deleteTile`), so for the active
        // project the filter and the files agreed. It did NOT bound the
        // supervised `AgentRecord`, which deliberately outlives its tile — but
        // an `AgentRecord` never reached this function to begin with. Feeding
        // those is P2B.4's one-snapshot wiring, not this walk.
        // The status fallback below already handles a record with no tile view.
        var records: [ManagedAgentSessionRecord] = []
        var seenTiles: Set<UUID> = []
        // P3.2: the ROOTS FIRST, because listing them is what sweeps them — and both
        // reads now THROW instead of swallowing. `(try? …) ?? []` here was the whole
        // defect in its quiet form: an unreadable or unswept listing was reported as
        // "you have no agents". The active store is read second and deduped
        // active-first, so its precedence is unchanged, and its own root is
        // guaranteed swept because `recordProjectInRegistry` put the booted project
        // in this registry.
        let roots = ReconciledManagedSessionSource.roots(
            in: (try? registryStore?.loadOrEmpty()) ?? Registry.empty()
        )
        let discovered = try reconciledManagedSessionSource.records(roots: roots, now: Date())
        if let activeStore = workspaceRuntime?.activeController?.managedSessionStore {
            for record in try activeStore.reconciledRecords(reconciledManagedSessionSource.proof())
            where seenTiles.insert(record.tileId).inserted {
                records.append(record)
            }
        }
        for found in discovered where seenTiles.insert(found.record.tileId).inserted {
            records.append(found.record)
        }

        // P2B.8: every agent whose status below comes from something LIVE. A record
        // read off disk is not in here, and that is the normal case for every
        // project whose `ZoneRuntimeController` has been released.
        var observedAgentIds: Set<UUID> = []

        var activities = records.map { record in
            let liveStatus = (canvasView?.tileView(for: record.tileId) as? ManagedAgentTileNSView)?.currentAgentStatus
            // P2A.8: the aggregate key is the agent's. A managed session with no
            // supervised agent (one restored from a store the supervisor has not
            // claimed) falls back to its tile id, which is the identity every event
            // written before this migration used.
            let supervisedId = agentSupervisor.agent(forTile: record.tileId)
            let agentId = supervisedId?.rawValue ?? record.tileId
            // P4.14: TURN state, not process liveness. `record.status` is written
            // once at spawn and never transitions, so reading `working` off it left
            // every row stuck on "working" for the life of the session.
            let hasLiveRunner = supervisedId.map { agentSupervisor.isRunning($0) } ?? false
            let status = Self.agentRowStatus(liveStatus: liveStatus, hasLiveRunner: hasLiveRunner, persisted: record.status)
            // P2B.8's rule, unchanged and now applied consistently: observed means
            // the status above came from something LIVE. A runner in flight is such
            // a source (it is what produces `working` here), so it counts exactly as
            // it already does for a supervised record in the loop below.
            if liveStatus != nil || hasLiveRunner { observedAgentIds.insert(agentId) }
            return DesktopManagedAgentActivity(
                agentId: agentId,
                tileId: record.tileId,
                agentKind: record.agentKind,
                status: status,
                updatedAt: record.lastSeenAt,
                recentEvents: managedAgentActivityByAgent[agentId] ?? []
            )
        }

        // P2B.4: and the agents the SUPERVISOR owns (P2A.2/P2A.6) — headless ones,
        // and ones that outlived the tile they were spawned in. They have no legacy
        // `ManagedAgentSessionRecord` and so reached no consumer at all before this:
        // the loop above lists files on disk, and `AgentStore` is a different store.
        // Appended, never overriding, so a supervised agent that ALSO has a legacy
        // record keeps the status the loop above reads off its live tile view.
        //
        // Projected onto `DesktopManagedAgentActivity` rather than passed as an
        // `AgentRecord`: this value is one step from the sync boundary and a record
        // is host-bound (`cwd`, `worktreeBranch`) — I5. The kind label is what the
        // summary is built from, exactly as for a legacy record.
        var seenAgentIds = Set(activities.map(\.agentId))
        for record in agentSupervisor.records.values.sorted(by: AgentStore.isOrderedBefore)
        where seenAgentIds.insert(record.id.rawValue).inserted {
            // A tiled agent's live view is the freshest status it has. Headless, the
            // supervisor still knows whether a prompt is in flight; without that a
            // running headless agent would read `idle` for its whole turn.
            //
            // HONEST LIMIT, from the cross-review: `recordManagedActivity` is wired
            // from the TILE's ingest, so a headless agent records no drafts, and
            // `isRunning` cannot tell "working" from "waiting on an approval". A hand
            // raised while headless is therefore not counted until a tile ingests it.
            // Closing that needs an app-owned subscription to
            // `agentSupervisor.events(for:)`, which is a change to the agent event
            // plumbing this packet's `## Files` does not name and which P4.1's
            // lifecycle state and `P5.10-agent-settled-signal` both land on.
            let liveStatus = (record.tileId.flatMap { canvasView?.tileView(for: $0) } as? ManagedAgentTileNSView)?.currentAgentStatus
            let isRunning = agentSupervisor.isRunning(record.id)
            // P4.14: the same one derivation as the legacy branch above. A supervised
            // record carries no `ManagedSessionStatus` at all, so there is nothing to
            // fall back to and `persisted` is nil — which the derivation reads as
            // "alive, not mid-turn", i.e. idle. That was already this branch's
            // behaviour; it now shares the function so the two cannot drift.
            let status = Self.agentRowStatus(liveStatus: liveStatus, hasLiveRunner: isRunning, persisted: nil)
            // P2B.8: a RESTORED record the supervisor merely holds is not observed —
            // `restore()` (P2A.7) adopts records without a runner, so the supervisor
            // knows the agent exists and hears nothing from it. Observed means a live
            // view or a runner actually in flight, which is exactly the pair the
            // status above is derived from.
            if liveStatus != nil || isRunning { observedAgentIds.insert(record.id.rawValue) }
            activities.append(DesktopManagedAgentActivity(
                agentId: record.id.rawValue,
                tileId: record.tileId,
                agentKind: .managed,
                status: status,
                updatedAt: record.lastActivityAt,
                recentEvents: managedAgentActivityByAgent[record.id.rawValue] ?? []
            ))
        }
        return ManagedAgentActivityScan(activities: activities, observedAgentIds: observedAgentIds)
    }

    // Ticket: docs/38-tickets/90-agent-ux/P4.14-row-status-is-turn-state.md
    //
    /// THE row-status derivation, for every agent the scan above lists.
    ///
    /// It exists because the row was showing PROCESS LIVENESS as TURN ACTIVITY.
    /// `ManagedSessionStatus` has no "alive and idle between turns" case — the state
    /// an agent spends almost all its life in — and nothing in the app ever writes
    /// the field after creation, so `.running → .working` meant a row went to
    /// "working" on spawn and stayed there until the record was deleted. The tile
    /// showed the truth (it consumes the live event stream); the sidebar showed a
    /// field written once, hours ago.
    ///
    /// The three inputs, in precedence order, and what each can honestly witness:
    ///
    ///  1. `liveStatus` — a rendering `ManagedAgentTileNSView`'s own derivation from
    ///     the event stream. The freshest thing there is, and the reason the tile and
    ///     the row now agree across a whole turn.
    ///  2. `hasLiveRunner` — `AgentSupervisor` holds `runners[id]` for exactly the
    ///     duration of a turn and refuses a second prompt while one is live. That is
    ///     the authoritative "a turn is in flight", and it is the ONLY source of
    ///     `working` here.
    ///  3. `persisted` — contributes only the states it can actually witness:
    ///     `.starting` is the genuine pre-first-event state, and `.error` is a fact
    ///     that survives a read from disk. `.running` contributes NOTHING: with no
    ///     live view and no runner we know the session was created, not that it is
    ///     busy, so it reads `idle` — alive, ready for a prompt.
    ///
    /// `.stopped` reads `stale`, not `idle`, deliberately: a dead session must stay
    /// distinguishable from a live one waiting on you. Both are muted and both fold
    /// to `InboxState.ready`; they differ by glyph and label (`◌ Stale` vs `○ Idle`),
    /// which is exactly the distinction `StatusChipPresenter` documents them as
    /// carrying. Writing `.stopped` for a finished turn would still be wrong — that
    /// spells "the session ended", which is the lie this ticket exists to avoid.
    ///
    /// No freshness window: we own these events. A row that self-corrects after N
    /// seconds is still wrong for N seconds. `PiAgentStateReader.freshWorkingWindow`
    /// is for a FOREIGN process nobody notifies us about and is untouched here.
    static func agentRowStatus(
        liveStatus: AgentStatus?,
        hasLiveRunner: Bool,
        persisted: ManagedSessionStatus?
    ) -> AgentStatus {
        if let liveStatus { return liveStatus }
        if hasLiveRunner { return .working }
        switch persisted {
        case .starting: return .configuring
        case .error: return .needsAttention
        // P3.1: system-cancel and user-stop are one status at this layer —
        // terminal, not live — and stay DISTINCT WORDS at the row, where
        // `endedReason` carries which one it was (P3.4 renders it).
        case .stopped, .cancelled: return .stale
        case .running, nil: return .idle
        }
    }

    // MARK: - One agent-status derivation (P2B.4)

    /// The one derivation's output: the inventory, plus which of its entries the
    /// DESKTOP treats as an agent. Held together in one value so a consumer cannot
    /// read a fresh snapshot against a stale membership set.
    ///
    /// THE INVARIANT, stated once so the two shapes below are not mistaken for two
    /// derivations: `rebuildAgentActivitySnapshot()` is a PURE recomputation from
    /// disk + canvas + the observer map, and it is the only thing that writes this
    /// value. A READER (the nav cycle, a sidebar reload, the companion closure)
    /// recomputes and then reads. A PUSHER (`refreshAgentSurfaces`) recomputes once
    /// and hands that same value to all four surfaces. Either way no surface can be
    /// looking at a status another surface would compute differently, which is the
    /// property this ticket exists to establish.
    struct AgentActivitySurface {
        var snapshot: ActivityLogSnapshot = .empty
        /// Agent identities the desktop shows a status for: every managed/supervised
        /// agent, plus terminal sessions that actually carry an `AgentDescriptor`.
        var agentIdentities: Set<UUID> = []
        // Ticket: docs/38-tickets/90-agent-ux/P3.16-inbox-lists-agents-only.md
        /// THE INBOX'S ROW SOURCE, and the ONE place that policy lives: the agents
        /// backed by an `AgentRecord` — every agent the SUPERVISOR owns, headless or
        /// tiled, orchestrator children included. That is the packet's criterion word
        /// for word, and it is narrower than "everything that is not a terminal" in
        /// two ways:
        ///
        ///   * a `claude` the owner started inside a terminal TILE carries an
        ///     `AgentDescriptor`, so it is an agent for the canvas badge, the outline
        ///     and the phone — but the inbox cannot settle, snooze, stop or archive a
        ///     process inside someone's shell, so it does not list it;
        ///   * a legacy `ManagedAgentSessionRecord` that no `AgentRecord` claims (a
        ///     pre-P2A tile, keyed by its tile id) is not listed either, for exactly
        ///     the same reason: every verb the list offers goes through
        ///     `AgentSupervisor`, which is keyed by `AgentID`. (Raised in cross-review,
        ///     which was right: admitting those would have contradicted the packet.)
        ///
        /// Derived here, beside `agentIdentities`, for the same reason that one is
        /// carried rather than re-derived per consumer: the two cannot then drift, and
        /// reversing this policy is one call site (`buildAgentInboxRows`) rather than
        /// an archaeology exercise. NARROWING `agentIdentities` instead is the wrong
        /// layer and breaks P2B.5 — ⌥-cycling and the sidebar outline read it.
        var managedAgentIdentities: Set<UUID> = []
        // Ticket: docs/38-tickets/90-agent-ux/P3.16-inbox-lists-agents-only.md
        /// Agents running inside terminal tiles — the descriptors carrying an
        /// `AgentDescriptor`, which is `agentIdentities` minus the managed scan.
        ///
        /// Carried rather than recomputed as a set difference, because the two
        /// exclusions above are NOT the same fact: only this one is "your agent is
        /// running, elsewhere", and it is the only one the empty state can honestly
        /// explain. A legacy managed session in neither set is a STATED LIMIT — the
        /// list would say "No agents yet" in front of one — and it is a pre-P2A
        /// artifact rather than anything Continuum still creates.
        var terminalHostedAgentIdentities: Set<UUID> = []
        /// P2B.7: which agents moved since the surfaces were last PUSHED — whatever
        /// advanced the snapshot in between, an incremental event or a reader's
        /// rebuild. Deliberately "since the surfaces last saw it" and not "the last
        /// event": a rebuild that a reader (`currentAgentTileIds`, the companion
        /// closure) triggered has found real changes the list has not rendered yet,
        /// and they must not be dropped on the floor. A reader rebuild that finds
        /// NOTHING new reports nothing, which is witnessed in
        /// `--agent-incremental-refresh-check`.
        ///
        /// Published by `pushAgentSurfaces` for the list view P3.6 builds, which
        /// diffs rows instead of reloading them. `WorkspaceSidebarView` still reloads
        /// whole — rewriting it is Phase 3's ticket, not this one.
        var lastChange: AgentsBoardChangeSet = .empty
        /// P2B.8: the agents in `snapshot` that nothing live reported at rebuild time.
        /// Their status is the last one anybody persisted, which is the CORRECT thing
        /// to show for an agent in a workspace whose `ZoneRuntimeController` has been
        /// released — with the fact that nobody has confirmed it attached, so the UI
        /// can say so. No time threshold is applied; see `AgentObservation`.
        ///
        /// NOT `AgentStatus.stale`, which is a derived state of the AGENT (see
        /// `AgentObservation`). Carried alongside the snapshot, like
        /// `agentIdentities`, rather than pushed into `AgentActivity`: that value
        /// crosses to the phone, and "the desktop has no observer for this" is a fact
        /// about this host. Phase 3 renders it; here it is only carried.
        var unobservedAgentIds: Set<UUID> = []
        /// P3.2: whether the value above was built from a RECONCILED listing.
        ///
        /// `false` means "we do not know yet", which is NOT "there are no agents".
        /// On a refusal the surface keeps its last good snapshot, the inbox push is
        /// skipped and the phone publish is skipped — never replaced with an empty
        /// one. Default false because a default-constructed surface has read nothing
        /// yet, which is what makes the inbox start empty and fill only after
        /// readiness. MUST STAY LAST: the memberwise initializer at
        /// `rebuildAgentActivitySnapshot` passes it last.
        var isReconciled: Bool = false
    }

    /// The replica the desktop stamps its own inventory with. Was a literal inside
    /// the companion `activitySnapshot` closure; hoisted so the snapshot the desktop
    /// holds IS the one that gets published, byte for byte, rather than a second one
    /// built next to it.
    private static let agentActivityReplicaId = UUID(uuidString: "75000000-0000-4000-8000-00000000D35A")!

    /// Rebuilds `agentActivity` from `AgentInventory` (P2B.1) — the one fold over
    /// terminal sessions and agents — and nothing else. Every consumer reads the
    /// result; none of them re-derives a status.
    ///
    /// Inputs, in override order (last wins), which is exactly the order the four
    /// old derivations used between them:
    ///   1. each project's persisted `AgentDescriptor.status`;
    ///   2. the live canvas tile view, for a tile that is rendering;
    ///   3. `observedAgentStatuses`, the runtime observer's map.
    private func rebuildAgentActivitySnapshot(now: Date = Date()) {
        let registry = (try? registryStore?.loadOrEmpty()) ?? Registry.empty()
        let projectCanvases = workspaceSidebarProjectCanvasSnapshots(registry: registry)
        let descriptors = currentTerminalSessionDescriptors(registry: registry, projectCanvases: projectCanvases)

        var liveStatuses: [UUID: AgentStatus] = [:]
        for descriptor in descriptors {
            if let live = canvasView?.agentStatus(for: descriptor.tileId) {
                liveStatuses[descriptor.tileId] = live
            }
        }
        for (tileId, status) in observedAgentStatuses {
            liveStatuses[tileId] = status
        }

        // P3.2: a refusal is not an empty inbox. Keep the last good value, flag it,
        // say so once, and come back — never publish `AgentActivitySurface()`, which
        // would tell a human (and the phone) that every agent disappeared.
        let managedScan: ManagedAgentActivityScan
        do {
            managedScan = try currentManagedAgentActivities()
        } catch {
            agentActivity.isReconciled = false
            fputs("agent activity: keeping the previous snapshot — \(error)\n", stderr)
            scheduleAgentActivityRebuildRetry()
            return
        }
        let managedAgents = managedScan.activities
        // A terminal session with no `AgentDescriptor` is a plain shell. It stays in
        // the snapshot — the phone has always listed one, as `Shell idle` — but it is
        // NOT an agent on the canvas or in the sidebar, where every shell tile would
        // otherwise start rolling up as "1 unknown". Carried alongside the snapshot
        // rather than re-derived per consumer, so the two cannot drift.
        var agentIdentities = Set(managedAgents.map(\.agentId))
        // P3.16: the same fold, two extra values — the INBOX's row source (the agents
        // an `AgentRecord` backs, which is a subset of the managed half above: a legacy
        // managed session the supervisor never claimed is keyed by its tile id and is
        // not one) and the terminal-hosted set its empty state explains. See
        // `AgentActivitySurface.managedAgentIdentities`.
        let managedAgentIdentities = Set(agentSupervisor.records.keys.map(\.rawValue))
        var terminalHostedAgentIdentities: Set<UUID> = []
        for descriptor in descriptors where descriptor.agentDescriptor != nil {
            agentIdentities.insert(descriptor.tileId)
            terminalHostedAgentIdentities.insert(descriptor.tileId)
        }

        let snapshot = DegradedDesktopActivitySnapshotSource.snapshot(
            descriptors: descriptors,
            liveStatuses: liveStatuses,
            managedAgents: managedAgents,
            replicaId: Self.agentActivityReplicaId,
            now: now
        )

        // P2B.8: who did anything LIVE report in this rebuild. For a terminal agent
        // that is the runtime observer's map ALONE (its key is its tile id) — NOT
        // `liveStatuses`, even though that is what overlays its status.
        //
        // The difference is the whole point: `canvasView?.agentStatus(for:)` reads the
        // BADGE, and the badge is what `applyAgentStatusesToCanvas` wrote from the
        // previous snapshot. Counting it as an observation would make the app confirm
        // its own echo — an agent would look observed forever after one sweep, which
        // since P2B.6 made badges sticky is exactly what would happen. A managed
        // agent's `currentAgentStatus` is a different animal: the tile derives it from
        // the agent's own event stream, so the scan above may and does count it.
        //
        // Everything else in the snapshot came off disk, and no controller is started
        // to change that.
        //
        // KNOWN AND DELIBERATE, from the cross-review: `SessionObserver`'s map is
        // SPARSE — `publishStatusesChanged` emits only observations whose
        // `lastWrittenStatus` is set — so a tile the observer is watching but has not
        // yet derived a status for reads as unobserved. That matches what this fact
        // means ("nothing live has told us anything about this agent yet"), and it is
        // the honest reading: its status in the snapshot did come from the file.
        // Distinguishing "an observer exists" from "an observer has reported" would
        // need the observed tile-id set published out of `ZoneRuntimeController`,
        // which is not this packet's file.
        var observedAgentIds = Set(observedAgentStatuses.keys)
        observedAgentIds.formUnion(managedScan.observedAgentIds)

        agentActivity = AgentActivitySurface(
            snapshot: snapshot,
            agentIdentities: agentIdentities,
            managedAgentIdentities: managedAgentIdentities,
            terminalHostedAgentIdentities: terminalHostedAgentIdentities,
            unobservedAgentIds: AgentObservation.unobservedAgentIds(
                in: snapshot,
                observedAgentIds: observedAgentIds
            ),
            isReconciled: true
        )
    }

    /// P3.2's retry. One in flight at a time, and deliberately NOT a loop: the only
    /// way to be unreconciled is to read before boot's arming sweep, so a second
    /// attempt either succeeds or the arming call is missing — which the log line in
    /// `rebuildAgentActivitySnapshot` names, once per rebuild, instead of spinning.
    private func scheduleAgentActivityRebuildRetry() {
        guard !isAgentActivityRebuildRetryScheduled else { return }
        isAgentActivityRebuildRetryScheduled = true
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.25) { [weak self] in
            guard let self else { return }
            self.isAgentActivityRebuildRetryScheduled = false
            self.rebuildAgentActivitySnapshot()
        }
    }

    /// Every terminal session descriptor that a canvas is actually holding a tile
    /// for, from every project. The canvas filter is what the sidebar, the badges
    /// and the dock each applied for themselves: a descriptor whose tile has been
    /// deleted is a leftover file, not an agent. Deduped by tile, the active
    /// project's own store first — it is the writer, so it can never be staler
    /// than the files on disk.
    private func currentTerminalSessionDescriptors(
        registry: Registry,
        projectCanvases: [UUID: CanvasState]
    ) -> [TerminalSessionDescriptor] {
        var terminalTileIds: Set<UUID> = []
        for canvas in projectCanvases.values {
            for tile in canvas.tiles where tile.kind == .terminal {
                terminalTileIds.insert(tile.id)
            }
        }

        var descriptors: [TerminalSessionDescriptor] = []
        var seenTiles: Set<UUID> = []
        func take(_ sessions: [TerminalSessionDescriptor]) {
            for session in sessions.sorted(by: { $0.id.uuidString < $1.id.uuidString })
            where terminalTileIds.contains(session.tileId) && seenTiles.insert(session.tileId).inserted {
                descriptors.append(session)
            }
        }
        take((try? projectStore?.listSessions()) ?? [])
        // Sorted by project identity, not registry order: `AgentInventory` numbers
        // events positionally, so an order that moved with the registry would
        // renumber unrelated agents' events between two publishes (P2B.2's trap).
        for project in registry.projects.sorted(by: { $0.id.uuidString < $1.id.uuidString }) {
            let store = ProjectStore(projectRoot: URL(fileURLWithPath: project.rootPath, isDirectory: true))
            take((try? store.listSessions()) ?? [])
        }
        return descriptors
    }

    /// The snapshot, keyed by the tile that is showing each agent — what the
    /// sidebar tree and the canvas badges both consume. Agents with no tile
    /// (headless) simply have nothing to key on here; they still reach the dock
    /// count and the phone.
    private func agentStatusesByTileId() -> [UUID: AgentStatus] {
        var statuses: [UUID: AgentStatus] = [:]
        for row in AgentsBoardProjection.rows(from: agentActivity.snapshot)
        where agentActivity.agentIdentities.contains(row.agentId) {
            guard let tileId = row.tileId else { continue }
            statuses[tileId] = row.status
        }
        return statuses
    }

    /// Rebuild once, then push that one value to all four surfaces.
    ///
    /// P2B.7: the FULL recomputation — every project's registry, canvas and session
    /// store read from disk. Reserved for a STRUCTURAL change, i.e. one this process
    /// cannot describe as an event on a known agent: a workspace switch, a project
    /// open, a tile added or deleted, an observer sweep, app activation. An agent's
    /// own activity takes the incremental path below instead.
    private func refreshAgentSurfaces(notify: Bool = true) {
        rebuildAgentActivitySnapshot()
        pushAgentSurfaces(notify: notify)
        warmCheckedOutBranchesIfNeeded()
    }

    /// The branch chips' freshness, moved OFF the main thread. The sidebar
    /// rebuild above serves the cache and never spawns git (a 20 s sample of a
    /// real session showed ~0.4 s frozen per app switch in synchronous
    /// `rev-parse` spawns from this path); this reads every agent repo once on a
    /// utility queue and re-renders one time if any chip changed.
    private func warmCheckedOutBranchesIfNeeded() {
        guard !branchWarmInFlight else { return }
        let targets = agentSupervisor.warmCheckedOutBranchTargets()
        guard !targets.isEmpty else { return }
        branchWarmInFlight = true
        Task { [weak self] in
            let read: [(URL, String?)] = await Task.detached(priority: .utility) {
                let manager = WorktreeManager()
                return targets.map { ($0, (try? manager.currentBranch(repo: $0)) ?? nil) }
            }.value
            guard let self else { return }
            var changed = false
            for (repo, branch) in read
            where self.agentSupervisor.storeCheckedOutBranch(branch, repo: repo) {
                changed = true
            }
            self.branchWarmInFlight = false
            if changed { self.reloadWorkspaceSidebar(rebuildAgentActivity: false) }
        }
    }

    private var branchWarmInFlight = false

    /// Push whatever `agentActivity` currently holds at all four surfaces, and
    /// publish the change-set that got it there. Split out of
    /// `refreshAgentSurfaces` by P2B.7 so the agent-event path can reach the
    /// surfaces without the disk read.
    private func pushAgentSurfaces(notify: Bool = true) {
        agentActivity.lastChange = AgentsBoardProjection.changeSet(
            from: agentActivityChangeBase, to: agentActivity.snapshot
        )
        agentActivityChangeBase = agentActivity.snapshot
        applyAgentStatusesToCanvas()
        updateAgentAttentionSurface(notify: notify)
        reloadWorkspaceSidebar(rebuildAgentActivity: false)
    }

    /// P2B.7: an agent's own event folds straight into the snapshot the desktop is
    /// already holding — no registry load, no canvas read, no `listSessions()` per
    /// project. The draft is already on `managedAgentActivityByAgent`, so the next
    /// full rebuild reproduces the same state from disk; this is the same fold,
    /// arriving earlier.
    ///
    /// `agentIdentities` gains the agent because a supervised agent IS an agent on
    /// the desktop by definition (P2A.6) — an agent whose first event arrives before
    /// any structural rebuild has listed it would otherwise be filtered out of every
    /// surface until something unrelated moved.
    private func ingestAgentActivityIncrementally(draft: AgentActivityEventDraft) {
        agentActivity.snapshot = AgentsBoardProjection.appendLocal(
            draft, to: agentActivity.snapshot, replicaId: Self.agentActivityReplicaId
        )
        agentActivity.agentIdentities.insert(draft.agentId)
        // P3.16: and the inbox's row source, for exactly the same reason — every
        // draft comes from `recordManagedActivity(agentId:)`, whose parameter is an
        // `AgentID`, so an agent that speaks here is a supervised one by construction.
        // Without this line the first event from a freshly spawned agent (an
        // orchestrator's child) would reach every surface except the list it is
        // supposed to appear in.
        agentActivity.managedAgentIdentities.insert(draft.agentId)
        // P2B.8: an event FROM the agent is the strongest possible observation of it,
        // so it stops being unobserved here rather than at the next full rebuild —
        // otherwise a headless agent that just spoke would keep a "not heard from"
        // mark until something structural moved.
        agentActivity.unobservedAgentIds.remove(draft.agentId)
    }

    /// Debounced `pushAgentSurfaces`, for the runner event stream: a sidebar reload
    /// plus a canvas sweep per streamed token is the jumpiness this ticket removes.
    /// It pushes; it does NOT rebuild — the snapshot was already advanced
    /// incrementally by the time this fires.
    private func scheduleAgentSurfacePush(debounce: TimeInterval) {
        agentSurfaceRefreshDebounceWorkItem?.cancel()
        let workItem = DispatchWorkItem { [weak self] in
            guard let self else { return }
            self.agentSurfaceRefreshDebounceWorkItem = nil
            self.pushAgentSurfaces()
        }
        agentSurfaceRefreshDebounceWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + debounce, execute: workItem)
    }

    /// `TmuxControl` is async throughout (it may shell out to a real `tmux`
    /// process); this call site is synchronous (a UI deletion callback), so it
    /// blocks on the same subprocess completion the previous raw-`Process`
    /// call already blocked on — no observable behavior change, just routed
    /// through the injectable seam.
    private static func runTmuxControlOperationSync(_ operation: @escaping @Sendable () async throws -> Void) -> Error? {
        final class ErrorBox: @unchecked Sendable { var error: Error? }
        let box = ErrorBox()
        let semaphore = DispatchSemaphore(value: 0)
        Task.detached {
            do {
                try await operation()
            } catch {
                box.error = error
            }
            semaphore.signal()
        }
        semaphore.wait()
        return box.error
    }

    private func restartTile(tileId: UUID) {
        guard let spawner = tileSpawner, let canvasView else { return }
        switch spawner.restartTerminalTile(tileId: tileId) {
        case let .restarted(runtime):
            wireRuntimeExitHandler(runtime)
            runtimes.append(runtime)
        case let .missingCommand(executable):
            if let tile = canvasView.tileRecord(for: tileId) {
                installRestartPlaceholder(
                    for: tile,
                    statusText: "\(executable) not found on $PATH",
                    restartable: true,
                    in: canvasView
                )
            }
            presentMissingCommand(executable: executable, profileId: "")
        case let .notConfigured(profileId):
            presentMissingCommand(executable: profileId, profileId: profileId, kind: .notConfigured)
        case let .unknownProfile(id):
            fputs("Restart: unknown profile '\(id)'\n", stderr)
        case .tileNotFound:
            fputs("Restart: tile \(tileId) no longer exists\n", stderr)
        case let .failure(error):
            fputs("Restart failed: \(error)\n", stderr)
        }
    }

    private func installInitialBrowserInspectorTile(_ tile: Tile, in canvasView: CanvasNSView, via spawner: TileSpawner) {
        spawner.installBrowserInspectorTile(tile, in: canvasView)
    }

    private func installInitialBrowserTile(_ tile: Tile, in canvasView: CanvasNSView, via spawner: TileSpawner) {
        switch spawner.restartBrowserTile(tileId: tile.id) {
        case let .restarted(runtime):
            wireContentProcessTerminationHandler(runtime)
            browserRuntimes.append(runtime)
            workspaceRuntime?.registerLiveBrowser(tileId: runtime.tileId)
            workspaceRuntime?.enforceBrowserRuntimeBudget()
        case let .invalidURL(url):
            installBrowserRestartPlaceholder(
                for: tile,
                statusText: "Invalid URL: \(url)",
                restartable: false,
                in: canvasView
            )
        case .tileNotFound:
            installBrowserRestartPlaceholder(
                for: tile,
                statusText: "Tile not found in canvas state",
                restartable: false,
                in: canvasView
            )
        case let .failure(error):
            fputs("Boot browser install failed: \(error)\n", stderr)
            installBrowserRestartPlaceholder(
                for: tile,
                statusText: "Failed to start browser",
                restartable: true,
                in: canvasView
            )
        }
    }

    private func installBrowserRestartPlaceholder(
        for tile: Tile,
        statusText: String,
        restartable: Bool,
        in canvasView: CanvasNSView
    ) {
        let onRestart: (() -> Void)?
        if restartable {
            let tileId = tile.id
            onRestart = { [weak self] in self?.restartBrowserTile(tileId: tileId) }
        } else {
            onRestart = nil
        }
        let view = BrowserRestartTileNSView(tile: tile, statusText: statusText, onRestart: onRestart)
        canvasView.install(tileView: view, for: tile)
    }

    private func restartBrowserTile(tileId: UUID) {
        guard let spawner = tileSpawner else { return }
        switch spawner.restartBrowserTile(tileId: tileId) {
        case let .restarted(runtime):
            wireContentProcessTerminationHandler(runtime)
            browserRuntimes.append(runtime)
            workspaceRuntime?.registerLiveBrowser(tileId: runtime.tileId)
            workspaceRuntime?.enforceBrowserRuntimeBudget()
        case let .invalidURL(url):
            fputs("Browser restart: invalid URL '\(url)'\n", stderr)
        case .tileNotFound:
            fputs("Browser restart: tile \(tileId) no longer exists\n", stderr)
        case let .failure(error):
            fputs("Browser restart failed: \(error)\n", stderr)
        }
    }

    static func browserBudgetSnapshotImage() -> NSImage {
        let image = NSImage(size: NSSize(width: 80, height: 60))
        image.lockFocus()
        NSColor.windowBackgroundColor.setFill()
        NSRect(x: 0, y: 0, width: 80, height: 60).fill()
        image.unlockFocus()
        return image
    }

    private func installInitialNoteTile(_ tile: Tile, in canvasView: CanvasNSView, via spawner: TileSpawner) {
        spawner.installNoteTile(tile, in: canvasView)
        if let view = canvasView.tileView(for: tile.id) as? NoteTileNSView {
            noteViews[view.noteId] = view
        }
    }

    private func installInitialFileTile(_ tile: Tile, in canvasView: CanvasNSView, via spawner: TileSpawner) {
        spawner.installFileTile(tile, in: canvasView)
    }

    private func installInitialRunArtifactsTile(_ tile: Tile, in canvasView: CanvasNSView, via spawner: TileSpawner) {
        spawner.installRunArtifactsTile(tile, in: canvasView)
    }

    private func installInitialFileTreeTile(_ tile: Tile, in canvasView: CanvasNSView, via spawner: TileSpawner) {
        switch spawner.restartFileTreeTile(tileId: tile.id) {
        case .restarted:
            if let view = canvasView.tileView(for: tile.id) as? FileTreeTileNSView {
                fileTreeViews[tile.id] = view
            }
        case .tileNotFound:
            fputs("Boot file-tree install failed: tile \(tile.id) not found in canvas\n", stderr)
        case let .failure(error):
            fputs("Boot file-tree install failed: \(error)\n", stderr)
        }
    }

    private func installInitialTicketQueueTile(_ tile: Tile, in canvasView: CanvasNSView) {
        let view = TicketQueueTileNSView(tile: tile, dispatchHandler: { [weak self] row in
            self?.dispatchAgent(for: row)
        }, fanOutHandler: { [weak self] rows in
            self?.fanOutAgents(for: rows, from: tile.id)
        })
        ticketQueueViews[tile.id] = view
        installFanOutCompletionRouting()
        // A completion that landed while this tile did not exist — it was closed, or
        // the workspace rebuilt it — still shows. Without this the check-off would be
        // whatever the live view happened to witness (from the cross-review).
        for itemId in agentSupervisor.completedFanOutItems { view.markItemDone(itemId) }
        canvasView.install(tileView: view, for: tile)
    }

    private func installInitialConductorQueueTile(_ tile: Tile, in canvasView: CanvasNSView) {
        if let activeProject {
            let root = URL(fileURLWithPath: activeProject.rootPath, isDirectory: true)
            canvasView.install(tileView: ConductorQueueTileNSView(tile: tile, projectRoot: root), for: tile)
        } else {
            canvasView.install(tileView: ConductorQueueTileNSView(tile: tile, snapshot: ConductorQueueSnapshot(tasks: [])), for: tile)
        }
    }

    private func installInitialDiffReviewTile(_ tile: Tile, in canvasView: CanvasNSView) {
        if let activeProject {
            let root = URL(fileURLWithPath: activeProject.rootPath, isDirectory: true)
            let diffView = DiffReviewTileNSView(tile: tile, repositoryURL: root, sendCommentsToAgent: { [weak self] in
                self?.sendReviewCommentsFromMenu(reviewTileId: tile.id)
            })
            diffView.onSourceChanged = { [weak canvasView] updated in canvasView?.updateTile(updated) }
            canvasView.install(tileView: diffView, for: tile)
        } else {
            canvasView.install(tileView: DescriptorTileNSView(tile: tile), for: tile)
        }
    }

    /// P3.15 (H5) calls this directly: it is the boot walk's own restore path.
    private func installInitialManagedAgentTile(_ tile: Tile, in canvasView: CanvasNSView) {
        canvasView.install(tileView: ManagedAgentTileNSView(tile: tile), for: tile)
        wireManagedAgentTile(tile.id)
    }

    private func dispatchAgent(for row: LinearTicketQueueRow) {
        guard let spawner = tileSpawner else { return }
        let activeProject = workspaceRuntime?.activeController?.project
        let prompt = AgentKickoffPrompt.make(row: row, repoPath: activeProject?.rootPath ?? FileManager.default.currentDirectoryPath, projectName: activeProject?.name)
        switch spawner.spawnTerminal(profileId: "claude") {
        case let .spawned(runtime):
            installSpawnedTerminal(runtime)
            runtime.sendInput(Data((prompt + "\n").utf8))
        case let .unknownProfile(id):
            fputs("Ticket queue dispatch failed: unknown launch profile \(id)\n", stderr)
        case let .missingCommand(executable):
            fputs("Ticket queue dispatch failed: missing command \(executable)\n", stderr)
        case let .notConfigured(profileId):
            fputs("Ticket queue dispatch failed: profile not configured \(profileId)\n", stderr)
        case let .failure(error):
            fputs("Ticket queue dispatch failed: \(error)\n", stderr)
        }
    }

    /// P2D.6 — N selected rows become N agents, one per row, each in its own
    /// worktree.
    ///
    /// `dispatchAgent` above is this gesture at one row and into a TERMINAL; this
    /// one goes through the supervisor, because a batch needs the things only the
    /// supervisor has: the cap, one isolated checkout per agent, and the item→agent
    /// mapping that lets a finished agent check its row off. Isolated is not
    /// optional here — N agents fanned out over one checkout is exactly the
    /// clobbering P2C exists to prevent.
    private func fanOutAgents(for rows: [LinearTicketQueueRow], from tileId: UUID) {
        let project = activeProject
        let repoPath = project?.rootPath ?? FileManager.default.currentDirectoryPath
        let model = AgentModelConfig.resolvedFromDefaults()
        let items = rows.map {
            AgentSupervisor.FanOutItem(
                id: $0.identifier,
                prompt: AgentKickoffPrompt.make(row: $0, repoPath: repoPath, projectName: project?.name)
            )
        }
        let report = agentSupervisor.fanOut(
            items: items,
            role: nil,
            cwd: URL(fileURLWithPath: repoPath, isDirectory: true),
            model: model.model,
            thinking: model.thinking,
            projectId: project?.id,
            isolated: true
        )
        // RENDERED, not logged: a batch held to the cap has to say so on the tile
        // that asked for it.
        ticketQueueViews[tileId]?.report(report.summary)
        refreshAgentSurfaces()
    }

    /// Routes a fan-out completion back to whichever queue tile holds that row.
    /// Broadcast rather than addressed: `markItemDone` ignores an identifier it does
    /// not render, and the alternative — remembering which tile owns which item —
    /// is a second mapping that can disagree with `AgentRecord.sourceItemId`.
    /// Installed once; the supervisor outlives every tile.
    private func installFanOutCompletionRouting() {
        guard agentSupervisor.onFanOutItemCompleted == nil else { return }
        agentSupervisor.onFanOutItemCompleted = { [weak self] itemId, _ in
            guard let self else { return }
            for view in self.ticketQueueViews.values { view.markItemDone(itemId) }
        }
    }

    /// The `agent.fanOut` command. Acts on the focused ticket-queue tile, which is
    /// the one whose selection the user can see; with none focused it says so rather
    /// than picking a tile for them.
    private func fanOutFocusedTicketQueue() {
        guard let tileId = canvasView?.canvasState.lastActiveTileId, let view = ticketQueueViews[tileId] else {
            fputs("Fan Out Selected Tickets: no ticket-queue tile is focused\n", stderr)
            return
        }
        view.fanOutSelection()
    }

    // MARK: - Hotkeys + spawning

    private func installHotkeyMonitor() {
        let monitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [weak self] event in
            guard let self else { return event }
            return self.handleHotkey(event) ? nil : event
        }
        self.hotkeyMonitor = monitor
        // Detect the held leader modifier. Never consume `.flagsChanged` (the
        // modifier itself must still flow to content); we only observe transitions
        // to arm/exit the hold-`⌥` leader.
        let flags = NSEvent.addLocalMonitorForEvents(matching: .flagsChanged) { [weak self] event in
            self?.handleFlagsChanged(event)
            return event
        }
        self.flagsMonitor = flags
    }

    /// Observe a modifier-flags transition: if the configured leader modifier is now
    /// held ALONE (no other modifier), arm the dwell → enter the leader; on any other
    /// transition (released, or a second modifier joined) cancel the pending dwell and
    /// exit the leader if open.
    func handleFlagsChanged(_ event: NSEvent) {
        let modifiers = FocusKeyModifiers(modifierFlags: event.modifierFlags)
        // P3.10: the inbox's ⌘-hold hint pills ride this monitor rather than a
        // `flagsChanged` override on the list. It is the only observer that sees a
        // release the list itself would miss — revealing an agent hands focus to its
        // tile, so the ⌘ that came up after a jump was never the inbox's event.
        updateInboxJumpHints(modifiers: modifiers)
        let leaderModifier = navKeymap.leaderHoldModifier
        if !leaderModifier.isEmpty, modifiers == leaderModifier {
            scheduleLeaderActivation()
        } else {
            disarmLeader()
        }
    }

    /// Body clicks (terminal surface, NSTextView, WKWebView, file tree row…)
    /// are consumed by the content child before TileNSView.mouseDown can fire,
    /// so the existing in-tile bring-to-front never runs for them. A
    /// non-consuming local monitor lets us bring the tile forward without
    /// taking the event away from its real target. Clicks route through
    /// FocusBroker so adapter-specific primary-input focus stays canonical.
    ///
    /// We listen on `.leftMouseUp` rather than `.leftMouseDown`: bringToFront
    /// removes the target view from its superview and re-adds it (to push it
    /// to the top of the subview array). Doing that during pre-dispatch on
    /// .leftMouseDown cancels AppKit's mouse-tracking continuation — the
    /// subsequent mouseDragged events never reach the tile. mouseUp fires
    /// after any drag has already completed, so reordering is safe and the
    /// "click → tile pops forward" delay is imperceptible.
    private func installTileFocusMonitor() {
        let monitor = NSEvent.addLocalMonitorForEvents(matching: .leftMouseUp) { [weak self] event in
            guard let self, let canvas = self.canvasView else { return event }
            guard self.focusModeSession == nil else { return event }
            guard let window = canvas.window, event.window === window else { return event }
            let pointInCanvas = canvas.convert(event.locationInWindow, from: nil)
            let clickedTileId = canvas.tileId(at: pointInCanvas)
            Self.routeTileClickFocus(at: event.locationInWindow, in: canvas, focusBroker: self.focusBroker)
            if let clickedTileId,
               canvas.canvasState.tiles.contains(where: { $0.id == clickedTileId && $0.kind == .browser }) {
                self.workspaceRuntime?.registerLiveBrowser(tileId: clickedTileId)
            }
            return event
        }
        self.tileFocusMonitor = monitor
    }

    /// Trackpad gestures (two-finger scroll, pinch) get consumed by tile
    /// content (NSScrollView in notes/file tree, Ghostty surface, WKWebView)
    /// before they can reach the canvas. Window-level monitors filter for the
    /// trackpad case and route background events to the canvas. Events over an
    /// NSScrollView/NSTextView, WKWebView/browser host, or Ghostty terminal host
    /// are passed through so tile content keeps native trackpad scrolling.
    static func routeTileClickFocus(at windowPoint: NSPoint, in canvas: CanvasNSView, focusBroker: FocusBroker) {
        // A click while an inline zone rename is open must not reroute focus out
        // from under the editing field. A click on the renamed zone's header keeps
        // editing (this is the mouse-up of the very double-click that opened it);
        // a click elsewhere commits the rename, then falls through to route focus
        // to whatever was clicked.
        if canvas.consumeZoneRenameClick(atWindowPoint: windowPoint) { return }
        let pointInCanvas = canvas.convert(windowPoint, from: nil)
        // Resolve the owning tile from the click point, falling back to the
        // live first responder so clicks inside body content (WKWebView, note,
        // terminal) that the semantic hit-test can't claim still set the tile
        // scope. A click that hits no tile is the canvas background → .canvas.
        let tileId = canvas.tileId(at: pointInCanvas)
            ?? TileNSView.enclosingTileId(of: canvas.window?.firstResponder)
        guard let tileId else {
            focusBroker.enterScope(.canvas, reason: .userClick)
            return
        }
        let surface: FocusSurfaceID = .tile(tileId)
        if let firstResponder = canvas.window?.firstResponder as? NSView,
           let tileView = canvas.tileView(for: tileId),
           firstResponder.isDescendant(of: tileView) {
            focusBroker.enterScope(surface, reason: .userClick, acceptingExisting: true)
            return
        }
        focusBroker.enterScope(surface, reason: .userClick)
    }

    private func installCanvasGestureMonitors() {
        let scrollMon = NSEvent.addLocalMonitorForEvents(matching: .scrollWheel) { [weak self] event in
            guard let self, let canvas = self.canvasView else { return event }
            guard let window = canvas.window, event.window === window else { return event }
            guard event.hasPreciseScrollingDeltas else { return event }
            // While a camera zoom session is live (pinch in progress, glide
            // running, or just after zoom input), the follow-through pan keeps
            // steering the CAMERA even over tile content. Without this, a
            // pinch over a terminal zooms the canvas and the pan that follows
            // scrolls the terminal — the canvas stops dead mid-gesture, which
            // is exactly the "lags when I start panning" handoff. Checking the
            // session first also skips the full-window hit test on every event
            // of an active camera gesture.
            if !canvas.cameraDriver.isCameraSessionActive,
               self.eventTargetsScrollableTileContent(event, in: window) {
                return event
            }
            canvas.scrollWheel(with: event)
            return nil
        }
        self.canvasScrollMonitor = scrollMon

        let magnifyMon = NSEvent.addLocalMonitorForEvents(matching: .magnify) { [weak self] event in
            guard let self, let canvas = self.canvasView else { return event }
            guard let window = canvas.window, event.window === window else { return event }
            canvas.handlePinch(event)
            return nil
        }
        self.canvasMagnifyMonitor = magnifyMon
    }

    private func eventTargetsScrollableTileContent(_ event: NSEvent, in window: NSWindow) -> Bool {
        pointTargetsScrollableTileContent(event.locationInWindow, in: window)
    }

    private func focusedResponderIsTerminalSurface() -> Bool {
        guard let view = window?.firstResponder as? NSView else { return false }
        return view.hasAncestor(ofType: GhosttyTerminalView.self)
            || view.hasAncestor(ofType: TerminalHostView.self)
    }

    private func pointTargetsScrollableTileContent(_ locationInWindow: NSPoint, in window: NSWindow) -> Bool {
        guard let contentView = window.contentView else { return false }
        let pointInContent = contentView.convert(locationInWindow, from: nil)
        guard let hitView = contentView.hitTest(pointInContent) else { return false }
        return hitView.hasAncestor(ofType: NSScrollView.self)
            || hitView.hasAncestor(ofType: NSTextView.self)
            || hitView.hasAncestor(ofType: WKWebView.self)
            || hitView.hasAncestor(ofType: BrowserHostView.self)
            || hitView.hasAncestor(ofType: GhosttyTerminalView.self)
            || hitView.hasAncestor(ofType: TerminalHostView.self)
    }

    func handleHotkey(_ event: NSEvent) -> Bool {
        if focusBroker.activeSurface == .modal(.focusMode) {
            if event.keyCode == 53 {
                closeFocusMode()
                return true
            }
            return handleReservedShortcut(event)
        }

        if focusBroker.activeSurface == .modal(.navMode) {
            let shortcut = focusBroker.reservedShortcut(for: event)
            if NavLeaderDecision.decide(
                shortcut: shortcut,
                navModeActive: true,
                eventOriginatedInFocusedSurface: focusedResponderIsTerminalSurface()
            ) == .closeNavModeAndPassThroughLiteral {
                closeNavMode()
                passThroughNavModeLeaderEvent = event
                return false
            }
            handleNavModeKey(event)
            return true
        }

        // Hold-`⌥` leader: while active, keys route to the leader handler BEFORE the
        // reserved/onlyCommand path, and unmatched keys are swallowed so nothing leaks
        // to terminal/text content. Release of the leader modifier exits via
        // `handleFlagsChanged`.
        if focusBroker.activeSurface == .modal(.leader) {
            return handleLeaderKey(event)
        }

        if profilePalette?.handleKeyEvent(event) == true {
            return true
        }

        let shortcut = focusBroker.reservedShortcut(for: event)
        // Text entry owns ordinary typing, while every app-reserved command and
        // inbox jump is withheld before it can open a modal, spawn, or navigate.
        // Unmatched keys still return false below and reach the field editor.
        if let inbox = workspaceSidebarView?.agentInbox,
           inbox.isTextEditorFocusedForGlobalShortcutGate,
           shortcut != nil || InboxJump.rowIndex(
               keyCode: event.keyCode,
               modifiers: FocusKeyModifiers(modifierFlags: event.modifierFlags)) != nil {
            return true
        }
        if shortcut == .navModeLeader {
            openNavMode()
            return true
        }

        let mods = event.modifierFlags.intersection(.deviceIndependentFlagsMask)

        // WS5 page zoom. Routed HERE, from the resolved focus scope, rather than
        // from a `performKeyEquivalent` override on the tile: AppKit walks the
        // whole view tree for a key equivalent, so a tile-local override would
        // let a background agent tile answer a chord meant for the focused one.
        // `focusedTileView()` is the same scope every other tile action uses.
        //
        // Nothing is consumed unless the focused tile IS a managed agent, so the
        // browser, the canvas, notes, terminals and every editable control keep
        // these chords; and `AgentPageZoomShortcut` returns nil for every chord
        // that is not one of the four, so nothing else is shadowed either.
        if handleManagedAgentPageZoom(event) { return true }

        // Cmd-Backspace (key code 51): delete the active tile. Only fires when
        // the canvas itself is first responder so a Cmd-Backspace inside an
        // NSTextView, terminal, or WKWebView form field still gets its native
        // semantics. The × close button covers the case where the user is
        // focused inside a tile's content.
        if mods == [.command], event.keyCode == 51 {
            guard window?.firstResponder === canvasView else { return false }
            guard let id = canvasView?.canvasState.lastActiveTileId else { return false }
            deleteTile(id: id)
            return true
        }

        // P3.10: ⌘1–⌘9 jump to an inbox row — but ONLY while the inbox list holds
        // first responder, and therefore BEFORE the reserved dispatch below, which is
        // where ⌘1–⌘4 mean "spawn launch profile N". The scope is the whole of the
        // collision resolution: the four profile chords are not moved, not
        // re-classified and not shadowed anywhere else in the app.
        if handleInboxJump(event) { return true }

        // Dispatch through FocusDispatch. It consumes a matching reserved global
        // or focused-tile action and otherwise returns false (.passThrough), so
        // non-⌘ chords (e.g. the ⌘⌃-digit resize presets) now reach the dispatcher
        // instead of being dropped by a coarse "⌘-only" gate — while unmatched
        // keys (typing) still fall through to the responder chain / content.
        return handleReservedShortcut(event)
    }

    // Ticket: docs/38-tickets/90-agent-ux/P3.10-jump-shortcuts.md
    /// Consume a ⌘1–⌘9 the inbox can act on, or return false so the event keeps its
    /// other meaning.
    ///
    /// Internal rather than private because the check drives this exact function with
    /// the responder in both positions — asserting the scope through a mirror of the
    /// guard would witness the mirror.
    func handleInboxJump(_ event: NSEvent) -> Bool {
        guard let inbox = focusedAgentInbox() else { return false }
        return inbox.jump(
            keyCode: event.keyCode, modifiers: FocusKeyModifiers(modifierFlags: event.modifierFlags))
    }

    /// Hint pills up while ⌘ is held AND the inbox is the thing that would act on it;
    /// down for every other modifier state, including a ⌘ that is still held over a
    /// surface the jump does not reach.
    ///
    /// The condition is `focusedAgentInbox()` — the SAME guard the jump uses — so the
    /// pills can never advertise a chord that would not fire.
    private func updateInboxJumpHints(modifiers: FocusKeyModifiers) {
        guard let inbox = workspaceSidebarView?.agentInbox else { return }
        inbox.setJumpHintsVisible(modifiers == .command && focusedAgentInbox() != nil)
    }

    /// The inbox, but only when it — or a view inside it, which is what the table is
    /// — holds first responder.
    ///
    /// The responder is read off the INBOX'S OWN window rather than `self.window`, so
    /// this asks the one question that matters ("does this list have the keyboard")
    /// and does not also depend on which window the app happens to hold a reference
    /// to.
    private func focusedAgentInbox() -> AgentInboxView? {
        guard let inbox = workspaceSidebarView?.agentInbox,
              !inbox.isHiddenOrHasHiddenAncestor,
              let responder = inbox.window?.firstResponder as? NSView,
              responder === inbox || responder.isDescendant(of: inbox),
              inbox.allowsGlobalShortcuts(for: responder) else { return nil }
        return inbox
    }

    private func openNavMode() {
        demonstrateOnboarding(.navigationModeEntered)
        focusBroker.openModal(.navMode)
        navSelectedZoneId = canvasView?.navZoneRenderModels.first?.placement.zoneId
        canvasView?.navModeHintLine = navKeymap.hintLine
        canvasView?.setNavModeOverlayVisible(true)
    }

    private func closeNavMode() {
        focusBroker.closeModal(.navMode)
        navSelectedZoneId = nil
        canvasView?.setNavModeOverlayVisible(false)
    }

    // MARK: - Hold-`⌥` leader

    /// Arm the dwell when the leader modifier is held alone; once it fires (or
    /// synchronously when `leaderDwell <= 0`) the leader scope opens. No-op if a
    /// modal is already active or the leader is already armed/open.
    private func scheduleLeaderActivation() {
        if let surface = focusBroker.activeSurface, case .modal = surface { return }
        guard leaderDwellWorkItem == nil else { return }
        if leaderDwell <= 0 {
            activateLeader()
            return
        }
        let work = DispatchWorkItem { [weak self] in
            self?.leaderDwellWorkItem = nil
            self?.activateLeader()
        }
        leaderDwellWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + leaderDwell, execute: work)
    }

    private func activateLeader() {
        guard focusBroker.activeSurface != .modal(.leader) else { return }
        focusBroker.openModal(.leader)
        canvasView?.leaderLabelAlphabet = navKeymap.leaderLabelAlphabet
        canvasView?.leaderZoneOrdinalAlphabet = navKeymap.leaderZoneOrdinalAlphabet
        canvasView?.setLeaderOverlayVisible(true)
    }

    /// Cancel a pending dwell and exit the leader if open (modifier released or a
    /// second modifier joined). Always hides the HUD (no-op if not shown). Releasing
    /// the leader COMMITS an in-flight ⌥+arrow dock — the tile keeps where it landed.
    private func disarmLeader() {
        leaderDwellWorkItem?.cancel()
        leaderDwellWorkItem = nil
        if focusBroker.activeSurface == .modal(.leader) {
            focusBroker.closeModal(.leader)
        }
        canvasView?.setLeaderOverlayVisible(false)
        _ = canvasView?.commitGeometryEdit()
        clearLeaderSnapSession()
    }

    /// Keys while the leader is held. Esc exits (restoring an in-flight dock); an
    /// arrow key docks/leapfrogs the focused tile (Phase D); a label key jumps to +
    /// centers the labeled tile (Phase C). Everything is swallowed so nothing leaks
    /// to content.
    private func handleLeaderKey(_ event: NSEvent) -> Bool {
        if event.keyCode == 53 { // Esc
            cancelLeaderSnap() // restore the tile if a dock is in flight (no-op otherwise)
            disarmLeader()
            return true
        }
        // Return activates the tile that is ALREADY current — the self-action the
        // label alphabet cannot express, because a fully-visible current tile is
        // deliberately excluded from the labels. Resolved BEFORE label lookup so
        // no alphabet edit can ever shadow it. Numpad Enter (76) counts: the
        // leader swallows it either way, so treating it as anything other than
        // Return would just be a dead key.
        if event.keyCode == 36 || event.keyCode == 76 {
            let tileId = canvasView?.canvasState.lastActiveTileId
            disarmLeader() // closes the leader modal (restores prior scope) + hides HUD
            guard let tileId, canvasView?.navigationTileSnapshot(for: tileId) != nil else { return true }
            revealTileForWork(tileId, historyReason: .directTileActivation, scopeReason: .modalDismissed)
            demonstrateOnboarding(.quickJumpUsed)
            return true
        }
        if let direction = leaderArrowDirection(event.keyCode) {
            leaderSnapStep(direction: direction)
            return true
        }
        let key = (event.charactersIgnoringModifiers ?? "").lowercased()
        // Zone-jump is resolved BEFORE tile-jump so a configured zone navKey that
        // collides with a tile label always wins (precedence rule 1).
        if !key.isEmpty, let zoneId = canvasView?.leaderZoneJumpTarget(forKey: key) {
            let targetViewport = canvasView?.fitZoneToViewport(zoneId: zoneId)
            disarmLeader()
            if let targetViewport {
                recordViewBeforeProgrammaticJumpIfNeeded(targetViewport: targetViewport)
                canvasView?.setViewport(targetViewport)
            }
            navSelectedZoneId = zoneId
            focusHistory.recordZoneFocus(zoneId, reason: .completedZoneJump)
            completeZoneJump(zoneId)
            return true
        }
        if !key.isEmpty, let tileId = canvasView?.leaderJumpTarget(forLabel: key) {
            disarmLeader() // closes the leader modal (restores prior scope) + hides HUD
            revealTileForWork(tileId, historyReason: .completedTileJump, scopeReason: .modalDismissed)
            demonstrateOnboarding(.quickJumpUsed)
            return true
        }
        return true
    }

    private func leaderArrowDirection(_ keyCode: UInt16) -> TileArrangement.Direction? {
        switch keyCode {
        case 123: return .left
        case 124: return .right
        case 125: return .down
        case 126: return .up
        default: return nil
        }
    }

    /// One ⌥+arrow press: dock the focused tile gap-adjacent + corner-aligned to the
    /// directional neighbor. A repeat in the same direction leapfrogs to the next
    /// tile further; the opposite direction steps back (and past the origin, docks
    /// the other way); a perpendicular direction restarts from the origin. Always
    /// computed against the tile's ORIGINAL frame so the leapfrog index is stable.
    private func leaderSnapStep(direction: TileArrangement.Direction) {
        guard let canvas = canvasView,
              let tileId = canvas.canvasState.lastActiveTileId,
              let tile = canvas.canvasState.tiles.first(where: { $0.id == tileId }) else { return }

        if leaderSnapTileId != tileId || leaderSnapOriginalFrame == nil {
            leaderSnapTileId = tileId
            leaderSnapOriginalFrame = tile.frame
            leaderSnapDirection = direction
            leaderSnapIndex = 0
            canvas.beginGeometryEdit(.dockTile, tileIds: [tileId], includeAllZones: true)
        } else if leaderSnapDirection == direction {
            leaderSnapIndex += 1
        } else if leaderSnapDirection == direction.opposite {
            leaderSnapIndex -= 1
            if leaderSnapIndex < 0 {
                leaderSnapDirection = direction
                leaderSnapIndex = 0
            }
        } else {
            leaderSnapDirection = direction
            leaderSnapIndex = 0
        }

        guard let original = leaderSnapOriginalFrame, let dir = leaderSnapDirection else { return }
        let others = canvas.canvasState.tiles.filter { $0.id != tileId }.map(\.frame)
        let candidates = TileArrangement.dockCandidates(ahead: original, direction: dir, among: others)
        guard !candidates.isEmpty else { leaderSnapIndex = 0; return }
        let index = min(max(leaderSnapIndex, 0), candidates.count - 1)
        leaderSnapIndex = index
        let dest = TileArrangement.dockDestination(original, direction: dir, against: candidates[index], gap: TileGapResolver.resolvedGap())
        var moved = tile
        moved.frame = dest
        canvas.updateTile(moved, recalculateZoneBounds: false, notifyChange: false)
    }

    /// Esc during a dock: restore the focused tile to where the session began.
    private func cancelLeaderSnap() {
        canvasView?.cancelGeometryEdit()
        clearLeaderSnapSession()
    }

    private func clearLeaderSnapSession() {
        leaderSnapTileId = nil
        leaderSnapOriginalFrame = nil
        leaderSnapDirection = nil
        leaderSnapIndex = 0
    }

    private func handleNavModeKey(_ event: NSEvent) {
        if event.keyCode == 53 || focusBroker.reservedShortcut(for: event) == .navModeLeader {
            closeNavMode()
            return
        }

        let rawKey = event.charactersIgnoringModifiers ?? ""
        let key = rawKey.lowercased()

        if navKeymap.keyMatches(rawKey, navKeymap.focusMode) {
            let selectedTileId = canvasView?.canvasState.lastActiveTileId
            closeNavMode()
            if let selectedTileId {
                openFocusMode(primaryTileId: selectedTileId)
            }
            return
        }

        if event.keyCode == 36 {
            guard let selectedTileId = canvasView?.canvasState.lastActiveTileId else {
                closeNavMode()
                return
            }
            closeNavMode()
            focusBroker.enterScope(.tile(selectedTileId), reason: .modalDismissed)
            demonstrateOnboarding(.navigationModeActivated)
            return
        }

        if key == "0" {
            fitAllNavZones()
            return
        }

        if let ordinal = Int(key), (1...9).contains(ordinal) {
            jumpToZoneOrdinal(ordinal)
            return
        }

        if event.keyCode == 48 {
            jumpToZoneByOrder(delta: event.modifierFlags.contains(.shift) ? -1 : 1)
            return
        }

        if navKeymap.keyMatches(rawKey, navKeymap.nextZone) {
            jumpToZoneByOrder(delta: 1)
            return
        }

        if navKeymap.keyMatches(rawKey, navKeymap.previousZone) {
            jumpToZoneByOrder(delta: -1)
            return
        }

        if navKeymap.keyMatches(rawKey, navKeymap.zonePicker) {
            closeNavMode()
            openProfilePalette(initialQuery: "zone")
            return
        }

        if navKeymap.keyMatches(rawKey, navKeymap.workspacePicker) {
            closeNavMode()
            openProfilePalette(initialQuery: "switch workspace")
            return
        }

        if navKeymap.keyMatches(rawKey, navKeymap.agentNeedsAttention) {
            cycleNavAgent(status: .needsAttention)
            return
        }

        if navKeymap.keyMatches(rawKey, navKeymap.agentCycle) {
            cycleNavAgent(status: nil)
            return
        }

        if let direction = TileArrangement.Direction.fromKey(key, keymap: navKeymap) {
            moveNavSelection(direction: direction)
            return
        }

        if navKeymap.keyMatches(rawKey, navKeymap.deleteTile), let selectedTileId = canvasView?.canvasState.lastActiveTileId {
            closeNavMode()
            deleteTile(id: selectedTileId)
        }
    }

    private func cycleNavAgent(status: AgentStatus?) {
        guard let canvasView else { return }
        let agentTileIds = currentAgentTileIds(status: status)
        guard !agentTileIds.isEmpty else { return }
        let selectedTileId = canvasView.canvasState.lastActiveTileId
        let nextId: UUID
        if let selectedTileId, let index = agentTileIds.firstIndex(of: selectedTileId) {
            nextId = agentTileIds[(index + 1) % agentTileIds.count]
        } else {
            nextId = agentTileIds[0]
        }
        canvasView.markActive(tileId: nextId)
        synchronizeAgentFocus(to: nextId)
        focusHistory.recordTileFocus(nextId, zoneId: zoneContainingTile(nextId), reason: .directTileActivation)
    }

    /// Nav-cycle order over the agent tiles ON THE CANVAS: z-order, which is a
    /// navigation concern. The STATUS it filters on is no longer re-derived here —
    /// it comes from the one snapshot (P2B.4), so ⌥-cycling and the badge on the
    /// tile it lands on can no longer disagree.
    ///
    /// P2B.5: "an agent tile" is a tile the INVENTORY has an agent for, not a tile
    /// whose kind is `.terminal`. The kind filter predated managed-agent tiles and
    /// silently skipped every one of them, so ⌥-cycling could not reach a managed
    /// agent and the attention cycle stepped over a raised hand. Terminal agents are
    /// unaffected: `statuses` is keyed by `agentIdentities`, so a plain shell tile is
    /// still not something to cycle to, whatever its kind.
    private func currentAgentTileIds(status: AgentStatus?) -> [UUID] {
        guard let canvasView else { return [] }
        // A keystroke, so it reads fresh — which is what the per-call
        // `listSessions()` this replaced did too.
        rebuildAgentActivitySnapshot()
        let statuses = agentStatusesByTileId()
        return canvasView.allWorkspaceTiles()
            .sorted { lhs, rhs in
                if lhs.zPosition != rhs.zPosition { return lhs.zPosition < rhs.zPosition }
                return lhs.id.uuidString < rhs.id.uuidString
            }
            .compactMap { tile in
                guard let agentStatus = statuses[tile.id] else { return nil }
                if let status, agentStatus != status { return nil }
                return tile.id
            }
    }

    /// The dock/attention surface, read off the snapshot and NOT off the canvas:
    /// an agent in another project, or with no tile at all, raises its hand the
    /// same way one on screen does.
    private func updateAgentAttentionSurface(notify: Bool) {
        let count = AgentsBoardProjection.attentionCount(from: agentActivity.snapshot)
        NSApplication.shared.dockTile.badgeLabel = Self.dockBadgeLabel(needsAttentionCount: count)
        if notify, Self.shouldNotifyNeedsAttention(previousCount: lastNeedsAttentionCount, newCount: count, appIsActive: NSApplication.shared.isActive) {
            deliverNeedsAttentionNotification(count: count)
        }
        lastNeedsAttentionCount = count
    }

    private func stopHarnessRun(tileId: UUID) {
        guard let session = (try? projectStore?.listSessions())??.first(where: { $0.tileId == tileId }),
              let runId = session.agentDescriptor?.runId,
              let projectRoot = activeProject?.rootPath else { return }
        let runDirectory = URL(fileURLWithPath: projectRoot, isDirectory: true)
            .appendingPathComponent(".pi/agent-runs/\(runId)", isDirectory: true)
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            do {
                let handle = try HarnessRunControl.readHandle(runDirectory: runDirectory, expectedRunId: runId)
                try HarnessRunControl.terminateProcessGroup(handle)
                DispatchQueue.main.async {
                    self?.updateAgentStatus(tileId: tileId, status: .done)
                }
            } catch {
                fputs("Stop run failed for \(runId): \(error)\n", stderr)
            }
        }
    }

    private func updateAgentStatus(tileId: UUID, status: AgentStatus, now: Date = Date()) {
        canvasView?.tileView(for: tileId)?.agentStatus = status
        if var sessions = try? projectStore?.listSessions(), let index = sessions.firstIndex(where: { $0.tileId == tileId }), var descriptor = sessions[index].agentDescriptor {
            descriptor.status = status
            descriptor.statusUpdatedAt = now
            sessions[index].agentDescriptor = descriptor
            try? projectStore?.saveSession(sessions[index])
        }
        // One rebuild, all four surfaces (P2B.4) — this was a dock refresh and a
        // sidebar reload that each re-derived the status this method just wrote.
        refreshAgentSurfaces()
    }

    private static func canvasBadgeStatus(_ status: AgentStatus?) -> AgentStatus? {
        switch status {
        case .working, .needsAttention, .done, .stale:
            return status
        case .configuring, .idle, nil:
            return nil
        }
    }

    private static func canvasRollup(from sidebar: SidebarAgentStatusRollup) -> CanvasNSView.AgentStatusRollup {
        CanvasNSView.AgentStatusRollup(
            working: sidebar.working,
            needsAttention: sidebar.needsAttention,
            done: sidebar.done,
            stale: sidebar.stale
        )
    }

    private static func canvasRollupsByZone(
        statuses: [UUID: AgentStatus],
        canvas: CanvasNSView,
        signals: [UUID: AgentSignal] = [:]
    ) -> [UUID: CanvasNSView.AgentStatusRollup] {
        var sidebarRollups: [UUID: SidebarAgentStatusRollup] = [:]
        for (tileId, status) in statuses {
            guard let zoneId = canvas.qaZoneMembership(of: tileId) else { continue }
            sidebarRollups[zoneId, default: .empty].add(status)
        }
        var result = sidebarRollups.mapValues(canvasRollup(from:))
        for (tileID, signal) in signals {
            guard let zoneID = canvas.qaZoneMembership(of: tileID) else { continue }
            switch signal.kind {
            case .gitPushSucceeded: result[zoneID, default: .empty].pushed += 1
            case .gitMergeSucceeded: result[zoneID, default: .empty].merged += 1
            case .completed, .failed, .actionRequired: break
            }
        }
        return result
    }

    /// The runtime observer's map is an INPUT to the one derivation (P2B.4), so it
    /// is stored rather than pushed straight at the canvas: a later rebuild for any
    /// other reason must see the same statuses this one did.
    private func applyObserverStatuses(_ statuses: [UUID: AgentStatus]) {
        for (tileID, status) in statuses where observedAgentStatuses[tileID] != status {
            let overrides = canvasView?.allWorkspaceTiles()
                .first(where: { $0.id == tileID })?.metadata.agentSoundOverrides
            _ = agentSignalCenter.ingestObserved(
                status: status,
                tileID: tileID,
                overrides: overrides
            )
        }
        observedAgentStatuses = statuses
        refreshAgentSurfaces()
    }

    private func applyAgentSignalVisual(tileID: UUID?) {
        guard let canvasView else { return }
        let tileIDs = tileID.map { [$0] } ?? Array(agentSignalCenter.currentByTile.keys)
        for id in tileIDs {
            (canvasView.tileView(for: id) as? ManagedAgentTileNSView)?
                .applyAwarenessSignal(agentSignalCenter.currentByTile[id])
        }
        applyAgentStatusesToCanvas()
    }

    /// Canvas badges and zone rollups, from the snapshot.
    private func applyAgentStatusesToCanvas() {
        guard let canvasView else { return }
        let statuses = agentStatusesByTileId()
        for tile in canvasView.allWorkspaceTiles() {
            // P2B.6: NO ENTRY is not an entry saying "no agent". This sweep used to
            // assign `canvasBadgeStatus(statuses[tile.id])` unconditionally, so a
            // tile the inventory has nothing to say about — a managed tile whose
            // record has not been written yet, and which set its own badge from its
            // own ingest — had that badge erased by the next sweep for any unrelated
            // agent. Absence of information is not information.
            //
            // An entry that EXISTS still clears the badge when it is idle or
            // configuring (`canvasBadgeStatus` returns nil for those), so a terminal
            // that genuinely went idle can still go dark. That is the distinction
            // this guard is drawing: "no entry" vs "entry says no badge".
            guard let status = statuses[tile.id] else { continue }
            canvasView.tileView(for: tile.id)?.agentStatus = Self.canvasBadgeStatus(status)
        }

        let rollupsByZone = Self.canvasRollupsByZone(
            statuses: statuses,
            canvas: canvasView,
            signals: agentSignalCenter.currentByTile
        )
        let updatedModels = canvasView.zoneRenderModels.map { model in
            var updated = model
            updated.agentStatusRollup = rollupsByZone[model.placement.zoneId] ?? .empty
            return updated
        }
        canvasView.updateZoneRenderModels(updatedModels)
    }

    private static func dockBadgeLabel(needsAttentionCount count: Int) -> String? {
        count > 0 ? String(count) : nil
    }

    private static func shouldNotifyNeedsAttention(previousCount: Int, newCount: Int, appIsActive: Bool) -> Bool {
        !appIsActive && previousCount == 0 && newCount > 0
    }

    private func deliverNeedsAttentionNotification(count: Int) {
        let notification = NSUserNotification()
        notification.title = "Continuum agent needs attention"
        notification.informativeText = count == 1 ? "1 agent needs input." : "\(count) agents need input."
        NSUserNotificationCenter.default.deliver(notification)
    }

    private func moveNavSelection(direction: TileArrangement.Direction) {
        guard let canvasView else { return }
        let worldTiles = canvasView.navigationTileSnapshots().compactMap { snapshot -> Tile? in
            guard var tile = canvasView.tileRecord(for: snapshot.tileId) else { return nil }
            tile.frame = snapshot.worldFrame
            return tile
        }
        guard let selectedTileId = canvasView.canvasState.lastActiveTileId,
              let nextTileId = CanvasEngine.nearestTile(
                from: selectedTileId,
                direction: direction,
                tiles: worldTiles
              ) else { return }
        canvasView.markActive(tileId: nextTileId)
        synchronizeAgentFocus(to: nextTileId)
        focusHistory.recordTileFocus(nextTileId, zoneId: zoneContainingTile(nextTileId), reason: .directTileActivation)
    }

    private func jumpToZoneOrdinal(_ ordinal: Int) {
        guard let canvasView else { return }
        let index = ordinal - 1
        guard canvasView.navZoneRenderModels.indices.contains(index) else { return }
        fitNavZone(canvasView.navZoneRenderModels[index].placement.zoneId)
    }

    private func jumpToZoneByOrder(delta: Int) {
        guard let canvasView else { return }
        let models = canvasView.navZoneRenderModels
        guard !models.isEmpty else { return }
        let currentId = navSelectedZoneId ?? models.first?.placement.zoneId
        let currentIndex = currentId.flatMap { id in models.firstIndex { $0.placement.zoneId == id } } ?? 0
        let nextIndex = currentIndex + delta
        guard models.indices.contains(nextIndex) else { return }
        fitNavZone(models[nextIndex].placement.zoneId)
    }

    private func recordViewBeforeProgrammaticJumpIfNeeded(targetViewport: CanvasViewport) {
        guard let canvasView else { return }
        let current = canvasView.canvasState.viewport
        guard Self.viewportChangeExceedsJumpEpsilon(from: current, to: targetViewport) else { return }
        focusHistory.recordViewBeforeProgrammaticJump(CameraSnapshot(viewport: current, focusedTileId: canvasView.canvasState.lastActiveTileId, focusedZoneId: navSelectedZoneId))
    }

    private static func viewportChangeExceedsJumpEpsilon(from current: CanvasViewport, to target: CanvasViewport) -> Bool {
        let zoom = max(max(abs(current.zoom), abs(target.zoom)), CameraFraming.minJumpZoom)
        let dxScreen = abs(current.x - target.x) * zoom
        let dyScreen = abs(current.y - target.y) * zoom
        return dxScreen > CameraFraming.finalViewportEpsilonScreenPx
            || dyScreen > CameraFraming.finalViewportEpsilonScreenPx
            || abs(current.zoom - target.zoom) > 0.0001
    }

    private func fitNavZone(_ zoneId: UUID) {
        guard let canvasView, let viewport = canvasView.fitZoneToViewport(zoneId: zoneId) else { return }
        recordViewBeforeProgrammaticJumpIfNeeded(targetViewport: viewport)
        navSelectedZoneId = zoneId
        canvasView.setViewport(viewport)
        focusHistory.recordZoneFocus(zoneId, reason: .completedZoneJump)
        // Nav mode is still open and still owns input; see completeZoneJump.
        completeZoneJump(zoneId, landingInputOnCanvas: false)
    }

    private func fitAllNavZones() {
        guard let viewport = canvasView?.fitAllToViewport() else { return }
        navSelectedZoneId = nil
        canvasView?.setViewport(viewport)
    }

    private func handleReservedShortcut(_ event: NSEvent) -> Bool {
        let modifiers = FocusKeyModifiers(modifierFlags: event.modifierFlags)
        if let registry = try? CommandRegistry.productRegistry() {
            let store = ShortcutBindingStore()
            if let matched = registry.shortcuts.first(where: {
                $0.contexts.contains(.global)
                    && store.matches(keyCode: event.keyCode, modifiers: modifiers, definition: $0)
            }), performRegisteredGlobalCommand(matched.commandID) {
                return true
            }

            // ReservedShortcut remains the compatibility classifier while nav
            // and tile-local bindings finish migrating. Registered globals own
            // their old defaults now: moving or unassigning one must not leave a
            // second invisible hardcoded route behind.
            if let legacy = ReservedShortcut.classify(keyCode: event.keyCode, modifiers: modifiers, keymap: navKeymap),
               let shortcutID = registeredShortcutID(for: legacy),
               let definition = registry.shortcuts.first(where: { $0.id == shortcutID }),
               !store.matches(keyCode: event.keyCode, modifiers: modifiers, definition: definition) {
                return false
            }
        }
        // Nav-mode leader carries special open/close/pass-through semantics, but
        // ONLY when the event actually classifies as the leader. Everything else
        // — including ⌘⌃ tile-action chords (resize presets, etc.) — must fall
        // through to FocusDispatch.resolve below. The old
        // `guard let shortcut … else { return false }` silently dropped every
        // tile-action chord because it doesn't classify as a ReservedShortcut,
        // which is why ⌘⌃ resize/throw never fired at runtime (docs/30).
        if let shortcut = focusBroker.reservedShortcut(for: event) {
            if shortcut == .navModeLeader, passThroughNavModeLeaderEvent === event {
                passThroughNavModeLeaderEvent = nil
                return false
            }
            switch NavLeaderDecision.decide(
                shortcut: shortcut,
                navModeActive: focusBroker.activeSurface == .modal(.navMode),
                eventOriginatedInFocusedSurface: true
            ) {
            case .closeNavModeAndPassThroughLiteral:
                closeNavMode()
                return false
            case .closeNavMode:
                closeNavMode()
                return true
            case .openNavMode, .ignore:
                break
            }
        }

        // The scattered `shouldSurfaceReceive` guards and the per-shortcut switch
        // are unified into one pure decision (docs/27 staging 3). `resolve`'s
        // inviolable-global ordering subsumes the old guards, and a focused tile's
        // catalog claim (e.g. browser Cmd-F) replaces the P0 special-case
        // responder-walk guard — that claim resolves to `.tileAction`, whose
        // executor (A2: passthrough stub) returns false so the event still reaches
        // the tile's own key path (BrowserHostView.performKeyEquivalent → find bar).
        let scope = reservedDispatchScope()
        let focusedKind: TileKind?
        if case let .tile(tileId) = scope {
            focusedKind = canvasView?.tileRecord(for: tileId)?.kind
        } else {
            focusedKind = nil
        }

        switch FocusDispatch.resolve(
            keyCode: event.keyCode,
            modifiers: FocusKeyModifiers(modifierFlags: event.modifierFlags),
            scope: scope,
            focusedKind: focusedKind,
            navKeymap: navKeymap
        ) {
        case let .global(shortcut):
            switch shortcut {
            case .focusMode:
                if focusModeSession == nil, let selectedTileId = canvasView?.canvasState.lastActiveTileId {
                    openFocusMode(primaryTileId: selectedTileId)
                } else {
                    closeFocusMode()
                }
                return true
            case .palette:
                openProfilePalette()
                return true
            case .spawnProfile(1):
                spawnTerminalFromProfile("claude", trigger: "hotkey:cmd-1")
                return true
            case .spawnProfile(2):
                spawnTerminalFromProfile("shell", trigger: "hotkey:cmd-2")
                return true
            case .spawnProfile(3):
                spawnBrowserDefault()
                return true
            case .spawnProfile(4):
                spawnTerminalFromProfile("nvim", trigger: "hotkey:cmd-4")
                return true
            case .navModeLeader:
                openNavMode()
                return true
            case .settings:
                toggleSettingsPanel()
                return true
            case .spawnProfile:
                return false
            }
        case let .tileAction(action):
            return executeTileAction(action)
        case .passThrough:
            return false
        }
    }

    private func performRegisteredGlobalCommand(_ commandID: CommandID) -> Bool {
        switch commandID.rawValue {
        case "app.commandCenter":
            openProfilePalette()
        case "app.openKeybindings":
            openKeybindingsSettings()
        case "app.focusMode":
            if focusModeSession == nil, let selectedTileId = canvasView?.canvasState.lastActiveTileId {
                openFocusMode(primaryTileId: selectedTileId)
            } else {
                closeFocusMode()
            }
        case "app.settings":
            toggleSettingsPanel()
        case "tile.quickSpawn.1":
            spawnTerminalFromProfile("claude", trigger: "shortcut:quick-spawn-1")
        case "tile.quickSpawn.2":
            spawnTerminalFromProfile("shell", trigger: "shortcut:quick-spawn-2")
        case "tile.quickSpawn.3":
            spawnBrowserDefault()
        case "tile.quickSpawn.4":
            spawnTerminalFromProfile("nvim", trigger: "shortcut:quick-spawn-4")
        case "view.toggleWorkspaceSidebar":
            toggleWorkspaceSidebar()
        default:
            return false
        }
        return true
    }

    private func registeredShortcutID(for legacy: ReservedShortcut) -> ShortcutID? {
        switch legacy {
        case .palette: return "global.commandCenter"
        case .focusMode: return "global.focusMode"
        case .settings: return "global.settings"
        case .spawnProfile(let number): return ShortcutID(rawValue: "global.spawnProfile.\(number)")
        case .navModeLeader: return nil
        }
    }

    /// The focus scope for reserved-shortcut dispatch. Prefers an authoritative
    /// tile `activeSurface` (A1), but falls back to the owning tile of the live
    /// first responder when the scope is not a tile — so a Cmd-F while web content
    /// is focused still resolves to the browser tile even if `activeSurface` is
    /// stale. This subsumes both removed guards (active-surface + P0 responder-walk).
    private func reservedDispatchScope() -> FocusSurfaceID {
        if case .tile = focusBroker.activeSurface {
            return focusBroker.activeSurface!
        }
        if let responderTileId = TileNSView.enclosingTileId(of: window?.firstResponder) {
            return .tile(responderTileId)
        }
        return focusBroker.activeSurface ?? .canvas
    }

    /// Resize ladder scale applied to a kind's base `TileGeometry.preset` size:
    /// compact ≈ 0.7×, default = base, large ≈ 1.4×. `fillViewport` ignores the
    /// ladder and sizes to the visible world rect (handled separately).
    static func resizeScale(for preset: TileSizePreset) -> Double {
        switch preset {
        case .compact: return 0.7
        case .default: return 1.0
        case .large: return 1.4
        case .fillViewport: return 1.0
        }
    }

    /// Every tile action is now consumed by the monitor when the focused tile
    /// matches (A4 wired browser/note executors onto the focused tile view). A
    /// chord pressed when the focused tile does NOT match its kind still returns
    /// false from `executeTileAction` (runtime passthrough), but the static
    /// consumption contract — used by `--reserved-dispatch-check` without an
    /// `AppDelegate` instance — treats all tile actions as non-passthrough.
    static func isPassthroughTileAction(_ action: TileAction) -> Bool {
        switch action {
        case .resizeToPreset,
             .browserFind, .browserFocusURL, .browserReload, .browserBack, .browserForward, .noteExport:
            return false
        }
    }

    /// Executes a resolved tile-local action against the FOCUSED tile (A3).
    /// Resolves the scope's `.tile(id)` to its `Tile` in the live canvas model,
    /// applies pure Core geometry (`TileGeometry` sizing / `TileArrangement`
    /// positioning) in world coordinates, and commits via `canvasView.updateTile`.
    /// Returns true when the action was applied (consumed by the monitor). With no
    /// focused tile, or for browser/note actions (A4), returns false so the event
    /// still reaches the focused tile's own key path (preserves P0 browser-find).
    @discardableResult
    func executeTileAction(_ action: TileAction) -> Bool {
        switch action {
        case let .resizeToPreset(preset):
            return resizeFocusedTile(to: preset)
        case .browserFind:
            guard let browser = focusedTileView() as? BrowserTileNSView else { return false }
            browser.performFindAction()
            return true
        case .browserFocusURL:
            guard let browser = focusedTileView() as? BrowserTileNSView else { return false }
            browser.focusURLField()
            return true
        case .browserReload:
            guard let browser = focusedTileView() as? BrowserTileNSView else { return false }
            browser.performReloadAction()
            return true
        case .browserBack:
            guard let browser = focusedTileView() as? BrowserTileNSView else { return false }
            browser.performBackAction()
            return true
        case .browserForward:
            guard let browser = focusedTileView() as? BrowserTileNSView else { return false }
            browser.performForwardAction()
            return true
        case .noteExport:
            guard let note = focusedTileView() as? NoteTileNSView else { return false }
            note.exportToFile()
            return true
        }
    }

    /// WS5 fixture seams. `canvasView` and `focusBroker` are private, and the
    /// page-zoom routing witness lives in its own file; these let it wire a real
    /// canvas and a real focus scope and then drive the PRODUCTION
    /// `handleManagedAgentPageZoom` below, rather than re-deriving what it does.
    func qaInstallCanvasForChecks(_ canvas: CanvasNSView) {
        // The broker must be wired BEFORE any tile is installed: tile views
        // register their focus adapters on install, and `acceptExistingFocus`
        // refuses a surface with no adapter (`adapters[id] != nil`). Without
        // this the fixture's focus silently did nothing, `activeSurface` stayed
        // nil, and every routing assertion below failed for a fixture reason
        // rather than a product one. Production wires it the same way, before
        // `setZones`.
        canvas.focusBroker = focusBroker
        canvasView = canvas
    }

    @discardableResult
    func qaEnterFocusScopeForChecks(_ scope: FocusSurfaceID) -> Bool {
        // `acceptingExisting`: the fixture installs tile VIEWS on a bare canvas
        // and registers no focus adapters, so the acquire path would refuse.
        // This is the same seam a content click uses, and it sets
        // `activeSurface` — which is all `reservedDispatchScope` reads.
        focusBroker.enterScope(scope, reason: .tileSpawned, acceptingExisting: true)
    }

    /// WS5: route a page-zoom chord to the FOCUSED managed-agent tile.
    ///
    /// Returns whether the event was consumed. A chord at an end stop is still
    /// consumed — it is unambiguously ours, and letting it fall through mid-
    /// gesture would hand a repeated Command-plus to some other owner the moment
    /// the reader hit 150%.
    func handleManagedAgentPageZoom(_ event: NSEvent) -> Bool {
        guard AgentPageZoomShortcut.command(
            characters: event.characters,
            charactersIgnoringModifiers: event.charactersIgnoringModifiers,
            modifiers: AgentPageZoomModifier.set(from: event.modifierFlags)
        ) != nil else { return false }
        guard let agent = focusedTileView() as? ManagedAgentTileNSView else { return false }
        return agent.handlePageZoomKeyEquivalent(with: event)
    }

    /// The focused tile (from `reservedDispatchScope`'s `.tile(id)`) in the live
    /// canvas model, or nil when scope is canvas/modal or no canvas exists.
    private func focusedTile() -> Tile? {
        guard let canvasView, case let .tile(tileId) = reservedDispatchScope() else { return nil }
        return canvasView.tileRecord(for: tileId)
    }

    /// The focused tile's live VIEW (not just its model) — the surface browser/
    /// note executors act on. Resolves the same `reservedDispatchScope` `.tile(id)`
    /// as `focusedTile()` through the canvas's tile-view accessor; nil when scope
    /// is canvas/modal, no canvas exists, or the view isn't installed.
    private func focusedTileView() -> TileNSView? {
        guard let canvasView, case let .tile(tileId) = reservedDispatchScope() else { return nil }
        return canvasView.tileView(for: tileId)
    }

    /// Resize the focused tile to a preset. Keeps the tile's top-left origin
    /// (matches drag/world convention) for the scale ladder; `fillViewport`
    /// sets origin + size to the visible world rect.
    private func resizeFocusedTile(to preset: TileSizePreset) -> Bool {
        guard let canvasView, var tile = focusedTile() else { return false }
        if preset == .fillViewport {
            let visible = CanvasEngine.visibleWorldRect(viewport: canvasView.canvasState.viewport, visibleSize: canvasView.bounds.size)
            tile.frame = TileFrame(x: Double(visible.minX), y: Double(visible.minY), width: Double(visible.width), height: Double(visible.height))
        } else {
            let base = TileGeometry.preset(for: tile.kind).defaultSize
            let scale = Self.resizeScale(for: preset)
            tile.frame = TileFrame(x: tile.frame.x, y: tile.frame.y, width: Double(base.width) * scale, height: Double(base.height) * scale)
        }
        _ = canvasView.performGeometryEdit(
            .resizeTileToPreset,
            tileIds: [tile.id],
            includeAllZones: true
        ) {
            canvasView.updateTile(tile, notifyChange: false)
        }
        return true
    }

    private func openFocusMode(primaryTileId: UUID) {
        guard focusModeSession == nil, let canvasView, let contentView = window?.contentView else { return }
        guard let primaryView = canvasView.tileView(for: primaryTileId) else { return }
        let companionId = focusModeCompanionAgent(for: primaryTileId)
        let companionView = companionId.flatMap { canvasView.tileView(for: $0) }
        let session = FocusModeSession(
            primaryTileId: primaryTileId,
            companionTileId: companionId,
            savedViewport: canvasView.canvasState.viewport,
            savedTiles: canvasView.canvasState.tiles,
            savedLastActiveTileId: canvasView.canvasState.lastActiveTileId,
            canvasView: canvasView,
            primaryView: primaryView,
            companionView: companionView
        )
        focusModeSession = session
        focusBroker.openModal(.focusMode)
        canvasView.isHidden = true
        contentView.addSubview(session.overlay)
        session.overlay.frame = contentView.bounds
        session.overlay.autoresizingMask = [.width, .height]
        workspaceRuntime?.enforceBrowserRuntimeBudget()
    }

    private func closeFocusMode() {
        guard let session = focusModeSession else { return }
        focusBroker.closeModal(.focusMode)
        session.restore()
        focusModeSession = nil
        canvasView?.isHidden = false
    }

    private func focusModeCompanionAgent(for primaryTileId: UUID) -> UUID? {
        guard let canvasView else { return nil }
        let primaryZoneId = canvasView.activeZone?.zoneId ?? canvasView.navZoneRenderModels.first?.placement.zoneId ?? UUID()
        let currentTerminalTileIds = Set(canvasView.canvasState.tiles.filter { $0.kind == .terminal }.map(\.id))
        let sessions = (try? projectStore?.listSessions()) ?? []
        let agentTileIds = Set(sessions.filter { currentTerminalTileIds.contains($0.tileId) && $0.agentDescriptor != nil }.map(\.tileId))
        let candidates = canvasView.canvasState.tiles.map { tile in
            FocusModePairingCandidate(
                tileId: tile.id,
                zoneId: primaryZoneId,
                isAgent: agentTileIds.contains(tile.id),
                status: canvasView.agentStatus(for: tile.id) ?? sessions.first(where: { $0.tileId == tile.id })?.agentDescriptor?.status,
                lastActiveAt: tile.id == canvasView.canvasState.lastActiveTileId ? Date() : nil
            )
        }
        return FocusModePairing.companionAgent(for: primaryTileId, primaryZoneId: primaryZoneId, candidates: candidates)
    }

    private func openProfilePalette(initialQuery: String = "") {
        // M1.11 (`.plans/46`): opens with NO active controller. A workspace with no
        // projects releases every controller, and this used to `guard` on one — so
        // ⌘K and the toolbar's "Add or jump…" did nothing at all, silently, in the
        // one state where the user most needs a way to add something. The palette
        // is the app's only add surface; the toolbar `+` creates a workspace.
        //
        // `activeController` was only ever used for two things: the row set, which
        // `ZoneRuntimeController.paletteRows` can now build statically, and the
        // project name, which is genuinely absent here.
        guard let host = window else { return }
        let activeController = workspaceRuntime?.activeController
        demonstrateOnboarding(.commandCenterOpened)
        let palette = profilePalette ?? makeProfilePalette()
        let wasVisible = palette.isVisible
        let focusedTileId = focusedTileIdForPaletteContext()
        let focusedZoneId = focusedTileId.flatMap { canvasView?.zoneId(containing: $0) }
            ?? canvasView?.activeProjectZonePlacement?.zoneId
            ?? canvasView?.activeZone?.zoneId
        let contextualActions = contextualPaletteActions(for: focusedTileId)
        profilePalette = palette
        paletteContextTileId = focusedTileId
        paletteContextZoneId = focusedZoneId
        if !wasVisible {
            focusBroker.openModal(.palette)
        }
        let rows = activeController?.paletteRows(registryStore: registryStore)
            // No project means no project root, so a launch profile resolved against
            // one would be a fiction. The `.addProject` action below is what the
            // home offers instead.
            ?? ZoneRuntimeController.paletteRows(
                registryStore: registryStore, profiles: [], excludingProjectId: nil)
        let zoneNames = Dictionary(uniqueKeysWithValues: (canvasView?.navZoneRenderModels ?? []).map {
            ($0.placement.zoneId, $0.displayName)
        })
        let workspaceName = rows.workspaces.first(where: { $0.id == workspaceRuntime?.workspaceId })?.name
        let projectName = activeController?.project.name
        let jumpTiles = (canvasView?.navigationTileSnapshots() ?? []).map { tile in
            let agentID = agentSupervisor.agent(forTile: tile.tileId)
            let record = agentID.flatMap { agentSupervisor.records[$0] }
            let snapshot = agentID.flatMap { agentSupervisor.turnSnapshot(for: $0) }
            let state = snapshot.map(commandCenterAgentState)
            let zoneName = tile.zoneId.flatMap { zoneNames[$0] }?.trimmingCharacters(in: .whitespacesAndNewlines)
            let context = [workspaceName, zoneName?.isEmpty == false ? zoneName : projectName]
                .compactMap { $0 }
                .reduce(into: [String]()) { result, value in
                    if !result.contains(value) { result.append(value) }
                }
                .joined(separator: " · ")
            let modelID = record?.model
            let modelDisplayName = modelID.map {
                AgentModelCatalog.shared.displayName(for: $0)
                    ?? $0.split(separator: "/").last.map(String.init)
                    ?? $0
            }
            return JumpTileRow(
                id: tile.tileId,
                title: record?.displayName ?? (tile.title.isEmpty ? "Untitled Tile" : tile.title),
                kind: tile.kind,
                contextTitle: context.isEmpty ? nil : context,
                modelID: modelID,
                modelDisplayName: modelDisplayName,
                statusLabel: state?.label,
                attentionReason: state?.attention
            )
        }
        let jumpZones = (canvasView?.navZoneRenderModels ?? []).map { model in
            JumpZoneRow(id: model.placement.zoneId, title: model.displayName)
        }
        // Every agent with NO canvas tile. `jumpTiles` above is built from tiles on
        // the canvas, so it cannot represent any of them, and "closed" is not the
        // only tile-less lifecycle: an agent is also tile-less while headless,
        // snoozed or settled. Without this the command center can only reach agents
        // that happen to be on screen, which is why deleting the sidebar's inbox
        // would strand the rest (.plans/10-command-center-absorbs-sidebar.md).
        //
        // Membership is asked of InboxSort, never re-derived here, so the palette
        // and the inbox cannot disagree about what closed means
        // (.plans/05-close-to-history.md).
        let tilelessNow = Date()
        // Exclude anything jumpTiles already offers — one agent, one row.
        let tiledAgentIDs = Set((canvasView?.navigationTileSnapshots() ?? []).compactMap {
            agentSupervisor.agent(forTile: $0.tileId)?.rawValue
        })
        let tilelessAgents = buildAgentInboxRows(now: tilelessNow)
            .filter { !tiledAgentIDs.contains($0.id) }
            .map { row -> TilelessAgentPaletteRow in
                let state = agentSupervisor.turnSnapshot(for: AgentID(rawValue: row.id))
                    .map(commandCenterAgentState)
                return TilelessAgentPaletteRow(
                    agentId: row.id,
                    displayName: row.title,
                    detail: row.model.flatMap { AgentModelCatalog.shared.displayName(for: $0) ?? $0 },
                    isClosed: InboxSort.section(for: row.lifecycle, now: tilelessNow) == .history,
                    statusLabel: state?.label,
                    attentionReason: state?.attention)
            }
        palette.show(near: host, profiles: rows.profiles, projects: rows.projects, workspaces: rows.workspaces, contextualActions: contextualActions, harnessRoles: harnessRolesForActiveProject(), jumpTiles: jumpTiles, jumpZones: jumpZones, tilelessAgents: tilelessAgents, initialQuery: initialQuery, filesystemCreationPreview: creationScopePreviewText())
    }

    private func creationScopePreviewText() -> String? {
        guard let scope = resolvedCreationScope() else { return "Choose Project / Home…" }
        let registry = (try? registryStore?.loadOrEmpty()) ?? Registry.empty()
        let projectName = registry.projects.first(where: { $0.id == scope.projectId })?.name
            ?? URL(fileURLWithPath: scope.projectRoot, isDirectory: true).lastPathComponent
        let home = scope.homeRelativePath?.isEmpty == false ? scope.homeRelativePath! : "Project Root"
        var parts = ["\(projectName) / \(home)"]
        if let tileId = focusedTileIdForPaletteContext(),
           let agentId = agentSupervisor.agent(forTile: tileId),
           let record = agentSupervisor.records[agentId],
           record.projectId == scope.projectId,
           let branch = record.worktreeBranch, !branch.isEmpty {
            parts.append(branch)
        }
        return parts.joined(separator: " · ")
    }

    private func commandCenterAgentState(
        _ snapshot: AgentTileTurnSnapshot
    ) -> (label: String, attention: CommandCenterAttentionReason?) {
        switch snapshot.state {
        case .ready: return (AgentStatusVocabulary.label(for: .idle), nil)
        case .working: return (AgentStatusVocabulary.label(for: .working), nil)
        case .queued: return ("Queued", nil)
        case let .needsAction(request):
            let attention: CommandCenterAttentionReason = request.kind == .approval ? .approval : .input
            return (AgentStatusVocabulary.label(for: .needsAttention), attention)
        case .failed: return (AgentStatusVocabulary.failed, nil)
        case .restored: return ("Restored", nil)
        case .starting: return (AgentStatusVocabulary.starting, nil)
        }
    }

    private func focusedTileIdForPaletteContext() -> UUID? {
        guard let canvasView else { return nil }
        guard case let .tile(tileId) = reservedDispatchScope(),
              canvasView.tileRecord(for: tileId) != nil else { return nil }
        return tileId
    }

    private func tileKind(for tileId: UUID?) -> TileKind? {
        guard let tileId else { return nil }
        return canvasView?.tileRecord(for: tileId)?.kind
    }

    private func contextualPaletteActions(for focusedTileId: UUID?) -> [LaunchPaletteAction] {
        var actions: [LaunchPaletteAction] = []
        if tileKind(for: focusedTileId) == .browser { actions.append(.openInspectorForFocusedBrowser) }
        let zoneId = focusedTileId.flatMap { canvasView?.zoneId(containing: $0) }
            ?? canvasView?.activeProjectZonePlacement?.zoneId
            ?? canvasView?.activeZone?.zoneId
        if zoneId != nil {
            actions += [.renameCurrentZone, .pickCurrentZoneColor, .changeCurrentZoneScope, .toggleCurrentZoneAutoLayout, .tidyCurrentZone]
        }
        return actions
    }

    private func contextualPaletteActionsForFocusedTile() -> [LaunchPaletteAction] {
        contextualPaletteActions(for: focusedTileIdForPaletteContext())
    }

    private func harnessRolesForActiveProject() -> [HarnessRole] {
        guard let rootPath = workspaceRuntime?.activeController?.project.rootPath else { return [] }
        // P2D.3: discovery lives in `RoleRegistry` now, so the palette and a spawn's
        // role resolution read the same list from the same code.
        return RoleRegistry(projectRoot: URL(fileURLWithPath: rootPath, isDirectory: true)).roles()
    }

    private func makeProfilePalette() -> LaunchProfilePalette {
        let palette = LaunchProfilePalette()
        palette.onSelectProfile = { [weak self] profileId in
            self?.spawnTerminalFromProfile(profileId, trigger: "palette:\(profileId)") ?? false
        }
        palette.onSelectAgentModel = { [weak self] modelID in
            self?.spawnManagedAgentFromPalette(model: modelID) ?? false
        }
        palette.onSelectAction = { [weak self] action in
            self?.performPaletteAction(action) ?? false
        }
        // Reuse the inbox's reveal wholesale rather than re-deriving it: it already
        // reopens the record, gives the agent a tile again (a closed agent has
        // none), reveals it, clears the unread mark and arms focus — in that order,
        // for reasons documented at that call site.
        palette.onOpenTilelessAgent = { [weak self] agentId in
            self?.revealAgentFromInbox(agentId) ?? false
        }
        palette.onClose = { [weak self] in
            self?.focusBroker.closeModal(.palette)
            self?.profilePalette = nil
            self?.paletteContextTileId = nil
            self?.paletteContextZoneId = nil
        }
        return palette
    }

