            } catch {
                Logger(subsystem: "continuum.companion", category: "sync").error("manual publish failed: \(String(describing: error), privacy: .public)")
                Self.appendCompanionSyncLog("manual publish FAILED: \(String(describing: error))")
            }
        }
    }

