                Self.appendCompanionSyncLog("manual fetch FAILED: \(String(describing: error))")
            }
        }
    }

    @MainActor
    private func scheduleCompanionSyncPublish(
        reason: DesktopCompanionPublishReason,
        diagnosticsReason: String,
        debounce: TimeInterval
    ) {
        companionPublishDebounceWorkItem?.cancel()
        let workItem = DispatchWorkItem { [weak self] in
            Task { @MainActor in
                guard let self else { return }
                self.companionPublishDebounceWorkItem = nil
                await self.publishCompanionSync(reason: reason, diagnosticsReason: diagnosticsReason)
            }
        }
        companionPublishDebounceWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + debounce, execute: workItem)
    }

    @MainActor
    private func publishCompanionSync(reason: DesktopCompanionPublishReason, diagnosticsReason: String) async {
        do {
            let service = try ensureDesktopCompanionSyncService()
            try await service.start()
            try await service.publishCurrentDesktopSnapshot(reason: reason)
            await logCompanionSyncDiagnostics(reason: diagnosticsReason)
        } catch {
            Logger(subsystem: "continuum.companion", category: "sync").error("scheduled publish failed reason=\(reason.rawValue, privacy: .public): \(String(describing: error), privacy: .public)")
        }
    }

    private func startDesktopCompanionSyncService() {
        Task { @MainActor in
            do {
                let service = try ensureDesktopCompanionSyncService()
                try await service.start()
                try await service.fetchChanges(reason: .startup)
                try await service.publishCurrentDesktopSnapshot(reason: .startup)
                await logCompanionSyncDiagnostics(reason: "startup")
            } catch {
                Logger(subsystem: "continuum.companion", category: "sync").error("startup failed: \(String(describing: error), privacy: .public)")
            }
        }
    }

    private func ensureDesktopCompanionSyncService() throws -> DesktopCompanionSyncService {
        if let companionSyncService { return companionSyncService }

        // D4-R1 (ticket 86): a configured relay URL selects the self-owned
        // relay transport — no iCloud entitlement, no CloudKit. Absent that,
        // the parked CloudKit path below still works unchanged.
        let hostedIdentity = try companionRelayProvisioning.loadIdentity()
        let relayConfig = hostedIdentity.map {
            RelayClientConfig(baseURL: companionRelayProvisioning.httpOrigin, operatorToken: $0.credential)
        } ?? RelayClientConfig.resolve()
        if let relayConfig {
            guard let operatorToken = relayConfig.operatorToken, !operatorToken.isEmpty else {
                throw CompanionSyncAppError.missingRelayOperatorToken
            }
            let transport = RelaySyncTransport(
                baseURL: relayConfig.baseURL,
                bearerToken: operatorToken,
                deviceLabel: "mac-desktop",
                startAtHead: true,
                apiVersion: hostedIdentity == nil ? .legacyV1 : .hardenedV2
            )
            transport.start()
            relaySyncTransport = transport
            relayTokenSyncTask?.cancel()
            relayTokenSyncTask = Task { @MainActor [weak self] in
                for await state in transport.connectionState {
                    guard case .connected = state else { continue }
                    guard let self else { return }
                    await self.registerActiveSessionTokensWithRelay(transport)
                }
            }
            let service = makeDesktopCompanionSyncService(
                configuration: DesktopCompanionSyncConfiguration(
                    containerIdentifier: "relay:\(relayConfig.baseURL.absoluteString)",
                    signedWithICloudEntitlement: false
                ),
                transport: transport,
                fetchChanges: {},        // the relay transport polls continuously
                ensureSubscription: {}   // no CK subscription in relay mode
            )
            companionSyncService = service
            return service
        }

        let signedWithICloudEntitlement = Self.hasICloudEntitlement(containerIdentifier: CompanionSyncConfig.cloudKitContainerIdentifier)
        guard signedWithICloudEntitlement else {
            throw CompanionSyncAppError.missingICloudEntitlement(containerIdentifier: CompanionSyncConfig.cloudKitContainerIdentifier)
        }
        let transport = CloudKitSyncTransport(containerIdentifier: CompanionSyncConfig.cloudKitContainerIdentifier)
        let service = makeDesktopCompanionSyncService(
            configuration: DesktopCompanionSyncConfiguration(
                containerIdentifier: CompanionSyncConfig.cloudKitContainerIdentifier,
                signedWithICloudEntitlement: signedWithICloudEntitlement
            ),
            transport: transport,
            fetchChanges: {
                try await transport.fetchChanges()
            },
            ensureSubscription: {
                try await transport.ensureSubscription()
            }
        )
        companionSyncService = service
        return service
    }

    private func makeDesktopCompanionSyncService(
        configuration: DesktopCompanionSyncConfiguration,
        transport: any ContinuumRevivedSync.SyncTransport,
        fetchChanges: @escaping @Sendable () async throws -> Void,
        ensureSubscription: @escaping @Sendable () async throws -> Void
    ) -> DesktopCompanionSyncService {
        let authService = companionAuthService
        let transcriptStore = agentTranscriptStore
        let supervisor = agentSupervisor
        return DesktopCompanionSyncService(
            configuration: configuration,
            transport: transport,
            pairingSnapshot: { [weak self] in
                guard let self else {
                    return DesktopCompanionPairingSnapshot.unpaired(instanceId: UUID(uuidString: "00000000-0000-4000-8000-000000000075")!)
                }
                return await self.desktopCompanionPairingSnapshot()
            },
            canvasSnapshot: { [weak self] in
                try await MainActor.run {
                    guard let self, let canvasView = self.canvasView else {
                        throw CompanionSyncAppError.missingCanvas
                    }
                    let workspace = self.workspaceRuntime?.document ?? WorkspaceDocument(
                        viewport: canvasView.canvasState.viewport,
                        zones: [],
                        lastActiveZoneId: nil
                    )
                    // Once WorkspaceRuntime installs ZoneLayers, the flat
                    // `canvasState.tiles` collection is intentionally no longer
                    // the source of truth. Export every installed tile in world
                    // coordinates so the companion receives the contents of each
                    // workspace zone, not just the zone geometry.
                    var companionCanvas = canvasView.canvasState
                    companionCanvas.tiles = canvasView.allTilesInWorldFrames()
                    return (companionCanvas, workspace)
                }
            },
            // P2B.4: the phone is published from the SAME value the desktop is
            // showing. This closure used to build its own — the active project's
            // sessions only, with its own status map — which is how a status could be
            // on the phone and not in the sidebar, and vice versa.
            //
            // DELIBERATE DEVIATION from the packet's "returns it directly": it
            // recomputes first, as a reader (see the invariant at
            // `AgentActivitySurface`). Returning the stored value alone would publish
            // `.empty` on the startup and pairing publishes, which run before any
            // surface refresh has happened — the phone would show an empty inbox
            // until something else moved. `--agent-inventory-wiring-check` gates that
            // this closure holds NO derivation of its own.
            activitySnapshot: { [weak self] in
                try await MainActor.run {
                    guard let self else { return ActivityLogSnapshot.empty }
                    self.rebuildAgentActivitySnapshot()
                    // P3.2: SKIP the publish rather than send an empty inventory. The
                    // provider is `async throws` and `publishCurrentDesktopSnapshot`
                    // calls it BEFORE either `demux.send`, so throwing here leaves the
                    // phone holding the last inventory it was given instead of being
                    // told every agent vanished. The startup and pairing publishes are
                    // exactly the two that can run before the sweep has committed.
                    guard self.agentActivity.isReconciled else {
                        throw CompanionSyncAppError.managedSessionsUnreconciled
                    }
                    return self.agentActivity.snapshot
                }
            },
            transcriptChannels: {
                guard let auth = authService,
                      let instance = try? await auth.instance() else { return [] }
                return await auth.activeSessionTokens().compactMap { session in
                    guard session.scopes.contains(.transcriptRead) else { return nil }
                    return TranscriptSyncCrypto.derivePairedSessionChannel(
                        token: session.token,
                        pairingID: instance.id
                    )
                }
            },
            transcriptDocument: { rawAgentID in
                let agentID = AgentID(rawValue: rawAgentID)
                // C3: this asked for the literal "thread-main" while the writer
                // used the TILE's thread id, so the companion never once found a
                // transcript. Both ends now name the agent.
                let sessionID = AgentTranscriptStore.canonicalSessionID(for: agentID)
                guard let document = try? await transcriptStore.load(
                    agentID: agentID,
                    sessionID: sessionID
                ) else { return nil }
                return (sessionID: sessionID, document: document)
            },
            stopAgent: { rawAgentID in
                await MainActor.run {
                    let agentID = AgentID(rawValue: rawAgentID)
                    guard supervisor.records[agentID] != nil else { return .notFound }
                    supervisor.stop(agentID)
                    return .stopped
                }
            },
            freshnessPublisher: DesktopCompanionLogFreshnessPublisher(),
            fetchChanges: fetchChanges,
            ensureSubscription: ensureSubscription
        )
    }

    private func desktopCompanionPairingSnapshot() async -> DesktopCompanionPairingSnapshot {
        do {
            if let hostedIdentity = try companionRelayProvisioning.loadIdentity() {
                let devices = try await companionRelayProvisioning.devices()
                return .hostedRelay(
                    instanceId: hostedIdentity.instanceID,
                    pairedDeviceCount: devices.count
                )
            }
            guard let companionAuthService else {
                return DesktopCompanionPairingSnapshot.unpaired(instanceId: UUID(uuidString: "00000000-0000-4000-8000-000000000075")!)
            }
            let instance = try await companionAuthService.instance()
            let devices = try await companionAuthService.listDevices().filter { $0.revokedAt == nil }
            let scope = devices.reduce(Scope()) { partial, device in partial.union(device.scopes) }
            guard !devices.isEmpty else {
                return DesktopCompanionPairingSnapshot.unpaired(instanceId: instance.id)
            }
            return DesktopCompanionPairingSnapshot(
                instanceId: instance.id,
                pairedDeviceCount: devices.count,
                authorizedScope: scope
            )
        } catch {
            Logger(subsystem: "continuum.companion", category: "sync").error("pairing snapshot failed: \(String(describing: error), privacy: .public)")
            return DesktopCompanionPairingSnapshot.unpaired(instanceId: UUID(uuidString: "00000000-0000-4000-8000-000000000075")!)
        }
    }

    /// Append one diagnostics line to app support (companion-sync.log).
    /// Unified log proved unreadable on the dogfood host (`log show` returns
    /// nothing even for a probe process), so the Phase-3 "diagnostic log line"
    /// contract needs a file the operator can actually read. Same sanitized
    /// content as the Logger line — counts, timestamps, and error summaries
    /// only; never transcript/paths/pids.
    nonisolated static func appendCompanionSyncLog(_ line: String) {
        let url = RegistryStore.defaultApplicationSupportDirectory()
            .appendingPathComponent("companion-sync.log", isDirectory: false)
        let stamped = "\(ISO8601DateFormatter().string(from: Date())) \(line)\n"
        guard let data = stamped.data(using: .utf8) else { return }
        if let handle = try? FileHandle(forWritingTo: url) {
            defer { try? handle.close() }
            _ = try? handle.seekToEnd()
            try? handle.write(contentsOf: data)
        } else {
            try? FileManager.default.createDirectory(
                at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            try? data.write(to: url)
        }
    }

    private func logCompanionSyncDiagnostics(reason: String) async {
        guard let companionSyncService else {
            Self.appendCompanionSyncLog("reason=\(reason) service=nil (ensureDesktopCompanionSyncService never succeeded)")
            return
        }
        let diagnostics = await companionSyncService.diagnostics
        let registeredObservedAgents = ((try? projectStore?.listSessions()) ?? [])
            .filter { $0.agentDescriptor != nil }
            .count
        // P2B.4: the observer's own map, which is what this field has always meant.
        // It used to be recomputed here from the active project's sessions; that
        // walk is now part of the one snapshot rebuild and not a diagnostic's job.
        let liveObservedAgents = observedAgentStatuses.count
        // P3.2: this line is what an operator reads when the phone shows no agents,
        // so a refused read must say so. A count of 0 from a read that never happened
        // is a lie in a log file.
        var managedAgentSessions = "unreconciled"
        if let activeStore = workspaceRuntime?.activeController?.managedSessionStore,
           let proof = try? reconciledManagedSessionSource.proof() {
            do {
                managedAgentSessions = String(try activeStore.reconciledRecords(proof)
                    .filter { $0.agentKind == .managed }
                    .count)
            } catch {
                managedAgentSessions = "unreadable"
            }
        }
        Logger(subsystem: "continuum.companion", category: "sync").notice(
            "reason=\(reason, privacy: .public) container=\(diagnostics.containerIdentifier, privacy: .public) paired=\(diagnostics.isPaired, privacy: .public) pairedDevices=\(diagnostics.pairedDeviceCount, privacy: .public) signedICloud=\(diagnostics.signedWithICloudEntitlement, privacy: .public) transportIsPairingProof=\(diagnostics.transportIsPairingProof, privacy: .public) registeredObservedAgents=\(registeredObservedAgents, privacy: .public) liveObservedAgents=\(liveObservedAgents, privacy: .public) managedAgentSessions=\(managedAgentSessions, privacy: .public) lastSpatial=\(String(describing: diagnostics.lastSpatialPublishAt), privacy: .public) lastActivity=\(String(describing: diagnostics.lastActivityPublishAt), privacy: .public) lastFetch=\(String(describing: diagnostics.lastFetchAt), privacy: .public) lastInbound=\(String(describing: diagnostics.lastInboundMessageKind), privacy: .public) lastApproval=\(String(describing: diagnostics.lastApprovalResponseOutcome), privacy: .public) lastError=\(String(describing: diagnostics.lastError), privacy: .public)"
        )
        Self.appendCompanionSyncLog(
            "reason=\(reason) transport=\(relaySyncTransport != nil ? "relay" : "cloudkit") container=\(diagnostics.containerIdentifier) paired=\(diagnostics.isPaired) pairedDevices=\(diagnostics.pairedDeviceCount) signedICloud=\(diagnostics.signedWithICloudEntitlement) registeredObservedAgents=\(registeredObservedAgents) liveObservedAgents=\(liveObservedAgents) managedAgentSessions=\(managedAgentSessions) lastSpatial=\(String(describing: diagnostics.lastSpatialPublishAt)) lastActivity=\(String(describing: diagnostics.lastActivityPublishAt)) lastFetch=\(String(describing: diagnostics.lastFetchAt)) lastError=\(String(describing: diagnostics.lastError))"
        )
    }

    private static func hasICloudEntitlement(containerIdentifier: String) -> Bool {
        hasMainBundleICloudEntitlement(containerIdentifier: containerIdentifier)
    }

    private enum CompanionSyncAppError: Error, CustomStringConvertible {
        case missingCanvas
        case missingICloudEntitlement(containerIdentifier: String)
        case missingRelayOperatorToken
        /// P3.2: refuse the publish rather than send an inventory built from records
        /// nobody has reconciled. Host-side only — this never crosses to the phone.
        case managedSessionsUnreconciled

        var description: String {
            switch self {
            case .managedSessionsUnreconciled:
                return "managed sessions are not reconciled yet; skipping this activity publish rather than publishing an empty inventory"
            case .missingCanvas:
                return "missing canvas"
            case let .missingICloudEntitlement(containerIdentifier):
                return "missing CloudKit entitlement for \(containerIdentifier); companion sync is disabled for this launch"
            case .missingRelayOperatorToken:
                return "relay URL is configured but no operator token is set (continuum.relay.operatorToken / CONTINUUM_RELAY_OPERATOR_TOKEN)"
            }
        }
    }

    /// WS7. The editor writes through `WorkspaceRuntime` — the one workspace
    /// writer — and through the channel-local global store. Nothing here
    /// persists a picked URL: `importImage` copies the bytes into the managed
    /// directory and returns a content-digest id.
    /// WS7: the reference-aware deferred sweep the locked contract calls for.
    ///
    /// Without this, `cleanup(referencedIDs:)` had NO production caller: every
    /// imported background stayed on disk forever, and "Remove Image" — whose own
    /// comment promised a deferred sweep — freed nothing. Imports are bounded at
    /// 64 MB each, so the directory grows without limit.
    ///
    /// The referenced set spans the channel-local global AND every workspace's
    /// override, read straight from disk rather than from the mounted runtime:
    /// sweeping against only the active workspace would delete an image another
    /// workspace still names. A workspace whose document cannot be read is
    /// treated as referencing everything — it contributes no ids, so the grace
    /// window keeps its assets rather than risking deletion on a transient read
    /// failure.
    /// QA seam: which defaults the sweep reads the global configuration from.
    /// Production leaves this nil and uses the channel's standard domain.
    var qaCanvasBackgroundSweepDefaults: UserDefaults?

    @discardableResult
    func sweepCanvasBackgroundAssets(
        grace: TimeInterval = CanvasBackgroundAssetStore.cleanupGrace
    ) -> CanvasBackgroundAssetStore.CleanupResult? {
        guard let registryStore else { return nil }
        // `resolveAppSupportDir` returns nil in production — it answers only for a
        // QA override or a smoke test — so a `guard let` on it would have made
        // this sweep dead code in the shipping app, which is precisely the bug it
        // exists to fix. Fall through to the canonical directory the way
        // `resolveAuthDirectory` does.
        let appSupport = Self.resolveAppSupportDir(smokeTest: false)
            ?? RegistryStore.defaultApplicationSupportDirectory()
        let registry = (try? registryStore.loadOrEmpty()) ?? Registry.empty()
        var configurations: [CanvasBackgroundConfiguration] = [
            qaCanvasBackgroundSweepDefaults.map { CanvasBackgroundGlobalStore.load(defaults: $0) }
                ?? CanvasBackgroundGlobalStore.load()
        ]
        var unreadableWorkspaces = 0
        for workspace in registry.workspaces {
            guard let document = try? WorkspaceStore(
                workspaceId: workspace.id, applicationSupportDirectory: appSupport).load() else {
                unreadableWorkspaces += 1
                continue
            }
            if let override = document.canvasBackground.overrideConfiguration {
                configurations.append(override)
            }
        }
        // A document we could not read might name an asset. Refuse to sweep at
        // all rather than delete something we cannot prove is unreferenced.
        guard unreadableWorkspaces == 0 else { return nil }
        let referenced = CanvasBackgroundAssetStore.referencedAssetIDs(in: configurations)
        return CanvasBackgroundAssetStore(applicationSupportDirectory: appSupport)
            .cleanup(referencedIDs: referenced, grace: grace)
    }

    private func makeCanvasBackgroundSettingsView() -> NSView {
        let assetStore = CanvasBackgroundAssetStore()
        let environment = CanvasBackgroundSettingsView.Environment(
            loadGlobal: { CanvasBackgroundGlobalStore.load() },
            saveGlobal: { [weak self] config in
                CanvasBackgroundGlobalStore.save(config)
                self?.workspaceRuntime?.applyCanvasBackground()
                // Changing a configuration is the only way an asset becomes
                // orphaned, so it is the only place worth sweeping. The store's
                // grace window means a file orphaned by THIS write is retained
                // now and collected by a later sweep, which is what makes the
                // cleanup "deferred" rather than destructive.
                self?.sweepCanvasBackgroundAssets()
            },
            loadWorkspace: { [weak self] in self?.workspaceRuntime?.document.canvasBackground ?? .inherit },
            saveWorkspace: { [weak self] value in
                try? self?.workspaceRuntime?.setWorkspaceCanvasBackground(value)
                self?.sweepCanvasBackgroundAssets()
            },
            importImage: { try assetStore.importImage(at: $0) },
            chooseImageURL: {
                let panel = NSOpenPanel()
                panel.allowsMultipleSelection = false
                panel.canChooseDirectories = false
                panel.allowedFileTypes = Array(CanvasBackgroundAssetID.allowedExtensions)
                panel.prompt = "Use Image"
                return panel.runModal() == .OK ? panel.url : nil
            },
            hasWorkspace: workspaceRuntime != nil)
        return CanvasBackgroundSettingsView(environment: environment)
    }

    private func makeSettingsPanel() -> SettingsPanel {
        let panel = SettingsPanel(
            navKeymap: navKeymap,
            customSectionViews: [
                "companion": { [weak self] in
                    self?.makeCompanionSettingsView() ?? NSView()
                },
                "canvasBackground": { [weak self] in
                    self?.makeCanvasBackgroundSettingsView() ?? NSView()
                },
            ]
        )
        panel.onClose = { [weak self] in
            self?.focusBroker.closeModal(.settings)
            self?.settingsPanel = nil
            // Pick up Navigation-section edits (leader modifier / hold delay), which
            // persist to continuum.keymap.* but don't flow through onKeymapChanged.
            self?.applyEditedNavKeymap(NavKeymap.resolve())
        }
        panel.onKeymapChanged = { [weak self] keymap in
            self?.applyEditedNavKeymap(keymap)
        }
        panel.onShortcutsChanged = { [weak self] in
            self?.refreshRegisteredShortcutSurfaces()
        }
        return panel
    }

    private func makeWorkspaceContentView(canvasView: CanvasNSView, frame: NSRect) -> NSView {
        let splitView = NSSplitView(frame: frame)
        splitView.isVertical = true
        splitView.dividerStyle = .thin
        splitView.autoresizingMask = [.width, .height]
        splitView.delegate = self

        let width = CGFloat(WorkspaceSidebarConfig.resolveWidth())
        let divider = splitView.dividerThickness
        let sidebar = WorkspaceSidebarView(frame: NSRect(x: 0, y: 0, width: width, height: frame.height))
        sidebar.autoresizingMask = [.height]
        configureWorkspaceSidebar(sidebar)

        // This is the persistent LEFT workspace sidebar. It is intentionally
        // distinct from the old bug where the ⌘K overlay was adopted by this
        // split view and rendered as a right-edge pane. The plain container
        // returned below prevents that overlay regression while preserving this
        // actual workspace surface.

        let contentPane = NSView(frame: NSRect(x: width + divider, y: 0, width: max(0, frame.width - width - divider), height: frame.height))
        contentPane.autoresizingMask = [.width, .height]
        let topBar = WorkspaceTopBarView(frame: NSRect(x: 0, y: max(0, frame.height - 38), width: contentPane.bounds.width, height: 38))
        configureWorkspaceTopBar(topBar)
        let shortcutRail = CanvasShortcutRailView(frame: .zero)
        shortcutRail.onOpenCommandCenter = { [weak self] in self?.openProfilePalette() }
        shortcutRail.onOpenKeybindings = { [weak self] in self?.openKeybindingsSettings() }
        let gettingStarted = CanvasGettingStartedView(frame: .zero)
        gettingStarted.onOpenCommandCenter = { [weak self] in self?.openProfilePalette() }
        gettingStarted.onShowZoneActions = { [weak self] in self?.openProfilePalette(initialQuery: "This Zone") }
        gettingStarted.onSkipTask = { [weak self] task in self?.skipGettingStartedTask(task) }

        topBar.translatesAutoresizingMaskIntoConstraints = false
        canvasView.translatesAutoresizingMaskIntoConstraints = false
        contentPane.addSubview(topBar)
        contentPane.addSubview(canvasView)
        shortcutRail.translatesAutoresizingMaskIntoConstraints = false
        contentPane.addSubview(shortcutRail, positioned: .above, relativeTo: canvasView)
        gettingStarted.translatesAutoresizingMaskIntoConstraints = false
        contentPane.addSubview(gettingStarted, positioned: .above, relativeTo: canvasView)
        NSLayoutConstraint.activate([
            topBar.leadingAnchor.constraint(equalTo: contentPane.leadingAnchor),
            topBar.trailingAnchor.constraint(equalTo: contentPane.trailingAnchor),
            topBar.topAnchor.constraint(equalTo: contentPane.topAnchor),
            topBar.heightAnchor.constraint(equalToConstant: 38),

            canvasView.leadingAnchor.constraint(equalTo: contentPane.leadingAnchor),
            canvasView.trailingAnchor.constraint(equalTo: contentPane.trailingAnchor),
            canvasView.topAnchor.constraint(equalTo: topBar.bottomAnchor),
            canvasView.bottomAnchor.constraint(equalTo: contentPane.bottomAnchor),

            shortcutRail.trailingAnchor.constraint(equalTo: contentPane.trailingAnchor, constant: -12),
            shortcutRail.bottomAnchor.constraint(equalTo: contentPane.bottomAnchor, constant: -12),

            gettingStarted.leadingAnchor.constraint(equalTo: contentPane.leadingAnchor, constant: 12),
            gettingStarted.topAnchor.constraint(equalTo: topBar.bottomAnchor, constant: 12),
        ])

        splitView.addSubview(sidebar)
        splitView.addSubview(contentPane)
        workspaceSidebarView = sidebar
        workspaceTopBarView = topBar
        canvasShortcutRailView = shortcutRail
        canvasGettingStartedView = gettingStarted
        workspaceSplitView = splitView
        refreshGettingStartedTasks()
        reloadWorkspaceSidebar()
        applyWorkspaceSidebarVisibility(WorkspaceSidebarConfig.resolveVisible())

        // Return a PLAIN container, not the split view itself.
        //
        // The window's contentView is what every overlay adds itself to
        // (`LaunchProfilePalette.show` does `host.contentView.addSubview(...)`).
        // While that was the NSSplitView, the split view adopted ⌘K as a PANE and
        // overwrote its frame on the next layout pass — so the command center's
        // carefully computed centred 660×520 float was discarded and it rendered
        // full-height against the window edge, i.e. as a sidebar. That is the
        // "⌘K still opens a sidebar" report, and it survived deleting the real
        // sidebar because the offender was the HOST, not the sidebar.
        //
        // A plain NSView does not lay out its children, so an overlay keeps the
        // frame it asked for.
        let container = NSView(frame: frame)
        container.autoresizingMask = [.width, .height]
        splitView.frame = container.bounds
        container.addSubview(splitView)
        return container
    }

    private func configureWorkspaceSidebar(_ sidebar: WorkspaceSidebarView) {
        sidebar.onSelection = { [weak self] selection in
            self?.handleWorkspaceSidebarSelection(selection)
        }
        sidebar.onCreateWorkspace = { [weak self] in
            self?.createWorkspaceFromChrome()
        }
        sidebar.onRenameWorkspace = { [weak self] workspaceId in
            self?.renameWorkspaceFromTopBar(workspaceId: workspaceId)
        }
        sidebar.onDeleteWorkspace = { [weak self] workspaceId in
            self?.deleteWorkspaceAndRelaunch(workspaceId: workspaceId)
        }
        // P3.8: the inbox scope survives a relaunch, and it is persisted here beside
        // the sidebar's width and visibility rather than inside the view — the view
        // is rendered by committed baselines and must not read anyone's defaults.
        sidebar.configureInboxScope(WorkspaceSidebarConfig.resolveScope()) { scope in
            WorkspaceSidebarConfig.setScope(scope)
        }
        // P3.9: the inbox is triage, the canvas is depth — a clicked row lands you on
        // the work.
        sidebar.configureInboxReveal { [weak self] agentId in
            self?.revealAgentFromInbox(agentId)
        }
        // P5.4: Space frames an existing tile without switching workspace,
        // changing tile focus, attaching a tile, or clearing the unread mark.
        sidebar.agentInbox.onPreviewRow = { [weak self] agentId in
            _ = self?.previewAgentFromInbox(agentId)
        }
        sidebar.configureInboxRename { [weak self] agentId, name in
            self?.renameAgentFromInbox(agentId, to: name)
        }
        // P3.15: the row menu and the bulk bar reach the supervisor. Until this call
        // existed the shipped app assigned neither callback, so every destructive item
        // was greyed and a stale agent could not be removed by any route.
        sidebar.configureInboxActions(
            rowActions: AppDelegate.wiredInboxRowActions,
            onRowAction: { [weak self] action, rowIds in
                self?.performInboxRowAction(action, on: rowIds)
            },
            bulkActions: AppDelegate.wiredInboxBulkActions,
            onBulkAction: { [weak self] action, rowIds in
                self?.performInboxBulkAction(action, on: rowIds)
            })
        // P6.3: the inbox resolves a preset at menu-open time and hands the
        // selected absolute wake to the supervisor; the supervisor writes both
        // snooze dates atomically.
        sidebar.agentInbox.onSnoozeSelection = { [weak self] rowIds, wakeAt in
            _ = self?.snoozeAgentsFromInbox(rowIds, wakeAt: wakeAt)
        }
        // P6.3: timer expiry is only a render signal. Rebuild from the current
        // records and real clock so an expired snooze changes lifecycle/variant;
        // reloading the view's already-derived rows would leave a stale shelf row.
        sidebar.agentInbox.onWakeRerender = { [weak self] in
            self?.reloadWorkspaceSidebar(rebuildAgentActivity: false)
        }
    }

    private func configureWorkspaceTopBar(_ topBar: WorkspaceTopBarView) {
        topBar.onOpenCommandCenter = { [weak self] in self?.openProfilePalette() }
        topBar.updateCommandCenterShortcut(resolvedShortcutDisplay(commandID: "app.commandCenter"))
        topBar.onSwitchWorkspace = { [weak self] workspaceId in
            self?.switchWorkspaceAndRelaunch(workspaceId: workspaceId)
        }
        topBar.onCreateWorkspace = { [weak self] in
            self?.createWorkspaceFromChrome()
        }
        topBar.onRenameWorkspace = { [weak self] workspaceId in
            self?.renameWorkspaceFromTopBar(workspaceId: workspaceId)
        }
        topBar.onDeleteWorkspace = { [weak self] workspaceId in
            self?.deleteWorkspaceAndRelaunch(workspaceId: workspaceId)
        }
        topBar.onToggleSidebar = { [weak self] in
            self?.toggleWorkspaceSidebar()
        }
    }

    private func resolvedShortcutDisplay(commandID: CommandID) -> String? {
        guard let registry = try? CommandRegistry.productRegistry(),
              let definition = registry.shortcuts.first(where: { $0.commandID == commandID }) else { return nil }
        return ShortcutBindingStore().gestures(for: definition).first?.displayString
    }

    private func refreshRegisteredShortcutSurfaces() {
        workspaceTopBarView?.updateCommandCenterShortcut(resolvedShortcutDisplay(commandID: "app.commandCenter"))
        canvasShortcutRailView?.reloadBindings(navKeymap: navKeymap)
        refreshGettingStartedTasks()
        ContinuumApp.refreshRegisteredCommandMenuItems()
    }

    private func currentWorkspaceIdForSidebar() -> UUID? {
        if let workspaceId = workspaceRuntime?.workspaceId { return workspaceId }
        guard let registryStore else { return nil }
        return (try? registryStore.loadOrEmpty())?.lastActiveWorkspaceId
    }

    private func buildWorkspaceTopBarModel() throws -> WorkspaceTopBarModel? {
        guard let registryStore else { return nil }
        let registry = try registryStore.loadOrEmpty()
        guard let currentWorkspaceId = currentWorkspaceIdForSidebar() ?? registry.lastActiveWorkspaceId else { return nil }
        let appSupport = registryStore.registryFile.deletingLastPathComponent()
        let document: WorkspaceDocument
        if let workspaceRuntime, workspaceRuntime.workspaceId == currentWorkspaceId {
            document = workspaceRuntime.document
        } else {
            let store = WorkspaceStore(workspaceId: currentWorkspaceId, applicationSupportDirectory: appSupport)
            document = try store.load()
        }
        let entry = registry.workspaces.first(where: { $0.id == currentWorkspaceId })
        return WorkspaceTopBarModel(
            currentWorkspaceId: currentWorkspaceId,
            currentWorkspaceName: entry?.name ?? "Workspace",
            projectCount: entry?.projectIds.count ?? 0,
            zoneCount: document.zones.count,
            saveState: workspaceDocumentSaveState(workspaceId: currentWorkspaceId, liveDocument: document),
            workspaces: registry.workspaces,
            managementMessage: workspaceManagementMessage
        )
    }

    private func workspaceDocumentSaveState(workspaceId: UUID, liveDocument: WorkspaceDocument) -> WorkspaceDocumentSaveState {
        guard let registryStore else { return .saved }
        let appSupport = registryStore.registryFile.deletingLastPathComponent()
        let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport)
        do {
            guard let persisted = try store.tryLoad() else { return .unsavedChanges }
            return persisted == liveDocument ? .saved : .unsavedChanges
        } catch {
            return .saveFailed
        }
    }

    private func reloadWorkspaceTopBar() {
        guard let topBar = workspaceTopBarView else { return }
        do {
            if let model = try buildWorkspaceTopBarModel() {
                topBar.reload(model)
            }
        } catch {
            fputs("Workspace top bar reload failed: \(error)\n", stderr)
        }
    }

    private func buildWorkspaceSidebarTree() throws -> SidebarTree {
        guard let registryStore else { return SidebarTree(workspaces: []) }
        let registry = try registryStore.loadOrEmpty()
        let appSupport = registryStore.registryFile.deletingLastPathComponent()
        var documents: [UUID: WorkspaceDocument] = [:]
        for workspace in registry.workspaces {
            let store = WorkspaceStore(workspaceId: workspace.id, applicationSupportDirectory: appSupport)
            if let document = try? store.tryLoad() {
                documents[workspace.id] = document
            }
        }
        if let workspaceRuntime {
            documents[workspaceRuntime.workspaceId] = workspaceRuntime.document
        }
        let projectCanvases = workspaceSidebarProjectCanvasSnapshots(registry: registry)
        return SidebarTreeBuilder.build(
            registry: registry,
            documents: documents,
            projectCanvases: projectCanvases,
            // P2B.4: from the one snapshot. This used to be its own walk over every
            // project's sessions with the observer map layered on top — a third
            // reading of the same statuses the badges and the dock were computing
            // separately, and the reason a tile could carry one status while its
            // sidebar row carried another.
            agentStatusesByTileId: agentStatusesByTileId()
        )
    }

    private func workspaceSidebarProjectCanvasSnapshots(registry: Registry) -> [UUID: CanvasState] {
        var snapshots: [UUID: CanvasState] = [:]
        for project in registry.projects {
            let store = ProjectStore(projectRoot: URL(fileURLWithPath: project.rootPath, isDirectory: true))
            if let canvas = try? store.tryLoadCanvas() {
                snapshots[project.id] = canvas
            }
        }
        if let activeProjectId = workspaceRuntime?.activeController?.project.id,
           let canvasView {
            snapshots[activeProjectId] = canvasView.canvasState
        }
        return snapshots
    }

    /// `rebuildAgentActivity: false` is for `refreshAgentSurfaces`, which has just
    /// rebuilt the snapshot and is pushing that same value at every surface —
    /// rebuilding again here would walk every project's store a second time for a
    /// result that cannot have changed. Every other caller (a rename, a zone edit, a
    /// workspace switch) wants the fresh read the old per-reload walk gave it.
    /// P3.6: the inbox's rows, from the SAME snapshot every other surface reads.
    ///
    /// Filtered by `managedAgentIdentities`, which is where this list's membership
    /// policy is written down (P3.16). It excludes what `agentIdentities` excludes for
    /// every surface — a terminal session with no `AgentDescriptor` is a plain shell,
    /// and a shell would otherwise arrive as a row titled "Agent" with no state — and
    /// then one thing more: a terminal session that IS running an agent. The inbox
    /// lists the agents Continuum owns.
    ///
    /// P3.8's force-include does not reach past this, and the answer is written down
    /// rather than discovered: the scope decides which of the list's rows are VISIBLE,
    /// this decides which rows EXIST, so focusing a terminal tile that runs an agent
    /// force-includes an id no row carries — a no-op, the same as focusing a note. The
    /// narrower change on purpose; the empty state below is what keeps the exclusion
    /// visible instead of silent.
    ///
    /// Read-state is layered on here rather than inside the fold, because
    /// `AgentSupervisor` owns it and Core cannot reach a supervisor (P3.3).
    private func buildAgentInboxRows(now: Date = Date()) -> [AgentInboxRow] {
        let registry = (try? registryStore?.loadOrEmpty()) ?? Registry.empty()
        var documents: [UUID: WorkspaceDocument] = [:]
        if let registryStore {
            let appSupport = registryStore.registryFile.deletingLastPathComponent()
            for workspace in registry.workspaces {
                let store = WorkspaceStore(workspaceId: workspace.id, applicationSupportDirectory: appSupport)
                if let document = try? store.tryLoad() { documents[workspace.id] = document }
            }
        }
        if let workspaceRuntime {
            documents[workspaceRuntime.workspaceId] = workspaceRuntime.document
        }
        let projectCanvases = workspaceSidebarProjectCanvasSnapshots(registry: registry)
        let records = agentSupervisor.records.values.sorted(by: AgentStore.isOrderedBefore)
        var checkedOutBranches: [UUID: String] = [:]
        var attention: [UUID: InboxAttention] = [:]
        // P3.3: the supervisor's turn snapshot is the row's ONE source of state. It is
        // resolved here, in the loop that already walks the records, because Core
        // cannot reach a supervisor — the same reason read-state is layered on here.
        var turnSnapshots: [UUID: AgentTileTurnSnapshot] = [:]
        var lifecycleFacts: [UUID: AgentLifecycleFacts] = [:]
        for record in records {
            if let branch = agentSupervisor.branchContextCachedOnly(for: record.id)?.checkedOutBranch {
                checkedOutBranches[record.id.rawValue] = branch
            }
            attention[record.id.rawValue] = agentSupervisor.attention(for: record.id, now: now)
            lifecycleFacts[record.id.rawValue] = AgentLifecycleFacts(
                hasLiveRunner: agentSupervisor.isRunning(record.id))
            if let snapshot = agentSupervisor.turnSnapshot(for: record.id) {
                turnSnapshots[record.id.rawValue] = snapshot
            }
        }
        let context = AgentContextIndex.build(
            registry: registry,
            documents: documents,
            projectCanvases: projectCanvases,
            terminalDescriptors: currentTerminalSessionDescriptors(registry: registry, projectCanvases: projectCanvases),
            agents: records,
            checkedOutBranches: checkedOutBranches
        )
        // P3.4 fence allowance: this is the single compiled call site where the
        // activity surface's observation fact can reach the rows. Stamping the
        // confidence modifier here preserves Core's pure join and keeps the
        // supervisor's turn snapshot as the sole state owner.
        let unobserved = agentActivity.unobservedAgentIds
        let builtRows = AgentInboxRowBuilder.rows(
            from: agentActivity.snapshot, context: context, attention: attention,
            turnSnapshots: turnSnapshots, records: Dictionary(uniqueKeysWithValues: records.map { ($0.id.rawValue, $0) }),
            lifecycleFacts: lifecycleFacts,
            autoSettleAfter: AgentAutoSettleConfig.resolvedFromDefaults().window,
            now: now
        )
        .filter { agentActivity.managedAgentIdentities.contains($0.id) }
        return unconfirmedFreeze.apply(rows: builtRows, unobserved: unobserved)
    }

    // Ticket: docs/38-tickets/90-agent-ux/P3.16-inbox-lists-agents-only.md
    /// How many agents the row-source policy above left out — agents running inside
    /// terminal tiles. The inbox needs the COUNT and nothing else: it is what makes
    /// its empty state honest ("No agents yet" in front of two working `claude`
    /// sessions is a lie), and a count cannot become a second way to list them.
    private func inboxExcludedTerminalAgentCount() -> Int {
        agentActivity.terminalHostedAgentIdentities.count
    }

    // Ticket: docs/38-tickets/90-agent-ux/P3.8-scope-dropdown.md
    /// The agent open in the focused tile, in the inbox's aggregate keyspace — the
    /// one row the scope may never hide.
    ///
    /// Two cases, because that keyspace has two halves (P3.1): a managed agent is
    /// keyed by its record, which `AgentSupervisor.agent(forTile:)` finds from the
    /// tile it is bound to, and a terminal-session agent is keyed by the TILE ID
    /// itself. The fallback is therefore the tile id, not nil. A focused tile that
    /// is neither — a note, a plain shell — yields an id no row carries, which makes
    /// the force-include a no-op rather than a special case.
    // Ticket: docs/38-tickets/90-agent-ux/P3.8-scope-dropdown.md
    /// Every project and workspace that is OPEN, as scopes — the packet's "one entry
    /// per open project · one per workspace".
    ///
    /// From the registry rather than from the rows, because a project with no agent
    /// running in it is exactly the one you are about to start an agent in, and a menu
    /// derived from the rows could not offer it. `missing` projects are left out: a
    /// checkout whose directory is gone is not open, and scoping to it could only ever
    /// be empty.
    private func inboxScopeCatalog(registry: Registry) -> [InboxScope] {
        return registry.projects.filter { !$0.missing }.map { .project($0.name) }
            + registry.workspaces.map { .workspace($0.name) }
    }

    private func focusedInboxAgentId() -> UUID? {
        guard let tileId = canvasView?.canvasState.lastActiveTileId else { return nil }
        return agentSupervisor.agent(forTile: tileId)?.rawValue ?? tileId
    }

    private func reloadWorkspaceSidebar(rebuildAgentActivity: Bool = true) {
        if rebuildAgentActivity { rebuildAgentActivitySnapshot() }
        defer { reloadWorkspaceTopBar() }
        guard let sidebar = workspaceSidebarView else { return }
        let registry = (try? registryStore?.loadOrEmpty()) ?? Registry.empty()
        // P3.6: the inbox is the sidebar's content, so it is fed on the same
        // reload. `applyInbox` and not `reloadInbox` — the change set says which
        // agents moved, and rebuilding every row for one streamed token is what
        // P2B.7 removed from the surfaces it could reach.
        // P3.8: BEFORE the rows, so the scope filter for this push already knows
        // which row it may not hide, and the popup can offer an open project the rows
        // do not mention.
        sidebar.setInboxOpenAgent(focusedInboxAgentId())
        sidebar.setInboxScopeCatalog(inboxScopeCatalog(registry: registry))
        sidebar.agentInbox.setProjectIconSources(Dictionary(
            uniqueKeysWithValues: registry.projects.filter { !$0.missing }.map {
                ($0.id, URL(fileURLWithPath: $0.rootPath, isDirectory: true))
            }))
        // P3.16: BEFORE the rows too, so the empty state this push may show already
        // knows why it is empty.
        sidebar.setInboxExcludedTerminalAgentCount(inboxExcludedTerminalAgentCount())
        // P3.2: skipping the push leaves whatever the list already had — on a cold
        // launch that is nothing, which is the packet's "the data source begins empty
        // and is populated only after readiness". `applyInbox([])` here would be the
        // "no agents" lie with a rendered empty state behind it.
        if agentActivity.isReconciled {
            sidebar.applyInbox(rows: buildAgentInboxRows(), changed: agentActivity.lastChange)
        }
        do {
            let tree = try buildWorkspaceSidebarTree()
            sidebar.reload(
                tree: tree,
                currentWorkspaceId: currentWorkspaceIdForSidebar(),
                selectedZoneId: navSelectedZoneId,
                selectedTileId: canvasView?.canvasState.lastActiveTileId
            )
            sidebar.setManagementMessage(workspaceManagementMessage)
        } catch {
            fputs("Workspace sidebar reload failed: \(error)\n", stderr)
            sidebar.reload(tree: SidebarTree(workspaces: []), currentWorkspaceId: nil)
            sidebar.setManagementMessage(workspaceManagementMessage)
        }
    }

    private func handleWorkspaceSidebarSelection(_ selection: WorkspaceSidebarSelection) {
        switch selection {
        case let .workspace(workspaceId):
            guard switchWorkspaceFromSidebarIfNeeded(workspaceId) else { return }
            workspaceSidebarView?.select(workspaceId: workspaceId)
        case let .zone(workspaceId, zoneId):
            guard switchWorkspaceFromSidebarIfNeeded(workspaceId) else { return }
            if focusZoneFromSidebar(zoneId) {
                workspaceSidebarView?.select(workspaceId: workspaceId, zoneId: zoneId)
            } else {
                workspaceSidebarView?.select(workspaceId: workspaceId)
            }
        case let .tile(workspaceId, zoneId, tileId):
            guard switchWorkspaceFromSidebarIfNeeded(workspaceId) else { return }
            if focusTileFromSidebar(tileId) {
                workspaceSidebarView?.select(workspaceId: workspaceId, zoneId: zoneId, tileId: tileId)
            } else {
                workspaceSidebarView?.select(workspaceId: workspaceId)
            }
        }
    }

    @discardableResult
    private func switchWorkspaceFromSidebarIfNeeded(_ workspaceId: UUID) -> Bool {
        if currentWorkspaceIdForSidebar() == workspaceId { return true }
        do {
            guard let workspaceRuntime else { return false }
            try workspaceRuntime.switchWorkspace(to: workspaceId)
            navSelectedZoneId = nil
            showWorkspaceSwitchTransitionLabel(workspaceId: workspaceId)
            reloadWorkspaceSidebar()
            return workspaceRuntime.workspaceId == workspaceId
        } catch {
            fputs("Workspace sidebar switch failed: \(error)\n", stderr)
            return false
        }
    }

    @discardableResult
    private func focusZoneFromSidebar(_ zoneId: UUID) -> Bool {
        guard let canvasView,
              let viewport = canvasView.fitZoneToViewport(zoneId: zoneId) else { return false }
        recordViewBeforeProgrammaticJumpIfNeeded(targetViewport: viewport)
        canvasView.setViewport(viewport)
        navSelectedZoneId = zoneId
        focusHistory.recordZoneFocus(zoneId, reason: .paletteJump)
        return true
    }

    @discardableResult
    private func focusTileFromSidebar(_ tileId: UUID) -> Bool {
        guard let canvasView,
              canvasView.navigationTileSnapshot(for: tileId) != nil else { return false }
        jumpToTileFromPalette(tileId)
        navSelectedZoneId = zoneContainingTile(tileId)
        return focusBroker.activeSurface == .tile(tileId) || canvasView.canvasState.lastActiveTileId == tileId
    }

    // Ticket: docs/38-tickets/94-sidebar-native-ux/P5.4-keyboard-traversal-jump-hints.md
    /// Space previews only a tile already present in the active canvas. Unlike
    /// reveal it never switches workspaces, attaches a tile, changes focus, or
    /// clears attention; it changes only the camera framing.
    @discardableResult
    func previewAgentFromInbox(_ rowId: UUID) -> Bool {
        let record = agentSupervisor.records[AgentID(rawValue: rowId)]
        let tileId = record?.tileId ?? (record == nil ? rowId : nil)
        guard let tileId, let canvasView,
              canvasView.navigationTileSnapshot(for: tileId) != nil else { return false }
        canvasView.centerOnTile(tileId)
        return true
    }

    // Ticket: docs/38-tickets/90-agent-ux/P3.9-reveal-on-click.md
    /// Clicking an inbox row takes you to that agent, wherever it is — another
    /// workspace, or no tile at all.
    ///
    /// The id is the inbox's AGGREGATE key (P3.1), which has two halves: a managed
    /// agent is keyed by its record and a terminal-session agent by its own tile id.
    /// So a record lookup decides which half this is, exactly the way
    /// `focusedInboxAgentId()` builds the same key from the other direction.
    ///
    /// READING IS FREE (P4.9, and this packet's first trap): the only state this
    /// changes is the read-mark and where the viewport is pointing. Nothing here
    /// settles, un-settles, stops, starts or archives anything.
    @discardableResult
    func revealAgentFromInbox(_ rowId: UUID) -> Bool {
        canvasView?.clearContextualAgentLineage()
        let agentId = AgentID(rawValue: rowId)
        guard let record = agentSupervisor.records[agentId] else {
            // A terminal-session agent: the row's id IS its tile. `focusTile` resolves
            // to no managed agent and therefore disarms the read-mark rather than
            // leaving the previous agent armed.
            let revealed = revealTileFromInbox(rowId)
            if revealed { agentSupervisor.focusTile(rowId) }
            return revealed
        }
        // A tile the agent already has is the tile it is revealed in — spawning a
        // second one for an agent that has one is the packet's other trap, and
        // `attach` would silently unbind the first.
        //
        // A RECORD CAN OUTLIVE ITS TILE, though, and then the recorded id names a
        // tile no canvas holds: `revealTileFromInbox` resolves nothing and returns
        // false, so clicking the row did NOTHING and the agent looked unreachable.
        // Measured on the owner's dev store — eight records, every one of them
        // still naming a tile the canvas had lost. A binding nothing can find is
        // not a binding, so it is cleared and the agent gets a fresh tile, which
        // is the same answer a headless agent already gets one line down
        // (.plans/05-close-to-history.md).
        let boundTileId = record.tileId.flatMap { tileIsReachable($0) ? $0 : nil }
        if record.tileId != nil, boundTileId == nil {
            fputs("Reveal from inbox: \(agentId.rawValue.uuidString) names tile \(record.tileId!.uuidString), which no canvas holds; giving it a new one\n", stderr)
            agentSupervisor.detachView(agentID: agentId)
        }
        // A headless agent still belongs to its project's one workspace. Move to
        // that canvas before creating its view; otherwise the fallback spawner
        // writes a foreign agent tile into whichever workspace happens to be open.
        if boundTileId == nil,
           let projectId = record.projectId,
           let registry = try? registryStore?.loadOrEmpty(),
           let owningWorkspaceId = registry.projects.first(where: { $0.id == projectId })?.workspaceId,
           owningWorkspaceId != currentWorkspaceIdForSidebar(),
           !switchWorkspaceFromSidebarIfNeeded(owningWorkspaceId) {
            return false
        }
        guard let tileId = boundTileId ?? attachTileToAgentFromInbox(agentId) else { return false }
        guard revealTileFromInbox(tileId) else { return false }
        // Out of History: reopening a closed agent is asking for it back, and its
        // row must not stay in a section whose promise is "no tile"
        // (.plans/05-close-to-history.md). After the reveal landed, for the same
        // reason the focus arm below is.
        agentSupervisor.reopen(agentID: agentId)
        // P3.3: opening a row clears the mark AND arms the focus, so a turn that
        // completes while you are sitting on the agent is not unread. Only after the
        // reveal landed — arming focus on an agent you failed to reach would suppress
        // the next mark for a row you never saw.
        agentSupervisor.focus(agentID: agentId)
        // C11: the parent's WHOLE visible fan, not just the child that was
        // revealed — every sibling that already has a reachable tile gets its
        // own edge, bounded to `InboxSort.maxVisibleChildren` inside
        // `showContextualAgentLineage(edges:)` (the same cap the inbox itself
        // enforces on a parent's visible children).
        if let parentAgentID = agentSupervisor.records[agentId]?.parentAgentID,
           let parentTileID = agentSupervisor.records[parentAgentID]?.tileId,
           canvasView?.tileView(for: parentTileID) != nil {
            let siblingEdges = agentSupervisor.records.values
                .filter { $0.parentAgentID == parentAgentID }
                .compactMap { record -> (parentTileID: UUID, childTileID: UUID)? in
                    guard let siblingTileID = record.tileId,
                          canvasView?.tileView(for: siblingTileID) != nil else { return nil }
                    return (parentTileID, siblingTileID)
                }
            canvasView?.showContextualAgentLineage(edges: siblingEdges)
        }
        // The mark is a fact the rows carry, so the list has to be told; a
        // cross-workspace reveal has already reloaded, and a same-workspace one has
        // not.
        reloadWorkspaceSidebar()
        return true
    }

    // Ticket: docs/38-tickets/90-agent-ux/P3.13-inline-rename.md
    /// A name committed in the inbox becomes the AGENT's name.
    ///
    /// The id is the inbox's aggregate key, whose two halves `revealAgentFromInbox`
    /// documents: only the managed half has a record, and a record is the only place a
    /// name can live — a terminal session's title belongs to its tile, and what
    /// renaming one means is undefined until a ticket rules on it. So that half is
    /// refused out loud rather than half-written.
    ///
    /// The re-push is the whole point of doing it here: the row's title is derived from
    /// the record on every build (`AgentInboxRowBuilder`), so one reload puts the new
    /// name on the row, in the scope popup's join and in anything else the snapshot
    /// feeds.
    @discardableResult
    func renameAgentFromInbox(_ rowId: UUID, to name: String) -> Bool {
        let agentId = AgentID(rawValue: rowId)
        guard agentSupervisor.records[agentId] != nil else {
            fputs("Rename ignored: \(rowId.uuidString) is not a managed agent\n", stderr)
            return false
        }
        guard agentSupervisor.rename(agentID: agentId, to: name) else { return false }
        reloadWorkspaceSidebar()
        return true
    }

    // MARK: - Inbox row and bulk actions (P3.15)

    /// The production row actions. Phase 6 supplies the lifecycle/read writers;
    /// the capability set is kept explicit so a menu item cannot outrun its host.
    static let wiredInboxRowActions: Set<InboxRowAction> = [
        .settle, .unsettle, .snooze, .wake, .markUnread,
        .stopAgent, .archive, .delete, .generateName,
    ]
    /// The bulk bar's half. No `.stopAgent` — the bar has no such action (`P3.11`'s five
    /// are settle / snooze / mark-unread / archive / delete).
    static let wiredInboxBulkActions: Set<InboxBulkAction> = [
        .settle, .snooze, .markUnread, .archive, .delete,
    ]

    /// A row-menu pick, for the agents it was raised over.
    @discardableResult
    func performInboxRowAction(_ action: InboxRowAction, on rowIds: [UUID]) -> Bool {
        switch action {
        case .stopAgent:
            return stopAgentsFromInbox(rowIds)
        case .settle:
            return settleAgentsFromInbox(rowIds)
        case .unsettle:
            return pinActiveAgentsFromInbox(rowIds)
        case .snooze:
            return snoozeAgentsFromInbox(rowIds)
        case .wake:
            return wakeAgentsFromInbox(rowIds)
        case .markUnread:
            return markUnreadAgentsFromInbox(rowIds)
        case .archive:
            return parkAgentsFromInbox(rowIds)
        case .delete:
            return archiveAgentsFromInbox(rowIds, verb: "Delete")
        case .generateName:
            // R2: this is the compile-forced callback callsite only. The
            // supervisor owns filtering, cap admission, CAS, and completion.
            return agentSupervisor.requestGeneratedNames(
                agentIDs: rowIds.map(AgentID.init(rawValue:)),
                onCompletion: { [weak self] _, _ in
                    Task { @MainActor [weak self] in
                        self?.reloadWorkspaceSidebar()
                    }
                })
                .didAcceptAny
        // `openInTile` and `rename` have their own paths (P3.9/P3.13). They are
        // deliberately not wired through this lifecycle callback.
        case .openInTile, .rename:
            fputs("Inbox action \(action.rawValue) has no lifecycle host\n", stderr)
            return false
        }
    }

    /// A bulk-bar pick. The two destructive verbs are the row menu's, on a set.
    @discardableResult
    func performInboxBulkAction(_ action: InboxBulkAction, on rowIds: [UUID]) -> Bool {
        switch action {
        case .settle:
            return settleAgentsFromInbox(rowIds)
        case .snooze:
            return snoozeAgentsFromInbox(rowIds)
        case .markUnread:
            return markUnreadAgentsFromInbox(rowIds)
        case .archive:
            return parkAgentsFromInbox(rowIds)
        case .delete:
            return archiveAgentsFromInbox(rowIds, verb: "Delete")
        }
    }

    /// The lifecycle writers are deliberately one-agent-at-a-time, but the host
    /// refreshes once after the batch so all row/shelf/timer derivations see one
    /// coherent push.
    @discardableResult
    private func settleAgentsFromInbox(_ rowIds: [UUID]) -> Bool {
        let rows = buildAgentInboxRows()
        let byID = Dictionary(uniqueKeysWithValues: rows.map { ($0.id, $0) })
        guard !rowIds.isEmpty,
              rowIds.allSatisfy({ byID[$0]?.canSettle() == true }) else { return false }
        let changed = rowIds.reduce(false) { result, rawID in
            agentSupervisor.settle(agentID: AgentID(rawValue: rawID)) || result
        }
        if changed { reloadWorkspaceSidebar() }
        return changed
    }

    @discardableResult
    private func pinActiveAgentsFromInbox(_ rowIds: [UUID]) -> Bool {
        let changed = rowIds.reduce(false) { result, rawID in
            agentSupervisor.pinActive(agentID: AgentID(rawValue: rawID)) || result
        }
        if changed { reloadWorkspaceSidebar() }
        return changed
    }

    /// P4.5 presets are resolved from one clock at the moment the snooze action
    /// opens. The first offered option is the deterministic fallback for the
    /// current row callback; the live menu supplies a different chosen wake when
    /// one is selected.
    @discardableResult
    private func snoozeAgentsFromInbox(_ rowIds: [UUID], wakeAt: Date? = nil, now: Date = Date()) -> Bool {
        let rows = buildAgentInboxRows(now: now)
        let byID = Dictionary(uniqueKeysWithValues: rows.map { ($0.id, $0) })
        let rollups = InboxSort.rollups(in: rows)
        guard !rowIds.isEmpty,
              rowIds.allSatisfy({
                  guard let row = byID[$0] else { return false }
                  return InboxRowAction.snooze.isAvailable(for: row, rollups: rollups)
              }) else { return false }
        let calendar = Calendar.autoupdatingCurrent
        let resolvedWake = wakeAt ?? SnoozePreset.offered(at: now, calendar: calendar).first?.wakeAt
        guard let resolvedWake else { return false }
        let changed = rowIds.reduce(false) { result, rawID in
            agentSupervisor.snooze(
                agentID: AgentID(rawValue: rawID), until: resolvedWake, now: now) || result
        }
        if changed { reloadWorkspaceSidebar() }
        return changed
    }

    @discardableResult
    private func wakeAgentsFromInbox(_ rowIds: [UUID]) -> Bool {
        let changed = rowIds.reduce(false) { result, rawID in
            agentSupervisor.wake(agentID: AgentID(rawValue: rawID)) || result
        }
        if changed { reloadWorkspaceSidebar() }
        return changed
    }

    @discardableResult
    private func markUnreadAgentsFromInbox(_ rowIds: [UUID]) -> Bool {
        let changed = rowIds.reduce(false) { result, rawID in
            agentSupervisor.markUnread(agentID: AgentID(rawValue: rawID)) || result
        }
        if changed { reloadWorkspaceSidebar() }
        return changed
    }

    /// Stop what these agents are doing. Not destructive — the agent stays, its record
    /// stays, and this is P2A.5's rule made reachable: closing a tile must never stop an
    /// agent, so somewhere has to deliberately.
    @discardableResult
    private func stopAgentsFromInbox(_ rowIds: [UUID]) -> Bool {
        let running = managedAgents(for: rowIds).filter { agentSupervisor.isRunning($0.id) }
        guard !running.isEmpty else {
            setWorkspaceManagementMessage("Nothing to stop — no selected agent has a prompt in flight.")
            return false
        }
        for record in running { agentSupervisor.stop(record.id) }
        setWorkspaceManagementMessage("Stopped \(countedAgents(running.count)): \(agentNameList(running)).")
        refreshAgentSurfaces(notify: false)
        return true
    }

    // Ticket: .plans/05-close-to-history.md

    /// Archive, the REVERSIBLE verb: the selected agents move to History and
    /// nothing is destroyed. Same park closing a tile performs, from the list
    /// instead of the canvas.
    ///
    /// NO CONFIRMATION SHEET, and that is the point of the split: an action you can
    /// undo by opening History and clicking the row does not get to interrupt you.
    /// The sheet belongs to Delete, which is the one that cannot be taken back.
    ///
    /// A BUSY AGENT IS REFUSED rather than silently skipped — `close` will not park
    /// one, and a message that said "Archived 3 agents" while one of them kept
    /// working is the over-claim `ArchiveReport` exists to stop.
    @discardableResult
    private func parkAgentsFromInbox(_ rowIds: [UUID]) -> Bool {
        let targets = managedAgents(for: rowIds)
        let ignored = rowIds.count - targets.count
        guard !targets.isEmpty else {
            setWorkspaceManagementMessage("Archive ignored: no managed agent was selected.")
            return false
        }
        // ARCHIVE TAKES THE TILE WITH IT. History's promise is "the tile is gone,
        // the agent is not", and archiving from the list while its tile sat on the
        // canvas would put the same agent in both places at once — a row saying
        // Closed above a tile you can type into.
        //
        // The park comes FIRST and the tile only follows a park that succeeded:
        // `deleteTile` closes a tile whether or not its agent can be parked, so
        // doing it the other way round would take the tile away from a busy agent
        // this action just refused to archive. The nested `close` inside
        // `deleteTile` then no-ops on the stamp already written.
        var parked: [AgentRecord] = []
        for record in targets where agentSupervisor.close(agentID: record.id) {
            parked.append(record)
            if let tileId = record.tileId { deleteTile(id: tileId) }
        }
        let refused = targets.filter { record in !parked.contains { $0.id == record.id } }
        var sentence: String
        if parked.isEmpty {
            sentence = "Archived nothing: \(countedAgents(refused.count)) still busy."
        } else {
            sentence = "Archived \(countedAgents(parked.count)) to History: \(agentNameList(parked))."
            if !refused.isEmpty {
                sentence += " Kept \(countedAgents(refused.count)) still busy: \(agentNameList(refused))."
            }
        }
        if ignored > 0 { sentence += " \(ignored) selected row(s) had no agent to archive." }
        setWorkspaceManagementMessage(sentence)
        refreshAgentSurfaces(notify: false)
        return !parked.isEmpty
    }

    /// THE DELETION PATH. `AgentSupervisor.archive` does the whole job in an order
    /// its own comments call load-bearing (stop, then the durable delete, then the
    /// worktree, keeping anything unmerged).
    ///
    /// ONE VERB REACHES HERE NOW. Delete and Archive used to be the same call and
    /// differed only in what the person was told; .plans/05-close-to-history.md
    /// makes Archive reversible (`parkAgentsFromInbox` above), so this is the only
    /// path that destroys anything. The `verb` parameter stays because the
    /// confirmation sheet and the report sentence are worded from it.
    @discardableResult
    private func archiveAgentsFromInbox(_ rowIds: [UUID], verb: String) -> Bool {
        let targets = managedAgents(for: rowIds)
        // A terminal-session row is keyed by its TILE and has no record (the split
        // `revealAgentFromInbox` documents), so there is no agent there to delete. Those
        // rows are COUNTED rather than quietly dropped: a selection that half-performed
        // and said "deleted" would be the same over-claim `ArchiveReport` exists to stop.
        // (Raised in cross-review.)
        let ignored = rowIds.count - targets.count
        guard !targets.isEmpty else {
            setWorkspaceManagementMessage("\(verb) ignored: no managed agent was selected.")
            return false
        }
        let request = AgentDeleteConfirmationRequest(
            verb: verb,
            agentNames: targets.map(\.displayName),
            runningCount: targets.filter { agentSupervisor.isRunning($0.id) }.count,
            branchesAtStake: targets.compactMap(\.worktreeBranch))
        guard agentDeleteConfirmationProvider?(request) ?? confirmDeleteAgents(request) else {
            setWorkspaceManagementMessage(
                "\(verb) canceled; \(countedAgents(targets.count)) kept.")
            return false
        }
        // Delete is the destructive pair operation: unlike closing/detaching or
        // reversible Archive, it removes both the durable agent and its canvas
        // view binding. Documents the agent referenced remain; only the workspace
        // relationship edges are removed.
        var reports: [AgentSupervisor.ArchiveReport] = []
        for record in targets {
            if let tileId = record.tileId { agentSupervisor.suppressAgentRespawn(forTile: tileId) }
            let report = agentSupervisor.archive(record.id)
            reports.append(report)
            guard report.recordDeleted else { continue }
            try? workspaceRuntime?.removeDocumentLinks(agentId: record.id)
            if let tileId = record.tileId { deleteTile(id: tileId) }
        }
        setWorkspaceManagementMessage(
            agentArchiveMessage(verb: verb, targets: targets, reports: reports, ignored: ignored))
        refreshAgentSurfaces(notify: false)
        return true
    }

    /// The inbox's aggregate ids resolved to records, in the order they were handed
    /// over. Ids with no record are dropped — those are terminal-session rows.
    private func managedAgents(for rowIds: [UUID]) -> [AgentRecord] {
        rowIds.compactMap { agentSupervisor.records[AgentID(rawValue: $0)] }
    }

    private func agentNameList(_ records: [AgentRecord]) -> String {
        records.map(\.displayName).joined(separator: ", ")
    }

    private func countedAgents(_ count: Int) -> String {
        "\(count) \(count == 1 ? "agent" : "agents")"
    }

    /// What actually happened, not what was asked for.
    ///
    /// `ArchiveReport` IS THE MESSAGE, not decoration: it reports a branch kept because
    /// deleting it would discard the agent's commits, and a worktree kept because it was
    /// dirty. Dropping that says "deleted" while a branch with their work survives. The
    /// wording follows P3.11's correction — `Unmerged work kept: ⎇ …`, because "keeps
    /// these branches" claims more than the app can know about a merged one.
    private func agentArchiveMessage(
        verb: String, targets: [AgentRecord], reports: [AgentSupervisor.ArchiveReport], ignored: Int
    ) -> String {
        // NAMED FROM THE REPORTS, not from what was asked for: a store that refused
        // leaves its agent exactly where it was, and listing it as deleted would be a
        // sentence about an agent still in the list. (Raised in cross-review.)
        let removed = zip(targets, reports).filter { $0.1.recordDeleted }.map(\.0)
        let stopped = reports.filter(\.wasRunning).count
        var sentence = "\(verb == "Delete" ? "Deleted" : "Archived") \(countedAgents(removed.count)): \(agentNameList(removed))."
        if removed.count < targets.count {
            let kept = targets.filter { record in !removed.contains { $0.id == record.id } }
            sentence += " \(countedAgents(kept.count)) could not be removed and stayed: \(agentNameList(kept))."
        }
        if ignored > 0 {
            sentence += " \(ignored) selected \(ignored == 1 ? "row is" : "rows are") not a managed agent and \(ignored == 1 ? "was" : "were") left alone."
        }
        if stopped > 0 { sentence += " Stopped \(countedAgents(stopped)) mid-turn." }
        let keptBranches = reports.compactMap { $0.branchRetained?.branch }
        if !keptBranches.isEmpty {
            sentence += " Unmerged work kept: \(keptBranches.map { "⎇ \($0)" }.joined(separator: ", "))."
        }
        let keptWorktrees = reports.compactMap { $0.worktreeRetained?.path.lastPathComponent }
        if !keptWorktrees.isEmpty {
            sentence += " Checkout kept: \(keptWorktrees.joined(separator: ", "))."
        }
        let removedBranches = reports.compactMap(\.branchDeleted)
        if !removedBranches.isEmpty {
            sentence += " Merged \(removedBranches.count == 1 ? "branch" : "branches") deleted: \(removedBranches.joined(separator: ", "))."
        }
        return sentence
    }

    /// The modal, reached only when no provider answered. Cancel is the DEFAULT button
    /// (first), the same way `confirmDeleteWorkspace` orders its two.
    private func confirmDeleteAgents(_ request: AgentDeleteConfirmationRequest) -> Bool {
        let alert = NSAlert()
        alert.alertStyle = .warning
        alert.messageText = request.agentNames.count == 1
            ? "\(request.verb) “\(request.agentNames[0])”?"
            : "\(request.verb) \(request.agentNames.count) agents?"
        var informative = "The agent's record is removed from this Mac. Its tile stays on the canvas and starts a new agent the next time you send a prompt from it."
        if request.runningCount > 0 {
            informative += "\n\n\(request.runningCount == 1 ? "One agent has" : "\(request.runningCount) agents have") a prompt in flight and will be stopped first."
        }
        if !request.branchesAtStake.isEmpty {
            informative += "\n\nUnmerged work is kept: \(request.branchesAtStake.map { "⎇ \($0)" }.joined(separator: ", "))."
        }
        alert.informativeText = informative
        alert.addButton(withTitle: "Cancel")
        alert.addButton(withTitle: request.verb)
        return alert.runModal() == .alertSecondButtonReturn
    }

    /// Frame and focus a tile, switching workspaces first when it lives in another
    /// one. Both halves are the sidebar's existing primitives — this adds no
    /// navigation of its own, it only supplies the workspace the tree row would have
    /// carried.
    @discardableResult
    private func revealTileFromInbox(_ tileId: UUID) -> Bool {
        if let workspaceId = workspaceContainingTile(tileId),
           !switchWorkspaceFromSidebarIfNeeded(workspaceId) { return false }
        return focusTileFromSidebar(tileId)
    }

    /// Whether anything can still show this tile — the same two places
    /// `revealTileFromInbox` looks, in the same order: the live canvas first (a
    /// tile just spawned is there before the tree is re-read), then the workspace
    /// tree. False means the id names a tile that no longer exists anywhere, which
    /// is a stale binding rather than a tile in another workspace.
    private func tileIsReachable(_ tileId: UUID) -> Bool {
        if canvasView?.navigationTileSnapshot(for: tileId) != nil { return true }
        return workspaceContainingTile(tileId) != nil
    }

    /// Which workspace holds this tile, from the same fold the sidebar draws
    /// (`buildWorkspaceSidebarTree`) — so "where is this tile" has one answer on the
    /// desktop, and a tile reachable from two workspaces resolves to the first, as
    /// `AgentContextIndex.tilePlacements` already decided for the row's own chip.
    ///
    /// nil for a tile the tree does not mention — a tile just spawned into the live
    /// canvas, before its project's canvas has been re-read — and the caller then
    /// focuses it where it is rather than refusing.
    private func workspaceContainingTile(_ tileId: UUID) -> UUID? {
        guard let tree = try? buildWorkspaceSidebarTree() else { return nil }
        return tree.workspaces.first { workspace in
            workspace.zones.contains { $0.tiles.contains { $0.tileId == tileId } }
        }?.workspaceId
    }

    /// Gives a headless agent (P2A.6) a view, so there is something to reveal.
    ///
    /// The tile is spawned by the same call `agent.newManaged` makes and then wired
    /// to THIS agent rather than a fresh one — `wireManagedAgentTile` is where
    /// `supervisor.attach` (P2A.5) lives, so the binding is recorded in one place and
    /// the tile subscribes to the agent's real stream and replays its history.
    ///
    /// WHERE THE TILE LANDS, and the limit on it (raised in cross-review). `tileSpawner`
    /// is built once at `startWorkspace` against the boot project's store, so EVERY
    /// spawn surface in the app — ⌘K's new managed agent, a new terminal, a note —
    /// puts its tile in that one project's canvas. A headless agent whose record names
    /// a different project therefore gets its view in the active project, not in its
    /// own. That is the app's existing behaviour rather than something this path
    /// invents, and giving the agent's own project a tile needs a per-project spawner,
    /// which is an architectural change no packet has asked for. So it is SAID on
    /// stderr rather than left silent, and the agent's own record — its cwd, its
    /// project, the project chip on its row — is untouched: only the view moved.
    private func attachTileToAgentFromInbox(_ agentId: AgentID) -> UUID? {
        // M1.6: put the tile in the AGENT'S project when that project has a live
        // zone. M1.3b gave every live controller a spawner, which is what makes
        // this possible at all; before it, only the active project had one and the
        // mismatch below was unavoidable.
        //
        // The scope override is not optional extra care: `spawnManagedAgent` frames
        // and installs against `creationScopeProvider()?.zoneId`, so using the
        // right store with the active zone still in place would install into one
        // project's layer and persist into another's.
        let recordProject = agentSupervisor.records[agentId]?.projectId
        var scopeOverrideApplied = false
        defer { if scopeOverrideApplied { explicitCreationScopeOverride = nil } }

        let spawner: TileSpawner
        if let recordProject, let (scoped, scope) = spawnerAndScope(forProject: recordProject) {
            spawner = scoped
            explicitCreationScopeOverride = scope
            scopeOverrideApplied = true
        } else {
            guard let fallback = tileSpawner else { return nil }
            spawner = fallback
            // Still SAY it. The remaining case is an agent whose project has no live
            // zone in this workspace, which no spawner can fix — the tile has to go
            // somewhere, and P3.9's negative-test ledger (item 7) explicitly rejects
            // refusing the reveal, because that "would make the click a no-op for
            // exactly the agents an orchestrator spawns."
            if let recordProject, let activeProjectId = activeProject?.id, recordProject != activeProjectId {
                fputs("Reveal from inbox: \(agentId.rawValue.uuidString) belongs to project \(recordProject.uuidString), which has no live zone in this workspace, so its new tile lands in the active project \(activeProjectId.uuidString)\n", stderr)
            }
        }
        // The agent EXISTS, so its tile is titled and its bootstrap line written from
        // ITS record, not from the Settings default: `wireManagedAgentTile` below binds
        // this agent and `ManagedAgentTileNSView.attach` then puts the record's model
        // in the composer, so a Settings-titled tile read "Claude Opus 5" over a
        // composer saying "GPT-5.6 Sol". The seam takes the supervisor rather than a
        // resolution so this call site cannot omit the lookup again.
        switch spawner.spawnManagedAgentForExistingAgent(agentId, supervisor: agentSupervisor) {
        case let .spawned(tileId):
            wireManagedAgentTile(tileId, agentID: agentId)
            scheduleCompanionSyncPublish(reason: .statusChanged, diagnosticsReason: "inbox-reveal-attach", debounce: 0.2)
            return tileId
        case let .failure(error):
            fputs("Reveal from inbox: could not attach a tile to \(agentId.rawValue.uuidString): \(error)\n", stderr)
            return nil
        }
    }

    @objc func toggleWorkspaceSidebarFromMenu(_ sender: Any?) {
        toggleWorkspaceSidebar()
    }

    private func toggleWorkspaceSidebar() {
        setWorkspaceSidebarVisible(!WorkspaceSidebarConfig.resolveVisible())
    }

    private func setWorkspaceSidebarVisible(_ visible: Bool) {
        WorkspaceSidebarConfig.setVisible(visible)
        applyWorkspaceSidebarVisibility(visible)
        if visible { reloadWorkspaceSidebar() }
    }

    private func applyWorkspaceSidebarVisibility(_ visible: Bool) {
        guard let splitView = workspaceSplitView,
              let sidebar = workspaceSidebarView else { return }
        isApplyingWorkspaceSidebarVisibility = true
        defer { isApplyingWorkspaceSidebarVisibility = false }
        sidebar.isHidden = !visible
        if visible {
            splitView.setPosition(CGFloat(WorkspaceSidebarConfig.resolveWidth()), ofDividerAt: 0)
        } else {
            splitView.setPosition(0, ofDividerAt: 0)
        }
        splitView.adjustSubviews()
        if !visible {
            sidebar.isHidden = true
        }
    }

    func validateMenuItem(_ menuItem: NSMenuItem) -> Bool {
        if menuItem.action == #selector(toggleWorkspaceSidebarFromMenu(_:)) {
            menuItem.state = WorkspaceSidebarConfig.resolveVisible() ? .on : .off
        }
        return true
    }

    func splitView(_ splitView: NSSplitView, constrainMinCoordinate proposedMinimumPosition: CGFloat, ofSubviewAt dividerIndex: Int) -> CGFloat {
        guard splitView === workspaceSplitView, dividerIndex == 0 else { return proposedMinimumPosition }
        if workspaceSidebarView?.isHidden == true { return 0 }
        return CGFloat(WorkspaceSidebarConfig.minWidth)
    }

    func splitView(_ splitView: NSSplitView, constrainMaxCoordinate proposedMaximumPosition: CGFloat, ofSubviewAt dividerIndex: Int) -> CGFloat {
        guard splitView === workspaceSplitView, dividerIndex == 0 else { return proposedMaximumPosition }
        if workspaceSidebarView?.isHidden == true { return 0 }
        return CGFloat(WorkspaceSidebarConfig.maxWidth)
    }

    func splitViewDidResizeSubviews(_ notification: Notification) {
        guard let splitView = notification.object as? NSSplitView,
              splitView === workspaceSplitView,
              let sidebar = workspaceSidebarView,
              !isApplyingWorkspaceSidebarVisibility,
              !sidebar.isHidden else { return }
        WorkspaceSidebarConfig.setWidth(Double(sidebar.frame.width))
    }

    static func runWorkspaceSidebarShellSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String {
                switch self { case let .failed(message): return message }
            }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }
        func tile(id: UUID, title: String, kind: TileKind, rank: Int) -> Tile {
            Tile(
                id: id,
                kind: kind,
                title: title,
                frame: TileFrame(x: Double(rank) * 40, y: 0, width: 320, height: 220),
                zPosition: .fromLegacyRank(rank),
                runtimeRef: nil,
                metadata: TileMetadata()
            )
        }

        let fm = FileManager.default
        let tempRoot = fm.temporaryDirectory.appendingPathComponent("continuum-workspace-sidebar-shell-\(UUID().uuidString)", isDirectory: true)
        let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
        try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: tempRoot) }

        let currentWorkspace = UUID(uuidString: "00000000-0000-0000-0000-00000000A001")!
        let otherWorkspace = UUID(uuidString: "00000000-0000-0000-0000-00000000A002")!
        let zoneOne = UUID(uuidString: "00000000-0000-0000-0000-00000000B001")!
        let zoneTwo = UUID(uuidString: "00000000-0000-0000-0000-00000000B002")!
        let otherZone = UUID(uuidString: "00000000-0000-0000-0000-00000000B003")!
        let currentTiles = [
            tile(id: UUID(uuidString: "00000000-0000-0000-0000-00000000C001")!, title: "Shell Agent", kind: .terminal, rank: 1),
            tile(id: UUID(uuidString: "00000000-0000-0000-0000-00000000C002")!, title: "Docs Browser", kind: .browser, rank: 2),
        ]
        let secondZoneTiles = [
            tile(id: UUID(uuidString: "00000000-0000-0000-0000-00000000C003")!, title: "Scratch Note", kind: .note, rank: 3),
        ]
        let otherTiles = [
            tile(id: UUID(uuidString: "00000000-0000-0000-0000-00000000C004")!, title: "Collapsed Workspace Tile", kind: .terminal, rank: 4),
        ]

        var registry = Registry.empty()
        registry.lastActiveWorkspaceId = currentWorkspace
        registry.workspaces = [
            WorkspaceEntry(id: currentWorkspace, name: "Current Workspace", projectIds: [], createdAt: Date(timeIntervalSince1970: 0), updatedAt: Date(timeIntervalSince1970: 0)),
            WorkspaceEntry(id: otherWorkspace, name: "Other Workspace", projectIds: [], createdAt: Date(timeIntervalSince1970: 0), updatedAt: Date(timeIntervalSince1970: 0)),
        ]
        let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
        try registryStore.save(registry)

        let currentDocument = WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [
                ZonePlacement(zoneId: zoneOne, projectId: nil, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 900, height: 600), color: "mint", collapsed: false, hydrationPolicy: .automatic, name: "Build", navKey: "1"),
                ZonePlacement(zoneId: zoneTwo, projectId: nil, origin: ZonePoint(x: 940, y: 0), size: ZoneSize(width: 900, height: 600), color: "blue", collapsed: false, hydrationPolicy: .automatic, name: "Research", navKey: "2"),
            ],
            zoneZOrder: [zoneOne, zoneTwo],
            lastActiveZoneId: zoneOne,
            ambientTiles: currentTiles.map { $0.with(zoneId: zoneOne) }
                + secondZoneTiles.map { $0.with(zoneId: zoneTwo) }
        )
        let otherDocument = WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [
                ZonePlacement(zoneId: otherZone, projectId: nil, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 900, height: 600), color: "orange", collapsed: false, hydrationPolicy: .automatic, name: "Collapsed Zone", navKey: nil),
            ],
            zoneZOrder: [otherZone],
            lastActiveZoneId: otherZone,
            ambientTiles: otherTiles.map { $0.with(zoneId: otherZone) }
        )
        try WorkspaceStore(workspaceId: currentWorkspace, applicationSupportDirectory: appSupport).save(currentDocument)
        try WorkspaceStore(workspaceId: otherWorkspace, applicationSupportDirectory: appSupport).save(otherDocument)

        let app = AppDelegate()
        app.registryStore = registryStore
        let tree = try app.buildWorkspaceSidebarTree()
        let sidebar = WorkspaceSidebarView(frame: NSRect(x: 0, y: 0, width: WorkspaceSidebarConfig.defaultWidth, height: 640))
        sidebar.reload(tree: tree, currentWorkspaceId: app.currentWorkspaceIdForSidebar())
        sidebar.layoutSubtreeIfNeeded()

        let workspaceRowsRendered = sidebar.workspaceRowsRenderedForQA
        let zoneRowsRendered = sidebar.zoneRowsRenderedForQA
        let tileRowsRendered = sidebar.tileRowsRenderedForQA
        let currentWorkspaceExpanded = sidebar.isWorkspaceExpandedForQA(currentWorkspace)
        let nonCurrentWorkspaceCollapsed = !sidebar.isWorkspaceExpandedForQA(otherWorkspace)
        let currentWorkspaceSelected = sidebar.isWorkspaceSelectedForQA(currentWorkspace)
        let visibleNames = sidebar.visibleDisplayNamesForQA
        try expect(workspaceRowsRendered == 2, "expected 2 visible workspace rows, got \(workspaceRowsRendered)")
        try expect(currentWorkspaceExpanded, "current workspace should be expanded")
        try expect(nonCurrentWorkspaceCollapsed, "non-current workspace should be collapsed")
        try expect(currentWorkspaceSelected, "current workspace should be selected")
        try expect(zoneRowsRendered == 2, "expected current workspace's 2 zones to render, got \(zoneRowsRendered)")
        try expect(tileRowsRendered == 3, "expected current workspace's 3 tiles to render, got \(tileRowsRendered)")
        try expect(visibleNames.contains("Current Workspace") && visibleNames.contains("Other Workspace"), "both workspace rows should be visible")
        try expect(visibleNames.contains("Shell Agent") && visibleNames.contains("Scratch Note"), "current workspace tile rows should be visible")
        try expect(!visibleNames.contains("Collapsed Workspace Tile"), "collapsed workspace tile row should not be visible")

        let suiteName = "continuum-workspace-sidebar-shell-\(UUID().uuidString)"
        guard let defaults = UserDefaults(suiteName: suiteName) else { throw CheckError.failed("could not create isolated defaults") }
        defer { defaults.removePersistentDomain(forName: suiteName) }
        WorkspaceSidebarConfig.setWidth(333, defaults: defaults)
        let widthPersistenceWorked = WorkspaceSidebarConfig.resolveWidth(defaults: defaults) == 333
        WorkspaceSidebarConfig.setVisible(false, defaults: defaults)
        let hiddenRoundTrip = WorkspaceSidebarConfig.resolveVisible(defaults: defaults) == false
        WorkspaceSidebarConfig.setVisible(true, defaults: defaults)
        let visibilityPersistenceWorked = hiddenRoundTrip && WorkspaceSidebarConfig.resolveVisible(defaults: defaults) == true
        try expect(widthPersistenceWorked, "sidebar width should round-trip through UserDefaults")
        try expect(visibilityPersistenceWorked, "sidebar visibility should round-trip through UserDefaults")

        let paletteRows = LaunchPaletteModel.filterRows(LaunchPaletteModel.makeRows(profiles: []), query: "workspace sidebar")
        let paletteActionDiscoverable = paletteRows.contains { $0.displayName == LaunchPaletteAction.toggleWorkspaceSidebar.displayName }
        try expect(paletteActionDiscoverable, "workspace sidebar toggle should be command-palette discoverable")

        let timestamp = String(Int(Date().timeIntervalSince1970))
        let directory = URL(fileURLWithPath: fm.currentDirectoryPath, isDirectory: true)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("workspace-sidebar-shell", isDirectory: true)
        try fm.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let manifest: [String: Any] = [
            "check": "workspace-sidebar-shell",
            "workspaceRowsRendered": workspaceRowsRendered,
            "currentWorkspaceExpanded": currentWorkspaceExpanded,
            "currentWorkspaceSelected": currentWorkspaceSelected,
            "nonCurrentWorkspaceCollapsed": nonCurrentWorkspaceCollapsed,
            "zoneRowsRendered": zoneRowsRendered,
            "tileRowsRendered": tileRowsRendered,
            "widthPersistenceWorked": widthPersistenceWorked,
            "visibilityPersistenceWorked": visibilityPersistenceWorked,
            "paletteActionDiscoverable": paletteActionDiscoverable,
            "artifactPath": artifact.path,
        ]
        try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys]).write(to: artifact, options: .atomic)
        return artifact
    }

    static func runWorkspaceSidebarDefaultVisibleSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String {
                switch self { case let .failed(message): return message }
            }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }
        func tile(id: UUID, title: String, kind: TileKind, rank: Int) -> Tile {
            Tile(
                id: id,
                kind: kind,
                title: title,
                frame: TileFrame(x: Double(rank) * 40, y: 0, width: 320, height: 220),
                zPosition: .fromLegacyRank(rank),
                runtimeRef: nil,
                metadata: TileMetadata()
            )
        }

        let fm = FileManager.default
        let tempRoot = fm.temporaryDirectory.appendingPathComponent("continuum-workspace-sidebar-default-visible-\(UUID().uuidString)", isDirectory: true)
        let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
        try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: tempRoot) }

        let suiteName = "continuum-workspace-sidebar-default-visible-\(UUID().uuidString)"
        guard let isolatedDefaults = UserDefaults(suiteName: suiteName) else {
            throw CheckError.failed("could not create isolated defaults")
        }
        defer { isolatedDefaults.removePersistentDomain(forName: suiteName) }
        try expect(isolatedDefaults.object(forKey: WorkspaceSidebarConfig.visibleKey) == nil, "isolated defaults must start without a sidebar visibility key")
        try expect(isolatedDefaults.object(forKey: WorkspaceSidebarConfig.widthKey) == nil, "isolated defaults must start without a sidebar width key")
        let defaultVisibleResolved = WorkspaceSidebarConfig.resolveVisible(defaults: isolatedDefaults)
        try expect(defaultVisibleResolved, "fresh UserDefaults must resolve sidebar visible == defaultVisible (true)")

        let standardDefaults = UserDefaults.standard
        let originalVisible = standardDefaults.object(forKey: WorkspaceSidebarConfig.visibleKey)
        let originalWidth = standardDefaults.object(forKey: WorkspaceSidebarConfig.widthKey)
        standardDefaults.removeObject(forKey: WorkspaceSidebarConfig.visibleKey)
        standardDefaults.removeObject(forKey: WorkspaceSidebarConfig.widthKey)
        defer {
            if let originalVisible {
                standardDefaults.set(originalVisible, forKey: WorkspaceSidebarConfig.visibleKey)
            } else {
                standardDefaults.removeObject(forKey: WorkspaceSidebarConfig.visibleKey)
            }
            if let originalWidth {
                standardDefaults.set(originalWidth, forKey: WorkspaceSidebarConfig.widthKey)
            } else {
                standardDefaults.removeObject(forKey: WorkspaceSidebarConfig.widthKey)
            }
        }

        let currentWorkspace = UUID(uuidString: "00000000-0000-0000-0000-00000000E001")!
        let otherWorkspace = UUID(uuidString: "00000000-0000-0000-0000-00000000E002")!
        let zoneOne = UUID(uuidString: "00000000-0000-0000-0000-00000000E101")!
        let otherZone = UUID(uuidString: "00000000-0000-0000-0000-00000000E102")!
        let currentTiles = [
            tile(id: UUID(uuidString: "00000000-0000-0000-0000-00000000E201")!, title: "Shell Agent", kind: .terminal, rank: 1),
            tile(id: UUID(uuidString: "00000000-0000-0000-0000-00000000E202")!, title: "Docs Browser", kind: .browser, rank: 2),
        ]
        let otherTiles = [
            tile(id: UUID(uuidString: "00000000-0000-0000-0000-00000000E203")!, title: "Scratch Note", kind: .note, rank: 3),
        ]

        var registry = Registry.empty()
        registry.lastActiveWorkspaceId = currentWorkspace
        registry.workspaces = [
            WorkspaceEntry(id: currentWorkspace, name: "Current Workspace", projectIds: [], createdAt: Date(timeIntervalSince1970: 0), updatedAt: Date(timeIntervalSince1970: 0)),
            WorkspaceEntry(id: otherWorkspace, name: "Other Workspace", projectIds: [], createdAt: Date(timeIntervalSince1970: 0), updatedAt: Date(timeIntervalSince1970: 0)),
        ]
        let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
        try registryStore.save(registry)

        let currentDocument = WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [
                ZonePlacement(zoneId: zoneOne, projectId: nil, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 900, height: 600), color: "mint", collapsed: false, hydrationPolicy: .automatic, name: "Build", navKey: "1"),
            ],
            zoneZOrder: [zoneOne],
            lastActiveZoneId: zoneOne,
            ambientTiles: currentTiles.map { $0.with(zoneId: zoneOne) }
        )
        let otherDocument = WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [
                ZonePlacement(zoneId: otherZone, projectId: nil, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 900, height: 600), color: "orange", collapsed: false, hydrationPolicy: .automatic, name: "Notes", navKey: "2"),
            ],
            zoneZOrder: [otherZone],
            lastActiveZoneId: otherZone,
            ambientTiles: otherTiles.map { $0.with(zoneId: otherZone) }
        )
        try WorkspaceStore(workspaceId: currentWorkspace, applicationSupportDirectory: appSupport).save(currentDocument)
        try WorkspaceStore(workspaceId: otherWorkspace, applicationSupportDirectory: appSupport).save(otherDocument)

        let app = AppDelegate()
        app.registryStore = registryStore
        // P3.2 (design §5.9): arm the listing gate exactly as boot does, through the
        // one entry point, or every read below refuses.
        try app.reconciledManagedSessionSource.reconcile(registry: try registryStore.loadOrEmpty(), reason: .continuumRestarted, now: Date())
        let canvas = CanvasNSView(canvasState: CanvasState(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            tiles: [],
            groups: [],
            lastActiveTileId: nil
        ))
        let content = app.makeWorkspaceContentView(canvasView: canvas, frame: NSRect(x: 0, y: 0, width: 1_200, height: 800))
        content.layoutSubtreeIfNeeded()
        guard let splitView = app.workspaceSplitView,
              let sidebar = app.workspaceSidebarView else {
            throw CheckError.failed("workspace sidebar mount did not retain split/sidebar views")
        }
        splitView.layoutSubtreeIfNeeded()
        sidebar.layoutSubtreeIfNeeded()

        let sidebarIsHiddenAfterMount = sidebar.isHidden
        let sidebarWidthAfterMount = Double(sidebar.frame.width)
        let workspaceRowsRenderedAfterMount = sidebar.workspaceRowsRenderedForQA
        try expect(!sidebarIsHiddenAfterMount, "mount must leave sidebar visible with no user action")
        try expect(sidebarWidthAfterMount > 0, "mount must allocate positive sidebar width, got \(sidebarWidthAfterMount)")
        try expect(workspaceRowsRenderedAfterMount >= 1, "mount reload must render at least one workspace row, got \(workspaceRowsRenderedAfterMount)")
        // The content view an overlay attaches to must NOT be a layout container.
        // While it was the NSSplitView, ⌘K became a split PANE and its centred
        // float was overwritten on layout — it rendered full-height against the
        // window edge, which is what "⌘K still opens a sidebar" was.
        try expect(!(content is NSSplitView),
                   "the window content view must not be an NSSplitView — it would lay out ⌘K as a pane and discard its floating frame")
        try expect(content.subviews.contains(where: { $0 === splitView }),
                   "the plain content container must host the split view")

        let timestamp = String(Int(Date().timeIntervalSince1970))
        let directory = URL(fileURLWithPath: fm.currentDirectoryPath, isDirectory: true)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("workspace-sidebar-default-visible", isDirectory: true)
        try fm.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let manifest: [String: Any] = [
            "check": "workspace-sidebar-default-visible",
            "defaultVisibleResolved": defaultVisibleResolved,
            "sidebarIsHiddenAfterMount": sidebarIsHiddenAfterMount,
            "dividerPositionAfterMount": sidebarWidthAfterMount,
            "workspaceRowsRenderedAfterMount": workspaceRowsRenderedAfterMount,
            "artifactPath": artifact.path,
        ]
        try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys]).write(to: artifact, options: .atomic)
        return artifact
    }

    static func runWorkspaceSidebarActionsSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String {
                switch self { case let .failed(message): return message }
            }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }
        func tile(id: UUID, title: String, x: Double = 40, y: Double = 40, rank: Int = 1) -> Tile {
            Tile(
                id: id,
                kind: .note,
                title: title,
                frame: TileFrame(x: x, y: y, width: 260, height: 180),
                zPosition: .fromLegacyRank(rank),
                runtimeRef: nil,
                metadata: TileMetadata(noteId: id)
            )
        }
        func viewportsNearlyEqual(_ lhs: CanvasViewport, _ rhs: CanvasViewport) -> Bool {
            max(abs(lhs.x - rhs.x), abs(lhs.y - rhs.y), abs(lhs.zoom - rhs.zoom)) < 0.001
        }
        func dividerPosition(_ sidebar: WorkspaceSidebarView) -> Double {
            sidebar.isHidden ? 0.0 : Double(sidebar.frame.width)
        }

        let fm = FileManager.default
        let now = Date(timeIntervalSince1970: 1_900_100_000)
        let tempRoot = fm.temporaryDirectory.appendingPathComponent("continuum-workspace-sidebar-actions-\(UUID().uuidString)", isDirectory: true)
        let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
        let projectARoot = tempRoot.appendingPathComponent("ProjectA", isDirectory: true)
        let projectBRoot = tempRoot.appendingPathComponent("ProjectB", isDirectory: true)
        let projectCRoot = tempRoot.appendingPathComponent("ProjectC", isDirectory: true)
        try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)
        try fm.createDirectory(at: projectARoot, withIntermediateDirectories: true)
        try fm.createDirectory(at: projectBRoot, withIntermediateDirectories: true)
        try fm.createDirectory(at: projectCRoot, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: tempRoot) }

        let workspaceA = UUID(uuidString: "00000000-0000-0000-0000-00000000D201")!
        let workspaceB = UUID(uuidString: "00000000-0000-0000-0000-00000000D202")!
        let projectA = UUID(uuidString: "00000000-0000-0000-0000-00000000D211")!
        let projectB = UUID(uuidString: "00000000-0000-0000-0000-00000000D212")!
        let projectC = UUID(uuidString: "00000000-0000-0000-0000-00000000D213")!
        let zoneA = UUID(uuidString: "00000000-0000-0000-0000-00000000D221")!
        let zoneB = UUID(uuidString: "00000000-0000-0000-0000-00000000D222")!
        let zoneC = UUID(uuidString: "00000000-0000-0000-0000-00000000D223")!
        let tileA = UUID(uuidString: "00000000-0000-0000-0000-00000000D231")!
        let tileB = UUID(uuidString: "00000000-0000-0000-0000-00000000D232")!
        let tileC = UUID(uuidString: "00000000-0000-0000-0000-00000000D233")!
        let missingTile = UUID(uuidString: "00000000-0000-0000-0000-00000000D234")!

        func makeProject(id: UUID, name: String, root: URL) -> Project {
            Project(
                id: id,
                name: name,
                rootPath: root.path,
                createdAt: now,
                updatedAt: now,
                defaultLaunchProfileId: "shell",
                editorPreference: .auto,
                settings: ProjectSettings(
                    restorePolicy: .restoreDescriptors,
                    browserStoragePolicy: .perProject,
                    terminalClosePolicy: .askWhenRunning
                )
            )
        }

        let tileAValue = tile(id: tileA, title: "Current Tile", x: 680, y: 460, rank: 1)
        let tileBValue = tile(id: tileB, title: "Zone Tile", x: 60, y: 60, rank: 1)
        let tileCValue = tile(id: tileC, title: "Cross Workspace Tile", x: 640, y: 420, rank: 1)
        let missingTileValue = tile(id: missingTile, title: "Stale Missing Tile", x: 80, y: 80, rank: 2)

        let projectAObject = makeProject(id: projectA, name: "Project A", root: projectARoot)
        let projectBObject = makeProject(id: projectB, name: "Project B", root: projectBRoot)
        let projectCObject = makeProject(id: projectC, name: "Project C", root: projectCRoot)
        let storeA = ProjectStore(projectRoot: projectARoot)
        let storeB = ProjectStore(projectRoot: projectBRoot)
        let storeC = ProjectStore(projectRoot: projectCRoot)
        try storeA.saveProject(projectAObject)
        try storeA.saveCanvas(CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [tileAValue], groups: [], lastActiveTileId: nil))
        try storeB.saveProject(projectBObject)
        try storeB.saveCanvas(CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [tileBValue], groups: [], lastActiveTileId: nil))
        try storeC.saveProject(projectCObject)
        try storeC.saveCanvas(CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [tileCValue], groups: [], lastActiveTileId: nil))

        let docA = WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [
                ZonePlacement(zoneId: zoneA, projectId: projectA, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 720, height: 520), color: "blue", collapsed: false, hydrationPolicy: .automatic, name: "Current Zone", navKey: "1"),
                ZonePlacement(zoneId: zoneB, projectId: projectB, origin: ZonePoint(x: 1_200, y: 0), size: ZoneSize(width: 720, height: 520), color: "mint", collapsed: false, hydrationPolicy: .automatic, name: "Second Zone", navKey: "2"),
            ],
            zoneZOrder: [zoneA, zoneB],
            lastActiveZoneId: zoneA,
            ambientTiles: [tileAValue.with(zoneId: zoneA), tileBValue.with(zoneId: zoneB)]
        )
        let docB = WorkspaceDocument(
            viewport: CanvasViewport(x: 10, y: 20, zoom: 1),
            zones: [
                ZonePlacement(zoneId: zoneC, projectId: projectC, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 720, height: 520), color: "orange", collapsed: false, hydrationPolicy: .automatic, name: "Other Zone", navKey: "3"),
            ],
            zoneZOrder: [zoneC],
            lastActiveZoneId: zoneC,
            ambientTiles: [tileCValue.with(zoneId: zoneC), missingTileValue.with(zoneId: zoneC)]
        )
        try WorkspaceStore(workspaceId: workspaceA, applicationSupportDirectory: appSupport).save(docA)
        try WorkspaceStore(workspaceId: workspaceB, applicationSupportDirectory: appSupport).save(docB)

        var registry = Registry.empty()
        registry.lastActiveWorkspaceId = workspaceA
        registry.lastActiveProjectId = projectA
        registry.workspaces = [
            WorkspaceEntry(id: workspaceA, name: "Workspace A", projectIds: [projectA, projectB], createdAt: now, updatedAt: now),
            WorkspaceEntry(id: workspaceB, name: "Workspace B", projectIds: [projectC], createdAt: now, updatedAt: now),
        ]
        registry.projects = [
            ProjectEntry(id: projectA, name: "Project A", rootPath: projectARoot.path, workspaceId: workspaceA, lastOpenedAt: now, pinned: false, missing: false),
            ProjectEntry(id: projectB, name: "Project B", rootPath: projectBRoot.path, workspaceId: workspaceA, lastOpenedAt: now, pinned: false, missing: false),
            ProjectEntry(id: projectC, name: "Project C", rootPath: projectCRoot.path, workspaceId: workspaceB, lastOpenedAt: now, pinned: false, missing: false),
        ]
        let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
        try registryStore.save(registry)

        let app = AppDelegate()
        let standardDefaults = UserDefaults.standard
        let originalSidebarVisible = standardDefaults.object(forKey: WorkspaceSidebarConfig.visibleKey)
        let originalSidebarWidth = standardDefaults.object(forKey: WorkspaceSidebarConfig.widthKey)
        defer {
            if let originalSidebarVisible {
                standardDefaults.set(originalSidebarVisible, forKey: WorkspaceSidebarConfig.visibleKey)
            } else {
                standardDefaults.removeObject(forKey: WorkspaceSidebarConfig.visibleKey)
            }
            if let originalSidebarWidth {
                standardDefaults.set(originalSidebarWidth, forKey: WorkspaceSidebarConfig.widthKey)
            } else {
                standardDefaults.removeObject(forKey: WorkspaceSidebarConfig.widthKey)
            }
        }
        let browserEngine = BrowserEngineContext()
        defer { browserEngine.shutdown() }
        let zoneRegistry = ZoneRuntimeRegistry(closeOnZero: true, makeController: { projectId in
            if projectId == projectA { return ZoneRuntimeController(projectRoot: projectARoot, projectStore: storeA, project: projectAObject) }
            if projectId == projectB { return ZoneRuntimeController(projectRoot: projectBRoot, projectStore: storeB, project: projectBObject) }
            if projectId == projectC { return ZoneRuntimeController(projectRoot: projectCRoot, projectStore: storeC, project: projectCObject) }
            throw CheckError.failed("unexpected project id \(projectId)")
        })
        let runtime = WorkspaceRuntime(
            workspaceId: workspaceA,
            document: docA,
            registry: zoneRegistry,
            focusBroker: app.focusBroker,
            registryStore: registryStore,
            ghostty: nil,
            browserEngine: browserEngine
        )
        let initialZoneRenderModels = Self.zoneRenderModels(from: docA, registry: registry)
        let canvas = CanvasNSView(canvasState: CanvasState(viewport: docA.viewport, tiles: [], groups: [], lastActiveTileId: nil), activeZone: nil, zoneRenderModels: initialZoneRenderModels, showsZoneChrome: false)
        canvas.frame = NSRect(x: 0, y: 0, width: 1_000, height: 700)
        app.registryStore = registryStore
        // P3.2 (design §5.9): arm the listing gate exactly as boot does.
        try app.reconciledManagedSessionSource.reconcile(registry: registry, reason: .continuumRestarted, now: now)
        app.workspaceRuntime = runtime
        app.canvasView = canvas
        app.focusBroker.onAcceptedTileFocus = { [weak canvas] tileId in canvas?.markActive(tileId: tileId) }
        app.focusBroker.onAcceptedCanvasScope = { [weak canvas] in canvas?.clearFocusBorder() }
        app.installAcceptedTileFocusHook()
        try runtime.install(into: canvas, appRegistry: registry)
        canvas.layoutSubtreeIfNeeded()

        let sidebar = WorkspaceSidebarView(frame: NSRect(x: 0, y: 0, width: WorkspaceSidebarConfig.defaultWidth, height: 640))
        sidebar.onSelection = { selection in app.handleWorkspaceSidebarSelection(selection) }
        app.workspaceSidebarView = sidebar
        let contentView = NSView(frame: NSRect(x: WorkspaceSidebarConfig.defaultWidth + 1, y: 0, width: 860, height: 640))
        let splitView = NSSplitView(frame: NSRect(x: 0, y: 0, width: 1_160, height: 640))
        splitView.isVertical = true
        splitView.dividerStyle = .thin
        splitView.addArrangedSubview(sidebar)
        splitView.addArrangedSubview(contentView)
        var resizeWrites: [Double] = []
        sidebar.setWidthPersistenceForQA { width in
            resizeWrites.append(width)
            WorkspaceSidebarConfig.setWidth(width)
        }
        app.workspaceSplitView = splitView
        splitView.layoutSubtreeIfNeeded()
        try expect(splitView.delegate is WorkspaceSidebarResizeController,
                   "the sidebar must replace the composition root as the live resize delegate")
        app.reloadWorkspaceSidebar()
        sidebar.layoutSubtreeIfNeeded()

        WorkspaceSidebarConfig.setWidth(340)
        app.setWorkspaceSidebarVisible(true)
        splitView.layoutSubtreeIfNeeded()
        let visibleAfterShow = !sidebar.isHidden
        let positionAfterShow = dividerPosition(sidebar)
        try expect(visibleAfterShow, "sidebar toggle check should show the sidebar")
        try expect(abs(positionAfterShow - 340.0) <= 1.0, "sidebar toggle check should restore width 340, got \(positionAfterShow)")
        app.setWorkspaceSidebarVisible(false)
        splitView.layoutSubtreeIfNeeded()
        let visibleAfterHide = !sidebar.isHidden
        let positionAfterHide = dividerPosition(sidebar)
        let widthAfterHide = WorkspaceSidebarConfig.resolveWidth()
        try expect(
            !visibleAfterHide,
            "sidebar toggle check should hide the sidebar; isHidden=\(sidebar.isHidden) frame=\(sidebar.frame) collapsed=\(splitView.isSubviewCollapsed(sidebar))"
        )
        try expect(positionAfterHide <= 1.0, "sidebar toggle check should move hidden divider to 0, got \(positionAfterHide)")
        try expect(widthAfterHide == 340.0, "hiding sidebar must not corrupt persisted width, got \(widthAfterHide)")
        WorkspaceSidebarConfig.setWidth(340)
        app.setWorkspaceSidebarVisible(true)
        // Simulated drag: all intermediate positions/layouts remain write-free.
        sidebar.beginResizeForQA()
        splitView.setPosition(340, ofDividerAt: 0)
        splitView.layoutSubtreeIfNeeded()
        try expect(resizeWrites.isEmpty, "first intermediate divider move wrote \(resizeWrites.count) time(s)")
        splitView.setPosition(360, ofDividerAt: 0)
        splitView.layoutSubtreeIfNeeded()
        try expect(resizeWrites.isEmpty, "second intermediate divider move wrote \(resizeWrites.count) time(s)")
        sidebar.finishResizeForQA()
        sidebar.finishResizeForQA()
        let widthAfterDividerMove = WorkspaceSidebarConfig.resolveWidth()
        try expect(resizeWrites == [360.0], "resize-end must write exactly once with 360, got \(resizeWrites)")
        try expect(widthAfterDividerMove == 360.0, "resize-end must persist width 360, got \(widthAfterDividerMove)")

        guard let expectedTileAViewport = canvas.framedViewportForTileJump(tileA) else {
            throw CheckError.failed("tileA must be frameable before sidebar click")
        }
        let currentTileClickDelivered = sidebar.clickTileRowForQA(workspaceId: workspaceA, zoneId: zoneA, tileId: tileA)
        let currentTileFocusWorked = currentTileClickDelivered
            && app.focusBroker.activeSurface == .tile(tileA)
            && canvas.canvasState.lastActiveTileId == tileA
            && sidebar.selectedTargetForQA == .tile(workspaceId: workspaceA, zoneId: zoneA, tileId: tileA)
            && viewportsNearlyEqual(canvas.viewport, expectedTileAViewport)
        let measuredTileAViewport = canvas.viewport
        try expect(currentTileFocusWorked, "current workspace tile row should pan canvas to tile, focus it, and select its row")

        guard let expectedZoneViewport = canvas.fitZoneToViewport(zoneId: zoneB) else {
            throw CheckError.failed("current zone must be frameable before sidebar click")
        }
        let currentZoneClickDelivered = sidebar.clickZoneRowForQA(workspaceId: workspaceA, zoneId: zoneB)
        let currentZoneFocusWorked = currentZoneClickDelivered
            && app.navSelectedZoneId == zoneB
            && viewportsNearlyEqual(canvas.viewport, expectedZoneViewport)
            && sidebar.selectedTargetForQA == .zone(workspaceId: workspaceA, zoneId: zoneB)
        let measuredZoneViewport = canvas.viewport
        try expect(currentZoneFocusWorked, "current workspace zone row should frame zone and select its row")

        let workspaceClickDelivered = sidebar.clickWorkspaceRowForQA(workspaceB)
        let workspaceSwitchFromRowWorked = workspaceClickDelivered
            && runtime.workspaceId == workspaceB
            && sidebar.selectedTargetForQA == .workspace(workspaceB)
        try expect(workspaceSwitchFromRowWorked, "non-current workspace row should switch workspace")

        try expect(sidebar.clickWorkspaceRowForQA(workspaceA), "setup: workspace A row should switch back")
        try expect(runtime.workspaceId == workspaceA, "setup: runtime should be back on workspace A")

        try expect(sidebar.clickWorkspaceRowForQA(workspaceB), "setup: workspace B row should switch before cross-workspace tile framing")
        canvas.layoutSubtreeIfNeeded()
        guard let expectedTileCViewport = canvas.framedViewportForTileJump(tileC) else {
            throw CheckError.failed("tileC must be frameable after workspace switch")
        }
        try expect(sidebar.clickWorkspaceRowForQA(workspaceA), "setup: workspace A row should switch back before cross-workspace tile click")
        try expect(runtime.workspaceId == workspaceA, "setup: runtime should be back on workspace A before cross-workspace tile click")
        let crossTileClickDelivered = sidebar.clickTileRowForQA(workspaceId: workspaceB, zoneId: zoneC, tileId: tileC)
        let crossWorkspaceTileFocusWorked = crossTileClickDelivered
            && runtime.workspaceId == workspaceB
            && app.focusBroker.activeSurface == .tile(tileC)
            && canvas.canvasState.lastActiveTileId == tileC
            && sidebar.selectedTargetForQA == .tile(workspaceId: workspaceB, zoneId: zoneC, tileId: tileC)
            && viewportsNearlyEqual(canvas.viewport, expectedTileCViewport)
        let measuredTileCViewport = canvas.viewport
        try expect(crossWorkspaceTileFocusWorked, "non-current tile row should switch, pan canvas to tile, focus it, and select its row")

        try expect(sidebar.clickWorkspaceRowForQA(workspaceA), "setup: workspace A row should switch back before missing-target probe")
        try expect(runtime.workspaceId == workspaceA, "setup: runtime should be back on workspace A before missing-target probe")
        let missingClickDelivered = sidebar.clickTileRowForQA(workspaceId: workspaceB, zoneId: zoneC, tileId: missingTile)
        let missingTargetHandled = missingClickDelivered
            && runtime.workspaceId == workspaceB
            && canvas.navigationTileSnapshot(for: missingTile) == nil
            && app.focusBroker.activeSurface != .tile(missingTile)
            && canvas.canvasState.lastActiveTileId != missingTile
        try expect(missingTargetHandled, "stale non-current tile row should switch safely and not focus missing tile")

        let timestamp = String(Int(Date().timeIntervalSince1970))
        let directory = URL(fileURLWithPath: fm.currentDirectoryPath, isDirectory: true)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("workspace-sidebar-actions", isDirectory: true)
        try fm.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let manifest: [String: Any] = [
            "check": "workspace-sidebar-actions",
            "path": "WorkspaceSidebarView row click -> AppDelegate.handleWorkspaceSidebarSelection -> WorkspaceRuntime.switchWorkspace / CanvasNSView focus APIs",
            "workspaceSwitchFromRowWorked": workspaceSwitchFromRowWorked,
            "currentZoneFocusWorked": currentZoneFocusWorked,
            "currentTileFocusWorked": currentTileFocusWorked,
            "crossWorkspaceTileFocusWorked": crossWorkspaceTileFocusWorked,
            "missingTargetHandled": missingTargetHandled,
            "visibleAfterShow": visibleAfterShow,
            "positionAfterShow": positionAfterShow,
            "visibleAfterHide": visibleAfterHide,
            "positionAfterHide": positionAfterHide,
            "widthAfterDividerMove": widthAfterDividerMove,
            "tileAViewport": ["x": measuredTileAViewport.x, "y": measuredTileAViewport.y, "zoom": measuredTileAViewport.zoom],
            "expectedTileAViewport": ["x": expectedTileAViewport.x, "y": expectedTileAViewport.y, "zoom": expectedTileAViewport.zoom],
            "tileCViewport": ["x": measuredTileCViewport.x, "y": measuredTileCViewport.y, "zoom": measuredTileCViewport.zoom],
            "expectedTileCViewport": ["x": expectedTileCViewport.x, "y": expectedTileCViewport.y, "zoom": expectedTileCViewport.zoom],
            "currentZoneViewport": ["x": measuredZoneViewport.x, "y": measuredZoneViewport.y, "zoom": measuredZoneViewport.zoom],
            "expectedCurrentZoneViewport": ["x": expectedZoneViewport.x, "y": expectedZoneViewport.y, "zoom": expectedZoneViewport.zoom],
            "selectedRowAfterMissingTarget": String(describing: sidebar.selectedTargetForQA),
            "artifactPath": artifact.path,
        ]
        try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys]).write(to: artifact, options: .atomic)
        return artifact
    }

    static func runWorkspaceSidebarLiveStatusSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String {
                switch self { case let .failed(message): return message }
            }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }
        func tile(id: UUID, title: String, x: Double, y: Double, kind: TileKind = .terminal, rank: Int = 1) -> Tile {
            Tile(
                id: id,
                kind: kind,
                title: title,
                frame: TileFrame(x: x, y: y, width: 180, height: 120),
                zPosition: .fromLegacyRank(rank),
                runtimeRef: nil,
                metadata: kind == .note ? TileMetadata(noteId: id) : TileMetadata()
            )
        }
        func saveSession(_ store: ProjectStore, tileId: UUID, status: AgentStatus, now: Date, root: URL) throws {
            try store.saveSession(TerminalSessionDescriptor(
                id: UUID(),
                tileId: tileId,
                launchProfileId: "agent",
                command: "/bin/zsh",
                args: [],
                cwd: root.path,
                env: [:],
                title: "Agent",
                createdAt: now,
                lastStartedAt: now,
                lastExit: nil,
                agentDescriptor: AgentDescriptor(agentKind: .unknown, worktreePath: root.path, status: status, statusUpdatedAt: now)
            ))
        }

        let fm = FileManager.default
        let now = Date(timeIntervalSince1970: 1_900_300_000)
        let tempRoot = fm.temporaryDirectory.appendingPathComponent("continuum-workspace-sidebar-live-status-\(UUID().uuidString)", isDirectory: true)
        let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
        let projectRoot = tempRoot.appendingPathComponent("Project", isDirectory: true)
        try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)
        try fm.createDirectory(at: projectRoot, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: tempRoot) }

        let workspaceId = UUID(uuidString: "00000000-0000-0000-0000-00000000E301")!
        let projectId = UUID(uuidString: "00000000-0000-0000-0000-00000000E302")!
        let projectZoneId = UUID(uuidString: "00000000-0000-0000-0000-00000000E303")!
        let groupZoneId = UUID(uuidString: "00000000-0000-0000-0000-00000000E304")!
        let workingTileId = UUID(uuidString: "00000000-0000-0000-0000-00000000E311")!
        let needsTileId = UUID(uuidString: "00000000-0000-0000-0000-00000000E312")!
        let doneTileId = UUID(uuidString: "00000000-0000-0000-0000-00000000E313")!
        let staleTileId = UUID(uuidString: "00000000-0000-0000-0000-00000000E314")!
        let createdTileId = UUID(uuidString: "00000000-0000-0000-0000-00000000E315")!
        let groupTileId = UUID(uuidString: "00000000-0000-0000-0000-00000000E316")!
        // P2B.5: a MANAGED-agent tile. `kind != .terminal`, which is the whole point —
        // the sidebar's status walk used to filter on that and printed "no agent"
        // beside a live agent.
        let managedTileId = UUID(uuidString: "00000000-0000-0000-0000-00000000E317")!

        let workingTile = tile(id: workingTileId, title: "Working Agent", x: 40, y: 40, rank: 1)
        let needsTile = tile(id: needsTileId, title: "Needs Agent", x: 260, y: 40, rank: 2)
        let doneTile = tile(id: doneTileId, title: "Done Agent", x: 40, y: 220, rank: 3)
        let staleTile = tile(id: staleTileId, title: "Stale Agent", x: 260, y: 220, rank: 4)
        let createdTile = tile(id: createdTileId, title: "Created Live Tile", x: 500, y: 40, kind: .note, rank: 5)
        let groupTile = tile(id: groupTileId, title: "Group Note", x: 940, y: 40, kind: .note, rank: 6)
        let managedTile = tile(id: managedTileId, title: "Managed Agent", x: 500, y: 220, kind: .managedAgent, rank: 7)

        let project = Project(
            id: projectId,
            name: "Live Status Project",
            rootPath: projectRoot.path,
            createdAt: now,
            updatedAt: now,
            defaultLaunchProfileId: "shell",
            editorPreference: .auto,
            settings: ProjectSettings(restorePolicy: .restoreDescriptors, browserStoragePolicy: .perProject, terminalClosePolicy: .askWhenRunning)
        )
        let projectStore = ProjectStore(projectRoot: projectRoot)
        try projectStore.saveProject(project)
        try projectStore.saveCanvas(CanvasState(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            tiles: [workingTile, needsTile, doneTile, staleTile, managedTile],
            groups: [],
            lastActiveTileId: workingTileId
        ))
        try saveSession(projectStore, tileId: workingTileId, status: .working, now: now, root: projectRoot)
        try saveSession(projectStore, tileId: needsTileId, status: .needsAttention, now: now, root: projectRoot)
        try saveSession(projectStore, tileId: doneTileId, status: .done, now: now, root: projectRoot)
        try saveSession(projectStore, tileId: staleTileId, status: .stale, now: now, root: projectRoot)
        // The managed agent has no `TerminalSessionDescriptor` — it is not a terminal
        // session. Its status lives in the per-project managed record store, which is
        // exactly why the terminal-only walk could not see it.
        try ManagedAgentSessionStore(projectRoot: projectRoot).upsert(ManagedAgentSessionRecord(
            tileId: managedTileId, agentKind: .managed, status: .running, lastSeenAt: now
        ))

        var registry = Registry.empty()
        registry.lastActiveWorkspaceId = workspaceId
        registry.lastActiveProjectId = projectId
        registry.workspaces = [
            WorkspaceEntry(id: workspaceId, name: "Live Workspace", projectIds: [projectId], createdAt: now, updatedAt: now)
        ]
        registry.projects = [
            ProjectEntry(id: projectId, name: "Live Status Project", rootPath: projectRoot.path, workspaceId: workspaceId, lastOpenedAt: now, pinned: false, missing: false)
        ]
        let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
        try registryStore.save(registry)

        let projectZone = ZonePlacement(zoneId: projectZoneId, projectId: projectId, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 820, height: 520), color: "blue", collapsed: false, hydrationPolicy: .automatic, name: "", navKey: "1")
        let groupZone = ZonePlacement(zoneId: groupZoneId, projectId: nil, origin: ZonePoint(x: 900, y: 0), size: ZoneSize(width: 360, height: 260), color: "mint", collapsed: false, hydrationPolicy: .automatic, name: "Review", navKey: "2")
        let document = WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [projectZone, groupZone],
            zoneZOrder: [projectZoneId, groupZoneId],
            lastActiveZoneId: projectZoneId,
            ambientTiles: [groupTile.with(zoneId: groupZoneId)]
        )
        try WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport).save(document)

        let app = AppDelegate()
        let browserEngine = BrowserEngineContext()
        defer { browserEngine.shutdown() }
        let controller = ZoneRuntimeController(projectRoot: projectRoot, projectStore: projectStore, project: project)
        let zoneRegistry = ZoneRuntimeRegistry(closeOnZero: true, makeController: { id in
            guard id == projectId else { throw CheckError.failed("unexpected project id \(id)") }
            return controller
        })
        let runtime = WorkspaceRuntime(
            boot: controller,
            workspaceId: workspaceId,
            document: document,
            registry: zoneRegistry,
            focusBroker: app.focusBroker,
            registryStore: registryStore,
            ghostty: nil,
            browserEngine: browserEngine
        )
        let renderModels = Self.zoneRenderModels(from: document, registry: registry)
        let canvas = CanvasNSView(canvasState: try projectStore.loadCanvas(), activeZone: projectZone, zoneRenderModels: renderModels, showsZoneChrome: false)
        canvas.delegate = app
        canvas.frame = NSRect(x: 0, y: 0, width: 1_000, height: 700)
        // No view for the managed tile ON PURPOSE (the P2B.4 precedent): a freshly
        // built `ManagedAgentTileNSView` reports `.configuring`, which would override
        // its persisted record and make the fixture describe the view instead of the
        // store.
        for tile in canvas.canvasState.tiles where tile.kind == .terminal {
            let view = TileNSView(tile: tile)
            if tile.id == workingTileId { view.agentStatus = .working }
            if tile.id == needsTileId { view.agentStatus = .needsAttention }
            if tile.id == doneTileId { view.agentStatus = .done }
            if tile.id == staleTileId { view.agentStatus = .stale }
            canvas.install(tileView: view, for: tile)
        }

        let sidebar = WorkspaceSidebarView(frame: NSRect(x: 0, y: 0, width: WorkspaceSidebarConfig.defaultWidth, height: 640))
        let sidebarIdentity = ObjectIdentifier(sidebar)
        app.registryStore = registryStore
        // P3.2 (design §5.9): arm the listing gate exactly as boot does.
        try app.reconciledManagedSessionSource.reconcile(registry: registry, reason: .continuumRestarted, now: now)
        app.workspaceRuntime = runtime
        app.canvasView = canvas
        app.workspaceSidebarView = sidebar
        app.reloadWorkspaceSidebar()
        sidebar.layoutSubtreeIfNeeded()

        let initialGlyphsRendered = sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: workingTileId) == "working"
            && sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: needsTileId) == "needs you"
            && sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: doneTileId) == "done"
            && sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: staleTileId) == "stale"
            && sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: groupZoneId, tileId: groupTileId) == "no agent"
        try expect(sidebar.tileStatusGlyphForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: needsTileId) == "◆", "needs-attention tile should render the attention glyph")
        try expect(initialGlyphsRendered, "sidebar should render working/needs/done/stale/no-agent status texts")

        // P2B.5 · A MANAGED-AGENT TILE SHOWS ITS STATUS. Its record says `.running`,
        // so its row must read "working" — the literal defect this ticket closes is
        // that it read "no agent" while the agent was alive.
        //
        // THREE NEGATIVE TESTS OBSERVED RED at exit 1 with the final code:
        //   1. `agentStatus: tile.kind == .terminal ? … : nil` put back in
        //      `SidebarTreeBuilder.build` — the pre-P2B.4 sidebar filter, restored →
        //      `a managed-agent tile must show its record's status in the sidebar —
        //      got 'no agent'`, and with that assertion stood down, the sweep below
        //      catches it too: `managed tile has an agent, so its row must not read
        //      'no agent'`.
        //   2. `.filter { $0.kind == .terminal }` put back in `currentAgentTileIds`
        //      → `--agent-inventory-wiring-check` red: `⌥-cycling must reach a
        //      managed-agent tile … got [2B4…E1]`.
        //   3. this fixture's `ManagedAgentSessionStore.upsert` deleted → the same
        //      "no agent", which is what proves the row's status comes from the
        //      record and not from something incidental to the tile.
        //
        // P4.14 MOVED THE WORD, not the property: the record is `.running` with no
        // live view and no runner in flight. P3.1/P3.2 moved this word: the arming
        // sweep terminalizes the persisted record, so the derived status is `stale`,
        // and `SidebarAgentStatusKind` keeps `stale` as its OWN word rather than
        // folding it to `unknown` the way it folds `configuring`/`idle`. What this
        // assertion exists to catch is unchanged and is stated twice below: the row
        // must not read "no agent" for a tile whose agent is alive.
        let managedRowText = sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: managedTileId) ?? ""
        try expect(managedRowText == "stale",
                   "a managed-agent tile must show its record's status in the sidebar — got '\(managedRowText)'")
        try expect(managedRowText != "no agent",
                   "the literal P2B.5 defect: a live managed agent's row read 'no agent'")
        // The regression witness, as the packet words it: "no agent" must not appear
        // for a tile that HAS an agent. Swept over every agent-bearing tile rather
        // than asserted once, so a future kind filter cannot hide behind one row.
        for (tileId, label) in [(workingTileId, "terminal working"), (needsTileId, "terminal needs-attention"), (doneTileId, "terminal done"), (staleTileId, "terminal stale"), (managedTileId, "managed")] {
            let text = sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: tileId) ?? "<no row>"
            try expect(text != "no agent", "\(label) tile has an agent, so its row must not read 'no agent'")
        }
        // Vacuity guard: "no agent" is still what a tile WITHOUT an agent reads, so
        // the sweep above is measuring something.
        try expect(sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: groupZoneId, tileId: groupTileId) == "no agent",
                   "a tile with no agent must still read 'no agent', or the sweep above is vacuous")

        // P4.14: ONE working agent, not two. The terminal agent is genuinely working;
        // the managed one was only ever "working" because its record said `running`,
        // and it now rolls up as the idle agent it is. The rollup is not smaller than
        // reality — it stopped counting a fact written once at spawn.
        try expect(sidebar.zoneStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId)?.contains("1 working") == true, "zone row should include working rollup text for the working terminal agent — got \(String(describing: sidebar.zoneStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId)))")
        try expect(sidebar.zoneStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId)?.contains("1 needs you") == true, "zone row should include needs-attention rollup text")

        canvas.install(tileView: TileNSView(tile: createdTile), for: createdTile)
        sidebar.layoutSubtreeIfNeeded()
        let tileCreateUpdatedSidebar = sidebar.visibleDisplayNamesForQA.contains("Created Live Tile")
        try expect(tileCreateUpdatedSidebar, "tile install should update the existing sidebar view")

        canvas.removeTile(id: createdTileId)
        sidebar.layoutSubtreeIfNeeded()
        let tileDeleteUpdatedSidebar = !sidebar.visibleDisplayNamesForQA.contains("Created Live Tile")
        try expect(tileDeleteUpdatedSidebar, "tile removal should update the existing sidebar view")

        app.persistRenamedZone(groupZoneId, name: "Renamed Review")
        sidebar.layoutSubtreeIfNeeded()
        let zoneRenameUpdatedSidebar = sidebar.visibleDisplayNamesForQA.contains("Renamed Review")
        try expect(zoneRenameUpdatedSidebar, "zone rename should update the existing sidebar view")

        app.updateAgentStatus(tileId: workingTileId, status: .done, now: now.addingTimeInterval(60))
        sidebar.layoutSubtreeIfNeeded()
        let statusChangeUpdatedSidebar = sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: workingTileId) == "done"
            && sidebar.zoneStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId)?.contains("2 done") == true
        try expect(statusChangeUpdatedSidebar, "agent status update should refresh the sidebar row view model")

        app.observedAgentStatuses = [workingTileId: .needsAttention, doneTileId: .working]
        app.reloadWorkspaceSidebar()
        sidebar.layoutSubtreeIfNeeded()
        let observerNeedsOverrideText = sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: workingTileId) ?? ""
        let observerWorkingOverrideText = sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: doneTileId) ?? ""
        let observerZoneStatusText = sidebar.zoneStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId) ?? ""
        // P4.14: "1 working", where it read "2" — the second was the managed agent's
        // persisted `running`, which no longer claims a turn is in flight. The
        // override under test is the `doneTile → working` one, and it is still counted.
        let observerOverrideWon = observerNeedsOverrideText == "needs you"
            && observerWorkingOverrideText == "working"
            && observerZoneStatusText.contains("2 needs you")
            && observerZoneStatusText.contains("1 working")
        try expect(
            observerOverrideWon,
            "observer-supplied statuses should override canvas/session values in the live sidebar path (workingTile='\(observerNeedsOverrideText)', doneTile='\(observerWorkingOverrideText)', zone='\(observerZoneStatusText)')"
        )

        app.observedAgentStatuses = [:]
        app.reloadWorkspaceSidebar()
        sidebar.layoutSubtreeIfNeeded()
        let observerClearReverted = sidebar.tileStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId, tileId: workingTileId) == "done"
            && sidebar.zoneStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId)?.contains("2 done") == true
        try expect(observerClearReverted, "clearing observer output should revert the sidebar to canvas/session values")

        let agentStatusGlyphsRendered = initialGlyphsRendered && statusChangeUpdatedSidebar
        let sidebarIdentityPreserved = ObjectIdentifier(sidebar) == sidebarIdentity
        try expect(sidebarIdentityPreserved, "check must update the existing sidebar instance, not rebuild the app/window")

        let timestamp = String(Int(Date().timeIntervalSince1970))
        let directory = URL(fileURLWithPath: fm.currentDirectoryPath, isDirectory: true)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("workspace-sidebar-live-status", isDirectory: true)
        try fm.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let manifest: [String: Any] = [
            "check": "workspace-sidebar-live-status",
            "tileCreateUpdatedSidebar": tileCreateUpdatedSidebar,
            "tileDeleteUpdatedSidebar": tileDeleteUpdatedSidebar,
            "zoneRenameUpdatedSidebar": zoneRenameUpdatedSidebar,
            "agentStatusGlyphsRendered": agentStatusGlyphsRendered,
            "managedAgentRowStatusText": managedRowText,
            "noNewStatusPipeline": true,
            "statusChangeUpdatedSidebar": statusChangeUpdatedSidebar,
            "observerNeedsOverrideText": observerNeedsOverrideText,
            "observerWorkingOverrideText": observerWorkingOverrideText,
            "observerZoneStatusText": observerZoneStatusText,
            "observerOverrideWon": observerOverrideWon,
            "observerClearReverted": observerClearReverted,
            "sidebarIdentityPreserved": sidebarIdentityPreserved,
            "projectZoneStatusText": sidebar.zoneStatusTextForQA(workspaceId: workspaceId, zoneId: projectZoneId) ?? "",
            "artifactPath": artifact.path,
        ]
        try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys]).write(to: artifact, options: .atomic)
        return artifact
    }

    static func runWorkspaceTopBarSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String {
                switch self { case let .failed(message): return message }
            }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }

        let fm = FileManager.default
        let now = Date(timeIntervalSince1970: 1_900_400_000)
        let tempRoot = fm.temporaryDirectory.appendingPathComponent("continuum-workspace-top-bar-\(UUID().uuidString)", isDirectory: true)
        let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
        try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: tempRoot) }

        let workspaceA = UUID(uuidString: "00000000-0000-0000-0000-00000000F401")!
        let workspaceB = UUID(uuidString: "00000000-0000-0000-0000-00000000F402")!
        let projectA = UUID(uuidString: "00000000-0000-0000-0000-00000000F411")!
        let projectB = UUID(uuidString: "00000000-0000-0000-0000-00000000F412")!
        let projectC = UUID(uuidString: "00000000-0000-0000-0000-00000000F413")!
        let zoneA1 = UUID(uuidString: "00000000-0000-0000-0000-00000000F421")!
        let zoneA2 = UUID(uuidString: "00000000-0000-0000-0000-00000000F422")!
        let zoneB1 = UUID(uuidString: "00000000-0000-0000-0000-00000000F423")!
        let zoneB2 = UUID(uuidString: "00000000-0000-0000-0000-00000000F424")!

        var registry = Registry.empty()
        registry.lastActiveWorkspaceId = workspaceA
        registry.workspaces = [
            WorkspaceEntry(id: workspaceA, name: "Alpha Workspace", projectIds: [projectA, projectB], createdAt: now, updatedAt: now),
            WorkspaceEntry(id: workspaceB, name: "Beta Workspace", projectIds: [projectC], createdAt: now, updatedAt: now),
        ]
        registry.projects = [
            ProjectEntry(id: projectA, name: "Project A", rootPath: "/tmp/project-a", workspaceId: workspaceA, lastOpenedAt: now, pinned: false, missing: false),
            ProjectEntry(id: projectB, name: "Project B", rootPath: "/tmp/project-b", workspaceId: workspaceA, lastOpenedAt: now, pinned: false, missing: false),
            ProjectEntry(id: projectC, name: "Project C", rootPath: "/tmp/project-c", workspaceId: workspaceB, lastOpenedAt: now, pinned: false, missing: false),
        ]
        let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
        try registryStore.save(registry)

        let documentA = WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [
                ZonePlacement(zoneId: zoneA1, projectId: nil, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 720, height: 520), color: "blue", collapsed: false, hydrationPolicy: .automatic, name: "Plan", navKey: "1"),
                ZonePlacement(zoneId: zoneA2, projectId: nil, origin: ZonePoint(x: 760, y: 0), size: ZoneSize(width: 720, height: 520), color: "mint", collapsed: false, hydrationPolicy: .automatic, name: "Build", navKey: "2"),
            ],
            zoneZOrder: [zoneA1, zoneA2],
            lastActiveZoneId: zoneA1
        )
        let documentB = WorkspaceDocument(
            viewport: CanvasViewport(x: 10, y: 20, zoom: 1),
            zones: [
                ZonePlacement(zoneId: zoneB1, projectId: nil, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 640, height: 480), color: "orange", collapsed: false, hydrationPolicy: .automatic, name: "Review", navKey: "3"),
            ],
            zoneZOrder: [zoneB1],
            lastActiveZoneId: zoneB1
        )
        try WorkspaceStore(workspaceId: workspaceA, applicationSupportDirectory: appSupport).save(documentA)
        try WorkspaceStore(workspaceId: workspaceB, applicationSupportDirectory: appSupport).save(documentB)

        let app = AppDelegate()
        let browserEngine = BrowserEngineContext()
        defer { browserEngine.shutdown() }
        let runtime = WorkspaceRuntime(
            workspaceId: workspaceA,
            document: documentA,
            registry: ZoneRuntimeRegistry(closeOnZero: true, makeController: { _ in
                throw CheckError.failed("workspace top bar check should not acquire project controllers")
            }),
            focusBroker: app.focusBroker,
            registryStore: registryStore,
            ghostty: nil,
            browserEngine: browserEngine
        )
        // M1.10: a switch now requires a canvas — the whole defect was that it
        // silently did the document half without one. This fixture only asserts the
        // top bar, but it must still drive a legal switch.
        let topBarCanvas = CanvasNSView(canvasState: CanvasState(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [], groups: [], lastActiveTileId: nil))
        runtime.adoptCanvas(topBarCanvas)
        let topBar = WorkspaceTopBarView(frame: NSRect(x: 0, y: 0, width: 900, height: 44))
        app.registryStore = registryStore
        app.workspaceRuntime = runtime
        app.workspaceTopBarView = topBar
        app.configureWorkspaceTopBar(topBar)
        app.reloadWorkspaceTopBar()
        topBar.layoutSubtreeIfNeeded()

        let currentWorkspaceNameRendered = topBar.workspaceNameForQA == "Alpha Workspace"
        let countsRendered = topBar.countsTextForQA == "2 projects · 2 zones"
            && topBar.switchWorkspaceNamesForQA == ["Alpha Workspace", "Beta Workspace"]
        try expect(currentWorkspaceNameRendered, "top bar should render the current workspace name")
        try expect(countsRendered, "top bar should render project/zone counts and switch menu workspace names")

        let switchDelivered = topBar.selectWorkspaceForQA(workspaceB)
        topBar.layoutSubtreeIfNeeded()
        let switchUpdatedName = switchDelivered
            && runtime.workspaceId == workspaceB
            && topBar.workspaceNameForQA == "Beta Workspace"
            && topBar.countsTextForQA == "1 project · 1 zone"
        try expect(switchUpdatedName, "top bar switch action should update rendered workspace identity/counts")

        app.workspaceRenamePromptProvider = { currentName in
            currentName == "Beta Workspace" ? "Beta Renamed" : nil
        }
        let renameDelivered = topBar.clickRenameForQA()
        topBar.layoutSubtreeIfNeeded()
        let renameUpdatedName = renameDelivered && topBar.workspaceNameForQA == "Beta Renamed"
        try expect(renameUpdatedName, "top bar rename action should refresh rendered workspace name")

        var unsavedDocument = documentB
        unsavedDocument.zones.append(ZonePlacement(zoneId: zoneB2, projectId: nil, origin: ZonePoint(x: 700, y: 0), size: ZoneSize(width: 640, height: 480), color: "purple", collapsed: false, hydrationPolicy: .automatic, name: "Unsaved", navKey: nil))
        unsavedDocument.bringZoneToFront(zoneB2)
        unsavedDocument.lastActiveZoneId = zoneB2
        runtime.replaceDocument(unsavedDocument, for: workspaceB)
        app.reloadWorkspaceTopBar()
        let unsavedStateRendered = topBar.saveStateTextForQA == WorkspaceDocumentSaveState.unsavedChanges.displayTitle
        let saveController = WorkspaceDocumentSaveController(store: WorkspaceStore(workspaceId: workspaceB, applicationSupportDirectory: appSupport))
        saveController.scheduleZoneLayoutSave(unsavedDocument)
        try expect(saveController.state == .unsavedChanges, "workspace save controller should expose unsaved state after scheduling")
        try saveController.flushPendingSave()
        app.reloadWorkspaceTopBar()
        let savedStateRendered = topBar.saveStateTextForQA == WorkspaceDocumentSaveState.saved.displayTitle
        let saveStateRendered = unsavedStateRendered && savedStateRendered && saveController.state == .saved
        try expect(saveStateRendered, "top bar should render workspace save state before and after a real save")

        let timestamp = String(Int(Date().timeIntervalSince1970))
        let directory = URL(fileURLWithPath: fm.currentDirectoryPath, isDirectory: true)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("workspace-top-bar", isDirectory: true)
        try fm.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let manifest: [String: Any] = [
            "check": "workspace-top-bar",
            "path": "WorkspaceTopBarView -> AppDelegate switch/rename/save-state reload paths",
            "currentWorkspaceNameRendered": currentWorkspaceNameRendered,
            "countsRendered": countsRendered,
            "switchUpdatedName": switchUpdatedName,
            "renameUpdatedName": renameUpdatedName,
            "saveStateRendered": saveStateRendered,
            "initialName": "Alpha Workspace",
            "renamedName": topBar.workspaceNameForQA,
            "finalCountsText": topBar.countsTextForQA,
            "artifactPath": artifact.path,
        ]
        try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys]).write(to: artifact, options: .atomic)
        return artifact
    }

    static func runWorkspaceManagementPolishSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String {
                switch self { case let .failed(message): return message }
            }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }
        func document(zoneId: UUID? = nil, name: String = "") -> WorkspaceDocument {
            let zones: [ZonePlacement]
            let order: [UUID]
            if let zoneId {
                zones = [ZonePlacement(zoneId: zoneId, projectId: nil, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 720, height: 520), color: "blue", collapsed: false, hydrationPolicy: .automatic, name: name, navKey: nil)]
                order = [zoneId]
            } else {
                zones = []
                order = []
            }
            return WorkspaceDocument(
                viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
                zones: zones,
                zoneZOrder: order,
                lastActiveZoneId: order.first
            )
        }

        let fm = FileManager.default
        let now = Date(timeIntervalSince1970: 1_900_500_000)
        let tempRoot = fm.temporaryDirectory.appendingPathComponent("continuum-workspace-management-polish-\(UUID().uuidString)", isDirectory: true)
        let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
        try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: tempRoot) }

        let workspaceA = UUID(uuidString: "00000000-0000-0000-0000-00000000F501")!
        let workspaceB = UUID(uuidString: "00000000-0000-0000-0000-00000000F502")!
        let zoneA = UUID(uuidString: "00000000-0000-0000-0000-00000000F511")!
        let zoneB = UUID(uuidString: "00000000-0000-0000-0000-00000000F512")!
        var registry = Registry.empty()
        registry.lastActiveWorkspaceId = workspaceA
        registry.workspaces = [
            WorkspaceEntry(id: workspaceA, name: "Alpha Workspace", projectIds: [], createdAt: now, updatedAt: now),
            WorkspaceEntry(id: workspaceB, name: "Beta Workspace", projectIds: [], createdAt: now, updatedAt: now),
        ]
        let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
        try registryStore.save(registry)
        try WorkspaceStore(workspaceId: workspaceA, applicationSupportDirectory: appSupport).save(document(zoneId: zoneA, name: "Alpha Zone"))
        try WorkspaceStore(workspaceId: workspaceB, applicationSupportDirectory: appSupport).save(document(zoneId: zoneB, name: "Beta Zone"))

        let app = AppDelegate()
        let browserEngine = BrowserEngineContext()
        defer { browserEngine.shutdown() }
        let runtime = WorkspaceRuntime(
            workspaceId: workspaceA,
            document: document(zoneId: zoneA, name: "Alpha Zone"),
            registry: ZoneRuntimeRegistry(closeOnZero: true, makeController: { _ in
                throw CheckError.failed("workspace management polish check should not acquire project controllers")
            }),
            focusBroker: app.focusBroker,
            registryStore: registryStore,
            ghostty: nil,
            browserEngine: browserEngine
        )
        let sidebar = WorkspaceSidebarView(frame: NSRect(x: 0, y: 0, width: WorkspaceSidebarConfig.defaultWidth, height: 640))
        let topBar = WorkspaceTopBarView(frame: NSRect(x: 0, y: 0, width: 980, height: 44))
        app.registryStore = registryStore
        // P3.2 (design §5.9): arm the listing gate exactly as boot does.
        try app.reconciledManagedSessionSource.reconcile(registry: registry, reason: .continuumRestarted, now: now)
        // M1.10: a switch now requires a canvas; see the top-bar fixture.
        let polishCanvas = CanvasNSView(canvasState: CanvasState(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [], groups: [], lastActiveTileId: nil))
        runtime.adoptCanvas(polishCanvas)
        app.workspaceRuntime = runtime
        app.workspaceSidebarView = sidebar
        app.workspaceTopBarView = topBar
        app.configureWorkspaceSidebar(sidebar)
        app.configureWorkspaceTopBar(topBar)
        app.reloadWorkspaceSidebar()
        sidebar.layoutSubtreeIfNeeded()
        topBar.layoutSubtreeIfNeeded()

        // Ticket: docs/38-tickets/90-agent-ux/P3.14-preserve-workspace-management.md
        //
        // The three verbs are no longer buttons in the sidebar header; they are the
        // separated block at the foot of the scope popup's menu. Asserted on the menu
        // AppKit is really showing, and asserted BEFORE the actions are driven —
        // `clickCreateForQA` and friends go through that menu now, so a check that only
        // called them could pass against a UI with no visible way in.
        let managementTitles = sidebar.workspaceManagementTitlesForQA
        try expect(
            managementTitles == ["New Workspace…", "Rename Workspace…", "Delete Workspace…"],
            "the scope menu should carry the three workspace verbs, got \(managementTitles)"
        )
        try expect(
            sidebar.isWorkspaceManagementSeparatedForQA,
            "the workspace verbs should be a separated section, below the scopes"
        )
        try expect(
            sidebar.inboxForQA.scopeTitlesForQA.allSatisfy { !managementTitles.contains($0) },
            "a verb must not read as a scope you can pick — got scopes \(sidebar.inboxForQA.scopeTitlesForQA)"
        )

        // "Acting on the currently scoped workspace": under a workspace scope the verbs
        // must land on THAT workspace, not on whichever one the canvas is showing.
        // Alpha stays open and untouched throughout.
        sidebar.configureInboxScope(.workspace("Beta Workspace")) { _ in }
        try expect(
            sidebar.workspaceIdForManagementActionForQA == workspaceB,
            "a workspace scope should name the verbs' target, got \(String(describing: sidebar.workspaceIdForManagementActionForQA))"
        )
        app.workspaceRenamePromptProvider = { currentName in
            currentName == "Beta Workspace" ? "Beta Renamed" : nil
        }
        let scopedRenameDelivered = sidebar.clickRenameForQA()
        sidebar.layoutSubtreeIfNeeded()
        let scopedRegistry = try registryStore.loadOrEmpty()
        let scopedRenameTargetedScope = scopedRenameDelivered
            && scopedRegistry.workspaces.contains(where: { $0.id == workspaceB && $0.name == "Beta Renamed" })
            && scopedRegistry.workspaces.contains(where: { $0.id == workspaceA && $0.name == "Alpha Workspace" })
            && runtime.workspaceId == workspaceA
        try expect(scopedRenameTargetedScope, "a scoped rename should act on the scoped workspace, not the open one")

        // Back to `.all` for the rest, which is both the default scope and the one the
        // header buttons' old behaviour (selection, then current workspace) is defined
        // under. Set explicitly rather than left to whatever `configureWorkspaceSidebar`
        // restored from this machine's defaults.
        sidebar.configureInboxScope(.all) { _ in }

        app.workspaceCreatePromptProvider = { "Created From Sidebar" }
        let createDelivered = sidebar.clickCreateForQA()
        sidebar.layoutSubtreeIfNeeded()
        topBar.layoutSubtreeIfNeeded()
        let createdRegistry = try registryStore.loadOrEmpty()
        guard let createdWorkspace = createdRegistry.workspaces.first(where: { $0.name == "Created From Sidebar" }) else {
            throw CheckError.failed("create action did not add workspace to registry")
        }
        let createdDocument = try WorkspaceStore(workspaceId: createdWorkspace.id, applicationSupportDirectory: appSupport).load()
        let createWorked = createDelivered
            && runtime.workspaceId == createdWorkspace.id
            && createdDocument.zones.isEmpty
            && topBar.countsTextForQA.contains("empty workspace")
            && topBar.workspaceNameForQA == "Created From Sidebar"
        try expect(createWorked, "sidebar create should create and switch to a visible empty workspace")

        app.workspaceRenamePromptProvider = { currentName in
            currentName == "Created From Sidebar" ? "Created Renamed" : nil
        }
        let renameDelivered = topBar.clickRenameForQA()
        topBar.layoutSubtreeIfNeeded()
        let renamedRegistry = try registryStore.loadOrEmpty()
        let renameWorked = renameDelivered
            && renamedRegistry.workspaces.contains(where: { $0.id == createdWorkspace.id && $0.name == "Created Renamed" })
            && topBar.workspaceNameForQA == "Created Renamed"
        try expect(renameWorked, "top bar rename should validate, persist, and refresh the workspace name")

        app.workspaceRenamePromptProvider = { _ in "   " }
        let invalidDelivered = topBar.clickRenameForQA()
        topBar.layoutSubtreeIfNeeded()
        let invalidRegistry = try registryStore.loadOrEmpty()
        let invalidRenameRejected = invalidDelivered
            && invalidRegistry.workspaces.contains(where: { $0.id == createdWorkspace.id && $0.name == "Created Renamed" })
            && topBar.managementMessageForQA.contains("can't be empty")
        try expect(invalidRenameRejected, "empty workspace rename should be rejected with a visible validation message")

        var deleteRequests: [WorkspaceDeleteConfirmationRequest] = []
        app.workspaceDeleteConfirmationProvider = { request in
            deleteRequests.append(request)
            return false
        }
        // P3.14: the sidebar's Delete verb, DECLINED — the guard the header button had,
        // reached through the menu, with the confirmation provider still in front of it.
        // (The popup keeping its scope title is asserted here too, but the witness for
        // it is in `runAgentInboxChecks`: every app path that runs a verb also pushes
        // rows, and the menu rebuild inside that push re-selects the scope anyway.)
        let cancelFromMenuDelivered = sidebar.clickDeleteForQA()
        sidebar.layoutSubtreeIfNeeded()
        let cancelFromMenuRegistry = try registryStore.loadOrEmpty()
        let scopeSurvivedVerb = cancelFromMenuDelivered
            && sidebar.inboxForQA.selectedScopeTitleForQA == InboxScope.allTitle
            && cancelFromMenuRegistry.workspaces.contains(where: { $0.id == createdWorkspace.id })
        try expect(
            scopeSurvivedVerb,
            "picking a verb should leave the popup on its scope, got '\(sidebar.inboxForQA.selectedScopeTitleForQA)'"
        )

        let cancelDelivered = topBar.clickDeleteForQA()
        topBar.layoutSubtreeIfNeeded()
        let cancelRegistry = try registryStore.loadOrEmpty()
        let deleteCancelPreservedWorkspace = cancelDelivered
            && cancelRegistry.workspaces.contains(where: { $0.id == createdWorkspace.id })
            && runtime.workspaceId == createdWorkspace.id
            && topBar.managementMessageForQA.contains("preserved")
        try expect(deleteCancelPreservedWorkspace, "canceling delete confirmation should preserve the workspace")

        app.workspaceDeleteConfirmationProvider = { request in
            deleteRequests.append(request)
            return true
        }
        let confirmDelivered = topBar.clickDeleteForQA()
        topBar.layoutSubtreeIfNeeded()
        let confirmRegistry = try registryStore.loadOrEmpty()
        let deletedStore = WorkspaceStore(workspaceId: createdWorkspace.id, applicationSupportDirectory: appSupport)
        let deleteConfirmRemovedWorkspace = confirmDelivered
            && !confirmRegistry.workspaces.contains(where: { $0.id == createdWorkspace.id })
            && !fm.fileExists(atPath: deletedStore.layout.workspaceDirectory.path)
            && runtime.workspaceId != createdWorkspace.id
            && topBar.managementMessageForQA.contains("not deleted")
        try expect(deleteConfirmRemovedWorkspace, "confirming delete should remove workspace registry/document while preserving project data semantics")

        // P3.14: driven from the SIDEBAR's menu this time — the delete path the header
        // button used to own, with the same confirmation provider in front of it.
        let workspaceAfterCreatedDelete = runtime.workspaceId
        let deleteReplacementDelivered = sidebar.clickDeleteForQA()
        sidebar.layoutSubtreeIfNeeded()
        topBar.layoutSubtreeIfNeeded()
        let oneWorkspaceRegistry = try registryStore.loadOrEmpty()
        try expect(deleteReplacementDelivered, "second delete should be delivered while two workspaces remain")
        try expect(oneWorkspaceRegistry.workspaces.count == 1, "second confirmed delete should leave exactly one workspace")
        try expect(!oneWorkspaceRegistry.workspaces.contains(where: { $0.id == workspaceAfterCreatedDelete }), "second confirmed delete should remove the current replacement workspace")

        let lastWorkspaceId = runtime.workspaceId
        let lastDeleteDelivered = topBar.clickDeleteForQA()
        topBar.layoutSubtreeIfNeeded()
        // P3.14: the same guard on the menu item. `deleteEnabledForQA` reads the item
        // after `NSMenu.update()`, so this is the enablement AppKit would draw and not
        // just the flag this code set.
        let lastDeleteFromMenuDelivered = sidebar.clickDeleteForQA()
        sidebar.layoutSubtreeIfNeeded()
        let lastRegistry = try registryStore.loadOrEmpty()
        let lastWorkspaceProtected = !lastDeleteDelivered
            && !topBar.deleteEnabledForQA
            && !lastDeleteFromMenuDelivered
            && !sidebar.deleteEnabledForQA
            && sidebar.renameEnabledForQA
            && lastRegistry.workspaces.count == 1
            && lastRegistry.workspaces.first?.id == lastWorkspaceId
            && runtime.workspaceId == lastWorkspaceId
        try expect(lastWorkspaceProtected, "last workspace delete action should be disabled and preserve the workspace")

        // Ticket: docs/38-tickets/90-agent-ux/P3.14-preserve-workspace-management.md
        //
        // AN AMBIGUOUS WORKSPACE SCOPE IS NOT A TARGET (from cross-review). Duplicate
        // workspace names are allowed — `Registry.createWorkspace` says so and the
        // check's own manifest records it — and the scope carries a NAME, so a
        // same-named pair leaves the verbs with nothing to act on. Falling back to the
        // open workspace would rename or delete one the control above does not name,
        // which is the one outcome worse than a greyed-out item. Run last, so the two
        // same-named workspaces cannot disturb anything above.
        let twinWorkspace = UUID(uuidString: "00000000-0000-0000-0000-00000000F503")!
        var twinnedRegistry = try registryStore.loadOrEmpty()
        let survivingName = twinnedRegistry.workspaces.first?.name ?? ""
        twinnedRegistry.workspaces.append(
            WorkspaceEntry(id: twinWorkspace, name: survivingName, projectIds: [], createdAt: now, updatedAt: now)
        )
        try registryStore.save(twinnedRegistry)
        try WorkspaceStore(workspaceId: twinWorkspace, applicationSupportDirectory: appSupport).save(document())
        app.reloadWorkspaceSidebar()
        sidebar.configureInboxScope(.workspace(survivingName)) { _ in }
        sidebar.layoutSubtreeIfNeeded()
        let ambiguousRenameRefused = !sidebar.clickRenameForQA()
        let ambiguousDeleteRefused = !sidebar.clickDeleteForQA()
        let ambiguousRegistry = try registryStore.loadOrEmpty()
        let ambiguousScopeHasNoTarget = sidebar.workspaceIdForManagementActionForQA == nil
            && !sidebar.renameEnabledForQA
            && !sidebar.deleteEnabledForQA
            && ambiguousRenameRefused
            && ambiguousDeleteRefused
            && ambiguousRegistry.workspaces.count == 2
            && ambiguousRegistry.workspaces.allSatisfy { $0.name == survivingName }
        try expect(
            ambiguousScopeHasNoTarget,
            "two workspaces of the same name should leave a scoped verb with no target rather than acting on the open one"
        )

        let timestamp = String(Int(Date().timeIntervalSince1970))
        let directory = URL(fileURLWithPath: fm.currentDirectoryPath, isDirectory: true)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("workspace-management-polish", isDirectory: true)
        try fm.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let manifest: [String: Any] = [
            "check": "workspace-management-polish",
            "path": "AgentInboxView scope menu / WorkspaceTopBarView buttons -> AppDelegate create/rename/delete validation and confirmation -> RegistryStore/WorkspaceStore/WorkspaceRuntime",
            "workspaceManagementTitles": managementTitles,
            "workspaceManagementSeparated": sidebar.isWorkspaceManagementSeparatedForQA,
            "scopedRenameTargetedScope": scopedRenameTargetedScope,
            "scopeSurvivedVerb": scopeSurvivedVerb,
            "ambiguousScopeHasNoTarget": ambiguousScopeHasNoTarget,
            "createWorked": createWorked,
            "renameWorked": renameWorked,
            "invalidRenameRejected": invalidRenameRejected,
            "deleteCancelPreservedWorkspace": deleteCancelPreservedWorkspace,
            "deleteConfirmRemovedWorkspace": deleteConfirmRemovedWorkspace,
            "lastWorkspaceProtected": lastWorkspaceProtected,
            "createdWorkspaceId": createdWorkspace.id.uuidString,
            "createdWorkspaceWasEmpty": createdDocument.zones.isEmpty,
            "deleteConfirmationRequests": deleteRequests.map { request in
                [
                    "workspaceId": request.workspaceId.uuidString,
                    "workspaceName": request.workspaceName,
                    "projectCount": request.projectCount,
                    "zoneCount": request.zoneCount,
                    "deletionCopy": request.deletionCopy,
                ]
            },
            "deleteSemantics": Self.workspaceDeleteSemanticsCopy,
            "duplicateNamePolicy": "allowed: Registry.createWorkspace and Registry.renameWorkspace already allow duplicate names",
            "artifactPath": artifact.path,
        ]
        try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys]).write(to: artifact, options: .atomic)
        return artifact
    }

    static func runWorkspaceSwitchPolishSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String { switch self { case let .failed(message): return message } }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }
        func viewportsNearlyEqual(_ lhs: CanvasViewport, _ rhs: CanvasViewport) -> Bool {
            max(abs(lhs.x - rhs.x), abs(lhs.y - rhs.y), abs(lhs.zoom - rhs.zoom)) < 0.001
        }
        func tile(id: UUID, title: String, x: Double, y: Double) -> Tile {
            Tile(
                id: id,
                kind: .note,
                title: title,
                frame: TileFrame(x: x, y: y, width: 240, height: 160),
                zPosition: .fromLegacyRank(1),
                runtimeRef: nil,
                metadata: TileMetadata(noteId: id)
            )
        }
        func makeProject(id: UUID, name: String, root: URL, now: Date) -> Project {
            Project(
                id: id,
                name: name,
                rootPath: root.path,
                createdAt: now,
                updatedAt: now,
                defaultLaunchProfileId: "shell",
                editorPreference: .auto,
                settings: ProjectSettings(
                    restorePolicy: .restoreDescriptors,
                    browserStoragePolicy: .perProject,
                    terminalClosePolicy: .askWhenRunning
                )
            )
        }

        let fm = FileManager.default
        let now = Date(timeIntervalSince1970: 1_900_600_000)
        let tempRoot = fm.temporaryDirectory.appendingPathComponent("continuum-workspace-switch-polish-\(UUID().uuidString)", isDirectory: true)
        let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
        let projectA1Root = tempRoot.appendingPathComponent("ProjectA1", isDirectory: true)
        let projectA2Root = tempRoot.appendingPathComponent("ProjectA2", isDirectory: true)
        let projectBRoot = tempRoot.appendingPathComponent("ProjectB", isDirectory: true)
        try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)
        try fm.createDirectory(at: projectA1Root, withIntermediateDirectories: true)
        try fm.createDirectory(at: projectA2Root, withIntermediateDirectories: true)
        try fm.createDirectory(at: projectBRoot, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: tempRoot) }

        let workspaceA = UUID(uuidString: "00000000-0000-0000-0000-00000000F601")!
        let workspaceB = UUID(uuidString: "00000000-0000-0000-0000-00000000F602")!
        let projectA1 = UUID(uuidString: "00000000-0000-0000-0000-00000000F611")!
        let projectA2 = UUID(uuidString: "00000000-0000-0000-0000-00000000F612")!
        let projectB = UUID(uuidString: "00000000-0000-0000-0000-00000000F613")!
        let zoneA1 = UUID(uuidString: "00000000-0000-0000-0000-00000000F621")!
        let zoneA2 = UUID(uuidString: "00000000-0000-0000-0000-00000000F622")!
        let zoneB = UUID(uuidString: "00000000-0000-0000-0000-00000000F623")!
        let tileA1 = UUID(uuidString: "00000000-0000-0000-0000-00000000F631")!
        let tileA2 = UUID(uuidString: "00000000-0000-0000-0000-00000000F632")!
        let tileB = UUID(uuidString: "00000000-0000-0000-0000-00000000F633")!
        let deletedTileB = UUID(uuidString: "00000000-0000-0000-0000-00000000F634")!

        let projectA1Object = makeProject(id: projectA1, name: "Project A1", root: projectA1Root, now: now)
        let projectA2Object = makeProject(id: projectA2, name: "Project A2", root: projectA2Root, now: now)
        let projectBObject = makeProject(id: projectB, name: "Project B", root: projectBRoot, now: now)
        let storeA1 = ProjectStore(projectRoot: projectA1Root)
        let storeA2 = ProjectStore(projectRoot: projectA2Root)
        let storeB = ProjectStore(projectRoot: projectBRoot)
        let tileA1Value = tile(id: tileA1, title: "A1", x: 20, y: 20)
        let tileA2Value = tile(id: tileA2, title: "A2", x: 40, y: 40)
        let tileBValue = tile(id: tileB, title: "B", x: 60, y: 60)
        try storeA1.saveProject(projectA1Object)
        try storeA1.saveCanvas(CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [tileA1Value], groups: [], lastActiveTileId: tileA1))
        try storeA2.saveProject(projectA2Object)
        try storeA2.saveCanvas(CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [tileA2Value], groups: [], lastActiveTileId: nil))
        try storeB.saveProject(projectBObject)
        try storeB.saveCanvas(CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [tileBValue], groups: [], lastActiveTileId: tileB))

        let docA = WorkspaceDocument(
            viewport: CanvasViewport(x: 10, y: 20, zoom: 1),
            zones: [
                ZonePlacement(zoneId: zoneA1, projectId: projectA1, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 640, height: 480), color: "blue", collapsed: false, hydrationPolicy: .automatic, name: "Alpha One", navKey: "1"),
                ZonePlacement(zoneId: zoneA2, projectId: projectA2, origin: ZonePoint(x: 900, y: 0), size: ZoneSize(width: 640, height: 480), color: "mint", collapsed: false, hydrationPolicy: .automatic, name: "Alpha Two", navKey: "2"),
            ],
            zoneZOrder: [zoneA1, zoneA2],
            lastActiveZoneId: zoneA1
        )
        let docB = WorkspaceDocument(
            viewport: CanvasViewport(x: 33, y: 44, zoom: 1.1),
            zones: [
                ZonePlacement(zoneId: zoneB, projectId: projectB, origin: ZonePoint(x: 200, y: 100), size: ZoneSize(width: 720, height: 520), color: "orange", collapsed: false, hydrationPolicy: .automatic, name: "Beta", navKey: "3"),
            ],
            zoneZOrder: [zoneB],
            lastActiveZoneId: zoneB
        )
        let workspaceStoreA = WorkspaceStore(workspaceId: workspaceA, applicationSupportDirectory: appSupport)
        let workspaceStoreB = WorkspaceStore(workspaceId: workspaceB, applicationSupportDirectory: appSupport)
        try workspaceStoreA.save(docA)
        try workspaceStoreB.save(docB)

        var registry = Registry.empty()
        registry.lastActiveWorkspaceId = workspaceA
        registry.lastActiveProjectId = projectA1
        registry.workspaces = [
            WorkspaceEntry(id: workspaceA, name: "Alpha Workspace", projectIds: [projectA1, projectA2], createdAt: now, updatedAt: now),
            WorkspaceEntry(id: workspaceB, name: "Beta Workspace", projectIds: [projectB], createdAt: now, updatedAt: now),
        ]
        registry.projects = [
            ProjectEntry(id: projectA1, name: "Project A1", rootPath: projectA1Root.path, workspaceId: workspaceA, lastOpenedAt: now, pinned: false, missing: false),
            ProjectEntry(id: projectA2, name: "Project A2", rootPath: projectA2Root.path, workspaceId: workspaceA, lastOpenedAt: now, pinned: false, missing: false),
            ProjectEntry(id: projectB, name: "Project B", rootPath: projectBRoot.path, workspaceId: workspaceB, lastOpenedAt: now, pinned: false, missing: false),
        ]
        let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
        try registryStore.save(registry)

        let app = AppDelegate()
        let browserEngine = BrowserEngineContext()
        defer { browserEngine.shutdown() }
        let zoneRegistry = ZoneRuntimeRegistry(closeOnZero: true, makeController: { projectId in
            if projectId == projectA1 { return ZoneRuntimeController(projectRoot: projectA1Root, projectStore: storeA1, project: projectA1Object) }
            if projectId == projectA2 { return ZoneRuntimeController(projectRoot: projectA2Root, projectStore: storeA2, project: projectA2Object) }
            if projectId == projectB { return ZoneRuntimeController(projectRoot: projectBRoot, projectStore: storeB, project: projectBObject) }
            throw CheckError.failed("unexpected project id \(projectId)")
        })
        let runtime = WorkspaceRuntime(
            workspaceId: workspaceA,
            document: docA,
            registry: zoneRegistry,
            focusBroker: app.focusBroker,
            registryStore: registryStore,
            ghostty: nil,
            browserEngine: browserEngine
        )
        let canvas = CanvasNSView(canvasState: CanvasState(viewport: docA.viewport, tiles: [], groups: [], lastActiveTileId: nil), activeZone: nil, zoneRenderModels: [], showsZoneChrome: false)
        canvas.frame = NSRect(x: 0, y: 0, width: 1_200, height: 800)
        app.registryStore = registryStore
        app.workspaceRuntime = runtime
        app.canvasView = canvas
        try runtime.install(into: canvas, appRegistry: registry)
        canvas.layoutSubtreeIfNeeded()

        let mutatedAViewport = CanvasViewport(x: 123, y: 234, zoom: 0.75)
        try expect(app.focusBroker.requestFocus(.tile(tileA2), reason: .userClick), "setup: tileA2 should be focusable before switch")
        canvas.setViewport(mutatedAViewport)

        try expect(app.switchWorkspaceFromSidebarIfNeeded(workspaceB), "switch to workspace B should succeed")
        canvas.layoutSubtreeIfNeeded()
        let persistedAAfterDeparture = try workspaceStoreA.load()
        let persistedA2Canvas = try storeA2.loadCanvas()
        let departingViewportSaved = viewportsNearlyEqual(persistedAAfterDeparture.viewport, mutatedAViewport)
        let departingFocusSaved = persistedAAfterDeparture.lastActiveZoneId == zoneA2 && persistedA2Canvas.lastActiveTileId == tileA2
        let targetViewportRestored = viewportsNearlyEqual(canvas.viewport, docB.viewport)
        let lastFocusRestored = app.focusBroker.activeSurface == .tile(tileB) && canvas.canvasState.lastActiveTileId == tileB
        try expect(departingViewportSaved, "departing workspace viewport should be saved before switch")
        try expect(departingFocusSaved, "departing workspace last zone/tile focus should be saved before switch")
        try expect(targetViewportRestored, "target workspace viewport should restore from document")
        try expect(lastFocusRestored, "target workspace valid last tile focus should restore")

        let mutatedBViewport = CanvasViewport(x: 301, y: 302, zoom: 0.9)
        canvas.setViewport(mutatedBViewport)
        try expect(app.switchWorkspaceFromSidebarIfNeeded(workspaceA), "round-trip switch back to workspace A should succeed")
        canvas.layoutSubtreeIfNeeded()
        let roundTripViewportRestored = viewportsNearlyEqual(canvas.viewport, mutatedAViewport)
        let roundTripFocusRestored = app.focusBroker.activeSurface == .tile(tileA2) && canvas.canvasState.lastActiveTileId == tileA2
        try expect(roundTripViewportRestored, "round trip should restore workspace A's saved viewport")
        try expect(roundTripFocusRestored, "round trip should restore workspace A's saved focused tile")

        try storeB.saveCanvas(CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [], groups: [], lastActiveTileId: deletedTileB))
        let expectedFallbackViewport = CanvasEngine.fit(
            worldRect: CGRect(x: 200, y: 100, width: 720, height: 520),
            viewportSize: canvas.bounds.size
        )
        try expect(app.switchWorkspaceFromSidebarIfNeeded(workspaceB), "switch to workspace B with deleted focus should succeed")
        canvas.layoutSubtreeIfNeeded()
        let deletedFocusFallbackWorked = app.focusBroker.activeSurface == .canvas
            && canvas.canvasState.lastActiveTileId != deletedTileB
            && viewportsNearlyEqual(canvas.viewport, expectedFallbackViewport)
        let transitionLabelShown = app.qaWorkspaceSwitchTransitionLabelText == "Switched to Beta Workspace"
        try expect(deletedFocusFallbackWorked, "deleted focused tile should fall back to canvas and frame workspace bounds")
        try expect(transitionLabelShown, "workspace switch should show transition label")

        let timestamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "")
        let directory = URL(fileURLWithPath: fm.currentDirectoryPath, isDirectory: true)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("workspace-switch-polish", isDirectory: true)
        try fm.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let manifest: [String: Any] = [
            "check": "workspace-switch-polish",
            "path": "AppDelegate switch path -> WorkspaceRuntime.switchWorkspace(to:) -> CanvasNSView.setViewport/focus/transition label",
            "departingViewportSaved": departingViewportSaved,
            "departingFocusSaved": departingFocusSaved,
            "targetViewportRestored": targetViewportRestored,
            "lastFocusRestored": lastFocusRestored && roundTripFocusRestored,
            "roundTripViewportRestored": roundTripViewportRestored,
            "deletedFocusFallbackWorked": deletedFocusFallbackWorked,
            "transitionLabelShown": transitionLabelShown,
            "departingViewport": ["x": persistedAAfterDeparture.viewport.x, "y": persistedAAfterDeparture.viewport.y, "zoom": persistedAAfterDeparture.viewport.zoom],
            "targetViewport": ["x": docB.viewport.x, "y": docB.viewport.y, "zoom": docB.viewport.zoom],
            "fallbackViewport": ["x": canvas.viewport.x, "y": canvas.viewport.y, "zoom": canvas.viewport.zoom],
            "expectedFallbackViewport": ["x": expectedFallbackViewport.x, "y": expectedFallbackViewport.y, "zoom": expectedFallbackViewport.zoom],
            "transitionLabelText": app.qaWorkspaceSwitchTransitionLabelText ?? "",
            "artifactPath": artifact.path,
        ]
        try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys]).write(to: artifact, options: .atomic)
        return artifact
    }

    private func installSettingsChangeObserver() {
        guard settingChangeObservers.isEmpty else { return }
        let center = NotificationCenter.default
        settingChangeObservers.append(center.addObserver(
            forName: SettingChangeEvent.name(for: SettingID(rawValue: BrowserInspectionPolicy.userDefaultsKey)),
            object: nil, queue: nil
        ) { [weak self] _ in
            Task { @MainActor in
                self?.applyBrowserInspectionPolicyToLiveWebViews()
            }
        })
        settingChangeObservers.append(center.addObserver(
            forName: SettingChangeEvent.name(for: SettingID(rawValue: CanvasShortcutRailConfig.visibleKey)),
            object: nil, queue: nil
        ) { [weak self] _ in
            Task { @MainActor in
                guard let self else { return }
                self.canvasShortcutRailView?.reloadBindings(navKeymap: self.navKeymap)
            }
        })
    }

    @discardableResult
    private func applyBrowserInspectionPolicyToLiveWebViews() -> Int {
        guard let browserEngine else { return 0 }
        var appliedRuntimeIds: Set<ObjectIdentifier> = []
        var appliedCount = 0

        func apply(to runtime: WKWebViewBrowserRuntime) {
            let identity = ObjectIdentifier(runtime)
            guard appliedRuntimeIds.insert(identity).inserted else { return }
            browserEngine.applyInspectionPolicy(to: runtime.webView)
            appliedCount += 1
        }

        for runtime in browserRuntimes {
            apply(to: runtime)
        }

        if let canvasView {
            for tile in canvasView.canvasState.tiles where tile.kind == .browser {
                guard let browserView = canvasView.tileView(for: tile.id) as? BrowserTileNSView,
                      let runtime = browserView.runtime as? WKWebViewBrowserRuntime
                else { continue }
                apply(to: runtime)
            }
        }

        return appliedCount
    }

    static func runBrowserInspectionLiveReapplySelfCheck() throws -> [String: Any] {
        struct CheckError: Error, CustomStringConvertible {
            let description: String
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError(description: message) }
        }

        let suiteName = "continuum-browser-inspection-live-reapply-\(UUID().uuidString)"
        guard let defaults = UserDefaults(suiteName: suiteName) else {
            throw CheckError(description: "could not create isolated defaults")
        }
        defer { defaults.removePersistentDomain(forName: suiteName) }
        defaults.set(false, forKey: BrowserInspectionPolicy.userDefaultsKey)

        let engine = BrowserEngineContext(inspectionPolicyProvider: {
            BrowserInspectionPolicy.resolved(defaults: defaults, environment: [:])
        })
        let tempRoot = FileManager.default.temporaryDirectory
            .appendingPathComponent("continuum-browser-inspection-live-reapply-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: tempRoot, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: tempRoot) }

        let profile = BrowserProfile.builtInDefault()
        let project = Project(
            id: UUID(),
            name: "browser-inspection-live-reapply-check",
            rootPath: tempRoot.path,
            createdAt: Date(timeIntervalSince1970: 1),
            updatedAt: Date(timeIntervalSince1970: 1),
            defaultLaunchProfileId: "shell",
            editorPreference: .auto,
            settings: ProjectSettings(
                restorePolicy: .restoreDescriptors,
                browserStoragePolicy: .perProject,
                terminalClosePolicy: .askWhenRunning,
                defaultBrowserProfileId: profile.id
            )
        )
        let store = ProjectStore(projectRoot: tempRoot)
        try store.saveProject(project)
        try store.saveCanvas(CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [], groups: [], lastActiveTileId: nil))
        let canvas = CanvasNSView(canvasState: try store.loadCanvas())
        let spawner = TileSpawner(
            canvasView: canvas,
            ghostty: nil,
            browserEngine: engine,
            projectStore: store,
            project: project,
            defaults: defaults,
            browserProfiles: [profile]
        )

        let opener: WKWebViewBrowserRuntime
        switch spawner.spawnBrowser(url: "data:text/html;charset=utf-8,opener") {
        case let .spawned(runtime): opener = runtime
        case let .invalidURL(url): throw CheckError(description: "opener spawn invalid URL \(url)")
        case let .failure(error): throw error
        }
        let request = URLRequest(url: URL(string: "data:text/html;charset=utf-8,target-blank-child")!)
        let childWebView = opener.onNewWindowRequest?(request, WKWebViewConfiguration(), WKNavigationAction(), WKWindowFeatures())
        try expect(childWebView != nil, "target blank seam should return child webview")
        guard let childTile = canvas.canvasState.tiles.first(where: { $0.id != opener.tileId }) else {
            throw CheckError(description: "target blank child tile missing")
        }
        guard let childView = canvas.tileView(for: childTile.id) as? BrowserTileNSView,
              let childRuntime = childView.runtime as? WKWebViewBrowserRuntime
        else {
            throw CheckError(description: "target blank child runtime not discoverable from canvas tile view")
        }

        let supportsInspectableAPI: Bool
        let initialOpenerInspectable: Bool
        let initialChildInspectable: Bool
        if #available(macOS 13.3, *) {
            supportsInspectableAPI = true
            initialOpenerInspectable = opener.webView.isInspectable
            initialChildInspectable = childRuntime.webView.isInspectable
        } else {
            supportsInspectableAPI = false
            initialOpenerInspectable = false
            initialChildInspectable = false
        }

        defaults.set(true, forKey: BrowserInspectionPolicy.userDefaultsKey)
        let delegate = AppDelegate()
        delegate.browserEngine = engine
        delegate.canvasView = canvas
        let reappliedOnCount = delegate.applyBrowserInspectionPolicyToLiveWebViews()

        let enabledOpenerInspectable: Bool
        let enabledChildInspectable: Bool
        if #available(macOS 13.3, *) {
            enabledOpenerInspectable = opener.webView.isInspectable
            enabledChildInspectable = childRuntime.webView.isInspectable
        } else {
            enabledOpenerInspectable = false
            enabledChildInspectable = false
        }

        defaults.set(false, forKey: BrowserInspectionPolicy.userDefaultsKey)
        let reappliedOffCount = delegate.applyBrowserInspectionPolicyToLiveWebViews()
        let disabledOpenerInspectable: Bool
        let disabledChildInspectable: Bool
        if #available(macOS 13.3, *) {
            disabledOpenerInspectable = opener.webView.isInspectable
            disabledChildInspectable = childRuntime.webView.isInspectable
        } else {
            disabledOpenerInspectable = false
            disabledChildInspectable = false
        }

        try expect(reappliedOnCount == 2, "settings reapply should visit opener and target blank child webviews; got \(reappliedOnCount)")
        try expect(reappliedOffCount == 2, "settings disable reapply should visit opener and target blank child webviews; got \(reappliedOffCount)")
        if supportsInspectableAPI {
            try expect(initialOpenerInspectable == false, "opener should start non-inspectable by default")
            try expect(initialChildInspectable == false, "target blank child should start non-inspectable by default")
            try expect(enabledOpenerInspectable == true, "settings opt-in should make existing opener inspectable")
            try expect(enabledChildInspectable == true, "settings opt-in should make existing target blank child inspectable")
            try expect(disabledOpenerInspectable == false, "settings opt-out should make existing opener non-inspectable")
            try expect(disabledChildInspectable == false, "settings opt-out should make existing target blank child non-inspectable")
        }

        return [
            "supportsInspectableAPI": supportsInspectableAPI,
            "liveCanvasBrowserWebViewsReappliedCount": reappliedOnCount,
            "liveCanvasBrowserWebViewsDisabledCount": reappliedOffCount,
            "initialOpenerInspectable": initialOpenerInspectable,
            "initialTargetBlankChildInspectable": initialChildInspectable,
            "existingOpenerReappliedAfterSettingsOptIn": enabledOpenerInspectable,
            "existingTargetBlankChildReappliedAfterSettingsOptIn": enabledChildInspectable,
            "existingOpenerReappliedAfterSettingsOptOut": disabledOpenerInspectable == false,
            "existingTargetBlankChildReappliedAfterSettingsOptOut": disabledChildInspectable == false
        ]
    }

    /// Live-applies a leader/nav rebind from the settings panel (no relaunch):
    /// swaps the app's live keymap + the broker's copy, and refreshes the nav
    /// hint line so an open nav overlay reflects the new bindings.
    private func applyEditedNavKeymap(_ keymap: NavKeymap) {
        navKeymap = keymap
        focusBroker.navKeymap = keymap
        canvasView?.navModeHintLine = keymap.hintLine
        canvasShortcutRailView?.reloadBindings(navKeymap: keymap)
        refreshGettingStartedTasks()
    }

    private func focusSpawnedTile(_ tileId: UUID) {
        focusBroker.enterScope(.tile(tileId), reason: .tileSpawned)
    }

    private func installSpawnedTerminal(_ runtime: GhosttyTerminalRuntime) {
        wireRuntimeExitHandler(runtime)
        runtimes.append(runtime)
        focusSpawnedTile(runtime.tileId)
    }

    private func liveTerminalRuntimeCount() -> Int {
        runtimes.filter { runtime in
            switch runtime.status {
            case .configuring, .running:
                return true
            case .exited, .error:
                return false
            }
        }.count
    }

    @discardableResult
    private func spawnTerminalFromProfile(_ profileId: String, trigger: String? = nil) -> Bool {
        guard resolvedCreationScope() != nil else {
            requestCreationScope { [weak self] in _ = self?.spawnTerminalFromProfile(profileId, trigger: trigger) }
            return false
        }
        guard let spawner = spawnerForFilesystemCreation() else { return false }
        let admissionTrigger = trigger ?? "profile:\(profileId)"
        if let refusal = terminalSpawnAdmission.admit(trigger: admissionTrigger, liveCount: liveTerminalRuntimeCount()) {
            fputs("\(refusal.message)\n", stderr)
            return false
        }
        switch spawner.spawnTerminal(profileId: profileId) {
        case let .spawned(runtime):
            installSpawnedTerminal(runtime)
            return true
        case let .missingCommand(executable):
            presentMissingCommand(executable: executable, profileId: profileId)
            return false
        case let .notConfigured(id):
            presentMissingCommand(executable: id, profileId: id, kind: .notConfigured)
            return false
        case let .unknownProfile(id):
            fputs("Unknown profile id: \(id)\n", stderr)
            return false
        case let .failure(error):
            fputs("TileSpawner.spawnTerminal failed: \(error)\n", stderr)
            return false
        }
    }

    private func spawnManagedAgentFromPalette(model: String? = nil) -> Bool {
        guard resolvedCreationScope() != nil else {
            requestCreationScope { [weak self] in _ = self?.spawnManagedAgentFromPalette(model: model) }
            return false
        }
        guard let spawner = spawnerForFilesystemCreation() else { return false }
        // The catalogue guard, the refusal's own voice, and the atomic threading all
        // live in `TileSpawner.spawnManagedAgentForSelectedModel` — one function, so
        // `--managed-agent-model-spawn-check` can DRIVE them and watch a departed
        // model leave no tile and no agent, instead of scanning this file for the
        // guard's text (which pinned the call, not the refusal: a reviewer swapped
        // the guard for `?? resolvedFromDefaults()` and the check stayed green).
        switch spawner.spawnManagedAgentForSelectedModel(model, wire: { tileId, providerSettings in
            wireManagedAgentTile(tileId, initialLaunchSelection: providerSettings)
        }) {
        case let .spawned(tileId, providerSettings):
            let modelApplied = agentSupervisor.agent(forTile: tileId)
                .flatMap { agentSupervisor.records[$0]?.model } == providerSettings.model
            focusSpawnedTile(tileId)
            scheduleCompanionSyncPublish(reason: .statusChanged, diagnosticsReason: "managed-agent-spawn", debounce: 0.2)
            return modelApplied
        case .refusedModel:
            // Already beeped and named itself on stderr, inside the seam — the
            // palette closes on dispatch either way, so the refusal has to speak.
            return false
        case let .failure(error):
            fputs("TileSpawner.spawnManagedAgent failed: \(error)\n", stderr)
            return false
        }
    }

    /// ⌘K `agent.newHeadless` (P2A.6) — an agent with NO tile. `agent.newManaged`
    /// above is spawn + attach a tile; this is the spawn alone, so nothing here
    /// touches `tileSpawner` or the canvas, and the record's `tileId` stays nil.
    ///
    /// This is what lets more than a handful of agents run at once (the zone
    /// hydration budget caps live ZONES, so tile-bound agents beyond it freeze) and
    /// what the orchestrator will use to start workers without doing layout.
    /// Until the Phase 3 inbox lands a headless agent has no surface at all, so the
    /// id is named on stderr; it is not lost — it is in `supervisor.records` and on
    /// disk in `AgentStore`.
    private func spawnHeadlessAgentFromPalette() {
        // The first prompt is collected HERE because a headless agent has no compose
        // row to type it into: `spawn` runs it immediately, which is what makes this a
        // RUNNING agent rather than an inert record nothing can reach until Phase 3.
        // Same modal, and the same reason for it, as `spawnHarnessRoleFromPalette`.
        guard let prompt = promptForAgentTask(
            title: "New Agent Without a Tile",
            informativeText: "The agent runs with no tile on the canvas. Enter its first prompt."
        ) else { return }
        guard let agentId = spawnSupervisedAgent(tileId: nil, prompt: prompt) else { return }
        fputs("Spawned headless agent \(agentId.rawValue.uuidString) (no tile; visible in the inbox from Phase 3, stopped on quit)\n", stderr)
    }

    /// The one place the app's spawn parameters are resolved — the active project's
    /// root and id, and the configured model/thinking level. `tileId` is a view
    /// binding, not identity, so `nil` is a headless agent; a non-nil `prompt` runs
    /// on spawn (`AgentSupervisor.spawn`'s own parameter).
    /// Kept on ONE line: `--agent-supervisor-check` pins this whole signature by exact
    /// line match (`paletteAgentSpawnBranch`), so wrapping it blinds that scan.
    private func spawnSupervisedAgent(tileId: UUID?, prompt: String? = nil, launchSelection: AgentLaunchSelection? = nil) -> AgentID? {
        // Plan 07. This used to read `activeProject.rootPath` unconditionally, which
        // is why changing an agent's Home never carried: the next ⌘K agent went back
        // to the active project regardless of where you had just been working.
        // Precedence now comes from `ManagedAgentSpawnHomeResolver` — explicit →
        // selected agent → context gravity → active project — and the resolver is
        // pure, so the ordering is witnessed in Core rather than asserted here.
        //
        // The SELECTED agent is the one whose tile has focus; its Home is ordinary
        // record state, so inheriting it is just reading it. Context gravity is not
        // wired at this call site yet and passes nil, which the precedence tolerates
        // (the rung is skipped, not defaulted).
        var selectedAgentHome: AgentHome?
        if let focusedTile = focusedTileIdForPaletteContext(),
           let focusedAgent = agentSupervisor.agent(forTile: focusedTile),
           let record = agentSupervisor.records[focusedAgent] {
            selectedAgentHome = AgentHome(
                projectId: record.projectId,
                projectRoot: record.projectRoot.map { URL(fileURLWithPath: $0, isDirectory: true) },
                checkoutRoot: URL(fileURLWithPath: record.checkoutRoot, isDirectory: true),
                homeRelativePath: record.homeRelativePath)
        }
        let activeProjectHome: AgentHome? = activeProject.map { project in
            let root = URL(fileURLWithPath: project.rootPath, isDirectory: true)
            return AgentHome(projectId: project.id, projectRoot: root, checkoutRoot: root)
        }
        // Validation stays at the App boundary — Core must not gain ambient
        // filesystem authority — and refusal stays refusal: an unusable Home beeps
        // rather than falling back to the process cwd.
        guard let resolution = ManagedAgentSpawnHomeResolver.resolve(
                selectedAgent: selectedAgentHome,
                activeProject: activeProjectHome),
              let cwd = usableAgentHomeDirectory(resolution.home.homeRoot) else {
            NSSound.beep()
            fputs("Managed agent spawn refused: choose an explicit Home; process cwd is never an agent Home fallback\n", stderr)
            return nil
        }
        return spawnSupervisedAgentAtHome(
            tileId: tileId,
            prompt: prompt,
            cwd: cwd,
            projectId: resolution.home.projectId,
            projectRoot: resolution.home.projectRoot,
            checkoutRoot: resolution.home.checkoutRoot,
            homeRelativePath: resolution.home.homeRelativePath,
            launchSelection: launchSelection)
    }

    /// Explicit-Home variant used only after the owner chooses a registered
    /// project or folder. Keeping it separate preserves the ordinary active-
    /// project spawn contract and allows a deliberately unregistered folder to
    /// carry a nil project id without falling back to the active project.
    private func spawnSupervisedAgentAtHome(
        tileId: UUID?,
        prompt: String? = nil,
        cwd: URL,
        projectId: UUID?,
        projectRoot: URL? = nil,
        checkoutRoot: URL? = nil,
        homeRelativePath: String? = nil,
        launchSelection: AgentLaunchSelection? = nil
    ) -> AgentID? {
        guard let selection = launchSelection ?? AgentModelConfig.launchSelection() else {
            NSSound.beep()
            fputs("Managed agent spawn refused: choose a model compatible with the selected harness. Help → Environment Setup…\n", stderr)
            return nil
        }
        return agentSupervisor.spawn(
            role: nil,
            prompt: prompt,
            cwd: cwd,
            harness: selection.harness,
            model: selection.model,
            thinking: selection.thinking,
            projectId: projectId,
            projectRoot: projectRoot ?? checkoutRoot,
            homeRelativePath: homeRelativePath,
            tileId: tileId
        )
    }

    /// Binds a managed-agent tile to the agent the supervisor owns (P2A.3).
    ///
    /// This used to construct a `PiAgentRunner` inside the tile's own submit
    /// closure, which made the view the runner's owner. Now the supervisor owns it:
    /// this method spawns (or re-finds) the agent bound to this tile, routes the
    /// compose row to `supervisor.send`, and SUBSCRIBES to
    /// `supervisor.events(for:)` — one consumer among however many, which is what
    /// makes the tile a view rather than the agent's home.
    ///
    /// P3.9 passes `agentID` for the one case that has an agent already and no tile
    /// yet: revealing a headless agent spawns a tile FOR it, so the spawn branch
    /// below — which would create a second agent over the top of it — must not run.
    ///
    /// Kept on ONE line: `--agent-restore-check` pins this whole signature by exact
    /// line match (`runAgentRestoreChecks`, via `paletteAgentSpawnBranch`), so wrapping
    /// it blinds that scan.
    func wireManagedAgentTile(_ tileId: UUID, agentID: AgentID? = nil, initialLaunchSelection: AgentLaunchSelection? = nil) {
        guard let view = canvasView?.tileView(for: tileId) as? ManagedAgentTileNSView else { return }
        let supervisor = agentSupervisor
        let agentId: AgentID
        if let agentID {
            agentId = agentID
        } else if let existing = supervisor.agent(forTile: tileId) {
            agentId = existing
        } else if supervisor.isAgentRespawnSuppressed(forTile: tileId) {
            // P3.15: this tile's agent was DELETED by a person. Restoring the canvas
            // must not mint a replacement — that is the resurrection measured on the
            // owner's machine, and it is worse than not deleting at all because it
            // looks like the delete worked. The tile is left alone (deleting an agent
            // is not deleting a tile, the inverse of P2A.5's rule that closing a tile
            // is not deleting an agent), so submitting a prompt in it is how you ask
            // for an agent here again — deliberately, by a gesture, not by a relaunch.
            // The suppressed tile renders no transcript until a prompt revives
            // it, but binding the reveal is safe (it needs no agent of its own)
            // and keeps any chip that ever renders here from clicking into
            // nothing.
            view.onRevealAgent = { [weak self, weak view] childID, _ in
                if self?.revealAgentFromInbox(childID.rawValue) != true {
                    view?.showActionFailedNotice(
                        "Couldn't open that subagent — it may have been deleted.")
                }
            }
            view.onSubmitPrompt = { [weak self, weak view] prompt in
                guard let self, let view else { return }
                supervisor.allowAgentRespawn(forTile: tileId)
                // Re-entrant only if the mark survived the line above, which would
                // otherwise recurse: the wire-up below replaces this closure.
                guard !supervisor.isAgentRespawnSuppressed(forTile: tileId) else { return }
                self.wireManagedAgentTile(tileId)
                view.onSubmitPrompt?(prompt)
            }
            return
        } else {
            // T4 (`.plans/47`): asked of the runtime, not of `tileSpawner`. The
            // memo lives on the spawner that CREATED the tile, which for a scoped
            // spawn is the scope's own project's spawner — not necessarily the
            // active one. Reading the active spawner returned nil across a project
            // boundary and dropped the agent back into the first project's home.
            let launchSelection = initialLaunchSelection
                ?? workspaceRuntime?.managedAgentLaunchSelection(tileId: tileId)
                ?? tileSpawner?.managedAgentLaunchSelection(tileId: tileId)
            let creationScope = workspaceRuntime?.managedAgentCreationScope(tileId: tileId)
                ?? tileSpawner?.managedAgentCreationScope(tileId: tileId)
            let spawned: AgentID?
            if let creationScope,
               let cwd = usableAgentHomeDirectory(URL(fileURLWithPath: creationScope.homePath(inCheckoutRoot: creationScope.projectRoot), isDirectory: true)) {
                let root = URL(fileURLWithPath: creationScope.projectRoot, isDirectory: true)
                spawned = spawnSupervisedAgentAtHome(
                    tileId: tileId,
                    cwd: cwd,
                    projectId: creationScope.projectId,
                    projectRoot: root,
                    checkoutRoot: root,
                    homeRelativePath: creationScope.homeRelativePath,
                    launchSelection: launchSelection
                )
            } else {
                spawned = spawnSupervisedAgent(tileId: tileId, launchSelection: launchSelection)
            }
            guard let spawnedAgentID = spawned else { return }
            agentId = spawnedAgentID
        }
        // The view binding lives in one place (P2A.5), so this is the site that
        // records it whichever branch above ran — and the site Phase 3's "open in
        // tile" reaches when it hands us an agent that was detached, whose record
        // therefore no longer names this tile.
        supervisor.attach(agentID: agentId, to: tileId)
        view.bindV2ComposerState(
            draftStore: agentComposerDraftStore,
            promptHistory: agentPromptHistory,
            attachmentStore: agentComposerAttachmentStore
        )

        view.onSubmitPrompt = { [weak view] prompt in
            guard let view else { return }
            // The supervisor validates the persisted harness and its cached
            // readiness before accepting the prompt. Only acknowledge a send
            // after acceptance so a refusal leaves the compose draft intact.
            guard supervisor.send(prompt, to: agentId) else {
                // A refusal used to be silent: the draft survived, but nothing said
                // why nothing happened. Show the supervisor's own reason.
                if let refusal = supervisor.sendRefusal(for: agentId) {
                    view.showSendRefusedNotice(refusal)
                }
                return
            }
            view.appendUserPrompt(prompt)
            view.acceptCurrentSendIntent()
        }

        // P2A.4: the subscription is the TILE's now, not this file's. What stays
        // here is the app's own interest in the stream — mirroring each event onto
        // the syncable activity timeline so the phone sees it (88.4c), with the
        // status the tile derived from that same event.
        view.onIngestedEvent = { [weak self, weak view] event in
            guard let view else { return }
            self?.recordManagedActivity(agentId: agentId, tileId: tileId, event: event, status: view.currentAgentStatus)
        }
        view.onLocationActionMenuRequested = { [weak self] requestedAgentID, anchor in
            self?.showLocationActionMenu(for: requestedAgentID, anchoredTo: anchor)
        }
        view.onOpenLocalFile = { [weak self] destination in
            self?.openAgentLocalFile(destination, agentID: agentId, sourceTileId: tileId)
        }
        view.onOpenWebLink = { [weak self] url, target in
            self?.openAgentWebLink(url, target: target, sourceTileId: tileId)
        }
        view.onRevealAgent = { [weak self, weak view] childID, _ in
            // A silent false here is a chip that clicks and does nothing — the
            // user cannot tell a dead chip from a slow reveal. Say it on the
            // tile, through the same notice seam a refused send uses.
            if self?.revealAgentFromInbox(childID.rawValue) != true {
                view?.showActionFailedNotice(
                    "Couldn't open that subagent — it may have been deleted.")
            }
        }
        // C4: transcript persistence moved to `AgentSupervisor` itself, fed from
        // the same restamped event stream every consumer sees, so a tile-less
        // agent (fan-out's common case) is no longer silently unsaved. The tile
        // is a reader of the agent's stream, same as before; it no longer owns
        // the write.
        // Replays the agent's history, then follows the tail; re-wiring the same
        // tile to the same agent is a no-op inside `attach`, so none of the three
        // call sites can double-ingest. Project NAME is supplied by the app's
        // registry rather than inferred from an isolated worktree's final path
        // component; full host paths remain inside the local snapshot/disclosure.
        let recordProjectId = supervisor.records[agentId]?.projectId
        let projectName: String?
        if activeProject?.id == recordProjectId {
            projectName = activeProject?.name
        } else {
            let registry = (try? registryStore?.loadOrEmpty()) ?? Registry.empty()
            projectName = registry.projects.first(where: { $0.id == recordProjectId })?.name
        }
        view.attach(
            agentID: agentId,
            supervisor: supervisor,
            projectName: projectName)
        view.applyAwarenessSignal(agentSignalCenter.currentByTile[tileId])

        // P2A.7: an agent restored from the previous launch has a real conversation
        // and an empty desktop transcript (that transcript lives only in the view,
        // and this one was just built). The replay above therefore renders nothing,
        // so the tile says where it stands instead of looking like a fresh agent.
        // Idempotent inside the model, so a re-wire cannot stack notices, and
        // narrowed to an agent that has produced nothing since the relaunch — one
        // that HAS been prompted replays a real transcript, and the placeholder would
        // land underneath it.
        if supervisor.needsPreviousSessionNotice(agentId) {
            rehydratePreviousSessionOrNotice(agentId: agentId, into: view)
        }
    }

    /// A restored agent's tile: rehydrate its prior transcript from the provider
    /// session file if one exists, else fall back to the plain notice
    /// (`.plans/03-transcript-rehydration.md`). The session file can run to
    /// hundreds of messages, so the read happens OFF the main thread; the seed
    /// and the render hop back onto it. Seeding flips
    /// `needsPreviousSessionNotice` false, so a re-wire during the read is a
    /// no-op and the placeholder never double-renders.
    private func rehydratePreviousSessionOrNotice(agentId: AgentID, into view: ManagedAgentTileNSView) {
        guard let inputs = agentSupervisor.rehydrationInputs(for: agentId) else {
            view.showPreviousSessionNotice()
            return
        }
        Task.detached(priority: .userInitiated) { [weak self, weak view] in
            let transcript = ManagedTranscriptRehydrator.rehydrate(inputs)
            await MainActor.run {
                guard let self, let view else { return }
                // A live prompt during the read makes rehydration moot: the real
                // transcript now replays, and the placeholder/rehydration would
                // land underneath it.
                guard self.agentSupervisor.needsPreviousSessionNotice(agentId) else { return }
                if let transcript {
                    self.agentSupervisor.seedRehydratedTranscript(transcript, for: agentId)
                    view.renderRehydratedPreviousSession(transcript)
                } else {
                    view.showPreviousSessionNotice()
                }
            }
        }
    }

    private func showLocationActionMenu(for agentID: AgentID, anchoredTo anchor: NSButton) {
        guard let snapshot = agentSupervisor.locationSnapshot(for: agentID) else { return }
        let menu = NSMenu(title: "Location Actions")
        let hasWork = agentSupervisor.hasUserWorkOrSessionHistory(agentID)
        let homeURL = snapshot.home.checkoutRoot
        let whereURL = snapshot.workingLocation.directory

        menu.addItem(locationPrimaryActionMenuItem(for: agentID, hasWork: hasWork))

        menu.addItem(.separator())
        addPathActions(to: menu, label: "Home", url: homeURL)
        if whereURL.standardizedFileURL.path != homeURL.standardizedFileURL.path {
            addPathActions(to: menu, label: "Where", url: whereURL)
        }
        menu.popUp(positioning: nil, at: NSPoint(x: 0, y: anchor.bounds.height), in: anchor)
    }

    private func locationPrimaryActionMenuItem(for agentID: AgentID, hasWork: Bool) -> NSMenuItem {
        if hasWork {
            let newHere = NSMenuItem(title: "New Agent Here", action: nil, keyEquivalent: "")
            newHere.submenu = projectActionSubmenu(prefix: "New Agent in", includeFolder: true) { [weak self] project in
                self?.spawnManagedAgentHere(cwd: URL(fileURLWithPath: project.rootPath, isDirectory: true), projectId: project.id)
            } folderHandler: { [weak self] url in
                self?.spawnManagedAgentHere(cwd: url, projectId: nil)
            }
            return newHere
        }

        let changeHome = NSMenuItem(title: "Change Home", action: nil, keyEquivalent: "")
        changeHome.submenu = projectActionSubmenu(prefix: "Use", includeFolder: true) { [weak self] project in
            self?.reassignHome(agentID: agentID, cwd: URL(fileURLWithPath: project.rootPath, isDirectory: true), projectId: project.id)
        } folderHandler: { [weak self] url in
            self?.reassignHome(agentID: agentID, cwd: url, projectId: nil)
        }
        return changeHome
    }

    private func projectActionSubmenu(
        prefix: String,
        includeFolder: Bool,
        projectHandler: @escaping (ProjectEntry) -> Void,
        folderHandler: @escaping (URL) -> Void
    ) -> NSMenu {
        let menu = NSMenu(title: prefix)
        let projects = ((try? registryStore?.loadOrEmpty()) ?? Registry.empty()).projects
            .filter {
                !$0.missing
                    && usableAgentHomeDirectory(
                        URL(fileURLWithPath: $0.rootPath, isDirectory: true)) != nil
            }
            .sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
        if projects.isEmpty {
            let item = NSMenuItem(title: "No registered projects", action: nil, keyEquivalent: "")
            item.isEnabled = false
            menu.addItem(item)
        } else {
            for project in projects {
                menu.addItem(ClosureMenuItem(title: "\(prefix) \(project.name)") { projectHandler(project) })
            }
        }
        if includeFolder {
            menu.addItem(.separator())
            menu.addItem(ClosureMenuItem(title: "Choose Folder…") { [weak self] in
                guard let self, let url = self.chooseAgentHomeFolder() else { return }
                folderHandler(url)
            })
        }
        return menu
    }

    private func chooseAgentHomeFolder() -> URL? {
        let panel = NSOpenPanel()
        panel.canChooseFiles = false
        panel.canChooseDirectories = true
        panel.allowsMultipleSelection = false
        panel.prompt = "Choose Home"
        guard panel.runModal() == .OK, let selected = panel.url else { return nil }
        return usableAgentHomeDirectory(selected)
    }

    private func usableAgentHomeDirectory(_ url: URL) -> URL? {
        guard url.isFileURL else { return nil }
        let normalized = url.standardizedFileURL.resolvingSymlinksInPath()
        var isDirectory: ObjCBool = false
        guard FileManager.default.fileExists(atPath: normalized.path, isDirectory: &isDirectory),
              isDirectory.boolValue else { return nil }
        return normalized
    }

    private func reassignHome(agentID: AgentID, cwd: URL, projectId: UUID?) {
        guard let cwd = usableAgentHomeDirectory(cwd),
              agentSupervisor.reassignProvisionalHome(
                  agentID: agentID,
                  cwd: cwd,
                  projectId: projectId) else {
            NSSound.beep()
            return
        }
        refreshAgentSurfaces()
        if let tileId = agentSupervisor.records[agentID]?.tileId,
           let view = canvasView?.tileView(for: tileId) as? ManagedAgentTileNSView {
            view.attach(agentID: agentID, supervisor: agentSupervisor, projectName: projectName(for: projectId))
        }
    }

    private func spawnManagedAgentHere(cwd: URL, projectId: UUID?) {
        guard let spawner = tileSpawner,
              let cwd = usableAgentHomeDirectory(cwd) else {
            NSSound.beep()
            return
        }
        switch spawner.spawnManagedAgent() {
        case let .spawned(tileId):
            guard let agentID = spawnSupervisedAgentAtHome(
                tileId: tileId,
                cwd: cwd,
                projectId: projectId) else { return }
            wireManagedAgentTile(tileId, agentID: agentID)
            focusSpawnedTile(tileId)
            scheduleCompanionSyncPublish(reason: .statusChanged, diagnosticsReason: "location-new-agent-here", debounce: 0.2)
        case let .failure(error):
            fputs("Location New Agent Here failed: \(error)\n", stderr)
        }
    }

    private func projectName(for projectId: UUID?) -> String? {
        guard let projectId else { return nil }
        if activeProject?.id == projectId { return activeProject?.name }
        let registry = (try? registryStore?.loadOrEmpty()) ?? Registry.empty()
        return registry.projects.first(where: { $0.id == projectId })?.name
    }

    private func addPathActions(to menu: NSMenu, label: String, url: URL) {
        let path = url.path
        menu.addItem(ClosureMenuItem(title: "Copy \(label) Path") {
            NSPasteboard.general.clearContents()
            NSPasteboard.general.setString(path, forType: .string)
        })
        var isDirectory: ObjCBool = false
        let exists = FileManager.default.fileExists(atPath: path, isDirectory: &isDirectory)
        menu.addItem(ClosureMenuItem(title: "Reveal \(label) in Finder", enabled: exists) {
            NSWorkspace.shared.activateFileViewerSelecting([url])
        })
        let terminalSupported = exists && isDirectory.boolValue
            && NSWorkspace.shared.urlForApplication(withBundleIdentifier: "com.apple.Terminal") != nil
        menu.addItem(ClosureMenuItem(title: "Open Terminal at \(label)", enabled: terminalSupported) {
            self.openTerminal(at: url)
        })
        menu.addItem(ClosureMenuItem(
            title: "Open \(label) File Tree",
            enabled: exists && isDirectory.boolValue
        ) { [weak self] in
            self?.openFileTree(at: url)
        })
    }

    private func openFileTree(at url: URL) {
        guard let spawner = tileSpawner else { return }
        switch spawner.spawnFileTree(rootPath: url.path) {
        case let .spawned(tileId, _):
            if let view = canvasView?.tileView(for: tileId) as? FileTreeTileNSView {
                fileTreeViews[tileId] = view
            }
            focusSpawnedTile(tileId)
        case .invalidPath:
            NSSound.beep()
        case let .failure(error):
            fputs("Location Open File Tree failed: \(error)\n", stderr)
        }
    }

    private func openTerminal(at url: URL) {
        let script = "tell application \"Terminal\" to do script "
            + String(reflecting: "cd " + url.path.shellQuoted())
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
        process.arguments = ["-e", script]
        try? process.run()
    }

    static func runLocationActionPolicySelfCheck() throws {
        struct LocationActionPolicyCheckError: Error, CustomStringConvertible {
            let description: String
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw LocationActionPolicyCheckError(description: message) }
        }

        let fileManager = FileManager.default
        let root = fileManager.temporaryDirectory
            .appendingPathComponent("continuum-location-action-policy-\(UUID().uuidString)", isDirectory: true)
        try fileManager.createDirectory(at: root, withIntermediateDirectories: true)
        defer { try? fileManager.removeItem(at: root) }

        let validRoot = root.appendingPathComponent("valid-project", isDirectory: true)
        let symlinkTarget = root.appendingPathComponent("selected-target", isDirectory: true)
        let symlinkRoot = root.appendingPathComponent("selected-link", isDirectory: true)
        let regularFile = root.appendingPathComponent("not-a-directory.txt")
        let missingRoot = root.appendingPathComponent("missing-project", isDirectory: true)
        try fileManager.createDirectory(at: validRoot, withIntermediateDirectories: true)
        try fileManager.createDirectory(at: symlinkTarget, withIntermediateDirectories: true)
        try Data("file".utf8).write(to: regularFile)
        try fileManager.createSymbolicLink(at: symlinkRoot, withDestinationURL: symlinkTarget)

        let delegate = AppDelegate()
        try expect(delegate.usableAgentHomeDirectory(validRoot)?.path == validRoot.resolvingSymlinksInPath().path,
                   "location action policy rejected an existing directory")
        try expect(delegate.usableAgentHomeDirectory(regularFile) == nil,
                   "location action policy accepted a regular file")
        try expect(delegate.usableAgentHomeDirectory(missingRoot) == nil,
                   "location action policy accepted a missing directory")
        try expect(delegate.usableAgentHomeDirectory(URL(string: "https://example.invalid/home")!) == nil,
                   "location action policy accepted a non-file URL")
        try expect(delegate.usableAgentHomeDirectory(symlinkRoot)?.path == symlinkTarget.resolvingSymlinksInPath().path,
                   "an explicitly selected symlink did not resolve to its existing directory target")

        let now = Date(timeIntervalSince1970: 1_700_000_000)
        func project(_ name: String, _ url: URL, missing: Bool = false) -> ProjectEntry {
            ProjectEntry(
                id: UUID(),
                name: name,
                rootPath: url.path,
                workspaceId: nil,
                lastOpenedAt: now,
                pinned: false,
                missing: missing)
        }
        var registry = Registry.empty()
        registry.projects = [
            project("Alpha", validRoot),
            project("File", regularFile),
            project("Missing Path", missingRoot),
            project("Marked Missing", validRoot, missing: true),
            project("Symlink", symlinkRoot),
        ]
        let registryStore = RegistryStore(applicationSupportDirectory: root.appendingPathComponent("registry", isDirectory: true))
        try registryStore.save(registry)
        delegate.registryStore = registryStore

        let probeAgentID = AgentID(rawValue: UUID())
        let changeHome = delegate.locationPrimaryActionMenuItem(for: probeAgentID, hasWork: false)
        try expect(changeHome.title == "Change Home", "zero-turn location menu lost Change Home")
        let changeTitles = changeHome.submenu?.items.filter { !$0.isSeparatorItem }.map(\.title) ?? []
        try expect(changeTitles == ["Use Alpha", "Use Symlink", "Choose Folder…"],
                   "Change Home menu exposed invalid projects or lost valid choices: \(changeTitles)")

        let newAgent = delegate.locationPrimaryActionMenuItem(for: probeAgentID, hasWork: true)
        try expect(newAgent.title == "New Agent Here", "worked/restored location menu can still retarget Home")
        let newTitles = newAgent.submenu?.items.filter { !$0.isSeparatorItem }.map(\.title) ?? []
        try expect(newTitles == ["New Agent in Alpha", "New Agent in Symlink", "Choose Folder…"],
                   "New Agent Here menu exposed invalid projects or lost valid choices: \(newTitles)")

        let agentSupport = root.appendingPathComponent("agents", isDirectory: true)
        let agentStore = AgentStore(applicationSupportDirectory: agentSupport)
        delegate.agentSupervisor = AgentSupervisor(store: agentStore, makeRunner: { _ in ScriptedAgentRunner(script: []) })
        let agentID = delegate.agentSupervisor.spawn(
            role: nil,
            prompt: nil,
            cwd: validRoot,
            model: "test-model",
            thinking: "off")
        let before = delegate.agentSupervisor.records[agentID]
        for invalid in [regularFile, missingRoot, URL(string: "https://example.invalid/home")!] {
            delegate.reassignHome(agentID: agentID, cwd: invalid, projectId: UUID())
            try expect(delegate.agentSupervisor.records[agentID] == before,
                       "invalid Home action mutated the live record for \(invalid.absoluteString)")
            let durableRecord = try agentStore.load(id: agentID)
            try expect(durableRecord == before,
                       "invalid Home action mutated the durable record for \(invalid.absoluteString)")
        }

        // POSITIVE path — the "selected a new Home did nothing" report. A valid
        // Home on a zero-turn agent must actually move BOTH the record's cwd and
        // the live location snapshot the tile renders (the refusal cases above
        // never proved the accept case worked).
        let movedHome = root.appendingPathComponent("moved-home", isDirectory: true)
        try FileManager.default.createDirectory(at: movedHome, withIntermediateDirectories: true)
        let movedHomePath = movedHome.standardizedFileURL.resolvingSymlinksInPath().path
        delegate.reassignHome(agentID: agentID, cwd: movedHome, projectId: nil)
        try expect(delegate.agentSupervisor.records[agentID]?.cwd == movedHomePath,
                   "valid Change Home did not move the record's cwd (got \(delegate.agentSupervisor.records[agentID]?.cwd ?? "nil"))")
        try expect(delegate.agentSupervisor.locationSnapshot(for: agentID)?.home.checkoutRoot.path == movedHomePath,
                   "valid Change Home did not move the live location snapshot Home (got \(delegate.agentSupervisor.locationSnapshot(for: agentID)?.home.checkoutRoot.path ?? "nil"))")

        // FORK path — "New Agent Here" spawns a NEW agent that must land in the
        // chosen Home, not the active-project default.
        let forkHome = root.appendingPathComponent("fork-home", isDirectory: true)
        try FileManager.default.createDirectory(at: forkHome, withIntermediateDirectories: true)
        let forkHomePath = forkHome.standardizedFileURL.resolvingSymlinksInPath().path
        let forkAgentID = delegate.agentSupervisor.spawn(
            role: nil, prompt: nil, cwd: forkHome, model: "test-model", thinking: "off", projectId: nil)
        try expect(delegate.agentSupervisor.records[forkAgentID]?.cwd == forkHomePath,
                   "New Agent Here did not spawn the new agent in the chosen Home (got \(delegate.agentSupervisor.records[forkAgentID]?.cwd ?? "nil"))")
        try expect(delegate.agentSupervisor.locationSnapshot(for: forkAgentID)?.home.checkoutRoot.path == forkHomePath,
                   "the forked agent's live location snapshot did not use the chosen Home (got \(delegate.agentSupervisor.locationSnapshot(for: forkAgentID)?.home.checkoutRoot.path ?? "nil"))")

        // DISPLAY: re-attaching after a Change Home to a custom FOLDER (projectId
        // nil → projectName nil) must drop the prior project name from the header,
        // or the tile shows the old Home though the cwd moved. Drives the real
        // attach re-entry path (not the ComponentLab presentation injection).
        let namedHome = root.appendingPathComponent("Alpha-Root", isDirectory: true)
        try FileManager.default.createDirectory(at: namedHome, withIntermediateDirectories: true)
        let displayAgent = delegate.agentSupervisor.spawn(
            role: nil, prompt: nil, cwd: namedHome, model: "test-model", thinking: "off", projectId: nil)
        let displayTile = ManagedAgentTileNSView(tile: Tile(
            id: UUID(), kind: .managedAgent, title: "T",
            frame: TileFrame(x: 0, y: 0, width: 520, height: 320),
            zPosition: .fromLegacyRank(1), runtimeRef: nil,
            metadata: TileMetadata(launchProfileId: "managed")))
        displayTile.frame = NSRect(x: 0, y: 0, width: 520, height: 320)
        displayTile.applyProviderSettings(.init(model: "openai/gpt-5.6-sol", thinking: "medium"))
        try expect(displayTile.chromeSnapshot?.title == "Agent · \(AgentRecord.defaultAgentName)",
                   "managed chrome must use the conversation name, not the model — got \(displayTile.chromeSnapshot?.title ?? "nil")")
        try expect(displayTile.chromeSnapshot?.showsProviderMark == true
                   && displayTile.chromeSnapshot?.providerModel == "openai/gpt-5.6-sol",
                   "managed chrome did not render the bundled provider mark with its exact model metadata")
        displayTile.attach(agentID: displayAgent, supervisor: delegate.agentSupervisor, projectName: "Alpha Project")
        try expect(displayTile.qaLocationText.contains("Alpha Project"),
                   "attach with a project name should show it, got \(displayTile.qaLocationText)")
        displayTile.attach(agentID: displayAgent, supervisor: delegate.agentSupervisor, projectName: nil)
        try expect(!displayTile.qaLocationText.contains("Alpha Project"),
                   "re-attach to a custom folder (nil project) must drop the stale project name, got \(displayTile.qaLocationText)")
        try expect(displayTile.qaLocationText.contains("Alpha-Root"),
                   "re-attach to a custom folder must show the folder name, got \(displayTile.qaLocationText)")
        try expect(delegate.agentSupervisor.rename(agentID: displayAgent, to: "Investigate tile identity"),
                   "the chrome identity witness could not rename its attached agent")
        try expect(displayTile.chromeSnapshot?.title == "Agent · Investigate tile identity",
                   "record rename did not update the draggable chrome — got \(displayTile.chromeSnapshot?.title ?? "nil")")
    }

    /// Records a managed-agent runtime event onto the per-agent syncable
    /// timeline and nudges a companion publish so the phone updates (88.4c).
    /// `tileId` rides along as the optional view hint only (P2A.8).
    private func recordManagedActivity(agentId: AgentID, tileId: UUID?, event: AgentRuntimeEvent, status: AgentStatus) {
        let overrides = tileId.flatMap { id in
            canvasView?.allWorkspaceTiles().first(where: { $0.id == id })?.metadata.agentSoundOverrides
        }
        _ = agentSignalCenter.ingest(
            event: event,
            agentID: agentId,
            tileID: tileId,
            overrides: overrides
        )
        // WS4: the live half of a watched arrival, run here because this is the
        // first moment the signal for it exists.
        if let tileId { applyPendingWatchedArrival(tileID: tileId) }
        guard let draft = ManagedAgentActivityBridge.draft(
            for: event, agentId: agentId.rawValue, tileId: tileId, status: status, now: Date()
        ) else { return }
        var buffer = managedAgentActivityByAgent[agentId.rawValue] ?? []
        buffer.append(draft)
        if buffer.count > ManagedAgentActivityBridge.recentCap {
            buffer.removeFirst(buffer.count - ManagedAgentActivityBridge.recentCap)
        }
        managedAgentActivityByAgent[agentId.rawValue] = buffer
        scheduleCompanionSyncPublish(reason: .statusChanged, diagnosticsReason: "managed-agent-activity", debounce: 0.5)
        // P2B.4: and the DESKTOP surfaces, which this path used to reach not at all —
        // a managed agent raising its hand moved the phone and left the dock badge and
        // the sidebar row where they were.
        // P2B.7: the snapshot advances HERE, synchronously, by folding this one draft —
        // it used to schedule a full rebuild that re-read every project's store per
        // streamed token. Only the PUSH at the surfaces is debounced, on the same 0.5s
        // as the publish.
        ingestAgentActivityIncrementally(draft: draft)
        scheduleAgentSurfacePush(debounce: 0.5)
    }

    private func spawnBrowserDefault() {
        spawnBrowserFromPalette(url: nil)
    }

    @discardableResult
    private func spawnBrowserFromPalette(url: String?) -> Bool {
        // M1.11: same as the note path, same reason — this guarded only on
        // `tileSpawner`, so with no active controller it spawned into a departed
        // project AND dropped the runtime (`browserRuntimes`' setter is a no-op
        // without an active controller).
        guard let spawner = spawnerForFilesystemCreation() else {
            guard offerCreationScope(then: { [weak self] in _ = self?.spawnBrowserFromPalette(url: url) }) else {
                presentSpawnRefusal("Add a project to this workspace before opening a browser.")
                return false
            }
            return false
        }
        switch spawner.spawnBrowser(url: url) {
        case let .spawned(runtime):
            wireContentProcessTerminationHandler(runtime)
            browserRuntimes.append(runtime)
            focusSpawnedTile(runtime.tileId)
            workspaceRuntime?.registerLiveBrowser(tileId: runtime.tileId)
            workspaceRuntime?.enforceBrowserRuntimeBudget()
            return true
        case let .invalidURL(url):
            fputs("TileSpawner.spawnBrowser invalid URL: \(url)\n", stderr)
            return false
        case let .failure(error):
            fputs("TileSpawner.spawnBrowser failed: \(error)\n", stderr)
            return false
        }
    }

    private func switchBrowserTileProfile(tileId: UUID, profileId: UUID) {
        guard let spawner = tileSpawner else { return }
        switch spawner.switchBrowserTileProfile(tileId: tileId, profileId: profileId) {
        case let .switched(oldRuntimeId, runtime):
            if let oldRuntimeId { browserRuntimes.removeAll { $0.id == oldRuntimeId } }
            wireContentProcessTerminationHandler(runtime)
            browserRuntimes.append(runtime)
            workspaceRuntime?.registerLiveBrowser(tileId: runtime.tileId)
            workspaceRuntime?.enforceBrowserRuntimeBudget()
            focusSpawnedTile(runtime.tileId)
        case let .unknownProfile(id):
            fputs("Browser profile switch failed: unknown profile \(id)\n", stderr)
        case let .invalidURL(url):
            fputs("Browser profile switch failed: invalid URL \(url)\n", stderr)
        case .tileNotFound:
            fputs("Browser profile switch failed: tile not found \(tileId)\n", stderr)
        case let .failure(error):
            fputs("Browser profile switch failed: \(error)\n", stderr)
        }
    }

    private func createBrowserProfile(for tileId: UUID) {
        guard let name = promptForBrowserProfileName(title: "Create Browser Profile", defaultValue: "New Profile") else { return }
        guard let registryStore else { return }
        do {
            var registry = try registryStore.loadOrEmpty()
            guard let profile = BrowserProfilePersistenceActions.createProfile(named: name, in: &registry) else { return }
            try registryStore.save(registry)
            tileSpawner?.updateBrowserProfiles(registry.settings.browserProfiles)
            switchBrowserTileProfile(tileId: tileId, profileId: profile.id)
        } catch {
            fputs("Create Browser Profile failed: \(error)\n", stderr)
        }
    }

    private func renameBrowserProfile(tileId: UUID, profileId: UUID) {
        guard profileId != BrowserProfile.defaultProfileId, let registryStore else { return }
        do {
            var registry = try registryStore.loadOrEmpty()
            guard let existing = registry.settings.browserProfiles.first(where: { $0.id == profileId }) else { return }
            guard let name = promptForBrowserProfileName(title: "Rename Browser Profile", defaultValue: existing.name) else { return }
            guard BrowserProfilePersistenceActions.renameProfile(id: profileId, to: name, in: &registry) else { return }
            try registryStore.save(registry)
            tileSpawner?.updateBrowserProfiles(registry.settings.browserProfiles)
        } catch {
            fputs("Rename Browser Profile failed: \(error)\n", stderr)
        }
    }

    private func deleteBrowserProfile(tileId: UUID, profileId: UUID) {
        guard profileId != BrowserProfile.defaultProfileId, let registryStore else { return }
        let alert = NSAlert()
        alert.messageText = "Delete Browser Profile?"
        alert.informativeText = "Tiles using this profile will switch to Default. WebKit data for the deleted profile is not removed."
        alert.addButton(withTitle: "Delete")
        alert.addButton(withTitle: "Cancel")
        guard alert.runModal() == .alertFirstButtonReturn else { return }
        do {
            var registry = try registryStore.loadOrEmpty()
            var browserState = try projectStore?.loadBrowserState()
            var canvasState = canvasView?.canvasState
            let rewrite = BrowserProfilePersistenceActions.deleteProfile(id: profileId, in: &registry, browserState: &browserState, canvasState: &canvasState)
            guard rewrite.registryDeleted else { return }
            try registryStore.save(registry)
            if let browserState { try projectStore?.saveBrowserState(browserState) }
            if let canvasState {
                for tile in canvasState.tiles { canvasView?.updateTile(tile) }
                try projectStore?.saveCanvas(canvasState)
            }
            tileSpawner?.updateBrowserProfiles(registry.settings.browserProfiles)
            let idsToSwitch = rewrite.affectedTileIds.isEmpty ? [tileId] : rewrite.affectedTileIds
            for affectedTileId in idsToSwitch {
                switchBrowserTileProfile(tileId: affectedTileId, profileId: BrowserProfile.defaultProfileId)
            }
        } catch {
            fputs("Delete Browser Profile failed: \(error)\n", stderr)
        }
    }


    private func promptForBrowserProfileName(title: String, defaultValue: String) -> String? {
        let alert = NSAlert()
        alert.messageText = title
        alert.addButton(withTitle: "OK")
        alert.addButton(withTitle: "Cancel")
        let field = NSTextField(string: defaultValue)
        field.frame = NSRect(x: 0, y: 0, width: 260, height: 24)
        alert.accessoryView = field
        guard alert.runModal() == .alertFirstButtonReturn else { return nil }
        let trimmed = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    private func openProjectInEditor() {
        spawnTerminalFromProfile("nvim")
    }

    @discardableResult
    private func performPaletteAction(_ action: LaunchPaletteAction) -> Bool {
        let tileCount = { [weak self] in self?.canvasView?.navigationTileSnapshots().count ?? 0 }
        switch action {
        case .newManagedAgent:
            return spawnManagedAgentFromPalette()
        case .newHeadlessAgent:
            spawnHeadlessAgentFromPalette()
            return false // Not a safe recent; its modal/spawn path has no result seam yet.
        case .fanOutQueueSelection:
            fanOutFocusedTicketQueue()
            return false // Developer action; intentionally never recent.
        case .newNote:
            let before = tileCount()
            spawnNoteFromPalette()
            return tileCount() > before
        case .newBrowser:
            let before = tileCount()
            spawnBrowserDefault()
            return tileCount() > before
        case let .openURL(url):
            let before = tileCount()
            spawnBrowserFromPalette(url: url)
            return tileCount() > before
        case .openFile:
            let before = tileCount()
            openFileFromPalette()
            return tileCount() > before
        case .openFileTree:
            let before = tileCount()
            spawnFileTreeFromPalette()
            return tileCount() > before
        case .newDiffReview:
            let before = tileCount()
            spawnDiffReviewFromPalette()
            return tileCount() > before
        case .fitCanvasToAll:
            guard let canvasView, let viewport = canvasView.fitAllToViewport() else { return false }
            canvasView.setViewport(viewport)
            return true
        case .tidyCanvas:
            canvasView?.tidyAutoLayout()
            return canvasView != nil
        case .focusCurrentTile:
            // Same helper as hold-⌥ Return; `.tileSpawned` only because the
            // palette is the modal being dismissed here.
            return activateCurrentTile(scopeReason: .tileSpawned)
        case .previousView:
            return restorePreviousView()
        case .previousTile:
            return restorePreviousTile()
        case .previousZone:
            return restorePreviousZone()
        case .toggleWorkspaceSidebar:
            toggleWorkspaceSidebar()
            return true
        case let .switchProject(projectId):
            switchProjectAndRelaunch(projectId: projectId)
            return false // Completion is asynchronous across a relaunch.
        case let .addProjectToCanvas(projectId):
            let before = canvasView?.navZoneRenderModels.count ?? 0
            addProjectZone(projectId: projectId)
            return (canvasView?.navZoneRenderModels.count ?? 0) > before
        case .addProject:
            return addProjectFromDiskAndPlaceOnCanvas()
        case .newWorkspace:
            let before = workspaceRuntime?.workspaceId
            createWorkspaceFromChrome()
            return workspaceRuntime?.workspaceId != before
        case let .renameWorkspace(workspaceId):
            return renameWorkspace(workspaceId: workspaceId, name: "Renamed Workspace")
        case let .deleteWorkspace(workspaceId):
            return deleteWorkspaceAndRelaunch(workspaceId: workspaceId)
        case let .switchWorkspace(workspaceId):
            let before = workspaceRuntime?.workspaceId
            switchWorkspaceAndRelaunch(workspaceId: workspaceId)
            return workspaceRuntime?.workspaceId == workspaceId && workspaceRuntime?.workspaceId != before
        case .openInspectorForFocusedBrowser:
            return openInspectorForFocusedBrowserFromPalette()
        case let .spawnHarnessRole(role):
            spawnHarnessRoleFromPalette(role)
            return false // Developer action; intentionally never recent.
        case let .jumpToTile(tileId):
            return jumpToTileFromPalette(tileId)
        case let .jumpToZone(zoneId):
            return jumpToZoneFromPalette(zoneId)
        case .createZone:
            return createGroupZoneFromPalette()
        case .renameCurrentZone:
            guard let zoneId = paletteContextZoneId else { return false }
            canvasView?.beginZoneRename(zoneId: zoneId)
            return canvasView != nil
        case .pickCurrentZoneColor:
            guard let zoneId = paletteContextZoneId else { return false }
            canvasView?.presentZoneColorPicker(zoneId: zoneId)
            return canvasView != nil
        case .changeCurrentZoneScope:
            guard let zoneId = paletteContextZoneId else { return false }
            canvasView?.requestZoneScopeChange(zoneId: zoneId)
            return canvasView != nil
        case .toggleCurrentZoneAutoLayout:
            guard let zoneId = paletteContextZoneId else { return false }
            canvasView?.toggleZoneAutoLayout(zoneId: zoneId)
            return canvasView != nil
        case .tidyCurrentZone:
            guard let zoneId = paletteContextZoneId else { return false }
            canvasView?.tidyAutoLayout(zoneId: zoneId)
            return canvasView != nil
        case .replayGettingStarted:
            replayGettingStarted()
            return true
        }
    }

    @discardableResult
    private func openInspectorForFocusedBrowserFromPalette() -> Bool {
        let browserTileId = paletteContextTileId ?? focusedTileIdForPaletteContext()
        guard tileKind(for: browserTileId) == .browser,
              let browserTileId,
              let spawner = tileSpawner else { return false }
        switch spawner.spawnBrowserInspector(for: browserTileId) {
        case let .spawned(inspectorTileId):
            focusBroker.enterScope(.tile(inspectorTileId), reason: .tileSpawned)
            return true
        case .notBrowserTile:
            return false
        case let .failure(error):
            fputs("Open inspector for focused browser failed: \(error)\n", stderr)
            return false
        }
    }

    /// The ONE tile reveal/work path. Every keyboard route that puts a tile in
    /// front of the user to work in it — a hold-⌥ label, a ⌘K tile row,
    /// previous-tile, and hold-⌥ Return on the already-current tile — funnels
    /// through here, so framing, previous-view recording, focus history and
    /// input scope can't drift apart per entry point.
    ///
    /// `scopeReason` is the only per-caller difference and it exists for one
    /// reason: a jump made from inside the palette must enter with
    /// `.tileSpawned` so the palette's snapshot restore on close doesn't bounce
    /// focus back to the pre-palette tile. Leader routes use `.modalDismissed`
    /// because the leader is already closed by the time they land.
    @discardableResult
    func revealTileForWork(
        _ tileId: UUID,
        historyReason: FocusHistoryEventReason,
        scopeReason: FocusRequest
    ) -> Bool {
        guard let canvasView, canvasView.navigationTileSnapshot(for: tileId) != nil else { return false }
        if let targetViewport = canvasView.framedViewportForTileJump(tileId) {
            recordViewBeforeProgrammaticJumpIfNeeded(targetViewport: targetViewport)
            canvasView.setViewport(targetViewport)
        }
        focusHistory.recordTileFocus(tileId, zoneId: zoneContainingTile(tileId), reason: historyReason)
        focusBroker.enterScope(.tile(tileId), reason: scopeReason)
        return true
    }

    /// The zone's current/highlighted navigation tile: the one this zone was
    /// last on, else its first navigable tile. Empty zones return nil — a zone
    /// overview with no tile is a legitimate destination, not a place to
    /// fabricate a selection.
    private func currentTileForZone(_ zoneId: UUID) -> UUID? {
        guard let canvasView else { return nil }
        if let remembered = focusHistory.lastFocusedTileByZone[zoneId],
           canvasView.navigationTileSnapshot(for: remembered) != nil {
            return remembered
        }
        return firstTileInZone(zoneId)
    }

    /// The shared LANDING for every zone jump — ⌘K row, leader zone key, ordinal
    /// / next-previous, and Go to Previous Zone. Two halves, both required:
    ///
    /// 1. Input scope lands on the CANVAS, deterministically, whatever route got
    ///    here. A zone jump does not take a tile's input scope (the overview
    ///    camera is not a place to type), but it must not leave the PREVIOUS
    ///    tile holding the keyboard either: that tile is usually somewhere the
    ///    new overview has scrolled off screen, so the user's next keystrokes
    ///    would vanish into a tile they cannot see. `.tileSpawned` is the
    ///    broker's existing "this action already chose the post-close scope,
    ///    don't restore the modal's snapshot" signal — the same one every
    ///    palette spawn and tile jump uses.
    /// 2. The zone's remembered (else first) tile becomes CURRENT/highlighted,
    ///    without moving the overview camera. It becomes workable only when the
    ///    user activates it (hold-⌥ Return / ⌘K "Focus Current Tile" / a tile
    ///    jump).
    ///
    /// The tile-focus record is always `.completedZoneJump`, so no zone route
    /// pushes its tile onto the recent-tiles stack: "Go to Previous Tile" means
    /// the same thing however you reached the zone.
    ///
    /// - Parameter landingInputOnCanvas: false for the ONE route whose modal
    ///   stays open across the jump — nav mode's ordinal / next-previous keys.
    ///   Nav mode routes keys only while it owns `activeSurface`
    ///   (`handleHotkey`), so taking that surface mid-mode would silently deafen
    ///   it; and while it is open no TILE holds the keyboard, so there is
    ///   nothing to strand. Where nav mode leaves scope on exit is nav mode's
    ///   own (legacy) contract, out of this plan's scope.
    private func completeZoneJump(_ zoneId: UUID, landingInputOnCanvas: Bool = true) {
        if landingInputOnCanvas {
            focusBroker.enterScope(.canvas, reason: .tileSpawned)
        }
        guard let canvasView, let tileId = currentTileForZone(zoneId) else { return }
        canvasView.markActive(tileId: tileId)
        focusHistory.recordTileFocus(tileId, zoneId: zoneId, reason: .completedZoneJump)
    }

    /// Hold-⌥ Return / "Focus Current Tile": activate the tile that is ALREADY
    /// current. Re-applies reveal/work framing and repairs input focus even when
    /// the tile id has not changed — that is the whole point of the action.
    @discardableResult
    func activateCurrentTile(scopeReason: FocusRequest) -> Bool {
        guard let tileId = canvasView?.canvasState.lastActiveTileId else { return false }
        return revealTileForWork(tileId, historyReason: .directTileActivation, scopeReason: scopeReason)
    }

    /// ⌘K "Jump to <title>" — the palette's entry into the shared reveal/work path.
    @discardableResult
    private func jumpToTileFromPalette(_ tileId: UUID) -> Bool {
        revealTileForWork(tileId, historyReason: .paletteJump, scopeReason: .tileSpawned)
    }

    /// QA accessor for `navSelectedZoneId` (mirrors `searchTextForQA` precedent).
    var navSelectedZoneIdForQA: UUID? { navSelectedZoneId }

    /// ⌘K "Jump to <zone name>" — a zone jump produces OVERVIEW: it fits the zone,
    /// sets navSelectedZoneId, and makes the zone's remembered (else first) tile
    /// current/highlighted. It deliberately does NOT take that tile's input scope
    /// — the camera is at overview zoom, where typing into a tile you cannot read
    /// is a trap. Hold-⌥ Return (or a tile jump) is what activates it. Input
    /// lands on the canvas instead of wherever it was; see `completeZoneJump`.
    @discardableResult
    private func jumpToZoneFromPalette(_ zoneId: UUID) -> Bool {
        guard let canvasView,
              canvasView.navZoneRenderModels.contains(where: { $0.placement.zoneId == zoneId }),
              let viewport = canvasView.fitZoneToViewport(zoneId: zoneId) else { return false }
        recordViewBeforeProgrammaticJumpIfNeeded(targetViewport: viewport)
        canvasView.setViewport(viewport)
        navSelectedZoneId = zoneId
        focusHistory.recordZoneFocus(zoneId, reason: .paletteJump)
        completeZoneJump(zoneId)
        return true
    }

    @discardableResult
    private func restorePreviousView() -> Bool {
        guard let snapshot = focusHistory.previousView(), let canvasView else { NSSound.beep(); return false }
        canvasView.setViewport(snapshot.viewport)
        navSelectedZoneId = snapshot.focusedZoneId
        if let tileId = snapshot.focusedTileId, canvasView.navigationTileSnapshot(for: tileId) != nil {
            focusBroker.enterScope(.tile(tileId), reason: .tileSpawned)
        }
        return true
    }

    @discardableResult
    private func restorePreviousTile() -> Bool {
        guard let canvasView,
              let tileId = focusHistory.previousTile(valid: { [weak self] id in self?.canvasView?.navigationTileSnapshot(for: id) != nil }) else { NSSound.beep(); return false }
        canvasView.markActive(tileId: tileId)
        navSelectedZoneId = zoneContainingTile(tileId)
        return revealTileForWork(tileId, historyReason: .previousNavigation, scopeReason: .tileSpawned)
    }

    @discardableResult
    private func restorePreviousZone() -> Bool {
        guard let canvasView,
              let zoneId = focusHistory.previousZone(valid: { [weak self] id in self?.canvasView?.navZoneRenderModels.contains(where: { $0.placement.zoneId == id }) == true }) else { NSSound.beep(); return false }
        navSelectedZoneId = zoneId
        // Go to Previous Zone is a ZONE jump: overview camera, remembered/first
        // tile current, no tile input scope — same contract as every other zone
        // route, through the same helper. It used to reveal the remembered tile
        // for work instead, which made it the one zone command that zoomed into
        // a tile and took its keyboard, and its own inline remembered-tile
        // lookup left a zone with NO current tile when that tile had been
        // deleted.
        if let viewport = canvasView.fitZoneToViewport(zoneId: zoneId) {
            recordViewBeforeProgrammaticJumpIfNeeded(targetViewport: viewport)
            canvasView.setViewport(viewport)
        }
        focusHistory.recordZoneFocus(zoneId, reason: .previousNavigation)
        completeZoneJump(zoneId)
        return true
    }

    private func zoneContainingTile(_ tileId: UUID) -> UUID? {
        guard let canvasView else { return nil }
        if let zoneId = canvasView.navigationTileSnapshot(for: tileId)?.zoneId {
            return zoneId
        }
        guard let tile = canvasView.tileRecord(for: tileId) else { return nil }
        let tileRect = CGRect(x: tile.frame.x, y: tile.frame.y, width: tile.frame.width, height: tile.frame.height)
        return canvasView.navZoneRenderModels.first { model in
            let frame = CanvasEngine.zoneWorldFrame(model.placement)
            return CGRect(x: frame.x, y: frame.y, width: frame.width, height: frame.height).intersects(tileRect)
        }?.placement.zoneId
    }

    /// Returns the id of the first tile whose world frame intersects the zone's world rect.
    private func firstTileInZone(_ zoneId: UUID) -> UUID? {
        guard let canvasView,
              let model = canvasView.navZoneRenderModels.first(where: { $0.placement.zoneId == zoneId }) else { return nil }
        if let tileId = canvasView.firstNavigationTileId(inZone: zoneId) {
            return tileId
        }
        let zoneFrame = CanvasEngine.zoneWorldFrame(model.placement)
        let zoneRect = CGRect(x: zoneFrame.x, y: zoneFrame.y, width: zoneFrame.width, height: zoneFrame.height)
        return canvasView.navigationTileSnapshots().first { snapshot in
            let frame = snapshot.worldFrame
            let tileRect = CGRect(x: frame.x, y: frame.y, width: frame.width, height: frame.height)
            return zoneRect.intersects(tileRect)
        }?.tileId
    }

    /// ⌘K "Create Zone" enters the same provisional project/Home flow as a
    /// marquee. A blank project-less zone is never written to disk.
    @discardableResult
    private func createGroupZoneFromPalette() -> Bool {
        guard let canvasView else { return false }
        _ = canvasView.beginProvisionalZone()
        return true
    }

    /// Persist a group zone created by the on-canvas drag-to-create gesture (T19).
    /// Appends the placement as-is (origin/size come from the drag rect) to the stored
    /// Present the keep-or-delete confirm for closing a zone (zone-unify P5),
    /// then drive `closeZone`. Keep is the default (non-destructive) button.
    private func presentZoneCloseConfirm(_ zoneId: UUID) {
        let alert = NSAlert()
        alert.messageText = "Close this zone?"
        alert.informativeText = "Keep the tiles on the canvas, or delete them along with the zone."
        alert.addButton(withTitle: "Keep Tiles")
        alert.addButton(withTitle: "Delete Tiles")
        alert.addButton(withTitle: "Cancel")
        switch alert.runModal() {
        case .alertFirstButtonReturn: canvasView?.closeZone(zoneId: zoneId, keepTiles: true)
        case .alertSecondButtonReturn: canvasView?.closeZone(zoneId: zoneId, keepTiles: false)
        default: break
        }
    }

    /// Drop a closed zone from the WorkspaceDocument (placement, z-order, and any
    /// persisted group-zone tiles) and flush. Called from canvasView.onZoneClosed.
    private func persistClosedZone(_ zoneId: UUID) {
        if let workspaceRuntime {
            do {
                try workspaceRuntime.commitClosedZone(zoneId)
                reloadWorkspaceSidebar()
            } catch {
                fputs("persistClosedZone failed: \(error)\n", stderr)
            }
            return
        }
        guard let registryStore else { return }
        do {
            let workspaceId: UUID
            if let wId = workspaceRuntime?.workspaceId {
                workspaceId = wId
            } else if let wId = (try? registryStore.loadOrEmpty())?.lastActiveWorkspaceId {
                workspaceId = wId
            } else {
                fputs("persistClosedZone: no active workspace\n", stderr)
                return
            }
            let appSupport = registryStore.registryFile.deletingLastPathComponent()
            let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport)
            var document = try store.load()
            document.zones.removeAll { $0.zoneId == zoneId }
            if document.lastActiveZoneId == zoneId {
                document.lastActiveZoneId = document.zonesInZOrder.last?.zoneId
            }
            document.setTiles([], forZone: zoneId)
            let saveController = WorkspaceDocumentSaveController(store: store)
            saveController.scheduleZoneLayoutSave(document)
            try saveController.flushPendingSave()
            workspaceRuntime?.replaceDocument(document, for: workspaceId)
            reloadWorkspaceSidebar()
        } catch {
            fputs("persistClosedZone failed: \(error)\n", stderr)
        }
    }

    /// WorkspaceDocument and flushes the save. Called from canvasView.onZoneCreated.
    private func persistCreatedGroupZone(_ placement: ZonePlacement) {
        if let workspaceRuntime {
            do {
                try workspaceRuntime.commitCreatedZone(placement)
                reloadWorkspaceSidebar()
            } catch {
                fputs("persistCreatedGroupZone failed: \(error)\n", stderr)
            }
            return
        }
        guard let registryStore else { return }
        do {
            let workspaceId: UUID
            if let wId = workspaceRuntime?.workspaceId {
                workspaceId = wId
            } else if let wId = (try? registryStore.loadOrEmpty())?.lastActiveWorkspaceId {
                workspaceId = wId
            } else {
                fputs("persistCreatedGroupZone: no active workspace\n", stderr)
                return
            }
            let appSupport = registryStore.registryFile.deletingLastPathComponent()
            let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport)
            var document = try store.load()
            // Only append if not already present (idempotent guard).
            guard !document.zones.contains(where: { $0.zoneId == placement.zoneId }) else { return }
            document.zones.append(placement)
            document.bringZoneToFront(placement.zoneId)
            document.lastActiveZoneId = placement.zoneId
            let saveController = WorkspaceDocumentSaveController(store: store)
            saveController.scheduleZoneLayoutSave(document)
            try saveController.flushPendingSave()
            workspaceRuntime?.replaceDocument(document, for: workspaceId)
            reloadWorkspaceSidebar()
        } catch {
            fputs("persistCreatedGroupZone failed: \(error)\n", stderr)
        }
    }

    /// Persist a zone's moved origin after an on-canvas chrome-drag gesture (T19).
    /// Finds the zone by zoneId in the stored WorkspaceDocument, replaces its origin/size
    /// with the committed placement, and flushes the save. Called from canvasView.onZoneMoved.
    private func persistMovedZone(_ placement: ZonePlacement) {
        if let workspaceRuntime {
            do {
                try workspaceRuntime.commitZonePlacement(placement)
            } catch {
                fputs("persistMovedZone failed: \(error)\n", stderr)
            }
            return
        }
        guard let registryStore else { return }
        do {
            let workspaceId: UUID
            if let wId = workspaceRuntime?.workspaceId {
                workspaceId = wId
            } else if let wId = (try? registryStore.loadOrEmpty())?.lastActiveWorkspaceId {
                workspaceId = wId
            } else {
                fputs("persistMovedZone: no active workspace\n", stderr)
                return
            }
            let appSupport = registryStore.registryFile.deletingLastPathComponent()
            let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport)
            var document = try store.load()
            guard let i = document.zones.firstIndex(where: { $0.zoneId == placement.zoneId }) else {
                fputs("persistMovedZone: zone \(placement.zoneId) not in document\n", stderr)
                return
            }
            document.zones[i] = placement
            let saveController = WorkspaceDocumentSaveController(store: store)
            saveController.scheduleZoneLayoutSave(document)
            try saveController.flushPendingSave()
            workspaceRuntime?.replaceDocument(document, for: workspaceId)
        } catch {
            fputs("persistMovedZone failed: \(error)\n", stderr)
        }
    }

    /// One solver gesture may move an entire contact chain. Project canvases and
    /// the workspace document are saved synchronously from one snapshot. If any
    /// write fails, already-written project canvases are restored before the
    /// caller rolls the preview back in memory.
    private func persistLayoutTransaction(_ transaction: CanvasLayoutTransaction) -> Bool {
        guard let registryStore else { return false }
        do {
            let workspaceId: UUID
            if let id = workspaceRuntime?.workspaceId {
                workspaceId = id
            } else if let id = (try? registryStore.loadOrEmpty())?.lastActiveWorkspaceId {
                workspaceId = id
            } else {
                fputs("persistLayoutTransaction: no active workspace\n", stderr)
                return false
            }
            let appSupport = registryStore.registryFile.deletingLastPathComponent()
            let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport)
            var document = try store.load()
            for (zoneId, placement) in transaction.zonePlacements {
                if let index = document.zones.firstIndex(where: { $0.zoneId == zoneId }) {
                    document.zones[index] = placement
                }
            }
            // WS2 F2: store the WORLD frame verbatim. `transaction.tileFrames` is
            // already world-space (`CanvasNSView.captureGeometry` converts every
            // layer tile through `CanvasEngine.worldFrame(tile:in:)`), and
            // `ambientTiles` is a WORLD register — the read
            // (`WorkspaceRuntime.makeAmbientZoneLayer`) converts to zone-local on
            // the way into the layer, and the pre-v3 migration flattened
            // world-framed group-zone tiles into it untouched. Converting here as
            // well subtracted the zone origin twice, so an ambient tile drifted by
            // −zoneOrigin on every commit/remount cycle and the error accumulated.
            // Witness: `--ambient-tile-frame-space-check`.
            for (tileId, worldFrame) in transaction.tileFrames {
                guard let index = document.ambientTiles.firstIndex(where: { $0.id == tileId }) else { continue }
                document.ambientTiles[index].frame = worldFrame
            }

            let registry = try registryStore.loadOrEmpty()
            var projectZones: [UUID: ZonePlacement] = [:]
            for zone in document.zones {
                if let projectId = zone.projectId { projectZones[projectId] = zone }
            }
            var projectWrites: [(store: ProjectStore, original: CanvasState, updated: CanvasState)] = []
            for (projectId, _) in projectZones.sorted(by: { $0.key.uuidString < $1.key.uuidString }) {
                guard let entry = registry.projects.first(where: { $0.id == projectId }) else { continue }
                let projectStore = ProjectStore(projectRoot: URL(fileURLWithPath: entry.rootPath, isDirectory: true))
                guard let original = try projectStore.tryLoadCanvas() else { continue }
                var updated = original
                var changed = false
                // WS2 F2, same defect as the ambient register above: `canvas.json`
                // holds WORLD frames (`WorkspaceRuntime.memberTiles` converts on the
                // way into a ZoneLayer, `CanvasNSView.tilesInWorldFrames` on the way
                // back out), so converting to zone-local here made this writer
                // disagree with `canvasStateForPersistence`, the other writer of the
                // same file. It was usually masked: a later debounced canvas save
                // rewrote world frames over it. Quit before that save and every
                // moved tile came back displaced by its zone origin.
                for index in updated.tiles.indices {
                    guard let worldFrame = transaction.tileFrames[updated.tiles[index].id] else { continue }
                    updated.tiles[index].frame = worldFrame
                    changed = true
                }
                if changed { projectWrites.append((projectStore, original, updated)) }
            }

            var savedProjectWrites: [(store: ProjectStore, original: CanvasState)] = []
            do {
                for write in projectWrites {
                    try write.store.saveCanvas(write.updated)
                    savedProjectWrites.append((write.store, write.original))
                }
                let saveController = WorkspaceDocumentSaveController(store: store)
                saveController.scheduleZoneLayoutSave(document)
                try saveController.flushPendingSave()
            } catch {
                for saved in savedProjectWrites.reversed() {
                    do { try saved.store.saveCanvas(saved.original) }
                    catch { fputs("persistLayoutTransaction rollback failed: \(error)\n", stderr) }
                }
                throw error
            }
            workspaceRuntime?.replaceDocument(document, for: workspaceId)
            return true
        } catch {
            fputs("persistLayoutTransaction failed: \(error)\n", stderr)
            return false
        }
    }

    /// Persist a zone rename: update the stored zone's name so it survives relaunch.
    /// Mirrors `persistMovedZone` (full document load → mutate → save).
    private func persistRenamedZone(_ zoneId: UUID, name: String) {
        if let workspaceRuntime, var placement = canvasView?.zonePlacement(for: zoneId) {
            placement.name = name
            do {
                try workspaceRuntime.commitZonePlacement(placement)
                reloadWorkspaceSidebar()
            } catch {
                fputs("persistRenamedZone failed: \(error)\n", stderr)
            }
            return
        }
        guard let registryStore else { return }
        do {
            let workspaceId: UUID
            if let wId = workspaceRuntime?.workspaceId {
                workspaceId = wId
            } else if let wId = (try? registryStore.loadOrEmpty())?.lastActiveWorkspaceId {
                workspaceId = wId
            } else {
                fputs("persistRenamedZone: no active workspace\n", stderr)
                return
            }
            let appSupport = registryStore.registryFile.deletingLastPathComponent()
            let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport)
            var document = try store.load()
            guard let i = document.zones.firstIndex(where: { $0.zoneId == zoneId }) else {
                fputs("persistRenamedZone: zone \(zoneId) not in document\n", stderr)
                return
            }
            document.zones[i].name = name
            let saveController = WorkspaceDocumentSaveController(store: store)
            saveController.scheduleZoneLayoutSave(document)
            try saveController.flushPendingSave()
            workspaceRuntime?.replaceDocument(document, for: workspaceId)
            reloadWorkspaceSidebar()
        } catch {
            fputs("persistRenamedZone failed: \(error)\n", stderr)
        }
    }

    private func zoneScopeLabel(_ scope: ZoneScope) -> String {
        guard let projectId = scope.projectId,
              let registry = try? registryStore?.loadOrEmpty(),
              let project = registry.projects.first(where: { $0.id == projectId }) else {
            return "Needs Project"
        }
        return scope.homeRelativePath.map { "\(project.name) / \($0)" }
            ?? "\(project.name) / Project Root"
    }

    private func filesystemScopeEvidence(forTile tileId: UUID) -> ZoneScope? {
        if let agentId = agentSupervisor.agent(forTile: tileId),
           let record = agentSupervisor.records[agentId],
           let projectId = record.projectId {
            return ZoneScope(projectId: projectId, homeRelativePath: record.homeRelativePath)
        }
        guard let tile = canvasView?.tileRecord(for: tileId) else { return nil }
        if let projectId = tile.metadata.filesystemProjectId {
            return ZoneScope(projectId: projectId, homeRelativePath: tile.metadata.filesystemHomeRelativePath)
        }
        if let location = tile.metadata.documentLocation,
           let projectId = location.projectId {
            return ZoneScope(projectId: projectId, homeRelativePath: location.relativeDirectory == "." ? nil : location.relativeDirectory)
        }
        guard tile.kind == .fileTree,
              let rootPath = tile.metadata.filePath,
              let registry = try? registryStore?.loadOrEmpty() else { return nil }
        let selected = URL(fileURLWithPath: rootPath, isDirectory: true)
        for project in registry.projects where !project.missing {
            let projectRoot = URL(fileURLWithPath: project.rootPath, isDirectory: true)
            if let relative = try? ProjectHomeValidator.relativeHome(projectRoot: projectRoot, selectedHome: selected) {
                return ZoneScope(projectId: project.id, homeRelativePath: relative)
            }
        }
        return nil
    }

    private func presentProjectHomePicker(
        for placement: ZonePlacement,
        anchor: CGPoint,
        isNewZone: Bool
    ) {
        guard let canvasView, let registryStore else {
            if isNewZone { self.canvasView?.cancelProvisionalZone(zoneId: placement.zoneId) }
            return
        }
        let registry = (try? registryStore.loadOrEmpty()) ?? Registry.empty()
        let selected = placement.projectId.flatMap { projectId in
            registry.projects.first(where: { $0.id == projectId }).map {
                ProjectHomeSelection(project: $0, homeRelativePath: placement.homeRelativePath)
            }
        }
        var recents: [ProjectHomeSelection] = []
        if let workspaceId = workspaceRuntime?.workspaceId {
            let store = WorkspaceStore(
                workspaceId: workspaceId,
                applicationSupportDirectory: registryStore.registryFile.deletingLastPathComponent()
            )
            if let document = try? store.load(),
               let scope = document.lastExplicitCreationScope,
               let projectId = scope.projectId,
               let project = registry.projects.first(where: { $0.id == projectId }) {
                recents.append(ProjectHomeSelection(project: project, homeRelativePath: scope.homeRelativePath))
            }
        }
        let picker = ProjectHomePickerController()
        projectHomePicker?.dismiss(cancelled: false)
        projectHomePicker = picker
        picker.present(
            projects: registry.projects,
            recents: recents,
            selected: selected,
            anchor: anchor,
            relativeTo: canvasView,
            addProject: { [weak self] in self?.registerProjectUsingOpenPanel() },
            confirmsDestructiveCancellation: isNewZone,
            onInteractionOwnershipChanged: { [weak canvasView] owned in
                canvasView?.setZoneScopePickerInteractionOwned(owned)
            },
            onConfirm: { [weak self] selection in
                guard let self else { return }
                guard let workspaceId = self.workspaceRuntime?.workspaceId else {
                    if isNewZone {
                        canvasView.cancelProvisionalZone(zoneId: placement.zoneId)
                    }
                    self.projectHomePicker = nil
                    self.setWorkspaceManagementMessage("Couldn't determine the active workspace.")
                    return
                }
                do {
                    var liveRegistry = try registryStore.loadOrEmpty()
                    if let owner = try liveRegistry.exclusiveWorkspaceOwner(of: selection.project.id),
                       owner != workspaceId {
                        // The picker used to commit the placement first and only
                        // discover the ownership conflict on the next workspace
                        // mount. The zone was durable but filtered as foreign, so
                        // switching away and back looked exactly like data loss.
                        // Keep the provisional zone memory-only, remove it before
                        // any optional switch, and route through the same friendly
                        // ownership helper as Add Project.
                        if isNewZone {
                            canvasView.cancelProvisionalZone(zoneId: placement.zoneId)
                        }
                        self.projectHomePicker = nil
                        self.offerSwitchToOwningWorkspace(
                            projectId: selection.project.id,
                            workspaceId: owner
                        )
                        return
                    }
                    if try liveRegistry.exclusiveWorkspaceOwner(of: selection.project.id) == nil {
                        try liveRegistry.assignProject(selection.project.id, to: workspaceId, now: Date())
                        try registryStore.save(liveRegistry)
                    }
                } catch {
                    if isNewZone {
                        canvasView.cancelProvisionalZone(zoneId: placement.zoneId)
                    }
                    self.projectHomePicker = nil
                    self.setWorkspaceManagementMessage(
                        "Couldn't use that project here: \(error.localizedDescription)"
                    )
                    return
                }
                let label = self.zoneScopeLabel(ZoneScope(
                    projectId: selection.project.id,
                    homeRelativePath: selection.homeRelativePath
                ))
                if isNewZone {
                    canvasView.commitProvisionalZone(
                        zoneId: placement.zoneId,
                        projectId: selection.project.id,
                        homeRelativePath: selection.homeRelativePath,
                        scopeLabel: label
                    )
                } else {
                    canvasView.setZoneScope(
                        zoneId: placement.zoneId,
                        projectId: selection.project.id,
                        homeRelativePath: selection.homeRelativePath,
                        scopeLabel: label
                    )
                    canvasView.showWorkspaceTransitionLabel("Future filesystem tiles will start in \(selection.displayPath)")
                }
                self.persistLastExplicitCreationScope(
                    ZoneScope(projectId: selection.project.id, homeRelativePath: selection.homeRelativePath)
                )
                self.demonstrateOnboarding(.zoneScopeInspected)
                self.projectHomePicker = nil
            },
            onCancel: { [weak self, weak canvasView] in
                if isNewZone { canvasView?.cancelProvisionalZone(zoneId: placement.zoneId) }
                self?.projectHomePicker = nil
            }
        )
    }

    private func persistLastExplicitCreationScope(_ scope: ZoneScope) {
        guard scope.projectId != nil,
              let registryStore,
              let workspaceId = workspaceRuntime?.workspaceId else { return }
        do {
            let store = WorkspaceStore(
                workspaceId: workspaceId,
                applicationSupportDirectory: registryStore.registryFile.deletingLastPathComponent()
            )
            var document = try store.load()
            document.lastExplicitCreationScope = scope
            let saveController = WorkspaceDocumentSaveController(store: store)
            saveController.scheduleZoneLayoutSave(document)
            try saveController.flushPendingSave()
            workspaceRuntime?.replaceDocument(document, for: workspaceId)
        } catch {
            fputs("persistLastExplicitCreationScope failed: \(error)\n", stderr)
        }
    }

    /// Register a folder and give it a zone, in one action. M1.11 (`.plans/46`).
    ///
    /// `registerProjectUsingOpenPanel` alone is not enough: it writes the registry
    /// but creates no zone, so a project chosen in an empty workspace becomes
    /// registered and invisible — the same dead end one level down. Choosing a
    /// project here has to give it somewhere to land.
    @discardableResult
    private func addProjectFromDiskAndPlaceOnCanvas() -> Bool {
        guard let entry = addProjectSelectionProvider?() ?? registerProjectUsingOpenPanel() else { return false }
        addProjectZone(projectId: entry.id)
        return workspaceRuntime?.controller(for: entry.id) != nil
    }

    private func registerProjectUsingOpenPanel() -> ProjectEntry? {
        guard let registryStore else { return nil }
        let panel = NSOpenPanel()
        panel.canChooseFiles = false
        panel.canChooseDirectories = true
        panel.allowsMultipleSelection = false
        panel.prompt = "Add Project"
        guard panel.runModal() == .OK, let rawURL = panel.url else { return nil }
        let root = rawURL.standardizedFileURL.resolvingSymlinksInPath()
        do {
            var registry = try registryStore.loadOrEmpty()
            if let existing = registry.projects.first(where: {
                URL(fileURLWithPath: $0.rootPath, isDirectory: true)
                    .standardizedFileURL.resolvingSymlinksInPath().path == root.path
            }) {
                return existing
            }
            let store = ProjectStore(projectRoot: root)
            let project = try Self.loadOrCreateProject(in: store, projectRoot: root)
            registry.upsertProject(project, openedAt: Date())
            if let workspaceId = workspaceRuntime?.workspaceId {
                try registry.assignProject(project.id, to: workspaceId, now: Date())
            }
            try registryStore.save(registry)
            reloadWorkspaceSidebar()
            return registry.projects.first(where: { $0.id == project.id })
        } catch {
            fputs("Add Project failed: \(error)\n", stderr)
            return nil
        }
    }

    private func spawnHarnessRoleFromPalette(_ role: HarnessRole) {
        guard let prompt = promptForHarnessRoleTask(role: role) else { return }
        guard let spawner = tileSpawner else { return }
        let admissionTrigger = "palette:harness:\(role.id)"
        if let refusal = terminalSpawnAdmission.admit(trigger: admissionTrigger, liveCount: liveTerminalRuntimeCount()) {
            fputs("\(refusal.message)\n", stderr)
            return
        }
        switch spawner.spawnHarnessRoleRun(role: role, prompt: prompt) {
        case let .spawned(runtime):
            installSpawnedTerminal(runtime)
        case let .failure(error):
            fputs("TileSpawner.spawnHarnessRoleRun failed: \(error)\n", stderr)
        case let .missingCommand(executable):
            presentMissingCommand(executable: executable, profileId: role.id)
        case let .notConfigured(id):
            presentMissingCommand(executable: id, profileId: id, kind: .notConfigured)
        case let .unknownProfile(id):
            fputs("Unknown harness role id: \(id)\n", stderr)
        }
    }

    private func promptForHarnessRoleTask(role: HarnessRole) -> String? {
        promptForAgentTask(
            title: "Run \(role.displayName) Agent",
            informativeText: "Enter the prompt for the .pi/agents/\(role.id).md role."
        )
    }

    /// The task prompt for a spawn-and-run agent action, or nil if the user cancels
    /// or leaves it empty. Was `promptForHarnessRoleTask`'s body; a headless agent
    /// (P2A.6) needs the same modal for the same reason — the run starts at spawn, so
    /// there is nowhere else to type the first prompt.
    private func promptForAgentTask(title: String, informativeText: String) -> String? {
        let alert = NSAlert()
        alert.messageText = title
        alert.informativeText = informativeText
        alert.addButton(withTitle: "Run")
        alert.addButton(withTitle: "Cancel")
        let field = NSTextField(string: "")
        field.placeholderString = "Task prompt"
        field.frame = NSRect(x: 0, y: 0, width: 360, height: 24)
        alert.accessoryView = field
        guard alert.runModal() == .alertFirstButtonReturn else { return nil }
        let trimmed = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    private func setWorkspaceManagementMessage(_ message: String?) {
        workspaceManagementMessage = message
        workspaceTopBarView?.setManagementMessage(message)
        workspaceSidebarView?.setManagementMessage(message)
    }

    private func createWorkspaceFromChrome() {
        let name = workspaceCreatePromptProvider?() ?? promptForWorkspaceName(
            title: "New Workspace",
            defaultValue: "Untitled Workspace",
            actionTitle: "Create"
        )
        guard let name else { return }
        _ = createWorkspaceAndRelaunch(name: name)
    }

    @discardableResult
    private func createWorkspaceAndRelaunch(name: String) -> Bool {
        guard let registryStore else { return false }
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            setWorkspaceManagementMessage("Workspace name can't be empty.")
            return false
        }
        let workspace: WorkspaceEntry
        do {
            var registry = try registryStore.loadOrEmpty()
            workspace = registry.createWorkspace(name: trimmed, now: Date())
            let appSupport = registryStore.registryFile.deletingLastPathComponent()
            try WorkspaceStore(workspaceId: workspace.id, applicationSupportDirectory: appSupport).save(
                WorkspaceDocument(
                    viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
                    zones: [],
                    zoneZOrder: [],
                    lastActiveZoneId: nil
                )
            )
            try registryStore.save(registry)
        } catch {
            fputs("Create Workspace failed: \(error)\n", stderr)
            setWorkspaceManagementMessage("Create workspace failed: \(error.localizedDescription)")
            return false
        }
        do {
            // Creation and navigation are deliberately reported separately. Once
            // the registry entry and empty document are durable, a switch problem
            // must not tell the user that creation failed or encourage duplicates.
            try workspaceRuntime?.switchWorkspace(to: workspace.id)
            setWorkspaceManagementMessage("Created empty workspace “\(workspace.name)”.")
        } catch {
            fputs("Created Workspace but switch failed: \(error)\n", stderr)
            setWorkspaceManagementMessage(
                "Created “\(workspace.name)”, but couldn't switch to it: \(error.localizedDescription)"
            )
        }
        reloadWorkspaceSidebar()
        return true
    }

    private func renameWorkspaceFromTopBar(workspaceId: UUID) {
        guard let registryStore else { return }
        do {
            let registry = try registryStore.loadOrEmpty()
            guard let currentName = registry.workspaces.first(where: { $0.id == workspaceId })?.name else { return }
            guard let newName = workspaceRenamePromptProvider?(currentName) ?? promptForWorkspaceRename(currentName: currentName) else { return }
            _ = renameWorkspace(workspaceId: workspaceId, name: newName)
        } catch {
            fputs("Rename Workspace failed: \(error)\n", stderr)
        }
    }

    private func promptForWorkspaceRename(currentName: String) -> String? {
        promptForWorkspaceName(title: "Rename Workspace", defaultValue: currentName, actionTitle: "Rename")
    }

    private func promptForWorkspaceName(title: String, defaultValue: String, actionTitle: String) -> String? {
        var validationMessage: String?
        while true {
            let alert = NSAlert()
            alert.messageText = title
            alert.informativeText = validationMessage ?? "Enter a workspace name. Duplicate names are allowed."
            alert.addButton(withTitle: actionTitle)
            alert.addButton(withTitle: "Cancel")
            let field = NSTextField(string: defaultValue)
            field.frame = NSRect(x: 0, y: 0, width: 320, height: 24)
            alert.accessoryView = field
            guard alert.runModal() == .alertFirstButtonReturn else { return nil }
            let trimmed = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty { return trimmed }
            validationMessage = "Workspace name can't be empty."
            setWorkspaceManagementMessage(validationMessage)
        }
    }

    @discardableResult
    private func renameWorkspace(workspaceId: UUID, name: String) -> Bool {
        guard let registryStore else { return false }
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            setWorkspaceManagementMessage("Workspace name can't be empty.")
            return false
        }
        do {
            var registry = try registryStore.loadOrEmpty()
            guard registry.renameWorkspace(id: workspaceId, name: trimmed, now: Date()) else {
                setWorkspaceManagementMessage("Workspace could not be renamed.")
                return false
            }
            try registryStore.save(registry)
            setWorkspaceManagementMessage("Renamed workspace to “\(trimmed)”.")
            reloadWorkspaceSidebar()
            return true
        } catch {
            fputs("Rename Workspace failed: \(error)\n", stderr)
            setWorkspaceManagementMessage("Rename workspace failed: \(error.localizedDescription)")
            return false
        }
    }

    private func confirmDeleteWorkspace(_ request: WorkspaceDeleteConfirmationRequest) -> Bool {
        let alert = NSAlert()
        alert.alertStyle = .warning
        alert.messageText = "Delete “\(request.workspaceName)” workspace?"
        alert.informativeText = "\(request.deletionCopy)\n\nThis workspace currently has \(request.projectCount) \(request.projectCount == 1 ? "project" : "projects") and \(request.zoneCount) \(request.zoneCount == 1 ? "zone" : "zones")."
        alert.addButton(withTitle: "Cancel")
        alert.addButton(withTitle: "Delete Workspace")
        return alert.runModal() == .alertSecondButtonReturn
    }

    @discardableResult
    private func deleteWorkspaceAndRelaunch(workspaceId: UUID) -> Bool {
        guard let registryStore else { return false }
        do {
            var registry = try registryStore.loadOrEmpty()
            guard let target = registry.workspaces.first(where: { $0.id == workspaceId }) else {
                setWorkspaceManagementMessage("Workspace could not be found.")
                return false
            }
            guard registry.workspaces.count > 1 else {
                setWorkspaceManagementMessage("Cannot delete the last workspace. Create another workspace first.")
                return false
            }
            let appSupport = registryStore.registryFile.deletingLastPathComponent()
            let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport)
            let zoneCount = (try? store.tryLoad()?.zones.count) ?? 0
            let request = WorkspaceDeleteConfirmationRequest(
                workspaceId: workspaceId,
                workspaceName: target.name,
                projectCount: target.projectIds.count,
                zoneCount: zoneCount,
                deletionCopy: Self.workspaceDeleteSemanticsCopy
            )
            let confirmed = workspaceDeleteConfirmationProvider?(request) ?? confirmDeleteWorkspace(request)
            guard confirmed else {
                setWorkspaceManagementMessage("Delete canceled; workspace “\(target.name)” was preserved.")
                reloadWorkspaceSidebar()
                return false
            }

            let deletingCurrent = workspaceRuntime?.workspaceId == workspaceId || registry.lastActiveWorkspaceId == workspaceId
            workspaceRuntime?.flushAll()
            killAmbientTmuxSessionForDeletedWorkspace(workspaceId: workspaceId)
            guard registry.deleteWorkspace(id: workspaceId, now: Date()) else {
                setWorkspaceManagementMessage("Workspace could not be deleted.")
                return false
            }
            try registryStore.save(registry)
            if deletingCurrent, let nextWorkspaceId = registry.lastActiveWorkspaceId {
                try workspaceRuntime?.switchWorkspace(to: nextWorkspaceId)
            }
            if FileManager.default.fileExists(atPath: store.layout.workspaceDirectory.path) {
                try store.deleteDocument()
            }
            setWorkspaceManagementMessage("Deleted workspace “\(target.name)”. Projects and project tile data were not deleted.")
            reloadWorkspaceSidebar()
            return true
        } catch {
            fputs("Delete Workspace failed: \(error)\n", stderr)
            setWorkspaceManagementMessage("Delete workspace failed: \(error.localizedDescription)")
            return false
        }
    }

    private func killAmbientTmuxSessionForDeletedWorkspace(workspaceId: UUID) {
        guard TmuxPersistenceConfig.enabled(defaults: tmuxDefaults),
              let tmuxPath = tmuxPathResolver(tmuxDefaults) else {
            return
        }
        let sessionName = TmuxSession.ambientSessionName(workspaceId: workspaceId)
        let control = makeTmuxControl(tmuxPath: tmuxPath, reach: .localhost)
        if let error = Self.runTmuxControlOperationSync({ try await control.killSession(name: sessionName) }) {
            fputs("tmux kill-session failed for workspace=\(workspaceId.uuidString) session=\(sessionName): \(error)\n", stderr)
        }
    }

    private func workspaceDisplayName(workspaceId: UUID) -> String {
        guard let registryStore,
              let registry = try? registryStore.loadOrEmpty(),
              let entry = registry.workspaces.first(where: { $0.id == workspaceId }) else {
            return "Workspace"
        }
        return entry.name
    }

    private func showWorkspaceSwitchTransitionLabel(workspaceId: UUID) {
        canvasView?.showWorkspaceTransitionLabel("Switched to \(workspaceDisplayName(workspaceId: workspaceId))")
    }

    var qaWorkspaceSwitchTransitionLabelText: String? {
        canvasView?.qaWorkspaceTransitionLabelText
    }

    private func switchWorkspaceAndRelaunch(workspaceId: UUID) {
        do {
            // Switch in-process — no relaunch needed.
            try workspaceRuntime?.switchWorkspace(to: workspaceId)
            showWorkspaceSwitchTransitionLabel(workspaceId: workspaceId)
            reloadWorkspaceSidebar()
        } catch {
            fputs("Switch Workspace failed: \(error)\n", stderr)
        }
    }

    private func addProjectZone(projectId: UUID) {
        guard let workspaceRuntime else { return }
        do {
            // Update registry workspace membership (AppDelegate-level concern).
            if let registryStore {
                var registry = try registryStore.loadOrEmpty()
                guard registry.projects.first(where: { $0.id == projectId }) != nil else {
                    fputs("Add Project to Canvas failed: unknown project \(projectId)\n", stderr)
                    return
                }
                let wId = workspaceRuntime.workspaceId
                try registry.assignProject(projectId, to: wId, now: Date())
                try registryStore.save(registry)
            }
            // Delegate zone creation + canvas install + document save to the runtime.
            try workspaceRuntime.addZone(projectId: projectId)
            reloadWorkspaceSidebar()
            fputs("Added project zone for \(projectId)\n", stderr)
        } catch let ProjectWorkspaceOwnershipError.alreadyOwned(conflictingProjectId, ownerWorkspaceId) {
            offerSwitchToOwningWorkspace(
                projectId: conflictingProjectId,
                workspaceId: ownerWorkspaceId
            )
        } catch {
            fputs("Add Project to Canvas failed: \(error)\n", stderr)
            setWorkspaceManagementMessage("Couldn't add project: \(error.localizedDescription)")
        }
    }

    private func offerSwitchToOwningWorkspace(projectId: UUID, workspaceId: UUID) {
        guard let registryStore,
              let registry = try? registryStore.loadOrEmpty(),
              let project = registry.projects.first(where: { $0.id == projectId }),
              let workspace = registry.workspaces.first(where: { $0.id == workspaceId }) else {
            setWorkspaceManagementMessage("That project already belongs to another workspace.")
            return
        }
        let request = ProjectWorkspaceConflictRequest(
            projectId: projectId,
            projectName: project.name,
            workspaceId: workspaceId,
            workspaceName: workspace.name
        )
        let shouldSwitch: Bool
        if let provider = projectWorkspaceConflictSwitchProvider {
            shouldSwitch = provider(request)
        } else {
            let alert = NSAlert()
            alert.messageText = "“\(project.name)” is already in “\(workspace.name)”"
            alert.informativeText = "A project belongs to one workspace. You can switch to its workspace without moving or duplicating anything."
            alert.addButton(withTitle: "Switch to \(workspace.name)")
            alert.addButton(withTitle: "Cancel")
            shouldSwitch = alert.runModal() == .alertFirstButtonReturn
        }
        guard shouldSwitch else {
            setWorkspaceManagementMessage("“\(project.name)” remains in “\(workspace.name)”.")
            return
        }
        do {
            try workspaceRuntime?.switchWorkspace(to: workspaceId)
            showWorkspaceSwitchTransitionLabel(workspaceId: workspaceId)
            setWorkspaceManagementMessage("Switched to “\(workspace.name)” for “\(project.name)”.")
            reloadWorkspaceSidebar()
        } catch {
            fputs("Switch to owning workspace failed: \(error)\n", stderr)
            setWorkspaceManagementMessage("Couldn't switch to “\(workspace.name)”: \(error.localizedDescription)")
        }
    }

    private func switchProjectAndRelaunch(projectId: UUID) {
        guard let registryStore else { return }
        do {
            var registry = try registryStore.loadOrEmpty()
            let rows = ProjectPickerModel.makeRows(registry: registry)
            guard case let .selected(projectRoot) = ProjectPickerModel.select(id: projectId, from: rows) else {
                fputs("Switch Project failed: unavailable project \(projectId)\n", stderr)
                return
            }
            guard registry.selectProjectForNextLaunch(id: projectId) else {
                fputs("Switch Project failed: unknown project \(projectId)\n", stderr)
                return
            }
            workspaceRuntime?.flushAll()
            try registryStore.save(registry)
            relaunchApplication(projectRoot: projectRoot)
        } catch {
            fputs("Switch Project failed: \(error)\n", stderr)
        }
    }

    private func relaunchApplication(projectRoot: URL) {
        let bundleURL = Bundle.main.bundleURL
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.createsNewApplicationInstance = true
        configuration.environment = ProcessInfo.processInfo.environment.merging([
            "CONTINUUM_PROJECT_ROOT": projectRoot.path
        ]) { _, selected in selected }
        NSWorkspace.shared.openApplication(
            at: bundleURL,
            configuration: configuration
        ) { _, error in
            if let error {
                fputs("Switch Project relaunch failed: \(error)\n", stderr)
                return
            }
            Task { @MainActor in NSApp.terminate(nil) }
        }
    }

    @discardableResult
    private func spawnNoteFromPalette() -> Bool {
        // M1.11: this used to guard only on `tileSpawner`, which fell back to the
        // DEPARTED boot project's spawner — so in a workspace with no projects the
        // note landed in another project's canvas and nothing appeared.
        //
        // The signal is "no spawner", not "no scope": a boot-only app has a live
        // boot spawner and no `WorkspaceRuntime` at all, and must keep working.
        guard let spawner = spawnerForFilesystemCreation() else {
            guard offerCreationScope(then: { [weak self] in self?.spawnNoteFromPalette() }) else {
                presentSpawnRefusal("Add a project to this workspace before creating a note.")
                return false
            }
            return false
        }
        switch spawner.spawnNote(title: "New Note") {
        case let .spawned(noteId, tileId):
            if let view = canvasView?.tileView(for: tileId) as? NoteTileNSView {
                noteViews[noteId] = view
            }
            focusSpawnedTile(tileId)
            return true
        case let .failure(error):
            fputs("TileSpawner.spawnNote failed: \(error)\n", stderr)
            return false
        }
    }

    private func openFileFromPalette() {
        // M1.11: refuse audibly, and offer a way out, instead of returning into
        // silence when there is no active controller.
        guard let project = activeProject else {
            guard offerCreationScope(then: { [weak self] in self?.openFileFromPalette() }) else {
                presentSpawnRefusal("Add a project to this workspace before opening a file.")
                return
            }
            return
        }
        let projectRoot = URL(fileURLWithPath: project.rootPath, isDirectory: true)
        let panel = NSOpenPanel()
        panel.title = "Open File"
        panel.directoryURL = projectRoot
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = false

        guard panel.runModal() == .OK,
              let selectedURL = panel.url else { return }
        guard LaunchPaletteModel.isFileURL(selectedURL, insideProjectRoot: projectRoot) else {
            presentFileOpenFailure("\(selectedURL.lastPathComponent) is outside this project.")
            return
        }

        openProjectFile(path: selectedURL.standardizedFileURL.path)
    }

    /// The one app-level file-open action. Command Center, file-tree activation,
    /// canvas file drop, and an agent's local-file link all land here, so the active
    /// project and zone are resolved now instead of when some earlier spawner was
    /// built. "Open in Preferred Editor" stays a separate external action.
    @discardableResult
    func openProjectFile(
        path: String,
        placement: WorkspaceRuntime.FileOpenPlacement = .automatic
    ) -> WorkspaceRuntime.FileOpenOutcome {
        guard let workspaceRuntime else {
            let outcome = WorkspaceRuntime.FileOpenOutcome.failure("No project is open yet.")
            presentFileOpenFailure("No project is open yet.")
            return outcome
        }
        let outcome = workspaceRuntime.openProjectFile(path: path, placement: placement)
        switch outcome {
        case let .opened(tileId), let .revealed(tileId):
            focusSpawnedTile(tileId)
        case let .failure(message):
            presentFileOpenFailure(message)
        }
        return outcome
    }

    /// A failed open has to say so. Beeping (or writing to stderr) left the user
    /// looking at an unchanged canvas with no idea why.
    private func presentFileOpenFailure(_ message: String) {
        fputs("Open file failed: \(message)\n", stderr)
        let alert = NSAlert()
        alert.messageText = "Couldn't open that file"
        alert.informativeText = message
        alert.alertStyle = .warning
        alert.addButton(withTitle: "OK")
        alert.runModal()
    }

    /// Resolves a local-file link an agent authored and opens it beside that agent.
    ///
    /// The agent's CURRENT `cwd` is the only base a relative path resolves against:
    /// not the process working directory, and not "the active project" — an agent
    /// running in an isolated worktree means a file it names lives in that checkout.
    /// Containment is enforced against the same checkout, so authored content can
    /// request resolution but cannot reach outside where its agent is working.
    @discardableResult
    func openAgentLocalFile(_ destination: String, agentID: AgentID, sourceTileId: UUID) -> Bool {
        guard let record = agentSupervisor.records[agentID] else { return false }
        let result = agentLocalFileOpener().open(
            destination: destination,
            checkoutRoot: URL(fileURLWithPath: record.cwd, isDirectory: true),
            sourceTileId: sourceTileId,
            sourceAgentId: agentID,
            projectId: record.projectId
        )
        if case let .refused(reason) = result {
            // A link that resolves to nothing is content, not an error worth a
            // modal: the agent may be naming a file it has not written yet.
            fputs("Agent local-file link did not resolve inside \(record.cwd): \(reason)\n", stderr)
            return false
        }
        return true
    }

    /// Opens an authorized transcript URL using the destination the click made
    /// explicit. Array-owned web opens are anchored to the authoring tile and
    /// its zone; Command-click/context-menu opens never create canvas state.
    @discardableResult
    func openAgentWebLink(
        _ url: URL,
        target: AgentLinkOpenTarget,
        sourceTileId: UUID
    ) -> Bool {
        switch target {
        case .systemBrowser:
            return NSWorkspace.shared.open(url)
        case .array:
            guard ["http", "https"].contains(url.scheme?.lowercased() ?? ""),
                  let spawner = tileSpawner,
                  let source = canvasView?.navigationTileSnapshot(for: sourceTileId)
            else { return false }
            switch spawner.spawnBrowser(
                url: url.absoluteString,
                beside: sourceTileId,
                targetZoneId: source.zoneId
            ) {
            case let .spawned(runtime):
                browserRuntimes.append(runtime)
                workspaceRuntime?.registerLiveBrowser(tileId: runtime.tileId)
                workspaceRuntime?.enforceBrowserRuntimeBudget()
                focusSpawnedTile(runtime.tileId)
                return true
            case .invalidURL, .failure:
                return false
            }
        }
    }

    func agentLocalFileOpener() -> AgentLocalFileOpener {
        AgentLocalFileOpener(
            openDocument: { [weak self] request in
                guard let self, let runtime = workspaceRuntime else { return .failure("No project is open yet.") }
                let outcome = runtime.openDocument(request)
                switch outcome {
                case let .opened(tileId), let .revealed(tileId): focusSpawnedTile(tileId)
                case let .failure(message): presentFileOpenFailure(message)
                }
                return outcome
            },
            fileTile: { [weak self] tileId in
                self?.canvasView?.tileView(for: tileId) as? FileTileNSView
            }
        )
    }

    /// Points a spawner's file-tree and drop routes at the shared open action.
    private func configureFileOpenRoute(on spawner: TileSpawner) {
        spawner.fileOpenHandler = { [weak self] path, worldPoint in
            guard let self else { return }
            let placement: WorkspaceRuntime.FileOpenPlacement = worldPoint.map { .at($0) } ?? .automatic
            openProjectFile(path: path, placement: placement)
        }
        spawner.documentLocationProvider = { [weak self] url in
            self?.resolveDocumentLocation(url) ?? DocumentLocation(path: url.standardizedFileURL.resolvingSymlinksInPath().path, scope: .standalone)
        }
        spawner.noteConvertedHandler = { [weak self] noteId, _ in
            self?.noteViews.removeValue(forKey: noteId)
        }
    }

    /// All filesystem-backed creation reads this one resolver at invocation.
    /// Merely focusing a tile never mutates the workspace recent scope.
    private func resolvedCreationScope(explicit: CreationScope? = nil) -> CreationScope? {
        let registry = (try? registryStore?.loadOrEmpty()) ?? Registry.empty()
        func root(for projectId: UUID) -> String? {
            registry.projects.first(where: { $0.id == projectId && !$0.missing })?.rootPath
        }

        // The armed zone, in order of authority. T1 (`.plans/47`).
        //
        // The middle rung is the fix. `activeProjectZonePlacement` requires an
        // INSTALLED LAYER, and `setActiveProjectZone` silently no-ops to nil
        // without one — so every moment the armed zone was not a live layer, this
        // fell through to `activeZone`, the BOOT zone, and creation reverted to the
        // first project in the workspace. That fallback was a magnet: at boot the
        // scene is flat and no layer exists at all, and a zone below the live
        // hydration tier has none either. `document.lastActiveZoneId` is the
        // authoritative answer to "which zone is armed"; whether that zone happens
        // to be hydrated is a rendering detail and must not change which project a
        // new tile belongs to. Placement still needs the layer, and
        // `installProjectTile` already falls back to the flat model without one.
        let armedFromDocument: ZonePlacement? = workspaceRuntime.flatMap { runtime in
            runtime.document.lastActiveZoneId.flatMap { armed in
                runtime.document.zones.first(where: { $0.zoneId == armed && $0.projectId != nil })
            }
        }
        let zonePlacement = canvasView?.activeProjectZonePlacement
            ?? armedFromDocument
            ?? canvasView?.activeZone.flatMap { $0.projectId == nil ? nil : $0 }
        let zoneScope: CreationScope? = zonePlacement.flatMap { zone in
            guard let projectId = zone.projectId, let projectRoot = root(for: projectId) else { return nil }
            return CreationScope(projectId: projectId, projectRoot: projectRoot, homeRelativePath: zone.homeRelativePath, source: .zone, zoneId: zone.zoneId)
        }
        let focusedScope: CreationScope? = {
            guard zoneScope == nil,
                  let tileId = focusedTileIdForPaletteContext(),
                  let agentId = agentSupervisor.agent(forTile: tileId),
                  let record = agentSupervisor.records[agentId],
                  let projectId = record.projectId else { return nil }
            return CreationScope(
                projectId: projectId,
                projectRoot: record.projectRoot ?? root(for: projectId) ?? record.checkoutRoot,
                homeRelativePath: record.homeRelativePath,
                source: .focusedAgent
            )
        }()
        let recentScope: CreationScope? = {
            guard let scope = workspaceRuntime?.document.lastExplicitCreationScope,
                  let projectId = scope.projectId,
                  let projectRoot = root(for: projectId) else { return nil }
            return CreationScope(projectId: projectId, projectRoot: projectRoot, homeRelativePath: scope.homeRelativePath, source: .recentExplicit)
        }()
        return CreationScopeResolver.resolve(explicit: explicit ?? explicitCreationScopeOverride, zone: zoneScope, focusedAgent: focusedScope, recentExplicit: recentScope)
    }

    /// Offer the user a project to create into, if there is one to offer.
    /// M1.11 (`.plans/46`).
    ///
    /// Returns false when there is nothing to ask about — no registry, or no
    /// registered project — so the caller refuses out loud instead of popping an
    /// empty picker. When it returns true the picker (or its QA seam) owns the
    /// retry.
    @discardableResult
    private func offerCreationScope(then action: @escaping () -> Void) -> Bool {
        let projects = ((try? registryStore?.loadOrEmpty()) ?? nil)?.projects.filter { !$0.missing } ?? []
        guard !projects.isEmpty else { return false }
        requestCreationScope(then: action)
        return true
    }

    /// Ask for a creation scope. M1.11: one route, so a `--*-check` can observe the
    /// ask without a `ChoicePopover` appearing (AGENTS hazard 6).
    private func requestCreationScope(then action: @escaping () -> Void) {
        if let presenter = creationScopePickerPresenterForQA { presenter(action); return }
        presentCreationScopePicker(then: action)
    }

    private func presentCreationScopePicker(then action: @escaping () -> Void) {
        guard let canvasView, let registryStore else { return }
        let registry = (try? registryStore.loadOrEmpty()) ?? Registry.empty()
        let recentSelection: ProjectHomeSelection? = workspaceRuntime?.document.lastExplicitCreationScope.flatMap { scope in
            guard let projectId = scope.projectId,
                  let project = registry.projects.first(where: { $0.id == projectId }) else { return nil }
            return ProjectHomeSelection(project: project, homeRelativePath: scope.homeRelativePath)
        }
        let picker = ProjectHomePickerController()
        projectHomePicker?.dismiss(cancelled: false)
        projectHomePicker = picker
        picker.present(
            projects: registry.projects,
            recents: recentSelection.map { [$0] } ?? [],
            selected: recentSelection,
            anchor: CGPoint(x: canvasView.bounds.midX, y: canvasView.bounds.midY),
            relativeTo: canvasView,
            addProject: { [weak self] in self?.registerProjectUsingOpenPanel() },
            onInteractionOwnershipChanged: { [weak canvasView] owned in canvasView?.setZoneScopePickerInteractionOwned(owned) },
            onConfirm: { [weak self] selection in
                guard let self else { return }
                let scope = CreationScope(
                    projectId: selection.project.id,
                    projectRoot: selection.project.rootPath,
                    homeRelativePath: selection.homeRelativePath,
                    source: .explicit
                )
                persistLastExplicitCreationScope(ZoneScope(projectId: selection.project.id, homeRelativePath: selection.homeRelativePath))
                // M1.11 (`.plans/46`): a project chosen in a workspace where it has
                // no zone was never acquired, so `spawnerForFilesystemCreation()`
                // finds no controller for it and falls through to the boot spawner
                // — spawning into a DEPARTED project. Give it somewhere to land
                // first. This one insertion is what repairs terminal, managed agent
                // and file tree in an empty workspace, not just note and browser.
                if workspaceRuntime?.controller(for: selection.project.id) == nil {
                    addProjectZone(projectId: selection.project.id)
                }
                // T3 (`.plans/47`): the pick has to ARM, not just apply once.
                //
                // `explicitCreationScopeOverride` is `defer`-cleared two lines
                // below, and the durable copy written by
                // `persistLastExplicitCreationScope` enters the resolver as
                // `.recentExplicit` — which ranks BELOW `.zone`. So a stale armed
                // zone overruled the user's correction on the very next spawn, and
                // every spawn after that. Arming the chosen project's zone makes
                // `.zone` and the explicit choice agree, which removes the conflict
                // instead of re-ranking it: `CreationScopeResolver`'s precedence is
                // deliberately locked and stays untouched.
                //
                // The zone's own Home is left alone. A one-off pick of a subfolder
                // applies to this spawn; a zone's default Home changes through
                // "Change Home…", matching `homeRelativePath`'s documented rule
                // that changing it never retargets what already exists.
                if let zoneId = workspaceRuntime?.document.zones
                    .first(where: { $0.projectId == selection.project.id })?.zoneId {
                    workspaceRuntime?.setActiveZone(zoneId, reason: .explicit)
                }
                explicitCreationScopeOverride = scope
                defer { explicitCreationScopeOverride = nil }
                projectHomePicker = nil
                action()
            },
            onCancel: { [weak self] in self?.projectHomePicker = nil }
        )
    }

    private func spawnerForFilesystemCreation() -> TileSpawner? {
        if let projectId = resolvedCreationScope()?.projectId {
            // The resolved scope names a project, so ONLY that project's spawner
            // may serve it. The fallback below used to run whenever the scoped
            // controller was missing, which is exactly the case where it is
            // wrong: the creation scope resolves from the app registry and is
            // happily correct for an unacquired project, so a tile created in a
            // second zone was framed and stamped for ITS project while being
            // persisted into the active project's canvas and its managed session
            // written under the active project's `.array/`.
            //
            // Refusing here surfaces the creation-scope picker instead, which is
            // the same contract `spawnerAndScope(forProject:)` already keeps.
            return workspaceRuntime?.controller(for: projectId)?.tileSpawner
        }
        return tileSpawner
    }

    /// The spawner and creation scope for a SUPPLIED project, rather than for
    /// whatever `resolvedCreationScope()` says is current. M1.6 (`.plans/46`).
    ///
    /// `spawnerForFilesystemCreation()` above keys on the resolved scope, which is
    /// exactly what a cross-project reveal must not do. Returns nil when the
    /// project has no LIVE zone in this workspace: that project has no controller,
    /// so there is no store to persist into and no layer to install into, and the
    /// caller falls back rather than pretending.
    ///
    /// The scope matters as much as the spawner. `spawnManagedAgent` frames and
    /// installs against `creationScopeProvider()?.zoneId`, so handing it the right
    /// store while leaving the active zone in place would install the tile into one
    /// project's layer and persist it into another's — a mismatch worse than the
    /// one being fixed.
    private func spawnerAndScope(forProject projectId: UUID) -> (TileSpawner, CreationScope)? {
        guard let spawner = workspaceRuntime?.controller(for: projectId)?.tileSpawner,
              let zone = workspaceRuntime?.document.zones.first(where: { $0.projectId == projectId }),
              let root = ((try? registryStore?.loadOrEmpty()) ?? Registry.empty())
                  .projects.first(where: { $0.id == projectId && !$0.missing })?.rootPath
        else { return nil }
        return (spawner, CreationScope(
            projectId: projectId,
            projectRoot: root,
            homeRelativePath: zone.homeRelativePath,
            source: .zone,
            zoneId: zone.zoneId
        ))
    }

    /// Every boot and post-workspace-switch spawner receives identical policy
    /// providers. This prevents creation semantics from changing after a switch.
    /// The app's focus broker, for an offline check that must construct a
    /// `WorkspaceRuntime` the way production does.
    var qaFocusBroker: FocusBroker { focusBroker }

    /// QA (M1.11): the palette surface, so a leg can assert it actually opened in a
    /// workspace with no active controller.
    var qaProfilePalette: LaunchProfilePalette? { profilePalette }
    /// QA (M1.11): `openProfilePalette` is private; a leg drives the real one.
    func qaOpenProfilePalette() { openProfilePalette() }
    /// QA (M1.11): the spoken refusal, so "it refused audibly" is assertable.
    var qaWorkspaceManagementMessage: String? { workspaceManagementMessage }
    /// QA (M1.11): reach the broken state through the real "+" route.
    func qaCreateWorkspaceFromChrome() { createWorkspaceFromChrome() }
    /// QA (M1.11): drive a palette action the way the palette does.
    @discardableResult
    func qaPerformPaletteAction(_ action: LaunchPaletteAction) -> Bool { performPaletteAction(action) }
    /// QA (M1.11): whether a spawner is reachable at all.
    var qaHasTileSpawner: Bool { tileSpawner != nil }
    /// QA (M1.11): live browser runtimes, to prove none was built and dropped.
    var qaBrowserRuntimeCount: Int { browserRuntimes.count }

    /// QA (T1-T3, `.plans/47`): the resolver every filesystem-backed spawn reads.
    /// A leg asserts the project AND the zone, because the pair disagreeing is
    /// precisely the bug: the scope named one zone while placement used another.
    var qaResolvedCreationScope: (projectId: UUID, zoneId: UUID?, source: CreationScopeSource)? {
        guard let scope = resolvedCreationScope() else { return nil }
        return (scope.projectId, scope.zoneId, scope.source)
    }

    /// QA (T2): drive the click-arming route the canvas fires, without synthesizing
    /// an NSEvent (`postToPid` does not reach a check's canvas).
    func qaActivateZoneByClick(_ zoneId: UUID) { canvasView?.onZoneActivated?(zoneId) }

    /// QA (WS9): the project whose spawner a filesystem-backed creation would
    /// actually use. The creation SCOPE and the SPAWNER are resolved separately
    /// -- the scope from the app registry, the spawner from the live controller
    /// -- and the bug this witnesses is precisely the two disagreeing: the scope
    /// named the armed zone's project while the spawner silently fell back to
    /// the active one, so the tile was stamped for one project and persisted
    /// into another. nil means creation refuses, which is the correct answer
    /// when the scope's project cannot be acquired.
    var qaCreationSpawnerProjectId: UUID? { spawnerForFilesystemCreation()?.qaProjectId }

    /// QA (T2): drive the focus-arming route with the reason production passes.
    func qaAcceptTileFocus(_ tileId: UUID, reason: FocusRequest) {
        focusBroker.appAcceptedTileFocusWithReason?(tileId, reason)
    }
    /// QA (M1.11): `openProfilePalette` needs a host window. Borderless and never
    /// ordered front, so a check cannot take the screen.
    func qaAttachWindowForOfflineCheck(_ window: NSWindow) { self.window = window }

    /// QA seam for `.addProject`, mirroring `workspaceCreatePromptProvider`. A
    /// `--*-check` may never raise an `NSOpenPanel` (AGENTS hazard 6).
    var addProjectSelectionProvider: (() -> ProjectEntry?)?

    /// QA seam for the creation-scope popover, same reason.
    var creationScopePickerPresenterForQA: ((@escaping () -> Void) -> Void)?

    /// How many managed agents the supervisor holds records for. Used by
    /// `--zone-tile-hydration-check` (M1.2b) to prove that hydrating a managed-agent
    /// tile with no bound agent does not MINT one.
    var qaManagedAgentCount: Int { agentSupervisor.records.count }

    /// M1.4: the detach-sweep leg needs a real agent record bound to a tile, and
    /// then needs to read the supervisor's observer counts back.
    var qaAgentSupervisor: AgentSupervisor { agentSupervisor }

    /// Minimal offline wiring so a check living in another file can drive the
    /// REAL `configureWorkspaceRuntimeHooks()` instead of substituting its own
    /// closures. `AppDelegate`'s scene properties are `private`, and file-private
    /// access is why every other delegate-driven check had to be pasted into this
    /// 20k-line file; this seam is the smaller price. Used by
    /// `--zone-tile-hydration-check` (M1.1, `.plans/46`).
    /// Minimal stored-property wiring for a leg that drives
    /// `mountWorkspaceSceneAtBoot` itself. M1.10 (`.plans/46`).
    ///
    /// Deliberately does NOT call `configureWorkspaceRuntimeHooks()` — the mount
    /// does that, and a leg that pre-wired it would be testing its own setup
    /// rather than the production sequence.
    func qaPrepareForBootMountCheck(
        canvas: CanvasNSView,
        browserEngine: BrowserEngineContext,
        runtime: WorkspaceRuntime,
        registryStore: RegistryStore
    ) {
        self.canvasView = canvas
        self.browserEngine = browserEngine
        self.workspaceRuntime = runtime
        self.registryStore = registryStore
    }

    func qaPrepareForOfflineSceneCheck(
        canvas: CanvasNSView,
        browserEngine: BrowserEngineContext,
        runtime: WorkspaceRuntime,
        registryStore: RegistryStore? = nil
    ) {
        self.canvasView = canvas
        self.browserEngine = browserEngine
        self.workspaceRuntime = runtime
        // M1.6: creation-scope resolution reads project roots out of the registry,
        // so a leg that drives a scoped spawn has to supply the same store the
        // runtime was built with. Optional, because the earlier scene legs do not
        // need it and passing nil keeps their behaviour identical.
        if let registryStore { self.registryStore = registryStore }
        configureWorkspaceRuntimeHooks()
    }

    /// Everything that turns a freshly built canvas, runtime and spawner into the
    /// live scene at launch. Extracted from `applicationDidFinishLaunching`
    /// (M1.10, `.plans/46`).
    ///
    /// **Why it is a method and not inline.** The scene work used to be buried in
    /// the middle of a 400-line launch handler, so no self-check could reach it —
    /// and every scene witness in M1 therefore drove
    /// `WorkspaceRuntime.install(into:appRegistry:)` instead, which has NEVER had
    /// a production caller. Six green legs proved nothing about the shipping app.
    /// This is the seam they should have driven; the precedent is
    /// `configureWorkspaceRuntimeHooks()`, extracted for exactly this reason.
    ///
    /// Order is load-bearing and matches launch exactly; do not reshuffle.
    func mountWorkspaceSceneAtBoot(
        canvasView: CanvasNSView,
        spawner: TileSpawner,
        projectStore: any ProjectStoring,
        canvasState: CanvasState,
        installsGlobalEventMonitors: Bool = true
    ) throws {
        workspaceRuntime?.lifecycleObserver?(.processLaunched)
        var persistedWorkspaceRegistry: Registry?
        if let runtime = workspaceRuntime, let registryStore {
            let loaded = try registryStore.loadOrEmpty()
            if loaded.workspaces.contains(where: { $0.id == runtime.workspaceId }) {
                persistedWorkspaceRegistry = loaded
            }
        }
        if let workspaceId = self.workspaceRuntime?.workspaceId {
            canvasView.activateUndoWorkspace(workspaceId)
        }

        self.bootTileSpawner = spawner
        // T2 (`.plans/47`): clicking a zone arms it for creation. Wired HERE, not
        // in the surrounding `applicationDidFinishLaunching` block with the other
        // canvas callbacks, so `--zone-arming-check` drives the same assignment
        // production does. A callback a witness cannot reach is the M1.10 trap:
        // seven tickets passed against code the app never executed.
        canvasView.onZoneActivated = { [weak self] zoneId in
            self?.workspaceRuntime?.setActiveZone(zoneId, reason: .click)
        }
        // WS2 F2: wired HERE for the same reason `onZoneActivated` is. This is the
        // ONLY production route from a committed canvas gesture to durable
        // storage, and while it lived in the middle of
        // `applicationDidFinishLaunching` no self-check could reach it — so the
        // frame space it persists went unwitnessed in both directions, and an
        // ambient tile drifted by its zone origin on every layout commit.
        canvasView.onLayoutCommitted = { [weak self] transaction in
            self?.persistLayoutTransaction(transaction) ?? false
        }
        configureCreationAndRuntimeRoutes(on: spawner)
        configureWorkspaceRuntimeHooks()
        installSettingsChangeObserver()
        configureActiveControllerRuntimeCallbacks()
        // M1.10 (`.plans/46`): THE turn-on. Until this line, nothing in production
        // ever handed the runtime a canvas, so every canvas call in
        // `switchWorkspace` optional-chained through nil — the document, the
        // registry and the toolbar header changed while the previous workspace's
        // tiles stayed on screen, and the whole M1 hydration/persistence/detach
        // programme was unreachable code.
        //
        // Synthetic compatibility state still receives its legacy boot zone. A
        // persisted workspace does not: its document is the complete scene, and a
        // missing zone may be the result of an intentional delete.
        if let runtime = workspaceRuntime {
            runtime.adoptCanvas(canvasView)
            if persistedWorkspaceRegistry == nil, let controller = runtime.activeController {
                runtime.ensureZoneForActiveProject(controller: controller)
            }
        }
        if persistedWorkspaceRegistry == nil {
            workspaceRuntime?.activeController?.attachUI(
                canvasView: canvasView, tileSpawner: spawner, focusBroker: focusBroker)
        }
        installAcceptedTileFocusHook()

        // Global NSEvent monitors: process-wide, and meaningless without a key
        // window. A headless leg passes false so it can drive this method without
        // installing them (AGENTS hazard 6).
        if installsGlobalEventMonitors {
            installHotkeyMonitor()
            installTileFocusMonitor()
            installCanvasGestureMonitors()
        }

        // P2A.7: adopt the agents a previous launch persisted BEFORE the tile
        // walk below. `installInitialManagedAgentTile` → `wireManagedAgentTile`
        // re-finds an agent by its `tileId`, so without this a restored tile
        // spawns a brand-new agent over the top of a record that survived, and
        // the old one's identity, model and role are lost. No provider process is
        // started here — see `AgentSupervisor.restore`.
        let agentRestore = agentSupervisor.restore()
        if !agentRestore.restored.isEmpty || !agentRestore.stale.isEmpty {
            fputs("AgentSupervisor: restored \(agentRestore.restored.count) agent(s) idle from the previous launch, skipped \(agentRestore.stale.count) whose project root is gone\n", stderr)
        }

        // Persisted workspaces use one installer on both cold launch and switching.
        // The old launch-only flat scene loaded just the remembered project's
        // canvas, so a multi-project workspace drew zone chrome with no tiles until
        // the user switched away and back. It also kept project-world frames in a
        // different model than the switch path's zone-local frames.
        if let runtime = workspaceRuntime, let appRegistry = persistedWorkspaceRegistry {
            canvasView.retireFlatCompatibilityScene()
            try runtime.install(into: canvasView, appRegistry: appRegistry)
            runtime.lifecycleObserver?(.firstHydrationPhase)
            runtime.lifecycleSnapshotObserver?(.firstHydrationPhase, canvasView)
            configureActiveControllerRuntimeCallbacks()
            runtime.refreshDocumentRelationships()
            runtime.lifecycleObserver?(.bootMounted)
            if runtime.lifecycleSnapshotObserver != nil { canvasView.layoutSubtreeIfNeeded() }
            runtime.lifecycleObserver?(.settled)
            runtime.lifecycleSnapshotObserver?(.settled, canvasView)
            return
        }

        // Walk every tile in the canvas, spawn a runtime for each terminal
        // tile (or install a Restart placeholder if the profile fails to
        // resolve), and install descriptor placeholders for non-terminal
        // tiles. The spawner persists each session descriptor; saveCanvas
        // happens once at the end.
        for tile in canvasState.tiles {
            switch tile.kind {
            case .terminal:
                installInitialTerminalTile(tile, in: canvasView, via: spawner)
            case .browser:
                installInitialBrowserTile(tile, in: canvasView, via: spawner)
            case .browserInspector:
                installInitialBrowserInspectorTile(tile, in: canvasView, via: spawner)
            case .note:
                installInitialNoteTile(tile, in: canvasView, via: spawner)
            case .file:
                installInitialFileTile(tile, in: canvasView, via: spawner)
            case .fileTree:
                installInitialFileTreeTile(tile, in: canvasView, via: spawner)
            case .ticketQueue:
                installInitialTicketQueueTile(tile, in: canvasView)
            case .conductorQueue:
                installInitialConductorQueueTile(tile, in: canvasView)
            case .diffReview:
                installInitialDiffReviewTile(tile, in: canvasView)
            case .runArtifacts:
                installInitialRunArtifactsTile(tile, in: canvasView, via: spawner)
            case .managedAgent:
                installInitialManagedAgentTile(tile, in: canvasView)
            }
        }

        // T10 (`.plans/48`): the membership repair, AFTER the install walk.
        //
        // Ordering is load-bearing. `canvasState` is a value-type snapshot taken
        // before this method ran, and the walk above installs from THAT — so a
        // repair applied earlier was immediately overwritten by each install
        // re-stamping membership from the stale copy. Running it here means the
        // live `canvasView.canvasState` carries the repair into the `saveCanvas`
        // on the next line, so the file and this session agree.
        if let runtime = workspaceRuntime, let controller = runtime.activeController {
            runtime.repairBootMembership(controller: controller, canvasView: canvasView)
        }
        // `.plans/45` §5a/§5c, second half: connectors were invisible on every cold
        // launch. `documentAgentTileIdsProvider` is assigned inside
        // `configureWorkspaceRuntimeHooks()` at the TOP of this method, and its
        // `didSet` refresh therefore runs before `agentSupervisor.restore()` and
        // before the install walk — against an empty tile table and no records. The
        // other three call sites are a file open and two workspace switches, so
        // nothing refreshed after boot finished building the scene. Both halves of
        // the relationship bug had to be fixed: painting them in the right place
        // does nothing if they are never built.
        workspaceRuntime?.refreshDocumentRelationships()

        try projectStore.saveCanvas(canvasView.canvasState)
    }

    private func configureActiveControllerRuntimeCallbacks() {
        workspaceRuntime?.activeController?.onBrowserRuntimeHydrated = { [weak self] runtime in
            self?.wireContentProcessTerminationHandler(runtime)
            self?.workspaceRuntime?.registerLiveBrowser(tileId: runtime.tileId)
            self?.workspaceRuntime?.enforceBrowserRuntimeBudget()
        }
        workspaceRuntime?.activeController?.onAgentStatusWritten = { [weak self] _, _ in
            guard let self else { return }
            self.refreshAgentSurfaces()
            self.scheduleCompanionSyncPublish(
                reason: .statusChanged, diagnosticsReason: "agent-status", debounce: 1.0)
        }
        workspaceRuntime?.activeController?.onCanvasStatePersisted = { [weak self] in
            self?.scheduleCompanionSyncPublish(
                reason: .canvasChanged, diagnosticsReason: "canvas-changed", debounce: 1.0)
        }
        workspaceRuntime?.activeController?.onObservedAgentStatusesChanged = { [weak self] statuses in
            DispatchQueue.main.async {
                guard let self else { return }
                self.applyObserverStatuses(statuses)
            }
        }
    }

    /// Every app-owned hook the `WorkspaceRuntime` needs, in one place.
    ///
    /// Extracted from `applicationDidFinishLaunching` (M1.1, `.plans/46`) so a
    /// self-check can drive the REAL wiring instead of substituting its own
    /// closures. That substitution is the failure mode `--agent-local-file-link-check`
    /// shipped with: it wired its own `onOpenLocalFile` and therefore never
    /// executed the production path it claimed to cover.
    ///
    /// Production calls this once, after `bootTileSpawner` is configured.
    func configureWorkspaceRuntimeHooks() {
        workspaceRuntime?.onSpawnerCreated = { [weak self] arriving in
            self?.configureCreationAndRuntimeRoutes(on: arriving)
        }
        workspaceRuntime?.hydrateZoneLayerTiles = { [weak self] canvas, layers, phase in
            self?.hydrateZoneLayerTiles(canvas, layers, phase: phase)
        }
        workspaceRuntime?.documentAgentTileIdsProvider = { [weak self] in
            guard let self else { return [:] }
            return Dictionary(uniqueKeysWithValues: agentSupervisor.records.values.compactMap { record in
                record.tileId.map { (record.id, $0) }
            })
        }
    }

    // MARK: - Zone tile hydration (M1.2, `.plans/46`)

    /// Replace a ZoneLayer's `DescriptorTileNSView` placeholders with real tiles.
    ///
    /// `WorkspaceRuntime` builds every layer's views as placeholders, and real views
    /// were only ever built by the boot walk — which runs once. So from the first
    /// in-process workspace switch onward every tile was a title label: no
    /// transcript, no composer, nothing to click. Witnessed by
    /// `--zone-tile-hydration-check`.
    ///
    /// **Per layer, per project.** A note's body, a diff's repository and a
    /// conductor queue's root all belong to the layer's OWN project, not the active
    /// one, so everything here resolves through
    /// `workspaceRuntime.controller(for: projectId)` rather than through
    /// `activeProject` or the boot spawner. Getting that wrong would render one
    /// project's notes inside another's tiles.
    func hydrateZoneLayerTiles(
        _ canvas: CanvasNSView,
        _ layers: [CanvasNSView.ZoneLayer],
        phase: WorkspaceRuntime.TileHydrationPhase
    ) {
        for layer in layers {
            // Ambient (project-less) zones keep their placeholders for now: their
            // tiles live in the workspace document's own register rather than in a
            // project store, so there is no controller to resolve a note body or a
            // repository root from. Tracked as M1.2's known gap.
            guard let projectId = layer.placement.projectId,
                  let controller = workspaceRuntime?.controller(for: projectId) else { continue }

            switch phase {
            case .beforeInstall:
                for tile in layer.tiles {
                    guard layer.tileViews[tile.id] is DescriptorTileNSView || layer.tileViews[tile.id] == nil,
                          let view = makeHydratedTileView(tile, controller: controller) else { continue }
                    layer.tileViews[tile.id] = view
                }
            case .afterInstall:
                hydrateRuntimeBackedTiles(in: layer, controller: controller, canvas: canvas)
            }
        }
    }

    /// A real view for every tile kind that can be built from the persisted `Tile`
    /// alone. Returns nil for terminal, browser, browser-inspector and file tree —
    /// those need a runtime and are Phase B's job.
    ///
    /// Deliberately NOT shared with the `installInitial*` boot walk, and the reason
    /// is behavioural rather than convenience: boot owns a legacy migration that
    /// hydration must never repeat. `TileSpawner.installNoteTile` mints a `noteId`
    /// for a pre-metadata tile and writes the canvas as a side effect; re-running
    /// that on every workspace switch would keep rewriting project files from a
    /// path whose job is to render, not to persist. A hydrated tile has been
    /// through boot already and always carries its metadata.
    private func makeHydratedTileView(
        _ tile: Tile,
        controller: ZoneRuntimeController
    ) -> TileNSView? {
        switch tile.kind {
        case .terminal, .browser, .browserInspector, .fileTree:
            return nil  // Phase B: needs a runtime.

        case .note:
            // No noteId means this tile predates note metadata. Leave the
            // placeholder rather than minting one here — see the note above.
            guard let noteId = tile.metadata.noteId else { return nil }
            let body = controller.projectStore.tryLoadNoteBody(id: noteId) ?? ""
            let view = NoteTileNSView(tile: tile, noteId: noteId, initialBody: body)
            view.onTextChange = { [weak controller] in controller?.scheduleNoteSave() }
            view.onSaveAsMarkdownRequested = { [weak controller] url in
                // nil until M1.3b gives every live controller a spawner; the active
                // project — the only one whose note menu is reachable today — has one.
                controller?.tileSpawner?.saveNoteAsMarkdown(
                    noteId: noteId, tileId: tile.id, destination: url)
            }
            noteViews[noteId] = view
            return view

        case .file:
            return FileTileNSView(tile: tile)

        case .runArtifacts:
            return RunArtifactsTileNSView(tile: tile)

        case .ticketQueue:
            let view = TicketQueueTileNSView(tile: tile, dispatchHandler: { [weak self] row in
                self?.dispatchAgent(for: row)
            }, fanOutHandler: { [weak self] rows in
                self?.fanOutAgents(for: rows, from: tile.id)
            })
            ticketQueueViews[tile.id] = view
            installFanOutCompletionRouting()
            for itemId in agentSupervisor.completedFanOutItems { view.markItemDone(itemId) }
            return view

        case .conductorQueue:
            return ConductorQueueTileNSView(tile: tile, projectRoot: controller.projectRoot)

        case .diffReview:
            let view = DiffReviewTileNSView(
                tile: tile,
                repositoryURL: controller.projectRoot,
                sendCommentsToAgent: { [weak self] in
                    self?.sendReviewCommentsFromMenu(reviewTileId: tile.id)
                })
            view.onSourceChanged = { [weak canvasView] updated in canvasView?.updateTile(updated) }
            return view

        case .managedAgent:
            let view = ManagedAgentTileNSView(tile: tile)
            // M1.2b: wire ONLY an agent that already exists. `wireManagedAgentTile`
            // spawns a brand-new agent when `supervisor.agent(forTile:)` is nil, and
            // resolves its scope through `tileSpawner.managedAgentCreationScope`,
            // which is empty on a spawner built for an arriving workspace. Hydrating
            // an unbound tile would therefore mint an agent in the wrong project on
            // every switch — hazard 10's duplicate-agent minting, in-process.
            // An unwired tile still renders; submitting a prompt in it asks for an
            // agent deliberately, which is the existing respawn-suppressed contract.
            return view
        }
    }

    /// Terminal, browser, browser-inspector and file-tree tiles, which need a
    /// runtime and therefore the layer to be installed first.
    ///
    /// These go through the `restart*` paths, which end in `installProjectTile` —
    /// and that fires `arrangeAutoLayoutAfterSpawn`, re-tidying the entire zone.
    /// Once per tile would shuffle the user's canvas, so auto-layout is suppressed
    /// for the duration. A hydration is not a spawn.
    private func hydrateRuntimeBackedTiles(
        in layer: CanvasNSView.ZoneLayer,
        controller: ZoneRuntimeController,
        canvas: CanvasNSView
    ) {
        // Managed agents are BUILT in Phase A but WIRED here: `wireManagedAgentTile`
        // resolves the view through `canvasView.tileView(for:)`, so the layer has to
        // be installed before it can find anything.
        for tile in layer.tiles where tile.kind == .managedAgent {
            guard agentSupervisor.agent(forTile: tile.id) != nil else { continue }
            wireManagedAgentTile(tile.id)
        }

        guard let spawner = controller.tileSpawner else { return }
        let candidates = layer.tiles.filter { tile in
            switch tile.kind {
            case .terminal, .browser, .fileTree: return true
            default: return false
            }
        }
        guard !candidates.isEmpty else { return }

        canvas.withAutoLayoutSuppressed {
            for tile in candidates {
                guard canvas.tileView(for: tile.id) is DescriptorTileNSView else { continue }
                switch tile.kind {
                case .terminal:
                    // M1.3: the controller may already hold a runtime for this tile
                    // — it survives a switch whenever the project is shared between
                    // the two workspaces, which `switchWorkspace` is explicitly
                    // written for. Retire it first; see `retireOrphanedRuntimes`.
                    retireOrphanedRuntimes(forTile: tile.id, controller: controller)
                    if case let .restarted(runtime) = spawner.restartTerminalTile(tileId: tile.id) {
                        controller.runtimes.append(runtime)
                    }
                case .browser:
                    retireOrphanedRuntimes(forTile: tile.id, controller: controller)
                    if case let .restarted(runtime) = spawner.restartBrowserTile(tileId: tile.id) {
                        controller.browserRuntimes.append(runtime)
                        wireContentProcessTerminationHandler(runtime)
                    }
                case .fileTree:
                    if case .restarted = spawner.restartFileTreeTile(tileId: tile.id),
                       let view = canvas.tileView(for: tile.id) as? FileTreeTileNSView {
                        fileTreeViews[tile.id] = view
                    }
                default:
                    continue
                }
            }
        }
        workspaceRuntime?.enforceBrowserRuntimeBudget()
    }

    /// Drop any runtime this controller still holds for `tileId`, before Phase B
    /// restarts it. M1.3 (`.plans/46`).
    ///
    /// A controller outlives a workspace switch whenever its project is shared
    /// between the two workspaces — `switchWorkspace` builds the arriving layers
    /// *before* releasing, precisely "so shared controllers stay alive"
    /// (`WorkspaceRuntime.swift:668`). Its `runtimes`/`browserRuntimes` are plain
    /// arrays with no uniqueness invariant, and `restartTerminalTile` never
    /// consults them: it always mints `GhosttyTerminalRuntime(id: UUID(), …)` and
    /// re-binds to the persisted tmux window, so hydrating such a tile a second
    /// time puts **two Ghostty surfaces on one pty**. `restartBrowserTile` is the
    /// same shape, where a duplicate is a leaked WKWebView content process.
    ///
    /// **Why retire rather than skip.** The obvious guard — leave the tile alone
    /// when a runtime already exists — keeps the count at one and leaves a dead
    /// `DescriptorTileNSView` on screen, trading this defect for the exact one M1.2
    /// just fixed. And the surviving runtime genuinely cannot be reused:
    /// `setZones` destroyed its host view, and `GhosttyTerminalRuntime.attach(to:)`
    /// constructs a **new** `GhosttyTerminalView`, so re-hosting the old object
    /// would spawn a second surface rather than move the first. Terminating it
    /// also stops a pty from running with nothing attached. With tmux on — the
    /// designed persistence mechanism — the restart re-binds to the persisted
    /// window and the session survives the round trip; browsers restore through
    /// the persisted `interactionState` (history, scroll, forms).
    ///
    /// *Noted, not done:* `WKWebViewBrowserRuntime.attach(to:)` re-adds the **same**
    /// `webView`, so a browser could be re-hosted instead of restarted, keeping the
    /// live page. Doing it needs the tab-model, profile-menu and inspector wiring
    /// that `TileSpawner.restartBrowserTile` owns, so it belongs in the spawner
    /// rather than duplicated here.
    private func retireOrphanedRuntimes(forTile tileId: UUID, controller: ZoneRuntimeController) {
        for runtime in controller.runtimes where runtime.tileId == tileId {
            runtime.detach()
            runtime.terminate(policy: .force)
        }
        controller.runtimes.removeAll { $0.tileId == tileId }
        for runtime in controller.browserRuntimes where runtime.tileId == tileId {
            runtime.detach()
            runtime.terminate(policy: .force)
        }
        controller.browserRuntimes.removeAll { $0.tileId == tileId }
    }

    private func configureCreationAndRuntimeRoutes(on spawner: TileSpawner) {
        spawner.creationScopeProvider = { [weak self] in self?.resolvedCreationScope() }
        spawner.terminalProjectContextProvider = { [weak self] in self?.activeZoneProjectEntry() }
        spawner.terminalSessionTargetProvider = { [weak self] in
            guard let self else { return nil }
            if let projectId = resolvedCreationScope()?.projectId { return .project(projectId: projectId) }
            if let workspaceId = workspaceRuntime?.workspaceId {
                return .ambient(workspaceId: workspaceId)
            }
            return nil
        }
        spawner.terminalFocusedPaneTargetProvider = { [weak self] in
            guard let self,
                  let tileId = canvasView?.canvasState.lastActiveTileId,
                  let record = managedSessionRecord(forTileId: tileId) else { return nil }
            return record.tmuxWindowTarget()
        }
        spawner.focusedTerminalCwdProvider = { [weak self] in
            guard let self,
                  let tileId = canvasView?.canvasState.lastActiveTileId,
                  let view = canvasView?.tileView(for: tileId) as? TerminalTileNSView else { return nil }
            return view.runtime.capturedCwd
        }
        spawner.reservedShortcutHandler = { [weak self] event in self?.handleReservedShortcut(event) ?? false }
        spawner.browserProfileMenuProvider = { [weak self] in
            (try? self?.registryStore?.loadOrEmpty().settings.browserProfiles) ?? [BrowserProfile.builtInDefault()]
        }
        spawner.browserProfileSwitchHandler = { [weak self] tileId, profileId in self?.switchBrowserTileProfile(tileId: tileId, profileId: profileId) }
        spawner.browserProfileCreateHandler = { [weak self] tileId in self?.createBrowserProfile(for: tileId) }
        spawner.browserProfileRenameHandler = { [weak self] tileId, profileId in self?.renameBrowserProfile(tileId: tileId, profileId: profileId) }
        spawner.browserProfileDeleteHandler = { [weak self] tileId, profileId in self?.deleteBrowserProfile(tileId: tileId, profileId: profileId) }
        spawner.browserPersistenceHandler = { [weak self] in self?.scheduleBrowserSave() }
        spawner.notePersistenceHandler = { [weak self] in self?.scheduleNoteSave() }
        spawner.fileTreePersistenceHandler = { [weak self] in self?.scheduleFileTreeSave() }
        configureFileOpenRoute(on: spawner)
        wireBrowserRuntimeRegistration(on: spawner)
    }

    private func resolveDocumentLocation(_ url: URL) -> DocumentLocation {
        let registryRoots: [DocumentLocationRoot] = ((try? registryStore?.loadOrEmpty().projects) ?? []).map {
            DocumentLocationRoot(rootURL: URL(fileURLWithPath: $0.rootPath, isDirectory: true), projectId: $0.id)
        }
        let agentRoots = agentSupervisor.records.values.map {
            DocumentLocationRoot(rootURL: URL(fileURLWithPath: $0.cwd, isDirectory: true), projectId: $0.projectId)
        }
        return DocumentLocationResolver.resolve(fileURL: url, knownRoots: registryRoots + agentRoots)
    }

    private func spawnDiffReviewFromPalette() {
        // M1.11: refuse audibly rather than returning into silence. Its flat-path
        // install is deliberately left alone — AGENTS hazard 9 names it as one of
        // the two remaining flat spawns, and that is its own ticket.
        guard let canvasView, let projectStore, let activeProject else {
            presentSpawnRefusal("Add a project to this workspace before opening a diff review.")
            return
        }
        let reviewId = UUID()
        var canvasState = canvasView.canvasState
        let tile = Self.materializeDiffReviewTile(in: &canvasState, reviewId: reviewId)
        let reviewState = ReviewCommentState(reviewId: reviewId, comments: [])
        do {
            try projectStore.saveReviewCommentState(reviewState)
            let root = URL(fileURLWithPath: activeProject.rootPath, isDirectory: true)
            let diffView = DiffReviewTileNSView(tile: tile, repositoryURL: root, sendCommentsToAgent: { [weak self] in
                self?.sendReviewCommentsFromMenu(reviewTileId: tile.id)
            })
            diffView.onSourceChanged = { [weak canvasView] updated in canvasView?.updateTile(updated) }
            canvasView.install(tileView: diffView, for: tile)
            try projectStore.saveCanvas(canvasView.canvasState)
            focusSpawnedTile(tile.id)
        } catch {
            fputs("spawnDiffReviewFromPalette failed: \(error)\n", stderr)
        }
    }

    private func spawnFileTreeFromPalette() {
        guard resolvedCreationScope() != nil else {
            requestCreationScope { [weak self] in self?.spawnFileTreeFromPalette() }
            return
        }
        guard let spawner = spawnerForFilesystemCreation() else { return }
        switch spawner.spawnFileTreeForCreationScope() {
        case let .spawned(tileId, _):
            if let view = canvasView?.tileView(for: tileId) as? FileTreeTileNSView {
                fileTreeViews[tileId] = view
            }
            focusSpawnedTile(tileId)
        case .invalidPath:
            fputs("TileSpawner.spawnFileTree requires a project/Home scope\n", stderr)
        case let .failure(error):
            fputs("TileSpawner.spawnFileTree failed: \(error)\n", stderr)
        }
    }

    private enum MissingKind { case notFound, notConfigured }

    private func presentMissingCommand(executable: String, profileId: String, kind: MissingKind = .notFound) {
        let alert = NSAlert()
        switch kind {
        case .notFound:
            alert.messageText = "\(executable) is not installed"
            alert.informativeText = "Couldn't find \(executable) on your $PATH. Environment Setup has install guidance, or pick a different profile from Cmd-K."
        case .notConfigured:
            alert.messageText = "Profile '\(profileId)' is not configured"
            alert.informativeText = "Custom profiles aren't editable yet — pick a built-in profile from Cmd-K."
        }
        alert.alertStyle = .informational
        alert.addButton(withTitle: "OK")
        if kind == .notFound {
            alert.addButton(withTitle: "Environment Setup…")
        }
        let response = alert.runModal()
        if kind == .notFound, response == .alertSecondButtonReturn {
            showOnboardingPanel()
        }
    }

    /// P2A.6: a headless agent has no tile to close, so nothing in the UI can reach
    /// its process until the Phase 3 inbox. Quitting must therefore end the work it
    /// started, or the run leaks past the session.
    func applicationWillTerminate(_ notification: Notification) {
        agentSupervisor.stopAll()
        // P3.1: the identical sweep the launch runs, with the reason a clean quit
        // deserves. Best-effort — a quit can be a kill we never see, which is why
        // the launch sweep is the load-bearing one.
        if let store = workspaceRuntime?.activeController?.managedSessionStore {
            do {
                try ManagedSessionReconciliation.reconcile(store: store, reason: .continuumQuit, now: Date())
            } catch {
                fputs("managed-session reconcile: quit sweep failed: \(error)\n", stderr)
            }
        }
        Task { await agentComposerDraftStore.flushAll() }
    }

    func applicationShouldTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply {
        do {
            try workspaceRuntime?.flushMountedWorkspaceState()
            closeFlushAcknowledgedWindow = window
            return .terminateNow
        } catch {
            fputs("workspace termination flush failed; termination cancelled\n", stderr)
            return .terminateCancel
        }
    }

    func applicationDidBecomeActive(_ notification: Notification) {
        // WS4: written BEFORE the broker re-acquires the remembered surface, so
        // the facts a completion delivered during reactivation reads are the ones
        // that actually hold.
        applicationIsActiveForAwareness = true
        if let app = try? ghostty?.app {
            ghostty_app_set_focus(app, true)
        }
        focusBroker.applicationDidBecomeActive()
        refreshAgentSurfaces()
    }

    func applicationDidResignActive(_ notification: Notification) {
        // WS4: the one writer that turns awareness off. Nothing delivered from
        // here until the next activation can be actively viewed, whatever the
        // broker still remembers.
        applicationIsActiveForAwareness = false
        if let app = try? ghostty?.app {
            ghostty_app_set_focus(app, false)
        }
        focusBroker.applicationDidResignActive()
        refreshAgentSurfaces()
    }

    func windowShouldClose(_ sender: NSWindow) -> Bool {
        guard sender === window else { return true }
        do {
            try workspaceRuntime?.flushMountedWorkspaceState()
            closeFlushAcknowledgedWindow = sender
            return true
        } catch {
            closeFlushAcknowledgedWindow = nil
            fputs("workspace close flush failed; close cancelled\n", stderr)
            return false
        }
    }

    func windowWillClose(_ notification: Notification) {
        // Direct/programmatic notification paths which did not ask the delegate
        // first retain the old save-before-teardown guarantee. A real user close
        // was already flushed in windowShouldClose and must not save twice.
        let closingWindow = notification.object as? NSWindow
        guard closingWindow == nil || closingWindow === window else { return }
        if closeFlushAcknowledgedWindow !== closingWindow || closingWindow == nil {
            do {
                try workspaceRuntime?.flushMountedWorkspaceState()
            } catch {
                fputs("workspace close flush failed before teardown\n", stderr)
                return
            }
        }
        closeFlushAcknowledgedWindow = nil
        if let monitor = hotkeyMonitor {
            NSEvent.removeMonitor(monitor)
            hotkeyMonitor = nil
        }
        if let monitor = tileFocusMonitor {
            NSEvent.removeMonitor(monitor)
            tileFocusMonitor = nil
        }
        if let monitor = canvasScrollMonitor {
            NSEvent.removeMonitor(monitor)
            canvasScrollMonitor = nil
        }
        if let monitor = canvasMagnifyMonitor {
            NSEvent.removeMonitor(monitor)
            canvasMagnifyMonitor = nil
        }
        profilePalette?.close()
        profilePalette = nil
        settingsPanel?.close()
        settingsPanel = nil
        localPairingListener?.stop()
        localPairingListener = nil

        // Browsers tear down first: WKWebView's process pool teardown is
        // independent of GhosttyKit's. Inverting the order risks WebKit KVO
        // callbacks firing into a half-torn-down app.
        for runtime in browserRuntimes {
            runtime.terminate(policy: .force)
        }
        browserRuntimes.removeAll()

        // Free every Ghostty surface before ghostty_app_free, per ADR-0010.
        // ghostty_app_free walks the surface registry and dereferences
        // PAC-protected pointers; if a surface is still alive at that point,
        // deinit traps with EXC_BAD_ACCESS.
        for runtime in runtimes {
            runtime.terminate(policy: .force)
        }
        // Release zone layers and controllers after terminating runtimes so that
        // the runtimes/browserRuntimes computed properties (which proxy through
        // workspaceRuntime?.activeController) are still readable during the loops above.
        workspaceRuntime?.closeAll()
        canvasView = nil
        runtimes.removeAll()
        noteViews.removeAll()
        fileTreeViews.removeAll()
        bootTileSpawner = nil
        ghostty?.shutdown()
        ghostty = nil
        browserEngine?.shutdown()
        browserEngine = nil
        workspaceRuntime = nil
        if !suppressTerminateOnWindowCloseForQA {
            if let exitCode = smokeTestExitCode {
                Foundation.exit(exitCode)
            }
            NSApp.terminate(nil)
        }
    }

