            settings: RegistrySettings(preferredEditor: .auto, zoomModifier: .command, openLastProjectOnLaunch: true)
        )
        try workspaceDeleteDelegate.registryStore?.save(workspaceDeleteRegistry)
        workspaceDeleteDelegate.workspaceDeleteConfirmationProvider = { request in
            request.workspaceId == deletedWorkspaceId
        }
        try expect(workspaceDeleteDelegate.deleteWorkspaceAndRelaunch(workspaceId: deletedWorkspaceId), "workspace delete should succeed in the two-workspace fixture")
        let expectedAmbientWorkspaceSession = TmuxSession.ambientSessionName(workspaceId: deletedWorkspaceId)
        try expect(
            workspaceDeleteTmuxControl.log.contains(.killSession(name: expectedAmbientWorkspaceSession)),
            "workspace delete should kill the ambient workspace tmux session before deleting registry entry, got \(workspaceDeleteTmuxControl.log)"
        )
        try expect(!workspaceDeleteTmuxControl.log.contains { call in
            if case let .killSession(name) = call { return name.hasPrefix("array-proj-") || name.hasPrefix("array-") && !name.hasPrefix("array-ws-") }
            return false
        }, "workspace delete must target only array-ws session, got \(workspaceDeleteTmuxControl.log)")

        let disabledTmuxControl = InMemoryTmuxControl()
        let disabledRoot = tempRoot.appendingPathComponent("disabled", isDirectory: true)
        try fileManager.createDirectory(at: disabledRoot, withIntermediateDirectories: true)
        let disabledDefaultsSuiteName = "continuum.test.terminalTmuxDeleteLifecycle.disabled.\(UUID().uuidString)"
        let disabledDefaults = UserDefaults(suiteName: disabledDefaultsSuiteName)!
        disabledDefaults.removePersistentDomain(forName: disabledDefaultsSuiteName)
        disabledDefaults.set(false, forKey: TmuxPersistenceConfig.enabledKey)
        let (disabledDelegate, disabledCanvas, disabledBrowserEngine, _) = try makeDelegate(root: disabledRoot, defaults: disabledDefaults, fakeTmuxPath: fakeTmuxPath, tmuxControl: disabledTmuxControl)
        defer {
            disabledDefaults.removePersistentDomain(forName: disabledDefaultsSuiteName)
            disabledBrowserEngine.shutdown()
        }
        _ = disabledDelegate
        let disabledTile = Tile(
            id: UUID(uuidString: "44444444-4444-4444-4444-444444444444")!,
            kind: .terminal,
            title: "Shell",
            frame: TileFrame(x: 40, y: 40, width: 300, height: 200),
            zPosition: .fromLegacyRank(1),
            runtimeRef: nil,
