        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let artifact = dir.appendingPathComponent("manifest.json")
        let json = """
        {"check":"agent-input","acceptedStatuses":["idle","needsAttention"],"refusedStatuses":["working"],"insertedPrompt":"flyback review prompt with Sources/App.swift new:42","returnCount":1,"status":"passed"}

        """
        try json.write(to: artifact, atomically: true, encoding: .utf8)
        return artifact
    }

    /// Drives the exact `handleReservedShortcut` decision path (A2): the real
    /// `FocusDispatch.resolve` resolver plus the real consumption contract
    /// (`.global`→consumed except spawn-default, `.tileAction`→`executeTileAction`,
    /// `.passThrough`→not-consumed). Asserts the P0 preservation — Cmd-F in a
    /// focused browser resolves to `.tileAction(.browserFind)` and is NOT consumed,
    /// so the event passes through to the browser's own find — without the deleted
    /// special-case guard. Also pins the canvas globals and inviolables.
    static func runReservedDispatchSelfCheck() throws -> URL {
        struct CheckError: Error, CustomStringConvertible {
            let description: String
            init(_ description: String) { self.description = description }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError(message) }
        }

        let keymap = NavKeymap.default
        let defaults = UserDefaults(suiteName: "reserved-dispatch-check-\(UUID().uuidString)")!
        let browserId = UUID(uuidString: "00000000-0000-0000-0000-0000000000B1")!

        // Mirrors `handleReservedShortcut`'s resolution→consumed mapping. The tile
        // branch's consumption is pinned by the static `isPassthroughTileAction`
        // predicate (no instance/canvas needed): post-A4 every tile action is
        // non-passthrough (consumed when the focused tile matches its kind). This
        // check drives the resolution + consumption contract; `--browser-note-action-check`
        // drives the real executors against live tile views.
        func consumes(_ resolution: FocusDispatchResolution) -> Bool {
            switch resolution {
            case let .global(shortcut):
                if case .spawnProfile(let n) = shortcut, !(1...4).contains(n) { return false }
                return true
            case let .tileAction(action):
                return !AppDelegate.isPassthroughTileAction(action)
            case .passThrough:
                return false
            }
        }

        func resolve(keyCode: UInt16, modifiers: FocusKeyModifiers, scope: FocusSurfaceID, focusedKind: TileKind?) -> FocusDispatchResolution {
            FocusDispatch.resolve(keyCode: keyCode, modifiers: modifiers, scope: scope, focusedKind: focusedKind, navKeymap: keymap, defaults: defaults)
        }

        // 1) Cmd-F with a focused browser → .tileAction(.browserFind), and now
        //    CONSUMED (A4 wired the executor: the monitor shows the find bar via
        //    the action). The find bar still appears — just through the action
        //    instead of performKeyEquivalent. The independent `performKeyEquivalent`
        //    fallback (`--browser-url-focus-check`) remains green.
        let browserFind = resolve(keyCode: 3, modifiers: .command, scope: .tile(browserId), focusedKind: .browser)
        try expect(browserFind == .tileAction(.browserFind), "Cmd-F in browser scope should resolve to .tileAction(.browserFind); got \(browserFind)")
        try expect(consumes(browserFind) == true, "Cmd-F in browser must be consumed by the monitor (A4 executor shows the find bar); consumed=\(consumes(browserFind))")

        // 2) Cmd-F with canvas scope → .global(.focusMode), consumed (handled).
        let canvasFind = resolve(keyCode: 3, modifiers: .command, scope: .canvas, focusedKind: nil)
        try expect(canvasFind == .global(.focusMode), "Cmd-F in canvas scope should resolve to .global(.focusMode); got \(canvasFind)")
        try expect(consumes(canvasFind) == true, "Cmd-F in canvas must be consumed (opens Focus Mode); consumed=\(consumes(canvasFind))")

        // 3) Inviolable globals resolve to .global from every scope, even a
        //    browser tile that might otherwise claim them — and are consumed.
        let paletteFromBrowser = resolve(keyCode: 40, modifiers: .command, scope: .tile(browserId), focusedKind: .browser)
        try expect(paletteFromBrowser == .global(.palette), "Cmd-K must always resolve to .global(.palette) even in browser scope; got \(paletteFromBrowser)")
        try expect(consumes(paletteFromBrowser) == true, "Cmd-K (palette) must be consumed")
        let settingsFromBrowser = resolve(keyCode: 43, modifiers: .command, scope: .tile(browserId), focusedKind: .browser)
        try expect(settingsFromBrowser == .global(.settings), "Cmd-, must always resolve to .global(.settings) even in browser scope; got \(settingsFromBrowser)")
        try expect(consumes(settingsFromBrowser) == true, "Cmd-, (settings) must be consumed")
        let leaderFromBrowser = resolve(keyCode: keymap.leader.keyCode, modifiers: keymap.leader.modifiers, scope: .tile(browserId), focusedKind: .browser)
        try expect(leaderFromBrowser == .global(.navModeLeader), "leader must always resolve to .global(.navModeLeader) even in browser scope; got \(leaderFromBrowser)")
        try expect(consumes(leaderFromBrowser) == true, "leader (open nav mode) must be consumed")

        // 4) Canvas-scope global passes through cleanly: Cmd-K/Cmd-, from canvas.
        try expect(resolve(keyCode: 40, modifiers: .command, scope: .canvas, focusedKind: nil) == .global(.palette), "Cmd-K from canvas → .global(.palette)")
        try expect(resolve(keyCode: 43, modifiers: .command, scope: .canvas, focusedKind: nil) == .global(.settings), "Cmd-, from canvas → .global(.settings)")

        let manifest: [String: Any] = [
            "check": "reserved-dispatch",
            "browserId": browserId.uuidString,
            "browserFindResolution": String(describing: browserFind),
            "browserFindConsumed": consumes(browserFind),
            "canvasFindResolution": String(describing: canvasFind),
            "canvasFindConsumed": consumes(canvasFind),
            "paletteFromBrowserResolution": String(describing: paletteFromBrowser),
            "settingsFromBrowserResolution": String(describing: settingsFromBrowser),
            "leaderFromBrowserResolution": String(describing: leaderFromBrowser),
        ]
        let timestamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "")
        let directory = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("reserved-dispatch", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
        try data.write(to: artifact, options: .atomic)
        return artifact
    }

    /// Drives the REAL keyDown path (`handleHotkey`, the hotkey monitor's handler)
    /// to prove the input-gate fix: a `⌘⌃`-digit resize preset now reaches the
    /// dispatcher and fires (it was silently dropped by the old
    /// `mods == onlyCommand` gate), while an unmodified key still passes through.
    /// This is NOT a bypass — it synthesizes real `NSEvent`s and pushes them
    /// through `handleHotkey`, asserting the observable effect (tile resized /
    /// event not consumed). Exactly the kind of check that would have caught the
    /// dead-`⌘⌃` bug (docs/30).
    static func runInputGateSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String { switch self { case let .failed(message): return message } }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }

        let tileId = UUID(uuidString: "00000000-0000-0000-0000-0000000006A1")!
        let startFrame = TileFrame(x: 80, y: 80, width: 200, height: 150)
        let tile = Tile(id: tileId, kind: .note, title: "GATE", frame: startFrame, zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata())
        let canvas = CanvasNSView(canvasState: CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [tile], groups: [], lastActiveTileId: nil))
        let appDelegate = AppDelegate()
        appDelegate.canvasView = canvas
        let focusBroker = appDelegate.focusBroker
        canvas.focusBroker = focusBroker
        focusBroker.onAcceptedTileFocus = { [weak canvas] id in canvas?.markActive(tileId: id) }
        canvas.frame = NSRect(x: 0, y: 0, width: 640, height: 360)
        let window = NSWindow(contentRect: canvas.frame, styleMask: [.borderless], backing: .buffered, defer: false)
        window.contentView = canvas
        window.orderFrontRegardless()
        let view = TileNSView(tile: tile)
        canvas.install(tileView: view, for: tile)
        canvas.layoutSubtreeIfNeeded()

        // Focus the tile through the production click router (title-bar click).
        let titlePoint = view.convert(NSPoint(x: view.bounds.midX, y: TileNSView.titleBarHeight / 2), to: nil)
        AppDelegate.routeTileClickFocus(at: titlePoint, in: canvas, focusBroker: focusBroker)
        try expect(focusBroker.activeSurface == .tile(tileId), "precondition: tile focused; activeSurface=\(String(describing: focusBroker.activeSurface))")

        func frameNow() -> TileFrame { canvas.canvasState.tiles.first(where: { $0.id == tileId })!.frame }

        // 1) ⌘⌃-3 (keyCode 20 = the large resize preset) through the REAL handler.
        guard let resizeEvent = NSEvent.keyEvent(with: .keyDown, location: .zero, modifierFlags: [.command, .control], timestamp: 0, windowNumber: window.windowNumber, context: nil, characters: "3", charactersIgnoringModifiers: "3", isARepeat: false, keyCode: 20) else {
            throw CheckError.failed("could not synthesize ⌘⌃-3 keyDown")
        }
        let resizeConsumed = appDelegate.handleHotkey(resizeEvent)
        let resized = frameNow()
        try expect(resizeConsumed == true, "⌘⌃-3 must be consumed by handleHotkey (the gate no longer drops non-⌘ chords); got \(resizeConsumed)")
        try expect(resized.width > startFrame.width && resized.height > startFrame.height, "⌘⌃-3 must resize the focused tile to the large preset via the real key path; start \(startFrame.width)x\(startFrame.height) got \(resized.width)x\(resized.height)")

        // 1b) ⌘⌃-→ (keyCode 124, the old one-shot "throw right") now passes through
        //     the REAL handler — the throw binding was removed; keyboard snapping is
        //     being rebuilt inside the leader (docs/30). Assert the handler does NOT
        //     consume it and the focused tile does not move.
        guard let throwEvent = NSEvent.keyEvent(with: .keyDown, location: .zero, modifierFlags: [.command, .control], timestamp: 0, windowNumber: window.windowNumber, context: nil, characters: "\u{F703}", charactersIgnoringModifiers: "\u{F703}", isARepeat: false, keyCode: 124) else {
            throw CheckError.failed("could not synthesize ⌘⌃-→ keyDown")
        }
        let throwConsumed = appDelegate.handleHotkey(throwEvent)
        try expect(throwConsumed == false, "⌘⌃-→ must pass through now that the throw binding is removed; got \(throwConsumed)")
        try expect(frameNow() == resized, "⌘⌃-→ must not move the focused tile (throw removed); frame=\(frameNow())")

        // 2) An unmodified key still passes through (handler returns false).
        guard let plainEvent = NSEvent.keyEvent(with: .keyDown, location: .zero, modifierFlags: [], timestamp: 0, windowNumber: window.windowNumber, context: nil, characters: "a", charactersIgnoringModifiers: "a", isARepeat: false, keyCode: 0) else {
            throw CheckError.failed("could not synthesize plain 'a' keyDown")
        }
        let plainConsumed = appDelegate.handleHotkey(plainEvent)
        try expect(plainConsumed == false, "an unmodified key must pass through (handleHotkey returns false); got \(plainConsumed)")

        let manifest: [String: Any] = [
            "check": "input-gate",
            "path": "synthesized NSEvent → handleHotkey (real monitor handler, not executor)",
            "tileId": tileId.uuidString,
            "startFrame": ["x": startFrame.x, "y": startFrame.y, "w": startFrame.width, "h": startFrame.height],
            "afterResize": ["x": resized.x, "y": resized.y, "w": resized.width, "h": resized.height],
            "resizeChord": "cmd+ctrl+3",
            "resizeConsumed": resizeConsumed,
            "throwChordPassesThrough": throwConsumed == false,
            "plainKeyConsumed": plainConsumed,
        ]
        let timestamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "")
        let directory = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("input-gate", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
        try data.write(to: artifact, options: .atomic)
        return artifact
    }

    /// Drives the REAL drag path (`TileNSView.mouseDown`/`mouseDragged`/`mouseUp`
    /// with synthesized mouse `NSEvent`s) to prove drag magnetization end to end:
    /// while dragging tile A near neighbor B the tile stays under the cursor (free)
    /// and a ghost previews the gap-adjacent destination; releasing commits to it.
    /// With drag snapping disabled there is no ghost and release keeps the free
    /// position. Assertions read the committed world frame + the real ghost overlay
    /// frame — never `snapAdjustment`/`snapTarget` directly.
    static func runDragMagnetizeSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String { switch self { case let .failed(message): return message } }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }

        let aId = UUID(uuidString: "00000000-0000-0000-0000-00000000DA61")!
        let bId = UUID(uuidString: "00000000-0000-0000-0000-00000000DA62")!
        let startFrame = TileFrame(x: 100, y: 100, width: 200, height: 150)
        // B sits to the right AND 20 world units lower than A — a vertical offset
        // inside the 44px pull radius. cornerSnap must dock the X gap AND align the
        // tops to B (the 90° corner); snapAdjustment alone could not, since a
        // side-by-side dock has no X overlap to gate the Y alignment.
        let neighborFrame = TileFrame(x: 520, y: 120, width: 200, height: 150)
        let tileA = Tile(id: aId, kind: .note, title: "DRAG_A", frame: startFrame, zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata())
        let tileB = Tile(id: bId, kind: .note, title: "DRAG_B", frame: neighborFrame, zPosition: .fromLegacyRank(2), runtimeRef: nil, metadata: TileMetadata())
        let canvas = CanvasNSView(canvasState: CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [tileA, tileB], groups: [], lastActiveTileId: nil))
        canvas.frame = NSRect(x: 0, y: 0, width: 900, height: 420)
        let window = NSWindow(contentRect: canvas.frame, styleMask: [.borderless], backing: .buffered, defer: false)
        window.contentView = canvas
        window.orderFrontRegardless()
        let viewA = TileNSView(tile: tileA)
        canvas.install(tileView: viewA, for: tileA)
        canvas.install(tileView: TileNSView(tile: tileB), for: tileB)
        canvas.layoutSubtreeIfNeeded()

        func frameOfA() -> TileFrame { canvas.canvasState.tiles.first(where: { $0.id == aId })!.frame }
        func mouse(_ type: NSEvent.EventType, at p: NSPoint) throws -> NSEvent {
            guard let e = NSEvent.mouseEvent(with: type, location: p, modifierFlags: [], timestamp: 0, windowNumber: window.windowNumber, context: nil, eventNumber: 0, clickCount: 1, pressure: 1) else {
                throw CheckError.failed("could not synthesize \(type) at \(p)")
            }
            return e
        }
        // Grab A by its title bar (move drag), in window coordinates.
        func grabPoint() -> NSPoint { viewA.convert(NSPoint(x: viewA.bounds.midX, y: TileNSView.titleBarHeight / 2), to: nil) }
        // Zoom 1 → window dx == world dx. +205 lands A.x at 305, whose right edge
        // (505) is 7 world units from the gap-adjacent target (B.left − gap = 512),
        // i.e. inside the pull radius.
        let worldDx: CGFloat = 205
        let gap = TileGapResolver.resolvedGap()
        // The cornered destination: gap-adjacent left of B (X) AND top-aligned to B (Y).
        let snapTargetFrame = TileFrame(x: neighborFrame.x - gap - startFrame.width, y: neighborFrame.y, width: startFrame.width, height: startFrame.height)
        let freeXAfterDrag = startFrame.x + Double(worldDx)

        // Scenario 1 — snapping ON, dwell delay 0 (arm synchronously). Drag toward B.
        viewA.dragGhostDelay = 0
        let p0 = grabPoint()
        viewA.mouseDown(with: try mouse(.leftMouseDown, at: p0))
        viewA.mouseDragged(with: try mouse(.leftMouseDragged, at: NSPoint(x: p0.x + worldDx, y: p0.y)))
        // Mid-drag: the TILE tracks the cursor (free), and a GHOST previews the snap.
        let duringDrag = frameOfA()
        try expect(duringDrag.x == freeXAfterDrag, "mid-drag the tile must track the cursor (free x=\(freeXAfterDrag)); got \(duringDrag.x)")
        try expect(duringDrag.y == startFrame.y, "mid-drag the tile must stay free on Y (the snap is preview-only); got \(duringDrag.y)")
        let expectedGhost = CanvasEngine.tileScreenFrame(snapTargetFrame, viewport: canvas.canvasState.viewport)
        try expect(canvas.qaDragGhostFrame == expectedGhost, "ghost must preview the gap-adjacent destination \(expectedGhost); got \(String(describing: canvas.qaDragGhostFrame))")
        // Release commits to the previewed snap and clears the ghost.
        viewA.mouseUp(with: try mouse(.leftMouseUp, at: NSPoint(x: p0.x + worldDx, y: p0.y)))
        let committed = frameOfA()
        try expect(committed == snapTargetFrame, "release must commit the previewed snap \(snapTargetFrame); got \(committed)")
        try expect(committed.x + committed.width + gap == neighborFrame.x, "committed tile must be gap-adjacent to B.left=\(neighborFrame.x); got A=\(committed)")
        try expect(committed.y == neighborFrame.y, "committed tile top must be flush with B (the 90° corner); got A.y=\(committed.y), B.y=\(neighborFrame.y)")
        try expect(canvas.qaDragGhostFrame == nil, "ghost must hide on release; got \(String(describing: canvas.qaDragGhostFrame))")

        // Scenario 1b — DWELL gates a quick drag-past. With a real (>0) delay, a
        // single in-range drag event must NOT arm yet (timer pending, no run loop
        // spun here), so no ghost shows and a quick release does NOT snap.
        viewA.dragGhostDelay = 0.15
        var rearm = canvas.canvasState.tiles.first(where: { $0.id == aId })!
        rearm.frame = startFrame
        canvas.updateTile(rearm)
        let d0 = grabPoint()
        viewA.mouseDown(with: try mouse(.leftMouseDown, at: d0))
        viewA.mouseDragged(with: try mouse(.leftMouseDragged, at: NSPoint(x: d0.x + worldDx, y: d0.y)))
        try expect(canvas.qaDragGhostFrame == nil, "dwell: a single in-range drag must not show the phantom before the delay; got \(String(describing: canvas.qaDragGhostFrame))")
        viewA.mouseUp(with: try mouse(.leftMouseUp, at: NSPoint(x: d0.x + worldDx, y: d0.y)))
        try expect(frameOfA().x == freeXAfterDrag, "dwell: a quick drag-past must place freely (x=\(freeXAfterDrag)); got \(frameOfA().x)")

        // Scenario 2 — snapping DISABLED → no ghost, release keeps the free position.
        let offSuite = "DragMagnetizeOffChecks-\(UUID().uuidString)"
        let offDefaults = UserDefaults(suiteName: offSuite)!
        defer { offDefaults.removePersistentDomain(forName: offSuite) }
        offDefaults.set(false, forKey: DragMagnetizeConfig.enabledKey)
        canvas.dragMagnetizeDefaults = offDefaults
        var reset = canvas.canvasState.tiles.first(where: { $0.id == aId })!
        reset.frame = startFrame
        canvas.updateTile(reset)
        try expect(frameOfA() == startFrame, "precondition: A reset to start; got \(frameOfA())")
        let q0 = grabPoint()
        viewA.mouseDown(with: try mouse(.leftMouseDown, at: q0))
        viewA.mouseDragged(with: try mouse(.leftMouseDragged, at: NSPoint(x: q0.x + worldDx, y: q0.y)))
        try expect(canvas.qaDragGhostFrame == nil, "disabled: no ghost during drag; got \(String(describing: canvas.qaDragGhostFrame))")
        viewA.mouseUp(with: try mouse(.leftMouseUp, at: NSPoint(x: q0.x + worldDx, y: q0.y)))
        let free = frameOfA()
        try expect(free.x == freeXAfterDrag, "disabled: release must keep the free position x=\(freeXAfterDrag); got \(free.x)")
        try expect(free.x + free.width + gap != neighborFrame.x, "disabled: must not be gap-adjacent to B; got A=\(free)")

        let manifest: [String: Any] = [
            "check": "drag-magnetize",
            "path": "synthesized mouse NSEvents → TileNSView.mouseDown/Dragged/Up (real drag + real ghost overlay)",
            "startFrame": ["x": startFrame.x, "y": startFrame.y, "w": startFrame.width, "h": startFrame.height],
            "neighborFrame": ["x": neighborFrame.x, "y": neighborFrame.y, "w": neighborFrame.width, "h": neighborFrame.height],
            "freeDuringDrag": ["x": duringDrag.x, "y": duringDrag.y, "w": duringDrag.width, "h": duringDrag.height],
            "committedSnap": ["x": committed.x, "y": committed.y, "w": committed.width, "h": committed.height],
            "disabledFree": ["x": free.x, "y": free.y, "w": free.width, "h": free.height],
            "gap": gap,
        ]
        let timestamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "")
        let directory = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("drag-magnetize", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
        try data.write(to: artifact, options: .atomic)
        return artifact
    }

    /// Drives the REAL live-resize path: synthesizes a mouseDown on a tile's bottom
    /// resize edge, drags it, and asserts the committed world frame in `canvasState`.
    /// `resizeEdgeSnap` should snap the dragged edge flush to a docked neighbor's edge
    /// so the tile matches the neighbor's dimension (drag a short tile's bottom down to
    /// a taller neighbor's bottom → equal heights), leave an out-of-range edge free,
    /// and never shrink below the kind's minimum. Expectations are derived
    /// independently from the tile geometry, never copied from the snap math.
    static func runResizeSnapSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String { switch self { case let .failed(message): return message } }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }

        let aId = UUID(uuidString: "00000000-0000-0000-0000-00000000DE51")!

        // Drive a real bottom-edge resize of tile A through a SEQUENCE of drag events
        // (`worldDys`: positive grows the tile downward, negative shrinks it), against
        // `neighbors`. Returns A's committed world frame after EACH event, so a snap
        // and a later pull-out-of-snap can both be asserted within one gesture.
        func driveBottomResize(aFrame: TileFrame, neighbors: [(UUID, TileFrame)], worldDys: [CGFloat]) throws -> [TileFrame] {
            let tileA = Tile(id: aId, kind: .note, title: "RESIZE_A", frame: aFrame, zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata())
            var tiles = [tileA]
            for (id, f) in neighbors {
                tiles.append(Tile(id: id, kind: .note, title: "N", frame: f, zPosition: .fromLegacyRank(2), runtimeRef: nil, metadata: TileMetadata()))
            }
            let canvas = CanvasNSView(canvasState: CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: tiles, groups: [], lastActiveTileId: nil))
            canvas.frame = NSRect(x: 0, y: 0, width: 1100, height: 760)
            let window = NSWindow(contentRect: canvas.frame, styleMask: [.borderless], backing: .buffered, defer: false)
            window.contentView = canvas
            window.orderFrontRegardless()
            let viewA = TileNSView(tile: tileA)
            canvas.install(tileView: viewA, for: tileA)
            for (id, _) in neighbors {
                let n = canvas.canvasState.tiles.first(where: { $0.id == id })!
                canvas.install(tileView: TileNSView(tile: n), for: n)
            }
            canvas.layoutSubtreeIfNeeded()

            func mouse(_ type: NSEvent.EventType, at p: NSPoint) throws -> NSEvent {
                guard let e = NSEvent.mouseEvent(with: type, location: p, modifierFlags: [], timestamp: 0, windowNumber: window.windowNumber, context: nil, eventNumber: 0, clickCount: 1, pressure: 1) else {
                    throw CheckError.failed("could not synthesize \(type) at \(p)")
                }
                return e
            }
            // Grab the bottom edge at mid-width (clear of the corner bands), in window
            // coordinates. Local y near bounds.height is the bottom edge (flipped view).
            let grabLocal = NSPoint(x: viewA.bounds.midX, y: viewA.bounds.height - 1)
            try expect(viewA.qaResizeEdge(at: grabLocal) == .bottom, "precondition: grab point must be the bottom resize edge; got \(String(describing: viewA.qaResizeEdge(at: grabLocal)))")
            var p = viewA.convert(grabLocal, to: nil)
            // delta.height = -(p_i.y - p_{i-1}.y); growing the tile downward (+worldDy)
            // needs delta.height = +worldDy → p_i.y = p_{i-1}.y - worldDy (zoom 1).
            viewA.mouseDown(with: try mouse(.leftMouseDown, at: p))
            var frames: [TileFrame] = []
            for dy in worldDys {
                p = NSPoint(x: p.x, y: p.y - dy)
                viewA.mouseDragged(with: try mouse(.leftMouseDragged, at: p))
                frames.append(canvas.canvasState.tiles.first(where: { $0.id == aId })!.frame)
            }
            viewA.mouseUp(with: try mouse(.leftMouseUp, at: p))
            return frames
        }

        let bId = UUID(uuidString: "00000000-0000-0000-0000-00000000DE52")!
        let cId = UUID(uuidString: "00000000-0000-0000-0000-00000000DE53")!
        let minH = Double(CanvasEngine.minimumFrame(for: .note).height) // 160 — derived, not hardcoded

        // 1) Dimension match: a short tile docked right of a taller one; dragging its
        // bottom edge down into range snaps flush so the heights match. Both start
        // above the minimum so CanvasEngine's own min-clamp never confounds the snap.
        let tall = TileFrame(x: 0, y: 0, width: 100, height: 260) // bottom at 260
        let shortStart = TileFrame(x: 120, y: 0, width: 120, height: 200) // bottom at 200
        let matched = try driveBottomResize(aFrame: shortStart, neighbors: [(bId, tall)], worldDys: [50]).last! // → bottom 250, snaps to 260
        try expect(matched.y == 0 && matched.x == 120 && matched.width == 120, "resize must keep the fixed edges (top/left/right); got \(matched)")
        try expect(matched.height == tall.height, "resize-snap must match the taller neighbor's height (\(tall.height)); got \(matched.height)")
        try expect(matched.y + matched.height == tall.y + tall.height, "snapped bottom must be flush with the neighbor's bottom")

        // 2) Out of range: a small drag that stays beyond the pull radius does not snap.
        let freeResize = try driveBottomResize(aFrame: shortStart, neighbors: [(bId, tall)], worldDys: [10]).last! // → bottom 210, 50 from 260
        try expect(freeResize.height == 210, "an out-of-range edge resizes freely (no snap); got \(freeResize.height)")

        // 3) Min-size clamp: a snap that would shrink the tile below its minimum clamps
        // to the minimum instead. A starts tall; C's top edge sits below A.top + minH,
        // and the post-drag bottom (170) stays above the minimum so only the SNAP would
        // violate it — isolating resizeEdgeSnap's own clamp.
        let aTall = TileFrame(x: 300, y: 0, width: 300, height: 300) // bottom at 300
        let cInside = TileFrame(x: 620, y: 155, width: 100, height: 300) // top edge at 155 (< minH 160)
        let clamped = try driveBottomResize(aFrame: aTall, neighbors: [(cId, cInside)], worldDys: [-130]).last! // → bottom 170, snap-to-155 would shrink below min
        try expect(clamped.height == minH, "resize-snap must clamp a sub-minimum snap to the minimum height (\(minH)); got \(clamped.height)")
        try expect(clamped.y == 0, "min clamp must keep the fixed (top) edge; got y=\(clamped.y)")

        // 4) Pull out of a snap: once snapped flush, continuing to drag the SAME edge
        // ~past the pull radius must release it to the free position — not re-capture
        // it every event (the "can't unsnap, flickers" bug). Event 1 grows bottom to
        // 250 → snaps to 260; event 2 shrinks the FREE edge by 35 (250→215, which is
        // 45 from 260, just past the 44px radius) → unsnaps to 215.
        let unsnap = try driveBottomResize(aFrame: shortStart, neighbors: [(bId, tall)], worldDys: [50, -35])
        try expect(unsnap[0].height == tall.height, "event 1 must snap flush to the neighbor (\(tall.height)); got \(unsnap[0].height)")
        try expect(unsnap[1].height == 215, "event 2 must pull out of the snap to the free height (215); got \(unsnap[1].height)")

        // 5) Stacked tiles (one above the other, same column, vertical gap): dragging
        // the TOP tile's bottom edge toward the lower tile's top snaps GAP-ADJACENT —
        // the case the Y-overlap-only gate missed, since the lower tile overlaps on X,
        // not Y. (Dylan's grid: two right-column tiles wouldn't snap to each other.)
        let gap = TileGapResolver.resolvedGap()
        let topT = TileFrame(x: 300, y: 0, width: 300, height: 200) // bottom at 200
        let lowerT = TileFrame(x: 300, y: 280, width: 300, height: 200) // top at 280 (X-overlap, Y-gap)
        let stacked = try driveBottomResize(aFrame: topT, neighbors: [(cId, lowerT)], worldDys: [40]).last! // bottom 240 → snaps gap-adjacent
        try expect(stacked.height == lowerT.y - gap, "stacked resize must snap the bottom edge gap-adjacent above the lower tile (\(lowerT.y - gap)); got \(stacked.height)")
        try expect(stacked.y + stacked.height + gap == lowerT.y, "snapped bottom must leave exactly one gap above the stacked tile's top")

        let manifest: [String: Any] = [
            "check": "resize-snap",
            "path": "synthesized mouse NSEvents → TileNSView.mouseDown/Dragged/Up on the bottom resize edge (real live resize)",
            "minimumHeight": minH,
            "dimensionMatch": ["x": matched.x, "y": matched.y, "w": matched.width, "h": matched.height],
            "outOfRange": ["x": freeResize.x, "y": freeResize.y, "w": freeResize.width, "h": freeResize.height],
            "minClamp": ["x": clamped.x, "y": clamped.y, "w": clamped.width, "h": clamped.height],
            "unsnapSnappedThenFree": [unsnap[0].height, unsnap[1].height],
        ]
        let timestamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "")
        let directory = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("resize-snap", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
        try data.write(to: artifact, options: .atomic)
        return artifact
    }

    /// Drives the real A3 sizing executor against a focused tile. Builds a canvas
    /// with one tile, focuses it through the production click router, then calls the
    /// real `executeTileAction` and asserts the committed world frame in
    /// `canvasState.tiles`. Expectations are derived INDEPENDENTLY from the pure
    /// Core math (`TileGeometry`), never copied from the executor. Also asserts an
    /// action with no focused tile returns false.
    static func runTileActionSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String {
                switch self { case let .failed(message): return message }
            }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }
        func approx(_ a: Double, _ b: Double, _ tol: Double = 0.001) -> Bool { abs(a - b) <= tol }

        // One note tile; A is the resize action target.
        let tileAId = UUID(uuidString: "00000000-0000-0000-0000-0000000003A1")!
        let startFrame = TileFrame(x: 60, y: 60, width: 280, height: 200)
        let tileA = Tile(id: tileAId, kind: .note, title: "ACTION_A", frame: startFrame, zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata())
        let viewport = CanvasViewport(x: 0, y: 0, zoom: 1)
        let canvas = CanvasNSView(canvasState: CanvasState(viewport: viewport, tiles: [tileA], groups: [], lastActiveTileId: nil))

        let appDelegate = AppDelegate()
        appDelegate.canvasView = canvas
        let focusBroker = appDelegate.focusBroker
        canvas.focusBroker = focusBroker
        focusBroker.onAcceptedTileFocus = { [weak canvas] id in canvas?.markActive(tileId: id) }
        canvas.frame = NSRect(x: 0, y: 0, width: 800, height: 360)

        let window = NSWindow(contentRect: canvas.frame, styleMask: [.borderless], backing: .buffered, defer: false)
        window.contentView = canvas
        window.orderFrontRegardless()

        let viewA = TileNSView(tile: tileA)
        canvas.install(tileView: viewA, for: tileA)
        canvas.layoutSubtreeIfNeeded()

        func frameOfA() -> TileFrame { canvas.canvasState.tiles.first(where: { $0.id == tileAId })!.frame }

        // 0) No focused tile (scope .canvas) → executor returns false (passthrough).
        focusBroker.enterScope(.canvas, reason: .userClick)
        let noFocusConsumed = appDelegate.executeTileAction(.resizeToPreset(.large))
        try expect(noFocusConsumed == false, "resize with no focused tile must return false (passthrough); got \(noFocusConsumed)")
        try expect(frameOfA() == startFrame, "no-focus resize must not mutate any tile; A frame=\(frameOfA())")

        // Focus A through the production router (title-bar click).
        let titleAPoint = viewA.convert(NSPoint(x: viewA.bounds.midX, y: TileNSView.titleBarHeight / 2), to: nil)
        AppDelegate.routeTileClickFocus(at: titleAPoint, in: canvas, focusBroker: focusBroker)
        try expect(focusBroker.activeSurface == .tile(tileAId), "precondition: A focused; activeSurface=\(String(describing: focusBroker.activeSurface))")

        // Expected preset sizes derived independently from TileGeometry.
        let base = TileGeometry.preset(for: .note).defaultSize
        let expectedLarge = CGSize(width: Double(base.width) * 1.4, height: Double(base.height) * 1.4)
        let expectedCompact = CGSize(width: Double(base.width) * 0.7, height: Double(base.height) * 0.7)

        // 1a) Resize to large → grows to 1.4× base, origin preserved.
        let largeConsumed = appDelegate.executeTileAction(.resizeToPreset(.large))
        let afterLarge = frameOfA()
        try expect(largeConsumed == true, "resize(.large) must be consumed; got \(largeConsumed)")
        try expect(approx(afterLarge.width, Double(expectedLarge.width)) && approx(afterLarge.height, Double(expectedLarge.height)), "large size mismatch: got \(afterLarge.width)x\(afterLarge.height), expected \(expectedLarge.width)x\(expectedLarge.height)")
        try expect(afterLarge.width > startFrame.width && afterLarge.height > startFrame.height, "large must grow vs start \(startFrame.width)x\(startFrame.height); got \(afterLarge.width)x\(afterLarge.height)")
        try expect(approx(afterLarge.x, startFrame.x) && approx(afterLarge.y, startFrame.y), "large must keep top-left origin (\(startFrame.x),\(startFrame.y)); got (\(afterLarge.x),\(afterLarge.y))")

        // 1b) Resize to compact → shrinks to 0.7× base.
        let compactConsumed = appDelegate.executeTileAction(.resizeToPreset(.compact))
        let afterCompact = frameOfA()
        try expect(compactConsumed == true, "resize(.compact) must be consumed; got \(compactConsumed)")
        try expect(approx(afterCompact.width, Double(expectedCompact.width)) && approx(afterCompact.height, Double(expectedCompact.height)), "compact size mismatch: got \(afterCompact.width)x\(afterCompact.height), expected \(expectedCompact.width)x\(expectedCompact.height)")
        try expect(afterCompact.width < afterLarge.width && afterCompact.height < afterLarge.height, "compact must shrink vs large; \(afterCompact.width)x\(afterCompact.height) vs \(afterLarge.width)x\(afterLarge.height)")

        let manifest: [String: Any] = [
            "check": "tile-action",
            "tileAId": tileAId.uuidString,
            "startFrame": ["x": startFrame.x, "y": startFrame.y, "w": startFrame.width, "h": startFrame.height],
            "baseNoteSize": ["w": Double(base.width), "h": Double(base.height)],
            "afterLarge": ["x": afterLarge.x, "y": afterLarge.y, "w": afterLarge.width, "h": afterLarge.height],
            "expectedLarge": ["w": Double(expectedLarge.width), "h": Double(expectedLarge.height)],
            "afterCompact": ["w": afterCompact.width, "h": afterCompact.height],
            "expectedCompact": ["w": Double(expectedCompact.width), "h": Double(expectedCompact.height)],
            "noFocusConsumed": noFocusConsumed,
        ]
        let timestamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "")
        let directory = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("tile-action", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
        try data.write(to: artifact, options: .atomic)
        return artifact
    }

    /// Drives the real A4 browser/note executors against live tile VIEWS (not just
    /// models). Builds a canvas with a focused browser tile (backed by a spy
    /// `BrowserRuntime` so reload/back/forward are observable without a heavy
    /// WKWebView) and a focused note tile, focuses each through the production
    /// click router, then calls `executeTileAction` and asserts the observable
    /// effect. Never triggers a save panel (the note path tests `exportContent()`,
    /// the pure payload — `runModal()` would hang the matrix).
    static func runBrowserNoteActionSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String { switch self { case let .failed(message): return message } }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }

        let browserTileId = UUID(uuidString: "00000000-0000-0000-0000-0000000004B1")!
        let noteTileId = UUID(uuidString: "00000000-0000-0000-0000-0000000004D2")!
        let noteId = UUID(uuidString: "00000000-0000-0000-0000-0000000004ED")!
        let browserFrame = TileFrame(x: 40, y: 40, width: 480, height: 320)
        let noteFrame = TileFrame(x: 560, y: 40, width: 360, height: 240)
        let browserTile = Tile(id: browserTileId, kind: .browser, title: "ACTION_BROWSER", frame: browserFrame, zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata(url: "https://example.test/start"))
        let noteBody = "first line\nsecond line\nexport me"
        let noteTile = Tile(id: noteTileId, kind: .note, title: "ACTION_NOTE", frame: noteFrame, zPosition: .fromLegacyRank(2), runtimeRef: nil, metadata: TileMetadata(noteId: noteId))
        let viewport = CanvasViewport(x: 0, y: 0, zoom: 1)
        let canvas = CanvasNSView(canvasState: CanvasState(viewport: viewport, tiles: [browserTile, noteTile], groups: [], lastActiveTileId: nil))

        let appDelegate = AppDelegate()
        appDelegate.canvasView = canvas
        let focusBroker = appDelegate.focusBroker
        canvas.focusBroker = focusBroker
        focusBroker.onAcceptedTileFocus = { [weak canvas] id in canvas?.markActive(tileId: id) }
        canvas.frame = NSRect(x: 0, y: 0, width: 960, height: 400)

        let window = NSWindow(contentRect: canvas.frame, styleMask: [.borderless], backing: .buffered, defer: false)
        window.contentView = canvas
        window.orderFrontRegardless()

        let runtime = SpyBrowserRuntime(tileId: browserTileId, initialURL: "https://example.test/start")
        let browserView = BrowserTileNSView(tile: browserTile, runtime: runtime)
        let noteView = NoteTileNSView(tile: noteTile, noteId: noteId, initialBody: noteBody)
        canvas.install(tileView: browserView, for: browserTile)
        canvas.install(tileView: noteView, for: noteTile)
        canvas.layoutSubtreeIfNeeded()
        defer {
            runtime.terminate(policy: .requestClose)
            window.close()
        }

        func focusTile(_ view: TileNSView) {
            let titlePoint = view.convert(NSPoint(x: view.bounds.midX, y: TileNSView.titleBarHeight / 2), to: nil)
            AppDelegate.routeTileClickFocus(at: titlePoint, in: canvas, focusBroker: focusBroker)
        }

        // --- Browser tile focused: browser actions consumed + invoke runtime. ---
        focusTile(browserView)
        try expect(focusBroker.activeSurface == .tile(browserTileId), "precondition: browser focused; activeSurface=\(String(describing: focusBroker.activeSurface))")

        let reloadConsumed = appDelegate.executeTileAction(.browserReload)
        try expect(reloadConsumed == true, "browserReload on focused browser must be consumed; got \(reloadConsumed)")
        try expect(runtime.reloadCount == 1, "browserReload must invoke runtime.reload() exactly once; got \(runtime.reloadCount)")

        let backConsumed = appDelegate.executeTileAction(.browserBack)
        try expect(backConsumed == true, "browserBack on focused browser must be consumed; got \(backConsumed)")
        try expect(runtime.goBackCount == 1, "browserBack must invoke runtime.goBack() exactly once; got \(runtime.goBackCount)")

        let forwardConsumed = appDelegate.executeTileAction(.browserForward)
        try expect(forwardConsumed == true, "browserForward on focused browser must be consumed; got \(forwardConsumed)")
        try expect(runtime.goForwardCount == 1, "browserForward must invoke runtime.goForward() exactly once; got \(runtime.goForwardCount)")

        try expect(browserView.findBarVisibleForQA == false, "find bar should be hidden before browserFind")
        let findConsumed = appDelegate.executeTileAction(.browserFind)
        try expect(findConsumed == true, "browserFind on focused browser must be consumed; got \(findConsumed)")
        try expect(browserView.findBarVisibleForQA == true, "browserFind must show the find bar")

        // --- Find-result indicator (P3): surface WKFindResult.matchFound as a
        //     found/not-found hint. No "N of M" count — WKFindResult has no public
        //     total. Driven via the spy runtime to avoid real-WKWebView timing.
        runtime.findCorpus = "the quick brown fox jumps over the lazy dog"
        try expect(browserView.findResultTextForQA.isEmpty, "find indicator should start clear; got \(browserView.findResultTextForQA.debugDescription)")
        // A query absent from the page → "No matches".
        browserView.performFindFieldCommandForQA(#selector(NSResponder.insertNewline(_:)), query: "zzznope")
        let noMatchText = browserView.findResultTextForQA
        try expect(noMatchText == "No matches", "a find with no match must show \"No matches\"; got \(noMatchText.debugDescription)")
        // A successful query → indicator cleared (no count shown).
        browserView.performFindFieldCommandForQA(#selector(NSResponder.insertNewline(_:)), query: "quick")
        let matchText = browserView.findResultTextForQA
        try expect(matchText.isEmpty, "a successful find must clear the indicator (no count shown); got \(matchText.debugDescription)")
        // Re-trigger a no-match, then empty the query → indicator cleared.
        browserView.performFindFieldCommandForQA(#selector(NSResponder.insertNewline(_:)), query: "zzznope")
        try expect(browserView.findResultTextForQA == "No matches", "precondition: no-match indicator visible before clearing query")
        browserView.setFindQueryForQA("")
        try expect(browserView.findResultTextForQA.isEmpty, "emptying the find query must clear the indicator; got \(browserView.findResultTextForQA.debugDescription)")

        let focusURLConsumed = appDelegate.executeTileAction(.browserFocusURL)
        try expect(focusURLConsumed == true, "browserFocusURL on focused browser must be consumed; got \(focusURLConsumed)")
        try expect(browserView.urlFieldHasFocusForQA == true, "browserFocusURL must focus the URL field")

        // A NOTE action while the browser is focused → passthrough (false), no crash.
        let noteExportOnBrowser = appDelegate.executeTileAction(.noteExport)
        try expect(noteExportOnBrowser == false, "noteExport on a focused BROWSER must return false (passthrough); got \(noteExportOnBrowser)")

        // --- Note tile focused: noteExport consumed; export payload == body. ---
        focusTile(noteView)
        try expect(focusBroker.activeSurface == .tile(noteTileId), "precondition: note focused; activeSurface=\(String(describing: focusBroker.activeSurface))")

        let exportContent = noteView.exportContent()
        try expect(exportContent.text == noteBody, "export content text must equal the note body; got \(exportContent.text.debugDescription)")
        try expect(!exportContent.suggestedFilename.isEmpty, "export must suggest a non-empty filename; got \(exportContent.suggestedFilename.debugDescription)")

        // A BROWSER action while the note is focused → passthrough (false), no crash,
        // and the spy runtime is NOT touched (counts unchanged).
        let reloadCountBefore = runtime.reloadCount
        let browserReloadOnNote = appDelegate.executeTileAction(.browserReload)
        try expect(browserReloadOnNote == false, "browserReload on a focused NOTE must return false (passthrough); got \(browserReloadOnNote)")
        try expect(runtime.reloadCount == reloadCountBefore, "browser action on a note must not touch the browser runtime; reloadCount=\(runtime.reloadCount)")

        // No focused tile (canvas scope) → browser/note actions passthrough.
        focusBroker.enterScope(.canvas, reason: .userClick)
        let findNoFocus = appDelegate.executeTileAction(.browserFind)
        try expect(findNoFocus == false, "browserFind with no focused tile must return false (passthrough); got \(findNoFocus)")
        let exportNoFocus = appDelegate.executeTileAction(.noteExport)
        try expect(exportNoFocus == false, "noteExport with no focused tile must return false (passthrough); got \(exportNoFocus)")

        let manifest: [String: Any] = [
            "check": "browser-note-action",
            "browserTileId": browserTileId.uuidString,
            "noteTileId": noteTileId.uuidString,
            "reloadConsumed": reloadConsumed,
            "reloadCount": runtime.reloadCount,
            "backConsumed": backConsumed,
            "goBackCount": runtime.goBackCount,
            "forwardConsumed": forwardConsumed,
            "goForwardCount": runtime.goForwardCount,
            "findConsumed": findConsumed,
            "findBarVisible": browserView.findBarVisibleForQA,
            "findNoMatchText": noMatchText,
            "findMatchClears": matchText.isEmpty,
            "focusURLConsumed": focusURLConsumed,
            "urlFieldHasFocus": browserView.urlFieldHasFocusForQA,
            "noteExportOnBrowser": noteExportOnBrowser,
            "exportText": exportContent.text,
            "exportSuggestedFilename": exportContent.suggestedFilename,
            "browserReloadOnNote": browserReloadOnNote,
            "findNoFocus": findNoFocus,
            "exportNoFocus": exportNoFocus,
        ]
        let timestamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "")
        let directory = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("browser-note-action", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let artifact = directory.appendingPathComponent("manifest.json")
        let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
        try data.write(to: artifact, options: .atomic)
        return artifact
    }

    static func runFocusModeSelfCheck() throws -> URL {
        struct CheckError: Error, CustomStringConvertible {
            let description: String
            init(_ description: String) { self.description = description }
        }

        let zone = UUID(uuidString: "10000000-0000-0000-0000-000000000001")!
        let primary = UUID(uuidString: "10000000-0000-0000-0000-000000000002")!
        let agentA = UUID(uuidString: "10000000-0000-0000-0000-000000000003")!
        let agentB = UUID(uuidString: "10000000-0000-0000-0000-000000000004")!
        let base = Date(timeIntervalSince1970: 1_000)
        let candidates = [
            FocusModePairingCandidate(tileId: agentA, zoneId: zone, isAgent: true, status: .needsAttention, lastActiveAt: base),
            FocusModePairingCandidate(tileId: agentB, zoneId: zone, isAgent: true, status: .idle, lastActiveAt: base.addingTimeInterval(60)),
        ]
        guard FocusModePairing.companionAgent(for: primary, primaryZoneId: zone, candidates: candidates) == agentA else {
            throw CheckError("focus-mode heuristic did not choose needsAttention agent")
        }
        guard FocusModePairing.companionAgent(for: primary, primaryZoneId: zone, candidates: candidates, manualOverride: agentB) == agentB else {
            throw CheckError("focus-mode session override did not choose requested same-zone agent")
        }
        guard FocusModePairing.companionAgent(for: primary, primaryZoneId: zone, candidates: candidates.filter { $0.tileId != agentB }, manualOverride: agentB) == agentA else {
            throw CheckError("focus-mode invalidated override did not fall back to heuristic")
        }
        guard ReservedShortcut.classify(keyCode: 3, modifiers: .command) == .focusMode else {
            throw CheckError("Cmd-F should classify as focus-mode shortcut")
        }
        guard FocusSurfaceID.modal(.focusMode) == .modal(.focusMode) else {
            throw CheckError("focus mode modal surface should be representable")
        }

        let primaryTile = Tile(id: primary, kind: .note, title: "Primary", frame: TileFrame(x: 10, y: 10, width: 200, height: 120), zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata())
        let agentTile = Tile(id: agentA, kind: .terminal, title: "Agent", frame: TileFrame(x: 260, y: 10, width: 200, height: 120), zPosition: .fromLegacyRank(0), runtimeRef: nil, metadata: TileMetadata())
        let savedState = CanvasState(viewport: CanvasViewport(x: 12, y: 34, zoom: 1.25), tiles: [primaryTile, agentTile], groups: [], lastActiveTileId: primary)
        let canvas = CanvasNSView(canvasState: savedState)
        let primaryView = TileNSView(tile: primaryTile)
        let agentView = TileNSView(tile: agentTile)
        canvas.install(tileView: primaryView, for: primaryTile)
        canvas.install(tileView: agentView, for: agentTile)
        let session = FocusModeSession(
            primaryTileId: primary,
            companionTileId: agentA,
            savedViewport: savedState.viewport,
            savedTiles: savedState.tiles,
            savedLastActiveTileId: savedState.lastActiveTileId,
            canvasView: canvas,
            primaryView: primaryView,
            companionView: agentView
        )
        guard session.protectedTileIds == [primary, agentA] else {
            throw CheckError("focus-mode protected ids did not include both panes")
        }
        guard primaryView.superview !== canvas, agentView.superview !== canvas else {
            throw CheckError("focus-mode session did not reparent pane views")
        }
        canvas.setViewport(CanvasViewport(x: 0, y: 0, zoom: 0.5))
        canvas.updateTile(Tile(id: primary, kind: .note, title: "Primary", frame: TileFrame(x: 999, y: 999, width: 100, height: 100), zPosition: .fromLegacyRank(99), runtimeRef: nil, metadata: TileMetadata()))
        session.restore()
        guard canvas.canvasState.viewport == savedState.viewport,
              canvas.canvasState.tiles == savedState.tiles,
              canvas.canvasState.lastActiveTileId == savedState.lastActiveTileId else {
            throw CheckError("focus-mode restore did not return canvas state exactly")
        }
        guard primaryView.superview === canvas, agentView.superview === canvas else {
            throw CheckError("focus-mode restore did not return pane views to canvas")
        }

        let timestamp = String(Int(Date().timeIntervalSince1970))
        let dir = URL(fileURLWithPath: "qa-runs/focus-mode-\(timestamp)", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let artifact = dir.appendingPathComponent("manifest.json")
        let json = """
        {"check":"focus-mode","primaryTileId":"\(primary.uuidString)","heuristicCompanion":"\(agentA.uuidString)","manualOverrideCompanion":"\(agentB.uuidString)","shortcut":"cmd-f","modalKind":"focusMode","restoreStateExact":true,"protectedPaneCount":2,"overrideScope":"session-only model seam","status":"passed"}

        """
        try json.write(to: artifact, atomically: true, encoding: .utf8)
        return artifact
    }

    static func runSpawnRateLimitSelfCheck() throws -> URL {
        struct CheckError: Error, CustomStringConvertible {
            let description: String
            init(_ description: String) { self.description = description }
        }

        let base = Date(timeIntervalSince1970: 1_000)
        var admission = TerminalSpawnAdmission(maxLive: 2, debounceWindow: 0.300)

        guard admission.admit(trigger: "hotkey:cmd-1", liveCount: 0, now: base) == nil else {
            throw CheckError("first spawn request should be admitted")
        }
        guard case let .rateLimited(trigger, retryAfter)? = admission.admit(trigger: "hotkey:cmd-1", liveCount: 1, now: base.addingTimeInterval(0.100)),
              trigger == "hotkey:cmd-1",
              retryAfter > 0.19 && retryAfter < 0.21 else {
            throw CheckError("same trigger inside 300ms was not rate-limited with measured retryAfter")
        }
        guard admission.admit(trigger: "palette:claude", liveCount: 1, now: base.addingTimeInterval(0.100)) == nil else {
            throw CheckError("different trigger inside 300ms should be admitted")
        }
        guard admission.admit(trigger: "hotkey:cmd-1", liveCount: 1, now: base.addingTimeInterval(0.301)) == nil else {
            throw CheckError("same trigger after 300ms should be admitted")
        }
        guard case let .liveRuntimeCapReached(maxLive, liveCount)? = admission.admit(trigger: "hotkey:cmd-4", liveCount: 2, now: base.addingTimeInterval(1.0)),
              maxLive == 2,
              liveCount == 2 else {
            throw CheckError("live runtime cap did not refuse at 2/2")
        }
        guard TerminalSpawnAdmission().maxLive == TerminalSpawnAdmission.defaultMaxLive else {
            throw CheckError("default terminal live cap changed unexpectedly")
        }

        let timestamp = String(Int(Date().timeIntervalSince1970))
        let dir = URL(fileURLWithPath: "qa-runs/spawn-rate-limit-\(timestamp)", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let artifact = dir.appendingPathComponent("manifest.json")
        let json = """
        {"check":"spawn-rate-limit","debounceWindow":0.3,"defaultMaxLive":\(TerminalSpawnAdmission.defaultMaxLive),"capScenario":{"maxLive":2,"liveCount":2,"refused":true},"status":"passed"}

        """
        try json.write(to: artifact, atomically: true, encoding: .utf8)
        return artifact
    }

    // MARK: - Persistence Crash-Safe Check

    static func runAtomicWriterLockChild() throws {
        func argument(_ name: String) throws -> String {
            guard let index = CommandLine.arguments.firstIndex(of: name),
                  CommandLine.arguments.indices.contains(index + 1) else {
                throw CocoaError(.fileReadCorruptFile)
            }
            return CommandLine.arguments[index + 1]
        }
        let root = URL(fileURLWithPath: try argument("--support"), isDirectory: true)
        let workspaceId = UUID(uuidString: try argument("--workspace-id"))!
        let fixedBackupDate: Date? = {
            if let epoch = try? argument("--backup-epoch"), let seconds = Double(epoch) {
                return Date(timeIntervalSince1970: seconds)
            }
            return CommandLine.arguments.contains("--fixed-backup-date")
                ? Date(timeIntervalSince1970: 1_900_000_000.123) : nil
        }()
        let generation = Int((try? argument("--generation")) ?? "177") ?? 177
        let document = WorkspaceDocument(
            viewport: .init(x: Double(generation), y: 188, zoom: 1.2), zones: [], lastActiveZoneId: nil)
        try WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
            retainedBackups: 4, backupDate: { fixedBackupDate ?? Date() }).save(document)
    }

    static func runWorkspaceRestartFaultChild() throws {
        enum Failure: Error { case message(String) }
        func argument(_ name: String) throws -> String {
            guard let i = CommandLine.arguments.firstIndex(of: name), CommandLine.arguments.indices.contains(i + 1) else {
                throw Failure.message("missing \(name)")
            }
            return CommandLine.arguments[i + 1]
        }
        let mode = try argument("--mode")
        let output = URL(fileURLWithPath: try argument("--output"))
        let closeOffset = UInt32(try argument("--close-offset-ms")) ?? 0
        guard let supportPath = ProcessInfo.processInfo.environment["CONTINUUM_APP_SUPPORT"] else {
            throw Failure.message("missing isolated app support")
        }
        let support = URL(fileURLWithPath: supportPath, isDirectory: true)
        let now = Date(timeIntervalSince1970: 1_900_000_000)
        let wa = UUID(uuidString: "71000000-0000-0000-0000-000000000001")!
        let wb = UUID(uuidString: "71000000-0000-0000-0000-000000000002")!
        let pa = UUID(uuidString: "71000000-0000-0000-0000-000000000011")!
        let pb = UUID(uuidString: "71000000-0000-0000-0000-000000000012")!
        let za1 = UUID(uuidString: "71000000-0000-0000-0000-000000000021")!
        let za2 = UUID(uuidString: "71000000-0000-0000-0000-000000000022")!
        let ambient = UUID(uuidString: "71000000-0000-0000-0000-000000000023")!
        let zb = UUID(uuidString: "71000000-0000-0000-0000-000000000024")!
        let ta1 = UUID(uuidString: "71000000-0000-0000-0000-000000000031")!
        let ta2 = UUID(uuidString: "71000000-0000-0000-0000-000000000032")!
        let tb = UUID(uuidString: "71000000-0000-0000-0000-000000000033")!
        let ambientTile = UUID(uuidString: "71000000-0000-0000-0000-000000000034")!
        let paRoot = support.appendingPathComponent("project-a", isDirectory: true)
        let pbRoot = support.appendingPathComponent("project-b", isDirectory: true)
        try FileManager.default.createDirectory(at: paRoot, withIntermediateDirectories: true)
        try FileManager.default.createDirectory(at: pbRoot, withIntermediateDirectories: true)
        let storeA = ProjectStore(projectRoot: paRoot)
        let storeB = ProjectStore(projectRoot: pbRoot)
        let projectA = Project(id: pa, name: "A", rootPath: paRoot.path, createdAt: now, updatedAt: now,
            defaultLaunchProfileId: "shell", editorPreference: .auto,
            settings: ProjectSettings(restorePolicy: .restoreDescriptors, browserStoragePolicy: .perProject, terminalClosePolicy: .askWhenRunning))
        let projectB = Project(id: pb, name: "B", rootPath: pbRoot.path, createdAt: now, updatedAt: now,
            defaultLaunchProfileId: "shell", editorPreference: .auto,
            settings: ProjectSettings(restorePolicy: .restoreDescriptors, browserStoragePolicy: .perProject, terminalClosePolicy: .askWhenRunning))
        func tile(_ id: UUID, zone: UUID, frame: TileFrame, rank: Int) -> Tile {
            var value = Tile(id: id, kind: .note, title: id == ta1 ? "focused" : "retained",
                frame: frame, zPosition: .fromLegacyRank(rank), runtimeRef: nil,
                metadata: TileMetadata(noteId: id))
            value.zoneId = zone
            return value
        }
        func zone(_ id: UUID, project: UUID?, x: Double, y: Double, name: String, rank: Int) -> ZonePlacement {
            var value = ZonePlacement(zoneId: id, projectId: project, origin: ZonePoint(x: x, y: y),
                size: ZoneSize(width: 901.5, height: 607.25), color: "mint", collapsed: false,
                hydrationPolicy: .automatic, name: name)
            value.zPosition = .fromLegacyRank(rank)
            return value
        }
        let registryStore = RegistryStore(applicationSupportDirectory: support)
        if mode == "seed-mutate-close" {
            try storeA.saveProject(projectA)
            try storeB.saveProject(projectB)
            try storeA.saveCanvas(CanvasState(viewport: .init(x: 0, y: 0, zoom: 1), tiles: [
                tile(ta1, zone: za1, frame: .init(x: -801.75, y: 509.5, width: 237.25, height: 141.5), rank: 3),
                tile(ta2, zone: za2, frame: .init(x: 1875.125, y: -615.75, width: 311.5, height: 177.25), rank: 7)
            ], groups: [], lastActiveTileId: ta1))
            try storeB.saveCanvas(CanvasState(viewport: .init(x: 0, y: 0, zoom: 1), tiles: [
                tile(tb, zone: zb, frame: .init(x: 410.5, y: 312.25, width: 260.5, height: 160.75), rank: 4)
            ], groups: [], lastActiveTileId: tb))
            let ambientTileValue = tile(ambientTile, zone: ambient,
                frame: .init(x: -2100.25, y: -299.75, width: 280.5, height: 155.25), rank: 8)
            // The persisted nonzero camera deliberately fits the primary zone
            // and hydrated tile inside the 1600×1000 evidence canvas.
            let docA = WorkspaceDocument(viewport: .init(x: -1050.5, y: 200.25, zoom: 0.8), zones: [
                zone(za1, project: pa, x: -913.25, y: 407.75, name: "A primary", rank: 3),
                zone(za2, project: pa, x: 1800.5, y: -722.125, name: "A lower tier", rank: 7),
                zone(ambient, project: nil, x: -2200.75, y: -400.5, name: "Ambient", rank: 9)
            ], zoneZOrder: [za1, za2, ambient], lastActiveZoneId: za1, ambientTiles: [ambientTileValue])
            let docB = WorkspaceDocument(viewport: .init(x: 900.25, y: -311.5, zoom: 0.875), zones: [
                zone(zb, project: pb, x: 300.25, y: 201.5, name: "B", rank: 4)
            ], zoneZOrder: [zb], lastActiveZoneId: zb)
            try WorkspaceStore(workspaceId: wa, applicationSupportDirectory: support).save(docA)
            try WorkspaceStore(workspaceId: wb, applicationSupportDirectory: support).save(docB)
            var registry = Registry.empty()
            registry.lastActiveWorkspaceId = wa
            registry.workspaces = [
                WorkspaceEntry(id: wa, name: "A", projectIds: [pa], createdAt: now, updatedAt: now),
                WorkspaceEntry(id: wb, name: "B", projectIds: [pb], createdAt: now, updatedAt: now)
            ]
            registry.projects = [
                ProjectEntry(id: pa, name: "A", rootPath: paRoot.path, workspaceId: wa, lastOpenedAt: now, pinned: false, missing: false),
                ProjectEntry(id: pb, name: "B", rootPath: pbRoot.path, workspaceId: wb, lastOpenedAt: now, pinned: false, missing: false)
            ]
            try registryStore.save(registry)
        }
        let registry = try registryStore.loadOrEmpty()
        let initialId = registry.lastActiveWorkspaceId ?? wa
        let initialDocument = try WorkspaceStore(workspaceId: initialId, applicationSupportDirectory: support).load()
        let browser = BrowserEngineContext()
        defer { browser.shutdown() }
        let delegate = AppDelegate()
        delegate.suppressTerminateOnWindowCloseForQA = true
        let zoneRegistry = ZoneRuntimeRegistry(closeOnZero: true) { id in
            if id == pa { return ZoneRuntimeController(projectRoot: paRoot, projectStore: storeA, project: projectA) }
            if id == pb { return ZoneRuntimeController(projectRoot: pbRoot, projectStore: storeB, project: projectB) }
            throw Failure.message("unexpected project \(id)")
        }
        let bootProject = initialId == wa ? projectA : projectB
        let bootStore: ProjectStore = initialId == wa ? storeA : storeB
        let runtime = WorkspaceRuntime(boot: try zoneRegistry.acquire(projectId: bootProject.id), workspaceId: initialId,
            document: initialDocument, registry: zoneRegistry, focusBroker: delegate.qaFocusBroker,
            registryStore: registryStore, ghostty: nil, browserEngine: browser)
        var readiness: [String] = []
        runtime.lifecycleObserver = { event in readiness.append(String(describing: event)) }
        let bootState = try bootStore.loadCanvas()
        let canvas = CanvasNSView(canvasState: bootState, activeZone: initialDocument.zones.first,
            zoneRenderModels: initialDocument.zones.map { .init(placement: $0, displayName: $0.name) }, showsZoneChrome: true)
        canvas.frame = CGRect(x: 0, y: 0, width: 1600, height: 1000)
        // Deterministic offscreen host for first-frame evidence. It is never
        // ordered onto the physical desktop; the explicit bitmap below locks 2×.
        let renderWindow = NSWindow(contentRect: canvas.frame, styleMask: [.borderless],
            backing: .buffered, defer: false)
        renderWindow.isReleasedWhenClosed = false
        renderWindow.contentView = canvas
        delegate.qaPrepareForBootMountCheck(canvas: canvas, browserEngine: browser, runtime: runtime, registryStore: registryStore)
        let spawner = TileSpawner(canvasView: canvas, ghostty: nil, browserEngine: browser, projectStore: bootStore, project: bootProject)
        func snapshot(_ phase: String) throws -> [String: Any] {
            let zones = canvas.renderedZonesInZOrder.map { z in ["id": z.zoneId.uuidString, "project": z.projectId?.uuidString ?? "ambient",
                "x": z.origin.x, "y": z.origin.y, "w": z.size.width, "h": z.size.height, "z": String(describing: z.zPosition)] as [String: Any] }
            var tiles: [[String: Any]] = []
            let mountedProjectIds = Set(runtime.document.zones.compactMap(\.projectId))
            for (projectId, projectStore) in [(pa, storeA), (pb, storeB)] where mountedProjectIds.contains(projectId) {
                var seen = Set<UUID>()
                for t in canvas.tilesInWorldFrames(forProjectId: projectId) {
                    seen.insert(t.id)
                    tiles.append(["id": t.id.uuidString, "zone": t.zoneId?.uuidString ?? "", "x": t.frame.x, "y": t.frame.y,
                        "w": t.frame.width, "h": t.frame.height, "z": String(describing: t.zPosition), "source": "live"])
                }
                if let persisted = try projectStore.tryLoadCanvas() {
                    for t in persisted.tiles where !seen.contains(t.id) {
                        // The fixture declares exactly one intentionally
                        // unhydrated lower-tier member. Every other automatic,
                        // mounted project member is required to come from the
                        // live CanvasNSView; retained state may not conceal a
                        // failed layer install.
                        guard projectId == pa, t.id == ta2, t.zoneId == za2 else {
                            throw Failure.message("hydrated project tile missing from live canvas: \(t.id)")
                        }
                        tiles.append(["id": t.id.uuidString, "zone": t.zoneId?.uuidString ?? "", "x": t.frame.x, "y": t.frame.y,
                            "w": t.frame.width, "h": t.frame.height, "z": String(describing: t.zPosition), "source": "retained"])
                    }
                }
            }
            for ambientZone in runtime.document.zones where ambientZone.projectId == nil {
                let retained = runtime.document.tiles(forZone: ambientZone.zoneId)
                let observed: [Tile]
                let source: String
                if let live = canvas.tilesInWorldFrames(forZoneId: ambientZone.zoneId) {
                    let liveIds = Set(live.map(\.id))
                    let retainedIds = Set(retained.map(\.id))
                    guard liveIds == retainedIds else {
                        throw Failure.message("installed ambient layer tile inventory diverged from document")
                    }
                    let retainedById = Dictionary(uniqueKeysWithValues: retained.map { ($0.id, $0) })
                    guard live.allSatisfy({ retainedById[$0.id] == $0 }) else {
                        throw Failure.message("installed ambient layer world geometry diverged from document")
                    }
                    observed = live
                    source = "live"
                } else {
                    observed = retained
                    source = "retained"
                }
                for t in observed {
                    tiles.append(["id": t.id.uuidString, "zone": t.zoneId?.uuidString ?? "", "x": t.frame.x, "y": t.frame.y,
                        "w": t.frame.width, "h": t.frame.height, "z": String(describing: t.zPosition), "source": source])
                }
            }
            let focus: String
            switch delegate.qaFocusBroker.activeSurface { case let .tile(id): focus = "tile:\(id.uuidString)"; case .canvas: focus = "canvas"; default: focus = "none" }
            let observedActiveZone = canvas.armedZoneId?.uuidString ?? ""
            let documentActiveZone = runtime.document.lastActiveZoneId?.uuidString ?? ""
            guard observedActiveZone == documentActiveZone else {
                throw Failure.message("canvas armed zone diverged from workspace document")
            }
            return ["phase": phase, "workspace": runtime.workspaceId.uuidString, "zones": zones, "tiles": tiles.sorted { ($0["id"] as! String) < ($1["id"] as! String) },
                "viewport": ["x": canvas.viewport.x, "y": canvas.viewport.y, "zoom": canvas.viewport.zoom],
                "activeZone": observedActiveZone, "documentActiveZone": documentActiveZone, "focus": focus]
        }
        var firstHydrated: [String: Any]?
        var bootSettled: [String: Any]?
        var visualEvidence: [[String: Any]] = []
        var visualCaptureFailures: [String] = []
        var visualCaptureSequence = 0
        func captureVisual(_ phase: String, appearanceName: NSAppearance.Name, slug: String) {
            guard ProcessInfo.processInfo.environment["CONTINUUM_WS2_CAPTURE_VISUALS"] == "1" else { return }
            visualCaptureSequence += 1
            let sequence = visualCaptureSequence
            let prior = canvas.appearance
            let priorViewport = canvas.viewport
            defer {
                canvas.setViewport(priorViewport)
                canvas.appearance = prior
                canvas.layoutSubtreeIfNeeded()
            }
            canvas.appearance = NSAppearance(named: appearanceName)

            // The persisted camera deliberately frames only the primary zone, so
            // capturing through it renders one zone against empty canvas and
            // proves nothing about topology. Fit the whole seeded scene for the
            // image, then restore the document camera in `defer` so every
            // viewport assertion still reads the persisted value. This fit is
            // evidence framing, never persisted state - it is recorded as
            // `cameraFit` so the image can never be misread as the saved camera.
            guard var fitted = canvas.fitAllToViewport() else {
                visualCaptureFailures.append("\(phase)-\(slug): no fitted camera for seeded scene")
                return
            }
            let visibleWorldWidth = canvas.bounds.width / fitted.zoom
            let visibleWorldHeight = canvas.bounds.height / fitted.zoom
            let centerWorldX = fitted.x + visibleWorldWidth / 2
            let centerWorldY = fitted.y + visibleWorldHeight / 2
            let margined = fitted.zoom * 0.88
            fitted = CanvasViewport(
                x: centerWorldX - canvas.bounds.width / margined / 2,
                y: centerWorldY - canvas.bounds.height / margined / 2,
                zoom: margined)
            canvas.setViewport(fitted)
            canvas.layoutSubtreeIfNeeded()

            guard let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: 3200, pixelsHigh: 2000,
                    bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                    colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0) else {
                visualCaptureFailures.append("\(phase)-\(slug): bitmap allocation")
                return
            }
            rep.size = NSSize(width: 1600, height: 1000)
            canvas.cacheDisplay(in: canvas.bounds, to: rep)

            // Every seeded zone must be COMPLETELY inside the raster with a real
            // margin. A rectangle that merely intersects the bounds is the
            // clipped-corner false-green this check was rejected for twice.
            let margin: CGFloat = 8
            let safe = canvas.bounds.insetBy(dx: margin, dy: margin)
            var expectedRects: [[String: Any]] = []
            var missing: [String] = []
            var clipped: [String] = []
            func requireInside(_ label: String, _ rect: CGRect?, minWidth: CGFloat, minHeight: CGFloat) {
                guard let rect else { missing.append(label); return }
                expectedRects.append(["label": label, "x": rect.minX, "y": rect.minY,
                    "width": rect.width, "height": rect.height, "insideSafeArea": safe.contains(rect)])
                if !safe.contains(rect) || rect.width < minWidth || rect.height < minHeight {
                    clipped.append("\(label)=\(rect)")
                }
            }
            requireInside("zone:A-primary", canvas.qaZoneChromeRectInCanvas(for: za1), minWidth: 120, minHeight: 90)
            requireInside("zone:A-lower-tier", canvas.qaZoneChromeRectInCanvas(for: za2), minWidth: 120, minHeight: 90)
            requireInside("zone:ambient", canvas.qaZoneChromeRectInCanvas(for: ambient), minWidth: 120, minHeight: 90)
            requireInside("tile:focused", canvas.qaTileRectInCanvas(for: ta1), minWidth: 24, minHeight: 16)
            // Tiles in zones below the live hydration tier legitimately have no
            // view; assert only the ones that are actually installed.
            for (label, id) in [("tile:retained-lower", ta2), ("tile:ambient", ambientTile)] {
                if let rect = canvas.qaTileRectInCanvas(for: id) {
                    requireInside(label, rect, minWidth: 24, minHeight: 16)
                }
            }
            guard missing.isEmpty, clipped.isEmpty else {
                visualCaptureFailures.append(
                    "\(phase)-\(slug): scene not completely framed missing=\(missing) clipped=\(clipped) bounds=\(canvas.bounds) camera=\(fitted)")
                return
            }

            let path = output.deletingLastPathComponent().appendingPathComponent("\(phase)-\(slug).png")
            guard let png = rep.representation(using: .png, properties: [:]) else {
                visualCaptureFailures.append("\(phase)-\(slug): PNG encoding")
                return
            }
            do { try png.write(to: path, options: .atomic) }
            catch {
                visualCaptureFailures.append("\(phase)-\(slug): PNG write \(error)")
                return
            }
            guard let bitmapData = rep.bitmapData else {
                visualCaptureFailures.append("\(phase)-\(slug): missing bitmap bytes")
                return
            }
            let byteCount = rep.bytesPerRow * rep.pixelsHigh
            let bytes = UnsafeBufferPointer(start: bitmapData, count: byteCount)
            let minimum = bytes.min() ?? 0
            let maximum = bytes.max() ?? 0

            // cacheDisplay writes row 0 at the top of the rep. Canvas points are
            // only top-left-origin when the view is flipped, so convert rather
            // than assume - a silently mirrored probe reads background as body.
            func rgba(at point: CGPoint) -> [Int] {
                let px = max(0, min(rep.pixelsWide - 1, Int(point.x * 2)))
                let canvasY = canvas.isFlipped ? point.y : (canvas.bounds.height - point.y)
                let py = max(0, min(rep.pixelsHigh - 1, Int(canvasY * 2)))
                let offset = py * rep.bytesPerRow + px * 4
                return (0..<4).map { Int(bitmapData[offset + $0]) }
            }
            let primaryZone = canvas.qaZoneChromeRectInCanvas(for: za1)!
            let lowerZone = canvas.qaZoneChromeRectInCanvas(for: za2)!
            let focusedTile = canvas.qaTileRectInCanvas(for: ta1)!
            let probes: [String: [Int]] = [
                "background": rgba(at: CGPoint(x: safe.minX + 2, y: safe.minY + 2)),
                "primaryZoneBorder": rgba(at: CGPoint(x: primaryZone.minX + 1, y: primaryZone.midY)),
                "primaryZoneHeader": rgba(at: CGPoint(x: primaryZone.midX, y: primaryZone.maxY - 6)),
                "primaryZoneBody": rgba(at: CGPoint(x: primaryZone.midX, y: primaryZone.midY)),
                "lowerZoneBody": rgba(at: CGPoint(x: lowerZone.midX, y: lowerZone.midY)),
                "tileBorder": rgba(at: CGPoint(x: focusedTile.minX + 1, y: focusedTile.midY)),
                "tileBody": rgba(at: CGPoint(x: focusedTile.midX, y: focusedTile.midY))]
            let distinctProbeColors = Set(probes.values.map { $0.map(String.init).joined(separator: ",") })
            if minimum == maximum || distinctProbeColors.count < 4 {
                visualCaptureFailures.append(
                    "\(phase)-\(slug): semantic raster probes lack background/border/body transitions probes=\(probes)")
                return
            }
            visualEvidence.append(["phase": phase, "appearance": slug, "path": path.path,
                "captureSequence": sequence, "lifecycleEvent": phase,
                "points": ["width": canvas.bounds.width, "height": canvas.bounds.height],
                "pixels": ["width": rep.pixelsWide, "height": rep.pixelsHigh],
                "backingScale": 2.0, "pixelMinimum": minimum, "pixelMaximum": maximum,
                "cameraFit": ["x": fitted.x, "y": fitted.y, "zoom": fitted.zoom,
                    "note": "evidence framing only; document camera restored after capture"],
                "documentCamera": ["x": priorViewport.x, "y": priorViewport.y, "zoom": priorViewport.zoom],
                "expectedRects": expectedRects, "safeArea": ["x": safe.minX, "y": safe.minY,
                    "width": safe.width, "height": safe.height],
                "semanticProbes": probes])
        }
        runtime.lifecycleSnapshotObserver = { event, _ in
            if event == .firstHydrationPhase {
                firstHydrated = try? snapshot("first-hydrated")
                captureVisual("first-hydrated", appearanceName: .aqua, slug: "aqua")
                captureVisual("first-hydrated", appearanceName: .darkAqua, slug: "dark-aqua")
            }
            if event == .settled {
                bootSettled = try? snapshot("settled")
                captureVisual("settled", appearanceName: .aqua, slug: "aqua")
                captureVisual("settled", appearanceName: .darkAqua, slug: "dark-aqua")
            }
        }
        try delegate.mountWorkspaceSceneAtBoot(canvasView: canvas, spawner: spawner, projectStore: bootStore,
            canvasState: bootState, installsGlobalEventMonitors: false)
        canvas.layoutSubtreeIfNeeded()
        if ProcessInfo.processInfo.environment["CONTINUUM_WS2_CAPTURE_VISUALS"] == "1" {
            guard visualCaptureFailures.isEmpty, visualEvidence.count == 4 else {
                throw Failure.message("offscreen visual capture failed: \(visualCaptureFailures), count=\(visualEvidence.count)")
            }
        }
        guard let firstHydrated, let bootSettled else { throw Failure.message("production hydration observations missing") }
        let firstViewport = firstHydrated["viewport"] as! [String: Double]
        guard firstViewport["x"] == initialDocument.viewport.x,
              firstViewport["y"] == initialDocument.viewport.y,
              firstViewport["zoom"] == initialDocument.viewport.zoom else {
            throw Failure.message("first hydration used project viewport instead of workspace viewport")
        }
        var switchSnapshots: [[String: Any]] = []
        var settled = try snapshot("settled")
        var mountedSceneContinuity = false
        var closeWitness: [String: Bool] = [:]
        var closeChronology: [String: Any] = [:]
        if mode == "seed-mutate-close" {
            // Keep switch coverage separate from the timed close witness. The
            // close clock starts only after returning to A and driving the live
            // mutation path below.
            switchSnapshots.append(try snapshot("A-before-switch"))
            try runtime.switchWorkspace(to: wb)
            switchSnapshots.append(try snapshot("B-after-switch"))
            try runtime.switchWorkspace(to: wa)
            switchSnapshots.append(try snapshot("A-after-return-before-mutation"))

            // Window construction/order is fixture setup, not close latency.
            // In particular the 0 ms leg has no work between the end of the
            // pending mutation and its first and only performClose request.
            let closeWindow = NSWindow(
                contentRect: NSRect(x: 0, y: 0, width: 640, height: 480),
                styleMask: [.titled, .closable], backing: .buffered, defer: false)
            closeWindow.isReleasedWhenClosed = false
            closeWindow.delegate = delegate
            delegate.window = closeWindow
            closeWindow.orderFront(nil)

            let mutationStartTick = DispatchTime.now().uptimeNanoseconds
            var placement = canvas.zonePlacement(for: za1)!
            placement.origin = .init(x: -1001.375, y: 333.625)
            placement.size = .init(width: 1111.75, height: 777.125)
            canvas.setZonePlacement(placement)
            // Geometry persistence is intentionally synchronous in production.
            canvas.onZoneMoved?(placement)
            canvas.setViewport(.init(x: -255.125, y: 144.875, zoom: 1.625))
            // Change arming via the real ambient path. This schedules the
            // runtime's long-lived arming controller and remains pending until
            // close drains it; viewport is captured by the departing write.
            _ = runtime.setActiveZone(za2, reason: .click)
            _ = delegate.qaFocusBroker.requestFocus(.tile(ta1), reason: .userClick)
            delegate.canvasDidChange(canvas)
            let scheduledGeneration = runtime.qaArmingScheduledGeneration
            let acknowledgedBeforeClose = runtime.qaArmingAcknowledgedGeneration
            guard scheduledGeneration > acknowledgedBeforeClose else {
                throw Failure.message("ambient arming save was not pending at mutation end")
            }
            settled = try snapshot("settled")
            switchSnapshots.append(settled.merging(["phase":"A-after-return-and-mutation"]) { _, new in new })
            // All fixture inspection is complete before this boundary. From
            // mutationEndTick onward the only operations are the requested
            // delay, the adjacent request timestamp, and performClose itself.
            let mutationEndTick = DispatchTime.now().uptimeNanoseconds
            if closeOffset > 0 { usleep(closeOffset * 1_000) }
            // Timestamp the actual request, immediately adjacent to it.
            let closeRequestTick = DispatchTime.now().uptimeNanoseconds
            closeWindow.performClose(nil)
            let acknowledgedGeneration = runtime.qaArmingAcknowledgedGeneration
            let closeCompleted = delegate.workspaceRuntime == nil && !closeWindow.isVisible
            guard closeCompleted else {
                throw Failure.message("timed close did not tear down exactly once")
            }
            closeWitness = ["timedCloseCompleted": closeCompleted]
            let elapsedMS = Double(closeRequestTick - mutationEndTick) / 1_000_000
            closeChronology = ["phase":"close-chronology", "requestedOffsetMs":closeOffset,
                "mutationStartTick":mutationStartTick, "mutationEndTick":mutationEndTick,
                "closeRequestTick":closeRequestTick, "observedElapsedMs":elapsedMS,
                "scheduledGeneration":scheduledGeneration,
                "acknowledgedGenerationAtMutationEnd":acknowledgedBeforeClose,
                "acknowledgedGenerationBeforeTeardown":acknowledgedGeneration,
                "departingWriteScheduledGeneration":runtime.qaLastScheduledWorkspaceGeneration,
                "departingWriteAcknowledgedGeneration":runtime.qaLastAcknowledgedWorkspaceGeneration]
        } else if mode == "failure-continuity" {
            // Fault continuity is intentionally untimed. It must never pollute
            // the mutation-to-close clock exercised by seed-mutate-close.
            func normalized(_ value: [String: Any]) throws -> Data {
                var copy = value
                copy["phase"] = nil
                return try JSONSerialization.data(withJSONObject: copy, options: [.sortedKeys])
            }
            let beforeFailedSwitch = try snapshot("before-failed-switch")
            runtime._workspaceDocumentSaver = { _, _ in throw Failure.message("injected departing save") }
            var switchFailed = false
            do { try runtime.switchWorkspace(to: wb) } catch { switchFailed = true }
            runtime._workspaceDocumentSaver = nil
            let afterFailedSwitch = try snapshot("after-failed-switch")
            let beforeFailedSwitchCanonical = try normalized(beforeFailedSwitch)
            let afterFailedSwitchCanonical = try normalized(afterFailedSwitch)
            mountedSceneContinuity = switchFailed
                && beforeFailedSwitchCanonical == afterFailedSwitchCanonical
            guard mountedSceneContinuity else {
                throw Failure.message("failed switch changed mounted scene")
            }

            let faultWindow = NSWindow(
                contentRect: NSRect(x: 0, y: 0, width: 640, height: 480),
                styleMask: [.titled, .closable], backing: .buffered, defer: false)
            faultWindow.isReleasedWhenClosed = false
            faultWindow.delegate = delegate
            delegate.window = faultWindow
            faultWindow.orderFront(nil)
            runtime._workspaceDocumentSaver = { _, _ in throw Failure.message("injected close save") }
            faultWindow.performClose(nil)
            let failedCloseVetoed = delegate.workspaceRuntime === runtime
                && faultWindow.delegate === delegate && faultWindow.isVisible
            runtime._workspaceDocumentSaver = nil
            faultWindow.performClose(nil)
            let recoveredCloseCompleted = delegate.workspaceRuntime == nil && !faultWindow.isVisible
            guard failedCloseVetoed && recoveredCloseCompleted else {
                throw Failure.message("failed close continuity/recovery mismatch")
            }
            closeWitness = ["failedCloseVetoed": failedCloseVetoed,
                "recoveredCloseCompleted": recoveredCloseCompleted]
        }
        let payload: [String: Any] = ["mode": mode, "closeOffsetMs": closeOffset, "readiness": readiness,
            "firstHydrated": firstHydrated, "bootSettled": bootSettled, "settled": settled,
            "mountedSceneContinuityOnSaveFailure": mountedSceneContinuity, "switchSnapshots": switchSnapshots,
            "closeWitness": closeWitness, "closeChronology": closeChronology,
            "visualEvidence": visualEvidence]
        try JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys]).write(to: output)
        print("WS2_ACK \(mode) \(output.path)")
    }

    static func runWorkspaceRestartFaultSelfCheck() throws -> URL {
        struct RestartFaultError: Error { let message: String }
        func expect(_ value: @autoclosure () -> Bool, _ message: String) throws {
            if !value() { throw RestartFaultError(message: message) }
        }
        let fm = FileManager.default
        guard let supportPath = ProcessInfo.processInfo.environment["CONTINUUM_APP_SUPPORT"], !supportPath.isEmpty else {
            throw RestartFaultError(message: "CONTINUUM_APP_SUPPORT must name the isolated root")
        }
        let support = URL(fileURLWithPath: supportPath, isDirectory: true)
            .appendingPathComponent("workspace-restart-fault", isDirectory: true)
        try? fm.removeItem(at: support)
        try fm.createDirectory(at: support, withIntermediateDirectories: true)
        let executable = URL(fileURLWithPath: CommandLine.arguments[0])
        func sha256(_ url: URL) throws -> String { SHA256.hash(data: try Data(contentsOf: url)).map { String(format: "%02x", $0) }.joined() }
        var repetitions: [[String: Any]] = []
        let repetitionCount = Int(ProcessInfo.processInfo.environment["CONTINUUM_WS2_REPETITIONS"] ?? "20") ?? 20
        let closeOffsets = ProcessInfo.processInfo.environment["CONTINUUM_WS2_CLOSE_OFFSETS"]
            .map { $0.split(separator: ",").compactMap { Int($0) } } ?? [0, 10, 50, 190]
        try expect(closeOffsets == [0, 10, 50, 190],
            "restart/fault offset inventory must be exactly 0/10/50/190, got \(closeOffsets)")
        for closeOffset in closeOffsets {
          for iteration in 1...repetitionCount {
            let root = support.appendingPathComponent("close-\(closeOffset)-iteration-\(iteration)", isDirectory: true)
            try fm.createDirectory(at: root, withIntermediateDirectories: true)
            var childResults: [[String: Any]] = []
            for mode in ["seed-mutate-close", "failure-continuity", "cold-reload"] {
                let output = root.appendingPathComponent("\(mode).json")
                let log = root.appendingPathComponent("\(mode).log")
                let process = Process(); process.executableURL = executable
                process.arguments = ["--workspace-restart-fault-child-check", "--mode", mode, "--output", output.path,
                    "--close-offset-ms", String(closeOffset)]
                var environment = ProcessInfo.processInfo.environment; environment["CONTINUUM_APP_SUPPORT"] = root.path
                if closeOffset == 0 && iteration == 1 && mode == "seed-mutate-close" {
                    environment["CONTINUUM_WS2_CAPTURE_VISUALS"] = "1"
                }
                process.environment = environment
                fm.createFile(atPath: log.path, contents: nil)
                let handle = try FileHandle(forWritingTo: log); process.standardOutput = handle; process.standardError = handle
                try process.run()
                let deadline = Date().addingTimeInterval(20)
                while process.isRunning && Date() < deadline { RunLoop.current.run(until: Date().addingTimeInterval(0.01)) }
                if process.isRunning { process.terminate(); process.waitUntilExit() }
                try handle.close()
                try expect(process.terminationStatus == 0, "iteration \(iteration) \(mode) child exit \(process.terminationStatus)")
                let object = try JSONSerialization.jsonObject(with: Data(contentsOf: output)) as! [String: Any]
                let readiness = object["readiness"] as! [String]
                try expect(readiness.contains(where: { $0.contains("bootMounted") }), "missing boot-mounted acknowledgement")
                try expect(readiness.contains(where: { $0.contains("firstHydrationPhase") }), "missing first-hydration acknowledgement")
                try expect(readiness.contains(where: { $0.contains("settled") }), "missing settled acknowledgement")
                childResults.append(["args": process.arguments ?? [], "exit": process.terminationStatus, "log": log.path,
                    "output": output.path, "outputSha256": try sha256(output), "readiness": readiness])
            }
            let seedObject = try JSONSerialization.jsonObject(with: Data(contentsOf: root.appendingPathComponent("seed-mutate-close.json"))) as! [String: Any]
            let failureObject = try JSONSerialization.jsonObject(with: Data(contentsOf: root.appendingPathComponent("failure-continuity.json"))) as! [String: Any]
            let reloadObject = try JSONSerialization.jsonObject(with: Data(contentsOf: root.appendingPathComponent("cold-reload.json"))) as! [String: Any]
            try expect(failureObject["mountedSceneContinuityOnSaveFailure"] as? Bool == true,
                "iteration \(iteration) failed switch changed mounted scene")
            let faultClose = failureObject["closeWitness"] as! [String: Bool]
            try expect(faultClose["failedCloseVetoed"] == true && faultClose["recoveredCloseCompleted"] == true,
                "iteration \(iteration) failed-close continuity/recovery mismatch")
            let chronology = seedObject["closeChronology"] as! [String: Any]
            let elapsed = chronology["observedElapsedMs"] as! Double
            let scheduled = chronology["scheduledGeneration"] as! UInt64
            let acknowledgedAtMutation = chronology["acknowledgedGenerationAtMutationEnd"] as! UInt64
            let acknowledged = chronology["acknowledgedGenerationBeforeTeardown"] as! UInt64
            try expect(elapsed >= Double(closeOffset) && elapsed <= Double(closeOffset + 50),
                "iteration \(iteration) close chronology outside tolerance requested=\(closeOffset) observed=\(elapsed)")
            try expect(scheduled > acknowledgedAtMutation && acknowledged == scheduled,
                "iteration \(iteration) close did not acknowledge scheduled generation \(scheduled)/\(acknowledged)")
            try expect(chronology["departingWriteScheduledGeneration"] as! UInt64
                    == chronology["departingWriteAcknowledgedGeneration"] as! UInt64,
                "iteration \(iteration) final departing-document generation was not acknowledged")
            let switched = seedObject["switchSnapshots"] as! [[String: Any]]
            func canonical(_ value: [String: Any]) throws -> Data {
                var normalized = value; normalized["phase"] = nil
                return try JSONSerialization.data(withJSONObject: normalized, options: [.sortedKeys])
            }
            try expect(switched.count == 4, "iteration \(iteration) missing A-B-A plus mutated snapshots")
            let beforeSwitchCanonical = try canonical(switched[0])
            let afterReturnCanonical = try canonical(switched[2])
            try expect(beforeSwitchCanonical == afterReturnCanonical, "iteration \(iteration) A-before/A-after canonical diff")
            let returned = switched.last!
            let cold = reloadObject["settled"] as! [String: Any]
            let lhsData = try canonical(returned)
            let rhsData = try canonical(cold)
            try expect(lhsData == rhsData, "iteration \(iteration) canonical cold diff")
            let expectedAIds = Set(["71000000-0000-0000-0000-000000000031", "71000000-0000-0000-0000-000000000032", "71000000-0000-0000-0000-000000000034"])
            for phase in [switched[0], switched[2], cold] {
                let phaseTiles = phase["tiles"] as! [[String: Any]]
                let ids = Set(phaseTiles.map { $0["id"] as! String })
                try expect(ids == expectedAIds, "iteration \(iteration) phase tile inventory mismatch: \(ids)")
                let sourceByID = Dictionary(uniqueKeysWithValues: phaseTiles.map {
                    ($0["id"] as! String, $0["source"] as! String)
                })
                try expect(sourceByID["71000000-0000-0000-0000-000000000031"] == "live",
                    "iteration \(iteration) hydrated sentinel was not observed live")
                try expect(sourceByID["71000000-0000-0000-0000-000000000032"] == "retained",
                    "iteration \(iteration) lower-tier retained contract changed")
                try expect(sourceByID["71000000-0000-0000-0000-000000000034"] == "live",
                    "iteration \(iteration) hydrated ambient tile was not observed live")
            }
            repetitions.append(["iteration": iteration, "closeOffsetMs": closeOffset,
                "children": childResults, "canonicalDiff": [], "inputSha256": try sha256(root.appendingPathComponent("seed-mutate-close.json")),
                "outputSha256": try sha256(root.appendingPathComponent("cold-reload.json"))])
          }
        }

        let zoneId = UUID(uuidString: "72000000-0000-0000-0000-000000000002")!
        let valid = WorkspaceDocument(
            viewport: CanvasViewport(x: 1, y: 2, zoom: 1.25), zones: [], lastActiveZoneId: nil)
        let replacement = WorkspaceDocument(
            viewport: CanvasViewport(x: -9, y: 12, zoom: 2.5), zones: [], lastActiveZoneId: zoneId)
        var faultResults: [[String: Any]] = []
        for seam in ["temporary-write", "temp-fsync", "temp-close", "atomic-rename",
                     "directory-open", "directory-fsync", "directory-close", "permission-denied"] {
            let root = support.appendingPathComponent("fault-\(seam)", isDirectory: true)
            let workspaceId = UUID(uuidString: "72000000-0000-0000-0000-000000000001")!
            let normal = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root)
            try normal.save(valid)
            let before = try Data(contentsOf: normal.layout.canvasFile)
            final class Counter: @unchecked Sendable { var opens = 0; var closes = 0 }
            let counter = Counter()
            let descriptors = AtomicWriterDescriptorOperations(open: { path, flags in
                counter.opens += 1
                if seam == "directory-open" && counter.opens == 2 { errno = EIO; return -1 }
                return Darwin.open(path, flags)
            }, fsync: { fd in
                if seam == "temp-fsync" && counter.opens == 1 { errno = EIO; return -1 }
                if seam == "directory-fsync" && counter.opens == 2 { errno = EIO; return -1 }
                return Darwin.fsync(fd)
            }, close: { fd in
                counter.closes += 1
                if seam == "temp-close" && counter.opens == 1 { errno = EINTR; _ = Darwin.close(fd); return -1 }
                if seam == "directory-close" && counter.opens == 2 { errno = EIO; _ = Darwin.close(fd); return -1 }
                return Darwin.close(fd)
            })
            let files = AtomicWriterFileOperations(writeTemporary: { data, url in
                if seam == "temporary-write" { throw POSIXError(.EIO) }
                if seam == "permission-denied" { throw POSIXError(.EACCES) }
                try data.write(to: url)
            }, replace: { source, destination in
                if seam == "atomic-rename" { throw POSIXError(.EXDEV) }
                if Darwin.rename(source.path, destination.path) != 0 { throw POSIXError(.EIO) }
            })
            let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
                descriptorOperations: descriptors, fileOperations: files)
            let controller = WorkspaceDocumentSaveController(store: store)
            let generation = controller.scheduleZoneLayoutSave(replacement)
            var failed = false
            do { try controller.flush(through: generation) } catch { failed = true }
            let after = try Data(contentsOf: normal.layout.canvasFile)
            if seam == "directory-close" {
                let closeFaultReload = try normal.load()
                try expect(!failed && controller.state == .saved,
                    "post-commit directory close noise became save failure")
                try expect(controller.acknowledgedGeneration == generation,
                    "post-commit directory close did not acknowledge generation")
                try expect(after != before && closeFaultReload == replacement,
                    "post-commit directory close did not preserve cold truth")
            } else {
                try expect(failed, "\(seam) did not fail")
                try expect(controller.state == .saveFailed, "\(seam) did not expose failure")
                try expect(controller.acknowledgedGeneration < generation, "\(seam) falsely advanced generation")
                try expect(after == before, "\(seam) changed prior bytes")
                _ = try normal.load()
            }
            if seam == "temp-close" {
                try expect(counter.closes == 1, "close EINTR was blindly retried")
            }
            let recovery = WorkspaceDocumentSaveController(store: normal)
            let recoveryGeneration = recovery.scheduleZoneLayoutSave(replacement)
            try recovery.flush(through: recoveryGeneration)
            let recoveredDocument = try normal.load()
            try expect(recoveredDocument == replacement, "\(seam) recovery failed")
            faultResults.append(["seam": seam, "priorValidByteExact": seam != "directory-close",
                "loadable": true, "successReported": seam == "directory-close", "failedGeneration": generation,
                "acknowledgedGeneration": controller.acknowledgedGeneration, "recoveryGeneration": recoveryGeneration,
                "mountedSceneUnchanged": seam != "directory-close", "closeAttempts": counter.closes])
        }

        // Post-commit maintenance is not part of acknowledgement. Enumeration
        // failure after the target rename+directory fsync must leave the new
        // durable document loadable and report success.
        do {
            let root = support.appendingPathComponent("fault-post-commit-prune", isDirectory: true)
            let workspaceId = UUID(uuidString: "72000000-0000-0000-0000-000000000011")!
            let normal = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root)
            try normal.save(valid)
            let files = AtomicWriterFileOperations(listDirectory: { _ in throw POSIXError(.EIO) })
            let maintenanceFault = WorkspaceStore(
                workspaceId: workspaceId, applicationSupportDirectory: root, fileOperations: files)
            try maintenanceFault.save(replacement)
            let maintenanceReload = try normal.load()
            try expect(maintenanceReload == replacement, "post-commit prune failure changed acknowledgement truth")
            faultResults.append(["seam": "post-commit-prune", "successReported": true,
                "loadable": true, "maintenanceFailureNonTransactional": true])
        }

        // True cross-process writers have independent in-memory counters. Pin
        // their backup clocks to the same millisecond and prove a collision is
        // preserved with distinct history and newest-first retention ordering.
        do {
            let root = support.appendingPathComponent("fault-backup-name-collision", isDirectory: true)
            let workspaceId = UUID(uuidString: "72000000-0000-0000-0000-000000000017")!
            let fixedDate = Date(timeIntervalSince1970: 1_900_000_000.123)
            let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
                retainedBackups: 4, backupDate: { fixedDate })
            try store.save(valid)
            try store.save(replacement) // process-local suffix 1
            for childGeneration in [201, 202, 203] {
                let process = Process()
                process.executableURL = URL(fileURLWithPath: CommandLine.arguments[0])
                process.arguments = ["--atomic-writer-lock-child", "--support", root.path,
                    "--workspace-id", workspaceId.uuidString, "--fixed-backup-date",
                    "--generation", String(childGeneration)]
                try process.run(); process.waitUntilExit()
                try expect(process.terminationStatus == 0, "backup collision child failed")
            }
            let backups = try FileManager.default.contentsOfDirectory(
                at: store.layout.backupsDirectory, includingPropertiesForKeys: nil)
                .filter { $0.lastPathComponent.hasPrefix("array-backup-v2-") }
                .sorted { $0.lastPathComponent > $1.lastPathComponent }
            try expect(backups.count == 4, "same-timestamp backup collision lost or overwrote history")
            let backupDocuments: [WorkspaceDocument] = try backups.map {
                try JSONDecoder().decode(WorkspaceDocument.self, from: Data(contentsOf: $0))
            }
            try expect(backupDocuments.map(\.viewport.x) == [202, 201, -9, 1],
                "same-timestamp backup retention/order was not newest-first and byte-distinct")
            let collisionReload = try store.load()
            try expect(collisionReload.viewport.x == 203,
                "latest cross-process collision writer was not durable truth")
            faultResults.append(["seam": "cross-process-same-timestamp-backups",
                "successReported": true, "backupCount": backups.count,
                "orderedViewportX": backupDocuments.map(\.viewport.x),
                "existingBackupNeverOverwritten": true])
        }

        // Identical predecessor/candidate witness: T3 -> T1 -> T2 must order by
        // durable on-disk generation, not timestamp. With retention two, corrupt
        // primary D3 recovers D2, the newest prior generation.
        do {
            let root = support.appendingPathComponent("fault-backward-clock", isDirectory: true)
            let workspaceId = UUID(uuidString: "72000000-0000-0000-0000-000000000018")!
            let dates = [1_900_000_300.0, 1_900_000_100.0, 1_900_000_200.0]
            let documents = [valid,
                WorkspaceDocument(viewport: .init(x: 301, y: 0, zoom: 1), zones: [], lastActiveZoneId: nil),
                WorkspaceDocument(viewport: .init(x: 302, y: 0, zoom: 1), zones: [], lastActiveZoneId: nil),
                WorkspaceDocument(viewport: .init(x: 303, y: 0, zoom: 1), zones: [], lastActiveZoneId: nil)]
            try WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
                retainedBackups: 2).save(documents[0])
            for index in 0..<3 {
                let writer = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
                    retainedBackups: 2, backupDate: { Date(timeIntervalSince1970: dates[index]) })
                try writer.save(documents[index + 1])
            }
            let layout = WorkspaceStoreLayout(applicationSupportDirectory: root, workspaceId: workspaceId)
            let names = try FileManager.default.contentsOfDirectory(atPath: layout.backupsDirectory.path).sorted()
            try expect(names.count == 2 && names.contains { $0.contains("00000000000000000002") }
                && names.contains { $0.contains("00000000000000000003") },
                "backward clock did not retain exact generations 2 and 3")
            try Data("corrupt".utf8).write(to: layout.canvasFile)
            let recovered: WorkspaceDocument = try AtomicWriter(
                backupsDirectory: layout.backupsDirectory, retainedBackups: 2,
                legacyBackupPolicy: .targetDedicated).read(at: layout.canvasFile)
            try expect(recovered == documents[2], "backward clock recovery did not choose D2")
            faultResults.append(["seam":"backward-clock-generations", "dates":dates,
                "writeBytesX":[301,302,303], "retainedGenerations":[3,2],
                "primaryBeforeCorruption":303, "recoveryChoice":302, "filenames":names])
        }

        // Legacy names remain behind all v2 generations, while malformed and
        // similarly-prefixed targets are excluded exactly.
        do {
            let root = support.appendingPathComponent("fault-legacy-target-isolation", isDirectory: true)
            let backups = root.appendingPathComponent("shared-backups", isDirectory: true)
            try FileManager.default.createDirectory(at: backups, withIntermediateDirectories: true)
            let target = root.appendingPathComponent("canvas.prod.json")
            let other = root.appendingPathComponent("canvas.prod.extra.json")
            let dLegacy1 = WorkspaceDocument(viewport:.init(x:401,y:0,zoom:1),zones:[],lastActiveZoneId:nil)
            let dLegacy2 = WorkspaceDocument(viewport:.init(x:402,y:0,zoom:1),zones:[],lastActiveZoneId:nil)
            let encoder = JSONCodec.makeEncoder(prettyPrinted: true)
            try encoder.encode(dLegacy1).write(to: backups.appendingPathComponent("canvas.prod.2030-01-01T00-00-00.000Z.000001.json"))
            try encoder.encode(dLegacy2).write(to: backups.appendingPathComponent("canvas.prod.2031-01-01T00-00-00.000Z.000002.json"))
            try encoder.encode(dLegacy1).write(to: backups.appendingPathComponent("canvas.prod.extra.2099-01-01T00-00-00.000Z.000999.json"))
            try encoder.encode(dLegacy1).write(to: backups.appendingPathComponent("array-backup-v2-00-malformed"))
            let writer = AtomicWriter(backupsDirectory: backups, retainedBackups: 3,
                backupDate: { Date(timeIntervalSince1970: 1_000) }, legacyBackupPolicy: .targetDedicated)
            try encoder.encode(valid).write(to: target)
            try writer.write(replacement, to: target)
            try encoder.encode(valid).write(to: other)
            try AtomicWriter(backupsDirectory: backups, retainedBackups: 3).write(dLegacy1, to: other)
            try Data("corrupt".utf8).write(to: target)
            let recovered: WorkspaceDocument = try writer.read(at: target)
            try expect(recovered == valid, "new generation did not sort ahead of legacy corpus")
            let targetRecovery: WorkspaceDocument = try AtomicWriter(backupsDirectory: backups).read(at: target)
            try expect(targetRecovery == valid, "similarly-prefixed target entered recovery")
            let legacyOnly = root.appendingPathComponent("archive.json")
            try encoder.encode(dLegacy1).write(to: backups.appendingPathComponent("archive.2030-01-01T00-00-00.000Z.000001.json"))
            try encoder.encode(dLegacy2).write(to: backups.appendingPathComponent("archive.2031-01-01T00-00-00.000Z.000002.json"))
            try Data("corrupt".utf8).write(to: legacyOnly)
            let legacyRecovered: WorkspaceDocument = try AtomicWriter(
                backupsDirectory: backups, retainedBackups: 2,
                legacyBackupPolicy: .targetDedicated).read(at: legacyOnly)
            try expect(legacyRecovered == dLegacy2, "legacy newest-first recovery changed")
            try encoder.encode(valid).write(to: legacyOnly)
            let legacyAger = AtomicWriter(backupsDirectory: backups, retainedBackups: 2,
                legacyBackupPolicy: .targetDedicated)
            try legacyAger.write(dLegacy1, to: legacyOnly)
            try legacyAger.write(dLegacy2, to: legacyOnly)
            let archiveEntries = try FileManager.default.contentsOfDirectory(atPath: backups.path)
                .filter { $0.hasPrefix("archive.") }
            try expect(archiveEntries.isEmpty, "legacy entries did not age out under normal retention")
            faultResults.append(["seam":"legacy-and-target-isolation", "legacyRecoverable":true,
                "newAheadOfLegacy":true, "legacyNewestChoice":402, "legacyAgedOut":true,
                "dottedTargetExact":true, "malformedExcluded":true])
        }

        // Alternating extreme clock jumps cannot perturb generation retention.
        do {
            let root = support.appendingPathComponent("fault-alternating-clock", isDirectory: true)
            let workspaceId = UUID(uuidString: "72000000-0000-0000-0000-000000000019")!
            let layout = WorkspaceStoreLayout(applicationSupportDirectory: root, workspaceId: workspaceId)
            let canonical = URL(fileURLWithPath: AtomicWriter.stablePrivatePrefix(
                layout.canvasFile.deletingLastPathComponent().resolvingSymlinksInPath().path))
                .appendingPathComponent(layout.canvasFile.lastPathComponent)
            let identity = SHA256.hash(data: Data(canonical.path.utf8)).map { String(format:"%02x",$0) }.joined()
            let prefix = "array-backup-v2-\(identity)-"
            try WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
                retainedBackups: 3).save(valid)
            let dates = [4_000_000_000.0, 10.0, 3_900_000_000.0, 20.0, 3_800_000_000.0, 30.0]
            var states: [[String:Any]] = []
            for (index, epoch) in dates.enumerated() {
                let document = WorkspaceDocument(viewport:.init(x:Double(500 + index),y:0,zoom:1),zones:[],lastActiveZoneId:nil)
                try WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
                    retainedBackups: 3, backupDate: { Date(timeIntervalSince1970:epoch) }).save(document)
                let names = try FileManager.default.contentsOfDirectory(atPath: layout.backupsDirectory.path).sorted()
                let generations = names.compactMap { name -> Int? in
                    guard name.hasPrefix(prefix) else { return nil }
                    return Int(name.dropFirst(prefix.count).prefix(20))
                }.sorted()
                let expectedGenerations = Array(max(1, index - 1)...(index + 1))
                try expect(generations == expectedGenerations,
                    "alternating clock retained wrong generations \(generations), expected \(expectedGenerations); prefix=\(prefix) canonical=\(canonical.path) names=\(names)")
                states.append(["write":index+1,"epoch":epoch,"retainedCount":names.count,
                    "primaryX":500+index,"retainedGenerations":generations])
            }
            faultResults.append(["seam":"alternating-clock-retention", "states":states,
                "retention":3, "generationAuthoritative":true])
        }

        // Generation overflow fails before replacement. Malformed tokens do not
        // inflate the sequence; a committed primary remains exact.
        do {
            let root = support.appendingPathComponent("fault-generation-overflow", isDirectory: true)
            let backups = root.appendingPathComponent("backups", isDirectory: true)
            let target = root.appendingPathComponent("overflow.json")
            try FileManager.default.createDirectory(at: backups, withIntermediateDirectories: true)
            try JSONCodec.makeEncoder(prettyPrinted:true).encode(valid).write(to: target)
            let canonical = target.deletingLastPathComponent().standardizedFileURL
                .resolvingSymlinksInPath().appendingPathComponent(target.lastPathComponent)
            let identity = SHA256.hash(data: Data(canonical.path.utf8)).map { String(format:"%02x",$0) }.joined()
            let malformed = [
                "array-backup-v2-\(identity)-18446744073709551615-2030-01-01T00-00-00.000Z-junk",
                "array-backup-v2-\(identity)-1844674407370955161-2030-01-01T00-00-00.000Z",
                "array-backup-v2-\(identity)-184467440737095516150-2030-01-01T00-00-00.000Z",
                "array-backup-v2-\(identity)-18446744073709551615-not-a-timestamp",
                "array_backup_v2-\(identity)-18446744073709551615-2030-01-01T00-00-00.000Z",
                "array-backup-v2-\(identity.uppercased())-00000000000000000042-2030-01-01T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2023-02-29T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-02-30T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-02-31T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-04-31T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-06-31T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-09-31T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-11-31T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-00-01T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-13-01T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-00T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-32T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-01T24-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-01T00-60-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-01T00-00-60.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-026-01-01T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-02026-01-01T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-01T00-00-00.00Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-01T00-00-00.0000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026_01_01T00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-01t00-00-00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-01T00:00:00.000Z",
                "array-backup-v2-\(identity)-00000000000000000042-2026-01-01T00-00-00.000z"
            ]
            for name in malformed { try Data("junk".utf8).write(to: backups.appendingPathComponent(name)) }
            try AtomicWriter(backupsDirectory: backups, retainedBackups: 4,
                backupDate: { Date(timeIntervalSince1970: 1_000) }).write(replacement, to: target)
            // Was a force-unwrap plus a magic `dropLast(45)`. A change to the v2
            // naming scheme trapped the process (exit 133) instead of reporting a
            // failed assertion, and a change to the timestamp format would have
            // built a garbage fixture and asserted against it silently.
            let generationOnePrefix = "array-backup-v2-\(identity)-00000000000000000001-"
            guard let generated = try FileManager.default.contentsOfDirectory(atPath: backups.path)
                .first(where: { $0.hasPrefix(generationOnePrefix) }) else {
                throw RestartFaultError(message: "the writer produced no generation-1 v2 backup for this target; "
                    + "the naming scheme changed. Directory holds "
                    + "\(try FileManager.default.contentsOfDirectory(atPath: backups.path))")
            }
            let generatedTimestamp = String(generated.dropFirst(generationOnePrefix.count))
            try expect(generatedTimestamp.count == 24 && generatedTimestamp.hasSuffix("Z"),
                "the derived max-generation fixture assumes a 24-character Z-suffixed timestamp; "
                + "the writer emitted \(generatedTimestamp.count) characters (\(generatedTimestamp))")
            let maxName = String(generationOnePrefix.dropLast("00000000000000000001-".count))
                + "18446744073709551615-2030-01-01T00-00-00.000Z"
            try Data("sentinel".utf8).write(to: backups.appendingPathComponent(maxName))
            try expect(FileManager.default.fileExists(atPath: backups.appendingPathComponent(maxName).path)
                && maxName.contains(identity), "valid exact-ID max fixture was not constructed")
            let overflowWriter = AtomicWriter(backupsDirectory: backups)
            let validLeap = "array-backup-v2-\(identity)-00000000000000000042-2024-02-29T00-00-00.000Z"
            try expect(overflowWriter.validBackupGeneration(named: validLeap, for: target) == 42,
                "strict production parser rejected valid Gregorian leap day")
            try expect(malformed.allSatisfy { overflowWriter.validBackupGeneration(named: $0, for: target) == nil },
                "strict production parser accepted malformed identity/generation/calendar input")
            try expect(overflowWriter.validBackupGeneration(named: maxName, for: target) == UInt64.max,
                "production parser did not classify the derived valid-max fixture")
            var overflowed = false
            do { try overflowWriter.write(replacement, to: target) }
            catch { overflowed = true }
            let primary: WorkspaceDocument = try JSONCodec.makeDecoder().decode(
                WorkspaceDocument.self, from: Data(contentsOf: target))
            try expect(overflowed && primary == replacement,
                "generation overflow did not fail closed overflowed=\(overflowed) primaryX=\(primary.viewport.x)")
            faultResults.append(["seam":"generation-overflow", "successReported":false,
                "primaryByteTruth":"replacement", "malformedLookalikesIgnored":malformed.count,
                "existingBackupPreserved":true])
        }

        // Same basename under different canonical parents shares neither lock
        // nor backup namespace, even with one shared backup directory.
        do {
            let root = support.appendingPathComponent("fault-canonical-target-namespace", isDirectory:true)
            let shared = root.appendingPathComponent("shared", isDirectory:true)
            let a = root.appendingPathComponent("a/canvas.ü.json")
            let b = root.appendingPathComponent("b/canvas.ü.json")
            try FileManager.default.createDirectory(at: a.deletingLastPathComponent(), withIntermediateDirectories:true)
            try FileManager.default.createDirectory(at: b.deletingLastPathComponent(), withIntermediateDirectories:true)
            let encoder = JSONCodec.makeEncoder(prettyPrinted:true)
            try encoder.encode(valid).write(to:a); try encoder.encode(replacement).write(to:b)
            let wa = AtomicWriter(backupsDirectory:shared, retainedBackups:3,
                backupDate:{ Date(timeIntervalSince1970:1_900_000_000) })
            let wb = AtomicWriter(backupsDirectory:shared, retainedBackups:3,
                backupDate:{ Date(timeIntervalSince1970:1_900_000_000) })
            let da = WorkspaceDocument(viewport:.init(x:701,y:0,zoom:1),zones:[],lastActiveZoneId:nil)
            let db = WorkspaceDocument(viewport:.init(x:702,y:0,zoom:1),zones:[],lastActiveZoneId:nil)
            let group = DispatchGroup(); final class Errors: @unchecked Sendable { let lock=NSLock(); var values:[Error]=[] }
            let errors=Errors()
            group.enter(); DispatchQueue.global().async { defer { group.leave() }; do { try wa.write(da,to:a) } catch { errors.lock.lock(); errors.values.append(error); errors.lock.unlock() } }
            group.enter(); DispatchQueue.global().async { defer { group.leave() }; do { try wb.write(db,to:b) } catch { errors.lock.lock(); errors.values.append(error); errors.lock.unlock() } }
            try expect(group.wait(timeout:.now()+5) == .success && errors.values.isEmpty,
                "same-basename canonical targets collided")
            try Data("corrupt".utf8).write(to:a); try Data("corrupt".utf8).write(to:b)
            let ra:WorkspaceDocument = try wa.read(at:a); let rb:WorkspaceDocument = try wb.read(at:b)
            try expect(ra == valid && rb == replacement, "same-basename targets cross-recovered")
            let names = try FileManager.default.contentsOfDirectory(atPath:shared.path)
            let namespaces = Set(names.compactMap { $0.split(separator:"-").dropFirst(3).first.map(String.init) })
            try expect(names.count == 2 && namespaces.count == 2, "canonical namespace IDs were not independent")
            faultResults.append(["seam":"canonical-target-namespace", "namespaceCount":namespaces.count,
                "concurrent":true,"sameBasename":true,"independentRecovery":[1,-9]])
        }

        do {
            let root = support.appendingPathComponent("fault-ambiguous-legacy", isDirectory:true)
            let shared = root.appendingPathComponent("shared", isDirectory:true)
            let target = root.appendingPathComponent("parent/canvas.json")
            try FileManager.default.createDirectory(at: shared, withIntermediateDirectories:true)
            try FileManager.default.createDirectory(at: target.deletingLastPathComponent(), withIntermediateDirectories:true)
            try Data("corrupt".utf8).write(to: target)
            try JSONCodec.makeEncoder(prettyPrinted:true).encode(valid).write(
                to: shared.appendingPathComponent("canvas.2030-01-01T00-00-00.000Z.000001.json"))
            var failedClosed = false
            do { let _:WorkspaceDocument = try AtomicWriter(backupsDirectory:shared).read(at:target) }
            catch AtomicWriterError.noValidBackup { failedClosed = true }
            try expect(failedClosed, "ambiguous shared-directory legacy cross-recovered")
            faultResults.append(["seam":"ambiguous-legacy-policy","policy":"disabled","failedClosed":true])
        }

        // An unreadable existing target is not the same state as ENOENT. It is
        // rejected before replacement, leaving the prior bytes exact.
        do {
            let root = support.appendingPathComponent("fault-unreadable-prior", isDirectory: true)
            let workspaceId = UUID(uuidString: "72000000-0000-0000-0000-000000000012")!
            let normal = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root)
            try normal.save(valid)
            let before = try Data(contentsOf: normal.layout.canvasFile)
            let files = AtomicWriterFileOperations(readExisting: { _ in throw POSIXError(.EACCES) })
            let unreadable = WorkspaceStore(
                workspaceId: workspaceId, applicationSupportDirectory: root, fileOperations: files)
            do { try unreadable.save(replacement); throw RestartFaultError(message: "unreadable prior unexpectedly saved") }
            catch AtomicWriterError.priorTargetUnreadable {}
            let unreadableAfter = try Data(contentsOf: normal.layout.canvasFile)
            try expect(unreadableAfter == before,
                "unreadable prior target was mutated")
            faultResults.append(["seam": "unreadable-prior", "successReported": false,
                "priorValidByteExact": true, "loadable": true])
        }

        // No-prior rollback removes the unacknowledged rename and durably syncs
        // that removal. A physical rollback failure is surfaced distinctly as
        // indeterminate rather than claiming ordinary byte-exact failure.
        for rollbackRemovalFails in [false, true] {
            let root = support.appendingPathComponent(
                rollbackRemovalFails ? "fault-rollback-removal" : "fault-no-prior-rollback", isDirectory: true)
            let workspaceId = UUID(uuidString: rollbackRemovalFails
                ? "72000000-0000-0000-0000-000000000013"
                : "72000000-0000-0000-0000-000000000014")!
            final class OpenCounter: @unchecked Sendable { var value = 0 }
            let opens = OpenCounter()
            let descriptors = AtomicWriterDescriptorOperations(open: { path, flags in
                opens.value += 1; return Darwin.open(path, flags)
            }, fsync: { fd in
                if opens.value == 2 { errno = EIO; return -1 }
                return Darwin.fsync(fd)
            })
            let files = AtomicWriterFileOperations(remove: { url in
                if rollbackRemovalFails { throw POSIXError(.EACCES) }
                try FileManager.default.removeItem(at: url)
            })
            let store = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
                descriptorOperations: descriptors, fileOperations: files)
            var caught: Error?
            do { try store.save(replacement) } catch { caught = error }
            if rollbackRemovalFails {
                try expect(caught as? AtomicWriterError == .rollbackIndeterminate,
                    "rollback operation failure was not classified indeterminate")
            } else {
                try expect(caught != nil && !FileManager.default.fileExists(atPath: store.layout.canvasFile.path),
                    "no-prior rollback did not remove the unacknowledged target")
            }
            faultResults.append(["seam": rollbackRemovalFails ? "rollback-removal" : "no-prior-rollback",
                "successReported": false, "indeterminate": rollbackRemovalFails])
        }

        // Cross-process semantics are provided by the same-volume flock. This
        // deterministic two-writer schedule proves B cannot enter while A is
        // paused after rename, and that B's later acknowledged bytes win after
        // A rolls back and releases the target lock.
        do {
            let root = support.appendingPathComponent("fault-concurrent-writers", isDirectory: true)
            let workspaceId = UUID(uuidString: "72000000-0000-0000-0000-000000000015")!
            let normal = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root)
            try normal.save(valid)
            let aAtDirectorySync = DispatchSemaphore(value: 0)
            let releaseA = DispatchSemaphore(value: 0)
            let bFinished = DispatchSemaphore(value: 0)
            final class ConcurrentOutcome: @unchecked Sendable {
                let lock = NSLock(); var aFailed = false; var bSucceeded = false; var opens = 0; var events: [String] = []
                func nextOpen() -> Int { lock.lock(); defer { lock.unlock() }; opens += 1; return opens }
                func openCount() -> Int { lock.lock(); defer { lock.unlock() }; return opens }
                func mark(_ event: String) { lock.lock(); events.append(event); lock.unlock() }
                func setA() { lock.lock(); aFailed = true; events.append("A-failed-after-rollback"); lock.unlock() }
                func setB() { lock.lock(); bSucceeded = true; events.append("B-acknowledged"); lock.unlock() }
                func snapshot() -> [String] { lock.lock(); defer { lock.unlock() }; return events }
            }
            let outcome = ConcurrentOutcome()
            let aDescriptors = AtomicWriterDescriptorOperations(open: { path, flags in
                _ = outcome.nextOpen(); return Darwin.open(path, flags)
            }, fsync: { fd in
                if outcome.openCount() == 2 {
                    outcome.mark("A-post-rename")
                    aAtDirectorySync.signal(); _ = releaseA.wait(timeout: .now() + 5)
                    errno = EIO; return -1
                }
                return Darwin.fsync(fd)
            })
            let writerA = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
                descriptorOperations: aDescriptors)
            let writerB = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root)
            DispatchQueue.global().async {
                do { try writerA.save(replacement) } catch { outcome.setA() }
            }
            try expect(aAtDirectorySync.wait(timeout: .now() + 5) == .success,
                "writer A never reached post-rename directory sync")
            outcome.mark("B-attempted")
            let finalB = WorkspaceDocument(
                viewport: .init(x: 77, y: 88, zoom: 1.1), zones: [], lastActiveZoneId: nil)
            DispatchQueue.global().async {
                do { try writerB.save(finalB); outcome.setB() } catch {}
                bFinished.signal()
            }
            try expect(bFinished.wait(timeout: .now() + 0.05) == .timedOut,
                "writer B entered the same-target transaction while writer A held the lock")
            releaseA.signal()
            try expect(bFinished.wait(timeout: .now() + 5) == .success,
                "writer B did not finish after writer A released the lock")
            let concurrentReload = try normal.load()
            try expect(outcome.aFailed && outcome.bSucceeded && concurrentReload == finalB,
                "concurrent writer acknowledgement was clobbered by rollback")
            faultResults.append(["seam": "concurrent-writers", "writerAFailed": true,
                "writerBSucceeded": true, "acknowledgedWinnerReloaded": true,
                "orderedEvents": outcome.snapshot()])
        }

        // Repeat the lock contention with a separate process. The child cannot
        // pass the fcntl lock while this process is paused post-rename.
        do {
            let root = support.appendingPathComponent("fault-cross-process-writers", isDirectory: true)
            let workspaceId = UUID(uuidString: "72000000-0000-0000-0000-000000000016")!
            let normal = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root)
            try normal.save(valid)
            let atSync = DispatchSemaphore(value: 0), release = DispatchSemaphore(value: 0)
            final class CrossState: @unchecked Sendable {
                let lock = NSLock(); var opens = 0; var failed = false
                func next() -> Int { lock.lock(); defer { lock.unlock() }; opens += 1; return opens }
                func count() -> Int { lock.lock(); defer { lock.unlock() }; return opens }
                func markFailed() { lock.lock(); failed = true; lock.unlock() }
            }
            let state = CrossState()
            let descriptors = AtomicWriterDescriptorOperations(open: { path, flags in
                _ = state.next(); return Darwin.open(path, flags)
            }, fsync: { fd in
                if state.count() == 2 {
                    atSync.signal(); _ = release.wait(timeout: .now() + 5); errno = EIO; return -1
                }
                return Darwin.fsync(fd)
            })
            let writerA = WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: root,
                descriptorOperations: descriptors)
            DispatchQueue.global().async { do { try writerA.save(replacement) } catch { state.markFailed() } }
            try expect(atSync.wait(timeout: .now() + 5) == .success, "cross-process A did not reach barrier")
            let process = Process()
            process.executableURL = URL(fileURLWithPath: CommandLine.arguments[0])
            process.arguments = ["--atomic-writer-lock-child", "--support", root.path,
                "--workspace-id", workspaceId.uuidString]
            try process.run()
            RunLoop.current.run(until: Date().addingTimeInterval(0.05))
            try expect(process.isRunning, "child writer bypassed cross-process target lock")
            release.signal()
            process.waitUntilExit()
            try expect(process.terminationStatus == 0 && state.failed,
                "cross-process writer schedule did not complete A-fail/B-success")
            let expectedChild = WorkspaceDocument(
                viewport: .init(x: 177, y: 188, zoom: 1.2), zones: [], lastActiveZoneId: nil)
            let childReload = try normal.load()
            try expect(childReload == expectedChild,
                "cross-process acknowledged child bytes were not reload truth")
            faultResults.append(["seam": "cross-process-writers", "writerAFailed": true,
                "childExit": process.terminationStatus, "acknowledgedWinnerReloaded": true,
                "orderedEvents": ["A-post-rename", "child-attempted-and-blocked", "A-rollback", "child-acknowledged"]])
        }
        let artifact = support.appendingPathComponent("manifest.json")
        let payload: [String: Any] = [
            "check": "workspace-restart-fault", "repetitions": 20,
            "closeOffsetsMs": closeOffsets, "repetitionsPerOffset": repetitionCount, "results": repetitions,
            "faults": faultResults, "status": "passed"
        ]
        try JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys]).write(to: artifact)
        return artifact
    }

    static func runPersistenceCrashSafeSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String {
                switch self { case let .failed(msg): return msg }
            }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }

        let fm = FileManager.default
        let appSupport: URL
        if let env = ProcessInfo.processInfo.environment["CONTINUUM_APP_SUPPORT"], !env.isEmpty {
            appSupport = URL(fileURLWithPath: env, isDirectory: true)
                .appendingPathComponent("persistence-crash-safe-\(UUID().uuidString)", isDirectory: true)
        } else {
            appSupport = fm.temporaryDirectory
                .appendingPathComponent("continuum-persistence-crash-safe-\(UUID().uuidString)", isDirectory: true)
        }
        try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)

        let wsId = UUID(uuidString: "11111111-1111-1111-1111-111111111101")!
        let projectZoneId = UUID(uuidString: "22222222-2222-2222-2222-222222222201")!
        let groupZoneId   = UUID(uuidString: "22222222-2222-2222-2222-222222222202")!
        let projectId     = UUID(uuidString: "33333333-3333-3333-3333-333333333301")!

        // Use a generous retainedBackups to prevent pruning from confounding the write-count assertions.
        let store = WorkspaceStore(
            workspaceId: wsId,
            applicationSupportDirectory: appSupport,
            retainedBackups: 64
        )

        func exactBackupGenerationNames() -> [String] {
            guard let entries = try? fm.contentsOfDirectory(
                at: store.layout.backupsDirectory,
                includingPropertiesForKeys: nil,
                options: [.skipsHiddenFiles]
            ) else { return [] }
            let productionParser = AtomicWriter(backupsDirectory: store.layout.backupsDirectory)
            return entries.compactMap { entry in
                let name = entry.lastPathComponent
                return productionParser.validBackupGeneration(named: name, for: store.layout.canvasFile) != nil ? name : nil
            }.sorted()
        }

        // Build D1: viewport (5, 7, 1.5), one project zone + one group zone.
        let D1 = WorkspaceDocument(
            viewport: CanvasViewport(x: 5, y: 7, zoom: 1.5),
            zones: [
                ZonePlacement(
                    zoneId: projectZoneId,
                    projectId: projectId,
                    origin: ZonePoint(x: 0, y: 0),
                    size: ZoneSize(width: 1280, height: 720),
                    color: "mint",
                    collapsed: false,
                    hydrationPolicy: .automatic
                ),
                ZonePlacement(
                    zoneId: groupZoneId,
                    projectId: nil,
                    origin: ZonePoint(x: 1400, y: 0),
                    size: ZoneSize(width: 800, height: 600),
                    color: "blue",
                    collapsed: false,
                    hydrationPolicy: .automatic
                ),
            ],
            zoneZOrder: [projectZoneId, groupZoneId],
            lastActiveZoneId: groupZoneId
        )

        // A1: save D1 and round-trip.
        try store.save(D1)
        try expect(fm.fileExists(atPath: store.layout.canvasFile.path), "A1: canvasFile must exist after save")
        let loaded1 = try store.load()
        try expect(loaded1 == D1, "A1: loaded document must equal D1 after round-trip")

        // A2: no leftover temp file from the write.
        let wsDir = store.layout.workspaceDirectory
        let wsDirContents = (try? fm.contentsOfDirectory(atPath: wsDir.path)) ?? []
        let tempFiles = wsDirContents.filter { $0.hasPrefix(".canvas.json.tmp-") }
        try expect(tempFiles.isEmpty, "A3: no .canvas.json.tmp-* leftover after durable write, found: \(tempFiles)")

        // B4: save D2 = D1 with zoom 3.0; assert round-trip.
        var D2 = D1
        D2.viewport = CanvasViewport(x: 5, y: 7, zoom: 3.0)
        try store.save(D2)
        let loaded2 = try store.load()
        try expect(loaded2 == D2, "B4: loaded document must equal D2 after second save")
        // After step 4: backups = {D1}, primary = D2.

        // B5: simulate crash that left a corrupt primary.
        let garbage = Data("{ \"schemaVer".utf8)
        try garbage.write(to: store.layout.canvasFile, options: .atomic)

        // B6: reader falls back to newest valid backup (D1, not D2).
        // Backup set: D1 backed up during save(D2), D2 never backed up (primary == D2, now garbage).
        let recovered = try store.load()
        try expect(recovered == D1, "B6: corrupt primary must recover to D1 (newest valid backup)")
        try expect(recovered.viewport.zoom == 1.5, "B6: recovered doc must have D1's zoom (1.5), got \(recovered.viewport.zoom)")

        // B7: stray temp file is never loaded as primary or backup.
        let strayTemp = wsDir.appendingPathComponent(".canvas.json.tmp-\(UUID().uuidString)")
        try Data("{ partial".utf8).write(to: strayTemp, options: .atomic)
        let afterStray = try store.load()
        try expect(afterStray == D1, "B7: stray temp file must not affect load, still returns D1")

        // C8: good primary survives a write; writer still healthy post-recovery.
        try store.save(D1)
        let afterResave = try store.load()
        try expect(afterResave == D1, "C8: save after recovery succeeds and round-trips D1")

        // D9-10: coalescing — N rapid schedules → exactly one atomic write.
        // NOTE: The controller already coalesces (it's a regression guard). Use a long enough
        // spin (0.3s) that covers both the current hardcoded 0.2s interval and the future
        // configured 10ms interval — the coalescing test is about write count, not speed.
        let suiteName = "PersistenceCrashSafeChecks-\(UUID().uuidString)"
        let suite = UserDefaults(suiteName: suiteName)!
        defer { suite.removePersistentDomain(forName: suiteName) }
        suite.removePersistentDomain(forName: suiteName)
        suite.set("10", forKey: AutosaveConfig.debounceMsKey)  // 10 ms window (post-fix)

        let saveController = WorkspaceDocumentSaveController(store: store, defaults: suite)
        let backupsBefore = exactBackupGenerationNames()
        let malformedForeignBackup = store.layout.backupsDirectory
            .appendingPathComponent("array-backup-v2-foreign-invalid-timestamp")
        try Data("foreign".utf8).write(to: malformedForeignBackup)

        // Schedule 5 documents without flushing.
        var scheduledGeneration: UInt64 = 0
        for x in [10.0, 11.0, 12.0, 13.0, 14.0] {
            scheduledGeneration = saveController.scheduleZoneLayoutSave(
                WorkspaceDocument(
                    viewport: CanvasViewport(x: x, y: 0, zoom: 1.0),
                    zones: [],
                    zoneZOrder: [],
                    lastActiveZoneId: nil
                )
            )
        }

        // Spin runloop long enough that any interval up to 250ms fires once.
        // (Pre-fix: controller ignores suite, uses 0.2s; 0.3s covers it. Post-fix: 10ms fires sooner.)
        RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.30))

        let backupsAfter = exactBackupGenerationNames()
        let delta = backupsAfter.count - backupsBefore.count
        try expect(delta == 1, "D10: coalesced N=5 schedules must create exactly 1 backup (got delta=\(delta))")
        try expect(saveController.acknowledgedGeneration == scheduledGeneration,
                   "D10: coalesced generation must be acknowledged exactly")
        let afterCoalesce = try store.load()
        try expect(afterCoalesce.viewport.x == 14.0, "D10: primary must hold last-scheduled doc (x=14), got \(afterCoalesce.viewport.x)")

        // D11: explicit flush.
        let D_f = WorkspaceDocument(
            viewport: CanvasViewport(x: 15, y: 0, zoom: 1.0),
            zones: [],
            zoneZOrder: [],
            lastActiveZoneId: nil
        )
        saveController.scheduleZoneLayoutSave(D_f)
        try saveController.flushPendingSave()
        let afterFlush = try store.load()
        try expect(afterFlush.viewport.x == 15.0, "D11: explicit flush writes synchronously (x=15), got \(afterFlush.viewport.x)")

        // E12-14: configurable debounce.
        let emptySuiteName = "PersistenceCrashSafeChecksEmpty-\(UUID().uuidString)"
        let emptySuite = UserDefaults(suiteName: emptySuiteName)!
        defer { emptySuite.removePersistentDomain(forName: emptySuiteName) }
        emptySuite.removePersistentDomain(forName: emptySuiteName)

        try expect(AutosaveConfig.debounceMs(defaults: emptySuite) == 200,
                   "E12: empty defaults must return 200 (default)")

        emptySuite.set("750", forKey: AutosaveConfig.debounceMsKey)
        try expect(AutosaveConfig.debounceMs(defaults: emptySuite) == 750,
                   "E13a: '750' must resolve to 750")

        emptySuite.set("-5", forKey: AutosaveConfig.debounceMsKey)
        try expect(AutosaveConfig.debounceMs(defaults: emptySuite) == AutosaveConfig.minDebounceMs,
                   "E13b: '-5' must clamp to min (\(AutosaveConfig.minDebounceMs))")

        emptySuite.set("99999", forKey: AutosaveConfig.debounceMsKey)
        try expect(AutosaveConfig.debounceMs(defaults: emptySuite) == AutosaveConfig.maxDebounceMs,
                   "E13c: '99999' must clamp to max (\(AutosaveConfig.maxDebounceMs))")

        emptySuite.set("abc", forKey: AutosaveConfig.debounceMsKey)
        try expect(AutosaveConfig.debounceMs(defaults: emptySuite) == 200,
                   "E13d: 'abc' non-numeric must fall back to 200")

        // E14: controller actually reads AutosaveConfig (0ms → fires next loop).
        let zeroSuiteName = "PersistenceCrashSafeChecksZero-\(UUID().uuidString)"
        let zeroSuite = UserDefaults(suiteName: zeroSuiteName)!
        defer { zeroSuite.removePersistentDomain(forName: zeroSuiteName) }
        zeroSuite.removePersistentDomain(forName: zeroSuiteName)
        zeroSuite.set("0", forKey: AutosaveConfig.debounceMsKey)

        let zeroController = WorkspaceDocumentSaveController(store: store, defaults: zeroSuite)
        let D_zero = WorkspaceDocument(
            viewport: CanvasViewport(x: 99, y: 0, zoom: 1.0),
            zones: [],
            zoneZOrder: [],
            lastActiveZoneId: nil
        )
        zeroController.scheduleZoneLayoutSave(D_zero)
        // 0ms interval: timer fires on next runloop pass.
        RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.01))
        let afterZero = try store.load()
        try expect(afterZero.viewport.x == 99.0,
                   "E14: controller with 0ms config must flush on next runloop (x=99), got \(afterZero.viewport.x)")

        // Write manifest.
        let timestamp = ISO8601DateFormatter().string(from: Date()).replacingOccurrences(of: ":", with: "-")
        let directory = URL(fileURLWithPath: fm.currentDirectoryPath)
            .appendingPathComponent("qa-runs", isDirectory: true)
            .appendingPathComponent(timestamp, isDirectory: true)
            .appendingPathComponent("persistence-crash-safe", isDirectory: true)
        try fm.createDirectory(at: directory, withIntermediateDirectories: true)
        let manifest = directory.appendingPathComponent("manifest.json")
        let manifestData: [String: Any] = [
            "check": "persistence-crash-safe",
            "recoveredViewportZoom": recovered.viewport.zoom,
            "backupDelta": delta,
            "coalesceCount": delta,
            "fixtureRoot": appSupport.path,
            "backupGenerationsBefore": backupsBefore,
            "backupGenerationsAfter": backupsAfter,
            "coalescedGenerationNames": Array(Set(backupsAfter).subtracting(backupsBefore)).sorted(),
            "scheduledGeneration": scheduledGeneration,
            "acknowledgedGeneration": saveController.acknowledgedGeneration,
            "coalescedGenerationAcknowledged": saveController.acknowledgedGeneration == scheduledGeneration,
            "postCoalesceViewportX": afterCoalesce.viewport.x,
            "flushViewportX": afterFlush.viewport.x,
            "status": "passed",
            "note": "fsync durability not observable in normal process exit; temp-hygiene (assertion 3) and crash-recovery (assertion 6) are the observable guarantees"
        ]
        let manifestJson = try JSONSerialization.data(withJSONObject: manifestData, options: [.prettyPrinted, .sortedKeys])
        try manifestJson.write(to: manifest)
        return manifest
    }

    private static func textFieldStrings(in view: NSView) -> [String] {
        var result: [String] = []
        if let textField = view as? NSTextField {
            result.append(textField.stringValue)
        }
        for subview in view.subviews {
            result.append(contentsOf: textFieldStrings(in: subview))
        }
        return result
    }

    private static func buttons(in view: NSView) -> [NSButton] {
        var result: [NSButton] = []
        if let button = view as? NSButton {
            result.append(button)
        }
        for subview in view.subviews {
            result.append(contentsOf: buttons(in: subview))
        }
        return result
    }

    // MARK: - Session Resume Check

    /// --session-resume-check: real-path check that terminal cwd + scrollback
    /// and browser interactionState survive a quit/relaunch cycle.
    /// Assertion 6 (scrollback on-screen replay) is deferred pending NEEDS-HUMAN
    /// decision on the replay mechanism (spec option c).
    static func runSessionResumeSelfCheck() throws -> URL {
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String {
                switch self { case let .failed(msg): return msg }
            }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }

        let started = Date()
        let fm = FileManager.default

        // MARK: Part A — Terminal cwd + scrollback resume

        let termRoot = fm.temporaryDirectory
            .appendingPathComponent("continuum-session-resume-term-\(UUID().uuidString)", isDirectory: true)
        try fm.createDirectory(at: termRoot, withIntermediateDirectories: true)
        let subDir = termRoot.appendingPathComponent("sub", isDirectory: true)
        try fm.createDirectory(at: subDir, withIntermediateDirectories: true)

        let context = try GhosttyRuntimeContext()
        defer { context.shutdown() }

        let host = TerminalHostView(frame: NSRect(x: 0, y: 0, width: 900, height: 600))
        let window = NSWindow(
            contentRect: NSRect(x: 100, y: 100, width: 900, height: 600),
            styleMask: [.titled], backing: .buffered, defer: false
        )
        window.contentView = host
        window.orderFront(nil)
        defer { window.close() }

        let now = Date()
        let project = Project(
            id: UUID(uuidString: "00000000-0000-0000-0000-000000001301")!,
            name: "session-resume-check",
            rootPath: termRoot.path,
            createdAt: now,
            updatedAt: now,
            defaultLaunchProfileId: "shell",
            editorPreference: .auto,
            settings: ProjectSettings(
                restorePolicy: .restoreDescriptors,
                browserStoragePolicy: .perProject,
                terminalClosePolicy: .askWhenRunning
            )
        )
        let store = ProjectStore(projectRoot: termRoot)
        try store.saveProject(project)
        // Pre-seed the canvas with a terminal tile so restartTerminalTile can find it.
        let termTileId = UUID(uuidString: "00000000-0000-0000-0000-000000001300")!
        try store.saveCanvas(CanvasState(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            tiles: [Tile(
                id: termTileId,
                kind: .terminal,
                title: "Shell",
                frame: TileFrame(x: 20, y: 20, width: 640, height: 420),
                zPosition: .fromLegacyRank(1),
                runtimeRef: nil,
                metadata: TileMetadata(launchProfileId: "shell")
            )],
            groups: [],
            lastActiveTileId: termTileId
        ))

        // Create the runtime directly (same pattern as runSnapshotTierSelfCheck),
        // bypassing spawnTerminal to avoid double-attach when the tile view is windowless.
        let canvas = CanvasNSView(canvasState: try store.loadCanvas())
        let browserEngine = BrowserEngineContext()
        defer { browserEngine.shutdown() }

        let tmuxDisabledDefaults = UserDefaults(suiteName: "continuum.test.sessionResumeTmuxDisabled.\(UUID().uuidString)")!
        tmuxDisabledDefaults.set(false, forKey: TmuxPersistenceConfig.enabledKey)
        let spawner = TileSpawner(
            canvasView: canvas,
            ghostty: context,
            browserEngine: browserEngine,
            projectStore: store,
            project: project,
            defaults: tmuxDisabledDefaults,
            tmuxPathResolver: { _ in nil }
        )

        let runtime = GhosttyTerminalRuntime(
            id: UUID(),
            tileId: termTileId,
            title: "Shell",
            launchProfile: LaunchProfile(command: "/bin/sh", arguments: [], cwd: termRoot.path, title: "Shell"),
            ghostty: context
        )

        host.attach(runtime: runtime)
        host.layoutSubtreeIfNeeded()

        // Wait for shell to be ready.
        runtime.sendInput(Data("printf 'con13-ready\\n'\n".utf8))
        try tickTerminal(context: context, timeout: 6.0) { runtime.visibleText().contains("con13-ready") }

        // Drive cd sub + a unique marker.
        runtime.sendInput(Data("cd '\(subDir.path)' && printf 'con13-line\\n'\n".utf8))
        try tickTerminal(context: context, timeout: 6.0) { runtime.visibleText().contains("con13-line") }

        // Save the initial descriptor (launch cwd) — mirrors what spawnTerminalTile does in
        // production. flushTerminalSessionSnapshot (below) will update it to the live cwd.
        let oldRuntimeId = runtime.id
        try store.saveSession(TerminalSessionDescriptor(
            id: oldRuntimeId,
            tileId: termTileId,
            launchProfileId: "shell",
            command: "/bin/sh",
            args: [],
            cwd: termRoot.path,            // launch cwd — intentionally NOT subDir.path
            env: [:],
            title: "Shell",
            createdAt: now,
            lastStartedAt: now,
            lastExit: nil,
            scrollback: nil
        ))

        // Emit OSC 7 from the real shell to report the post-cd cwd via GHOSTTY_ACTION_PWD.
        // The shell emits: \033]7;file://<hostname>/<path>\a — Ghostty decodes the file: URI
        // and fires the action with the plain path. Using printf with the raw ESC byte
        // avoids sh's echo interpretation differences across platforms.
        runtime.sendInput(Data("printf '\\033]7;file://%s%s\\a' \"$(hostname)\" \"$(pwd)\"\n".utf8))
        // Tick until the OSC 7 fires and capturedCwd reflects the subDir.
        try tickTerminal(context: context, timeout: 6.0) {
            runtime.capturedCwd == subDir.path
        }

        // Drive the real production flush path. This reads runtime.capturedCwd (live, from
        // OSC 7) and runtime.capturedScrollback (bounded), and persists both to the store.
        // This is NOT a hand-assembled bypass — the spawner reads from the live runtime.
        try spawner.flushTerminalSessionSnapshot(tileId: termTileId, runtime: runtime)

        // A1: Persisted cwd is the post-cd dir — reload through ProjectStore.
        let loadedDescriptor = try store.loadSession(id: oldRuntimeId)
        try expect(
            loadedDescriptor.cwd == subDir.path,
            "A1 FAIL: persisted cwd=\(loadedDescriptor.cwd) expected=\(subDir.path)"
        )

        // A2: Persisted scrollback present (gate-ON: flush with default .standard suite
        // which has no key set, so scrollbackEnabled defaults to true).
        try expect(
            loadedDescriptor.scrollback != nil,
            "A2 FAIL: scrollback should be non-nil after flush"
        )
        try expect(
            loadedDescriptor.scrollback!.contains("con13-line"),
            "A2 FAIL: scrollback missing con13-line; text=\(loadedDescriptor.scrollback!.prefix(200))"
        )

        // A2 bound: emit 15 distinct lines into the live shell, then flush with a small
        // maxLines cap (10) and assert the reloaded descriptor has EXACTLY 10 lines.
        // This exercises the real suffix() bound — without it the assertion would fail
        // because there would be >10 lines in the raw scrollback.
        let a2Sentinel = "con13-bound"
        for i in 1...15 {
            runtime.sendInput(Data("printf '\(a2Sentinel)-%02d\\n' \(i)\n".utf8))
        }
        // Wait until the last line is visible.
        try tickTerminal(context: context, timeout: 6.0) {
            runtime.visibleText().contains("\(a2Sentinel)-15")
        }
        // Second flush with maxLines: 10 — exercises the real suffix() path.
        try spawner.flushTerminalSessionSnapshot(tileId: termTileId, runtime: runtime, maxLines: 10)
        let boundedDescriptor = try store.loadSession(id: oldRuntimeId)
        let boundedLineCount = (boundedDescriptor.scrollback ?? "").components(separatedBy: "\n").count
        try expect(
            boundedLineCount == 10,
            "A2 FAIL: scrollback line count \(boundedLineCount) should be exactly maxLines=10 after suffix() cap"
        )

        // A3: Schema migration — hand-written v1 JSON literal decodes with scrollback==nil.
        let v1Json = """
        {
          "schemaVersion": 1,
          "id": "\(oldRuntimeId.uuidString)",
          "tileId": "\(termTileId.uuidString)",
          "launchProfileId": "shell",
          "command": "/bin/sh",
          "args": [],
          "cwd": "\(termRoot.path)",
          "env": {},
          "title": "Shell",
          "createdAt": 0,
          "lastStartedAt": 0
        }
        """.data(using: .utf8)!
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .secondsSince1970
        let migratedDescriptor = try decoder.decode(TerminalSessionDescriptor.self, from: v1Json)
        try expect(migratedDescriptor.scrollback == nil, "A3 FAIL: v1 descriptor should decode scrollback as nil")
        try expect(migratedDescriptor.cwd == termRoot.path, "A3 FAIL: v1 descriptor cwd not decoded correctly")

        // A4: Terminate old runtime — old PID dies.
        runtime.terminate(policy: .force)
        host.detachRuntime()
        try tickTerminal(context: context, seconds: 0.5)
        let oldPidDead = runtime.isProcessExitedForSnapshotCheck
        try expect(oldPidDead, "A4 FAIL: old runtime PID should be dead after terminate(.force)")

        // A5: Restart through real spawner; check fresh shell opens in persisted cwd.
        let restartedRuntime: GhosttyTerminalRuntime
        switch spawner.restartTerminalTile(tileId: termTileId) {
        case let .restarted(r): restartedRuntime = r
        case let .unknownProfile(id): throw CheckError.failed("restartTerminalTile unknownProfile \(id)")
        case let .missingCommand(cmd): throw CheckError.failed("restartTerminalTile missingCommand \(cmd)")
        case let .notConfigured(id): throw CheckError.failed("restartTerminalTile notConfigured \(id)")
        case .tileNotFound: throw CheckError.failed("restartTerminalTile tileNotFound")
        case let .failure(err): throw CheckError.failed("restartTerminalTile failure \(err)")
        }
        let host2 = TerminalHostView(frame: NSRect(x: 0, y: 0, width: 900, height: 600))
        let window2 = NSWindow(
            contentRect: NSRect(x: 200, y: 200, width: 900, height: 600),
            styleMask: [.titled], backing: .buffered, defer: false
        )
        window2.contentView = host2
        window2.orderFront(nil)
        defer { window2.close() }
        host2.attach(runtime: restartedRuntime)
        host2.layoutSubtreeIfNeeded()

        // A5: Distinct instance.
        try expect(
            restartedRuntime.id != oldRuntimeId,
            "A5 FAIL: restarted runtime should have a new id"
        )

        // A5: Fresh shell opens in the persisted cwd (probe live pwd).
        // Brief warmup tick, then send a command whose output (not echo) contains "/".
        // The sentinel "con13-cwdout-/" matches only the output because the echoed
        // command text has "%s" not "/".
        try tickTerminal(context: context, seconds: 0.5)
        restartedRuntime.sendInput(Data("printf 'con13-cwdout-%s\\n' \"$(pwd)\"\n".utf8))
        try tickTerminal(context: context, timeout: 8.0) {
            restartedRuntime.visibleText().contains("con13-cwdout-/")
        }
        let restartedText = restartedRuntime.visibleText()
        try expect(
            restartedText.contains(subDir.path),
            "A5 FAIL: restarted shell cwd should be \(subDir.path); visible=\(restartedText.prefix(400))"
        )

        // Assertion 6 (scrollback on-screen replay) — DEFERRED (NEEDS-HUMAN, spec option c).
        // The scrollback is persisted to disk and the replay mechanism is undecided.

        // A7: Config gate — with scrollback disabled, the REAL flush path persists nil
        // scrollback but still captures the live cwd (the toggle is orthogonal to cwd).
        // Uses a fresh UserDefaults suite so .standard is not polluted.
        //
        // Gate-ON (scrollbackEnabled=true) is proven by A2: the initial flush with default
        // .standard suite produced non-nil scrollback. Gate-OFF is proven here by driving
        // flushTerminalSessionSnapshot with a suite that has the key set to false, then
        // reloading through the store and asserting nil — if the production guard is removed
        // from flushTerminalSessionSnapshot, this assertion fails.
        let gateDefaults = UserDefaults(suiteName: "continuum.test.sessionResumeGate.\(UUID().uuidString)")!
        gateDefaults.set(false, forKey: SessionResumeConfig.scrollbackEnabledKey)
        try expect(
            !SessionResumeConfig.scrollbackEnabled(defaults: gateDefaults),
            "A7 FAIL: scrollbackEnabled resolver should return false with key=false"
        )
        // Remove the old (pre-restart) descriptor for termTileId so listSessions().first
        // is deterministic — only restartedRuntime.id's descriptor remains for that tile.
        // This ensures flushTerminalSessionSnapshot updates the correct file and the reload
        // below gets the flush result, not a stale copy.
        try? store.deleteSession(id: oldRuntimeId)
        // Drive the REAL production flush with the gate-off suite injected via defaults:.
        // This is not a bypass — deleting the guard in flushTerminalSessionSnapshot makes
        // this assertion fail because the reloaded descriptor will have non-nil scrollback.
        try spawner.flushTerminalSessionSnapshot(tileId: termTileId, runtime: restartedRuntime, defaults: gateDefaults)
        let gatedDescriptor = try store.loadSession(id: restartedRuntime.id)
        try expect(
            gatedDescriptor.scrollback == nil,
            "A7 FAIL: when scrollbackEnabled=false, flush must persist nil scrollback; got \(String(describing: gatedDescriptor.scrollback?.prefix(100)))"
        )
        // cwd is not gated by the scrollback toggle.
        try expect(
            !gatedDescriptor.cwd.isEmpty,
            "A7 FAIL: cwd should be persisted even when scrollback toggle is off"
        )

        restartedRuntime.terminate(policy: .force)
        host2.detachRuntime()

        // Clean up terminal temp dir.
        try? fm.removeItem(at: termRoot)

        // MARK: Part B — Browser interactionState resume

        let browserRoot = fm.temporaryDirectory
            .appendingPathComponent("continuum-session-resume-browser-\(UUID().uuidString)", isDirectory: true)
        try fm.createDirectory(at: browserRoot, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: browserRoot) }

        let browserTileId = UUID()
        let browserNow = Date()
        let initialURL = "data:text/html;charset=utf-8,<html><body><p>Page1</p></body></html>"
        let secondURL = "data:text/html;charset=utf-8,<html><body><p>Page2</p></body></html>"

        let browserProject = Project(
            id: UUID(uuidString: "00000000-0000-0000-0000-000000001302")!,
            name: "session-resume-browser-check",
            rootPath: browserRoot.path,
            createdAt: browserNow,
            updatedAt: browserNow,
            defaultLaunchProfileId: "shell",
            editorPreference: .auto,
            settings: ProjectSettings(
                restorePolicy: .restoreDescriptors,
                browserStoragePolicy: .perProject,
                terminalClosePolicy: .askWhenRunning
            )
        )
        let browserStore = ProjectStore(projectRoot: browserRoot)
        try browserStore.saveProject(browserProject)
        try browserStore.saveCanvas(CanvasState(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            tiles: [Tile(
                id: browserTileId,
                kind: .browser,
                title: "Browser",
                frame: TileFrame(x: 20, y: 20, width: 640, height: 420),
                zPosition: .fromLegacyRank(1),
                runtimeRef: nil,
                metadata: TileMetadata(url: initialURL)
            )],
            groups: [],
            lastActiveTileId: browserTileId
        ))
        let expectedStorageGroupId = BrowserState.storageGroupIdentifier(for: browserProject)
        try browserStore.saveBrowserState(BrowserState(tiles: [BrowserTile(
            id: UUID(),
            tileId: browserTileId,
            url: initialURL,
            title: "Page1",
            storageGroupId: expectedStorageGroupId,
            createdAt: browserNow,
            updatedAt: browserNow
        )]))

        let browserCanvas = CanvasNSView(canvasState: try browserStore.loadCanvas())
        let browserEngineB = BrowserEngineContext()
        defer { browserEngineB.shutdown() }
        let browserSpawner = TileSpawner(
            canvasView: browserCanvas,
            ghostty: nil,
            browserEngine: browserEngineB,
            projectStore: browserStore,
            project: browserProject
        )

        let firstRuntime: WKWebViewBrowserRuntime
        switch browserSpawner.restartBrowserTile(tileId: browserTileId) {
        case let .restarted(r): firstRuntime = r
        case let .invalidURL(url): throw CheckError.failed("B restartBrowserTile invalid URL \(url)")
        case .tileNotFound: throw CheckError.failed("B restartBrowserTile tileNotFound")
        case let .failure(err): throw CheckError.failed("B restartBrowserTile failure \(err)")
        }
        let firstOldWebView = firstRuntime.webView

        // Navigate to second page to build back history.
        firstRuntime.loadURL(secondURL)
        // Spin the run loop until WebKit commits the navigation and populates
        // interactionState (required for A8 unconditional assertion). WebKit needs
        // a committed navigation before interactionState is non-nil. Timeout 3s.
        let interactionStateDeadline = Date().addingTimeInterval(3.0)
        while firstRuntime.capturedInteractionState == nil, Date() < interactionStateDeadline {
            RunLoop.current.run(mode: .default, before: Date().addingTimeInterval(0.1))
        }

        // Persist via the real path.
        try browserSpawner.writeBrowserTileSnapshotOrThrow(for: firstRuntime)

        // A8: interactionState captured — unconditional. The run loop spin above
        // ensures WebKit has committed navigation and interactionState is populated.
        // If it's still nil after 3s the harness fails (WebKit regression or headless
        // limitation — not a pass).
        let postPersistState = try browserStore.loadBrowserState()
        let postPersistTile = postPersistState.tiles.first(where: { $0.tileId == browserTileId })
        try expect(
            postPersistTile?.interactionState != nil,
            "A8 FAIL: interactionState should be non-nil after real persist path"
        )
        try expect(
            !(postPersistTile!.interactionState!.isEmpty),
            "A8 FAIL: persisted interactionState must be non-empty Data"
        )

        // A9: Schema migration — hand-written v1 BrowserTile JSON decodes cleanly.
        let v1BrowserJson = """
        {
          "id": "00000000-0000-0000-0000-000000001399",
          "tileId": "\(browserTileId.uuidString)",
          "url": "about:blank",
          "title": "V1 Tile",
          "storageGroupId": "shared",
          "createdAt": 0,
          "updatedAt": 0
        }
        """.data(using: .utf8)!
        let browserDecoder = JSONDecoder()
        browserDecoder.dateDecodingStrategy = .secondsSince1970
        let migratedTile = try browserDecoder.decode(BrowserTile.self, from: v1BrowserJson)
        try expect(migratedTile.interactionState == nil, "A9 FAIL: v1 BrowserTile should decode interactionState as nil")
        try expect(migratedTile.url == "about:blank", "A9 FAIL: v1 BrowserTile url not decoded correctly")

        // A10/A11/A12: Restart fresh WKWebView, apply interactionState.
        firstRuntime.terminate(policy: .force)

        let secondRuntime: WKWebViewBrowserRuntime
        switch browserSpawner.restartBrowserTile(tileId: browserTileId) {
        case let .restarted(r): secondRuntime = r
        case let .invalidURL(url): throw CheckError.failed("B second restart invalid URL \(url)")
        case .tileNotFound: throw CheckError.failed("B second restart tileNotFound")
        case let .failure(err): throw CheckError.failed("B second restart failure \(err)")
        }
        let secondNewWebView = secondRuntime.webView

        // A11: Fresh WKWebView (different object).
        try expect(firstOldWebView !== secondNewWebView, "A11 FAIL: second restart should use a new WKWebView object")

        // A10: interactionState applied to fresh view — unconditional. The persisted
        // blob (proven non-nil by A8) must have been applied to the new WebView:
        // capturedInteractionState is non-nil AND back/forward history survived.
        // Primary proof: canGoBack == true (the back-history entry from the first→second
        // navigation survived the restore). Fallback per spec lines 179-182: if canGoBack
        // is flaky in the headless harness, the blob round-trips (appliedState == saved
        // blob), proving interactionState — not just URL — was set on the fresh WebView.
        // Give WebKit a run-loop tick to settle after restoreInteractionState.
        RunLoop.current.run(mode: .default, before: Date().addingTimeInterval(0.2))
        let appliedState = secondRuntime.capturedInteractionState
        try expect(
            appliedState != nil,
            "A10 FAIL: after restoreInteractionState, capturedInteractionState must be non-nil"
        )
        let canGoBackAfterRestore = secondRuntime.webView.canGoBack
        let blobRoundTrips = appliedState == postPersistTile!.interactionState!
        try expect(
            canGoBackAfterRestore || blobRoundTrips,
            "A10 FAIL: back/forward history must survive interactionState restore — canGoBack=\(canGoBackAfterRestore), blobRoundTrip=\(blobRoundTrips)"
        )

        // A12: URL still restored — specific URL (regression guard). No escape hatch:
        // the persisted URL must contain the last-committed page fragment.
        let postRestartBrowserState = try browserStore.loadBrowserState()
        let postRestartTile = postRestartBrowserState.tiles.first(where: { $0.tileId == browserTileId })
        let expectedURLFragment = "Page2"
        let persistedURL = postRestartTile?.url ?? ""
        try expect(
            persistedURL.contains(expectedURLFragment),
            "A12 FAIL: browser URL must be the specific persisted URL (contains '\(expectedURLFragment)'); got '\(persistedURL)'"
        )

        secondRuntime.terminate(policy: .force)

        // MARK: Part C — Config / Settings wiring

        // A13: SettingsSchema entries exist.
        let allFields = SettingsSchema.sections().flatMap(\.fields)
        let hasScrollbackEnabledField = allFields.contains(where: { $0.key == SessionResumeConfig.scrollbackEnabledKey })
        let hasScrollbackMaxLinesField = allFields.contains(where: { $0.key == SessionResumeConfig.scrollbackMaxLinesKey })
        try expect(hasScrollbackEnabledField, "A13 FAIL: SettingsSchema missing scrollbackEnabled field")
        try expect(hasScrollbackMaxLinesField, "A13 FAIL: SettingsSchema missing scrollbackMaxLines field")

        // A14: Default resolution (throwaway UserDefaults suite).
        let freshDefaults = UserDefaults(suiteName: "continuum.test.sessionResume.\(UUID().uuidString)")!
        try expect(
            SessionResumeConfig.scrollbackEnabled(defaults: freshDefaults) == true,
            "A14 FAIL: default scrollbackEnabled should be true"
        )
        try expect(
            SessionResumeConfig.scrollbackMaxLines(defaults: freshDefaults) == 2000,
            "A14 FAIL: default scrollbackMaxLines should be 2000"
        )
        freshDefaults.set(false, forKey: SessionResumeConfig.scrollbackEnabledKey)
        freshDefaults.set(50, forKey: SessionResumeConfig.scrollbackMaxLinesKey)
        try expect(
            SessionResumeConfig.scrollbackEnabled(defaults: freshDefaults) == false,
            "A14 FAIL: overridden scrollbackEnabled should be false"
        )
        try expect(
            SessionResumeConfig.scrollbackMaxLines(defaults: freshDefaults) == 50,
            "A14 FAIL: overridden scrollbackMaxLines should be 50"
        )

        // Write artifact manifest.
        let runId = ISO8601DateFormatter().string(from: started).replacingOccurrences(of: ":", with: "")
        let artifactDir = URL(fileURLWithPath: "qa-runs/session-resume-\(runId)", isDirectory: true)
        try fm.createDirectory(at: artifactDir, withIntermediateDirectories: true)
        let manifest = artifactDir.appendingPathComponent("manifest.json")
        let manifestObj: [String: Any] = [
            "check": "session-resume",
            "assertions": [
                "A1_cwd_persisted": loadedDescriptor.cwd == subDir.path,
                "A2_scrollback_bounded": boundedLineCount == 10,
                "A3_v1_migration": migratedDescriptor.scrollback == nil,
                "A4_old_pid_dead": oldPidDead,
                "A5_distinct_instance": restartedRuntime.id != oldRuntimeId,
                "A6_scrollback_replay": "deferred-needs-human",
                "A7_config_gate": gatedDescriptor.scrollback == nil,
                "A8_interactionState_captured": postPersistTile?.interactionState != nil,
                "A9_v1_browser_migration": migratedTile.interactionState == nil,
                "A10_interactionState_applied": appliedState != nil && (canGoBackAfterRestore || blobRoundTrips),
                "A11_fresh_webview": firstOldWebView !== secondNewWebView,
                "A12_url_specific_restored": persistedURL.contains(expectedURLFragment),
                "A13_settings_schema": hasScrollbackEnabledField && hasScrollbackMaxLinesField,
                "A14_config_defaults": true
            ]
        ]
        let manifestData = try JSONSerialization.data(withJSONObject: manifestObj, options: [.prettyPrinted])
        try manifestData.write(to: manifest, options: .atomic)
        return manifest
    }

    private static func tickTerminal(context: GhosttyRuntimeContext, seconds: TimeInterval) throws {
        let deadline = Date().addingTimeInterval(seconds)
        while Date() < deadline {
            ghostty_app_tick(try context.app)
            RunLoop.current.run(mode: .default, before: Date().addingTimeInterval(0.05))
        }
    }

    private static func tickTerminal(context: GhosttyRuntimeContext, timeout: TimeInterval, until condition: () -> Bool) throws {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            ghostty_app_tick(try context.app)
            if condition() { return }
            RunLoop.current.run(mode: .default, before: Date().addingTimeInterval(0.05))
        }
        throw NSError(
            domain: "ContinuumRevivedSessionResumeCheck",
            code: 2,
            userInfo: [NSLocalizedDescriptionKey: "session resume check timed out"]
        )
    }

    // swiftlint:disable:next function_body_length
    static func runWorkspaceProfileSelfCheck() throws {
        // T14 — WorkspaceProfileStore: snapshot/template capture + restore-over/instantiate-as-new.
        // Drives the REAL on-disk stores (WorkspaceProfileStore, WorkspaceStore, RegistryStore)
        // through a single hermetic temp applicationSupportDirectory.
        enum CheckError: Error, CustomStringConvertible {
            case failed(String)
            var description: String { switch self { case let .failed(m): return m } }
        }
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
            if !condition() { throw CheckError.failed(message) }
        }

        let fm = FileManager.default

        // Fixed timestamps (distinct so listProfiles sort is deterministic).
        let nowBase = Date(timeIntervalSince1970: 1_800_000_000)
        let now1 = nowBase
        let now2 = nowBase.addingTimeInterval(60)

        // Fixed UUIDs.
        let W0 = UUID(uuidString: "14000000-0000-4000-8000-000000000001")!
        let P1 = UUID(uuidString: "14000000-0000-4000-8000-000000000002")!
        let P2 = UUID(uuidString: "14000000-0000-4000-8000-000000000003")!
        let P3 = UUID(uuidString: "14000000-0000-4000-8000-000000000004")!  // future-schema
        let zone1Id = UUID(uuidString: "14000000-0000-4000-8000-000000000005")!
        let zone2Id = UUID(uuidString: "14000000-0000-4000-8000-000000000006")!
        let projectId1 = UUID(uuidString: "14000000-0000-4000-8000-000000000007")!

        // Hermetic temp directory.
        let appSupport = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent("continuum-workspace-profile-check-\(UUID().uuidString)", isDirectory: true)
        try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)
        defer { try? fm.removeItem(at: appSupport) }

        // Source document. WorkspaceDocument is layout-only (viewport, zones, zoneZOrder,
        // lastActiveZoneId, ambientTiles). T13 session-state fields (scrollback on
        // TerminalSessionDescriptor, interactionState on BrowserTile) live in ProjectStore
        // sibling stores keyed by tile id, NOT on WorkspaceDocument. There is no session
        // field to embed here; the template/snapshot distinction is layout-identical.
        let srcDoc = WorkspaceDocument(
            viewport: CanvasViewport(x: 10, y: 20, zoom: 1.5),
            zones: [
                ZonePlacement(
                    zoneId: zone1Id,
                    projectId: projectId1,
                    origin: ZonePoint(x: 0, y: 0),
                    size: ZoneSize(width: 800, height: 600),
                    color: "blue",
                    collapsed: false,
                    hydrationPolicy: .automatic,
                    name: "API",
                    navKey: "a"
                ),
                ZonePlacement(
                    zoneId: zone2Id,
                    projectId: nil,
                    origin: ZonePoint(x: 900, y: 0),
                    size: ZoneSize(width: 600, height: 400),
                    color: "green",
                    collapsed: false,
                    hydrationPolicy: .automatic,
                    name: "Scratch",
                    navKey: nil
                ),
            ],
            zoneZOrder: [zone1Id, zone2Id],
            lastActiveZoneId: zone1Id
        )

        // Save srcDoc as W0 workspace.
        try WorkspaceStore(workspaceId: W0, applicationSupportDirectory: appSupport).save(srcDoc)

        // Seed registry with W0.
        var registry = Registry.empty()
        registry.createWorkspace(id: W0, name: "Source", now: now1)
        let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
        try registryStore.save(registry)

        // Construct profile store.
        let store = WorkspaceProfileStore(applicationSupportDirectory: appSupport)

        // --- Assertion 1: Capture snapshot — round-trips through disk. ---
        let snap = store.captureProfile(name: "Snap", from: srcDoc, mode: .snapshot, id: P1, now: now1)
        try store.saveProfile(snap)
        let loadedSnap = try store.loadProfile(id: P1)
        try expect(loadedSnap == snap, "assertion 1: loadProfile(P1) == captured profile")
        try expect(fm.fileExists(atPath: store.profileFile(id: P1).path), "assertion 1: profile file exists on disk")
        try expect(loadedSnap.captureMode == .snapshot, "assertion 1: captureMode == .snapshot")
        try expect(loadedSnap.name == "Snap", "assertion 1: name == 'Snap'")
        try expect(loadedSnap.createdAt == now1, "assertion 1: createdAt == now1")
        try expect(loadedSnap.schemaVersion == 1, "assertion 1: schemaVersion == 1")

        // --- Assertion 2: Snapshot keeps the document verbatim. ---
        // WorkspaceDocument is layout-only. T13 session-state (scrollback on
        // TerminalSessionDescriptor, interactionState on BrowserTile) lives in ProjectStore
        // sibling stores keyed by tile id, NOT on WorkspaceDocument. The snapshot document
        // is byte-identical to srcDoc; there is no session field to keep/strip here.
        try expect(loadedSnap.document == srcDoc, "assertion 2: snapshot document == srcDoc (verbatim)")

        // --- Assertion 3: Template preserves all layout fields; captureMode is .template. ---
        // ARCHITECTURE-NOTE: snapshot and template currently produce byte-identical documents.
        // The captureMode field is persisted to distinguish them for future session-state
        // bridge work. Layout assertions prove the template did not corrupt the document.
        let tmpl = store.captureProfile(name: "Tmpl", from: srcDoc, mode: .template, id: P2, now: now2)
        try store.saveProfile(tmpl)
        let loadedTmpl = try store.loadProfile(id: P2)
        try expect(loadedTmpl.captureMode == .template, "assertion 3: captureMode == .template")
        let apiZone = loadedTmpl.document.zones.first(where: { $0.zoneId == zone1Id })!
        try expect(apiZone.name == "API", "assertion 3: template project zone name == 'API'")
        try expect(apiZone.navKey == "a", "assertion 3: template project zone navKey == 'a'")
        try expect(apiZone.origin == ZonePoint(x: 0, y: 0), "assertion 3: template project zone origin (0,0)")
        try expect(apiZone.size == ZoneSize(width: 800, height: 600), "assertion 3: template project zone size (800,600)")
        let scratchZone = loadedTmpl.document.zones.first(where: { $0.zoneId == zone2Id })!
        try expect(scratchZone.projectId == nil, "assertion 3: template group zone projectId nil")
        try expect(scratchZone.name == "Scratch", "assertion 3: template group zone name == 'Scratch'")
        try expect(loadedTmpl.document.viewport == srcDoc.viewport, "assertion 3: template viewport (10,20,1.5) preserved")
        try expect(
            loadedTmpl.document.zonesInZOrder.map(\.zoneId) == srcDoc.zonesInZOrder.map(\.zoneId),
            "assertion 3: template zone stacking order preserved"
        )

        // --- Assertion 4: captureMode is the distinguishing property; documents are equal. ---
        // ARCHITECTURE-NOTE: snapshot and template are layout-identical because WorkspaceDocument
        // has no session-state fields. The spec's `template.document != srcDoc` assertion is
        // unprovable until a session-state bridge (e.g., a sessionBundle alongside document) is
        // added to WorkspaceProfile. Instead, assert that captureMode correctly records the intent
        // and that both modes round-trip the document faithfully.
        try expect(loadedSnap.captureMode == .snapshot, "assertion 4: snapshot captureMode == .snapshot")
        try expect(loadedTmpl.captureMode == .template, "assertion 4: template captureMode == .template")
        try expect(loadedSnap.document == srcDoc, "assertion 4: snapshot document == srcDoc")
        try expect(loadedTmpl.document == srcDoc, "assertion 4: template document == srcDoc (layout-only; no strip possible)")
        // NOTE: loadedSnap.document == loadedTmpl.document is an honest consequence of the
        // current architecture. When a session-state bridge is added, this becomes != and the
        // spec's original assertion (template != srcDoc) becomes provable.

        // --- Assertion 5: Apply restore-over — overwrites W0's document. ---
        let dirtyDoc = WorkspaceDocument(
            viewport: CanvasViewport(x: 999, y: 999, zoom: 3),
            zones: [],
            zoneZOrder: [],
            lastActiveZoneId: nil
        )
        try WorkspaceStore(workspaceId: W0, applicationSupportDirectory: appSupport).save(dirtyDoc)
        // Restore-over recipe.
        try WorkspaceStore(workspaceId: W0, applicationSupportDirectory: appSupport)
            .save(store.loadProfile(id: P1).document)
        let restoredDoc = try WorkspaceStore(workspaceId: W0, applicationSupportDirectory: appSupport).load()
        try expect(restoredDoc == srcDoc, "assertion 5: after restore-over, W0 contains the profile's captured doc (srcDoc)")
        let regAfterRestore = try registryStore.load()
        try expect(regAfterRestore.workspaces.count == 1, "assertion 5: registry workspace count still 1 after restore-over")
        try expect(regAfterRestore.workspaces[0].id == W0, "assertion 5: registry still contains W0")

        // --- Assertion 6: restore-over leaves a backup. ---
        let wsBackupsDir = WorkspaceStore(workspaceId: W0, applicationSupportDirectory: appSupport).layout.backupsDirectory
        // The assertion is "restore-over left a backup", not "the file is named a
        // particular way". WS2 changed the scheme from `canvas.<iso>.<n>.json` to
        // `array-backup-v2-<identity>-<generation>-<iso>`, which is
        // identity-scoped and generation-ordered rather than stem-and-clock
        // ordered. Accept both: an installed copy's existing backups keep the old
        // names, so a filter that recognised only one scheme would be wrong in
        // the field as well as here.
        let allBackupFiles = try fm.contentsOfDirectory(at: wsBackupsDir, includingPropertiesForKeys: nil)
        let backupFiles = allBackupFiles.filter { url in
            let name = url.lastPathComponent
            return (name.hasPrefix("canvas.") && url.pathExtension == "json")
                || name.hasPrefix("array-backup-v2-")
        }
        try expect(backupFiles.count >= 1,
                   "assertion 6: backups directory contains at least one backup "
                   + "(canvas.*.json or array-backup-v2-*); found \(allBackupFiles.map(\.lastPathComponent))")

        // --- Assertion 7: Apply instantiate-as-new from template — new workspace created. ---
        let newEntry = registry.createWorkspace(name: "From Template", now: now2)
        let newId = newEntry.id
        try WorkspaceStore(workspaceId: newId, applicationSupportDirectory: appSupport)
            .save(store.loadProfile(id: P2).document)
        try registryStore.save(registry)

        let newCanvasFile = WorkspaceStore(workspaceId: newId, applicationSupportDirectory: appSupport).layout.canvasFile
        try expect(fm.fileExists(atPath: newCanvasFile.path), "assertion 7: new workspace canvas.json exists")
        let newDoc = try WorkspaceStore(workspaceId: newId, applicationSupportDirectory: appSupport).load()
        let tmplProfileDoc = try store.loadProfile(id: P2).document
        try expect(newDoc == tmplProfileDoc, "assertion 7: new workspace doc == template profile doc")
        let regAfterInstantiate = try registryStore.load()
        try expect(regAfterInstantiate.workspaces.count == 2, "assertion 7: registry now has 2 workspaces")
        let newWorkspace = regAfterInstantiate.workspaces.first(where: { $0.id == newId })
        try expect(newWorkspace != nil, "assertion 7: registry contains entry for newId")
        try expect(newWorkspace?.name == "From Template", "assertion 7: new workspace name == 'From Template'")
        let w0DocAfterInstantiate = try WorkspaceStore(workspaceId: W0, applicationSupportDirectory: appSupport).load()
        try expect(w0DocAfterInstantiate == srcDoc, "assertion 7: W0 canvas unchanged by instantiate-as-new")

        // --- Assertion 8: Instantiate from snapshot — new workspace gets the profile doc. ---
        // ARCHITECTURE-NOTE: snapshot and template are currently layout-identical (no session-state
        // bridge yet). This assertion proves the instantiate recipe works for snapshot profiles and
        // the document round-trips faithfully. Apply mode is orthogonal to capture mode.
        let newEntry2 = registry.createWorkspace(name: "From Snapshot", now: now2)
        let newId2 = newEntry2.id
        try WorkspaceStore(workspaceId: newId2, applicationSupportDirectory: appSupport)
            .save(store.loadProfile(id: P1).document)
        let newDoc2 = try WorkspaceStore(workspaceId: newId2, applicationSupportDirectory: appSupport).load()
        try expect(newDoc2 == srcDoc, "assertion 8: instantiate from snapshot: new workspace doc == srcDoc")

        // --- Assertion 9: listProfiles enumerates both, sorted, skips garbage. ---
        // Write a junk file BEFORE assertion 9 (assertion 10 writes P3 after).
        let junkURL = store.profilesDirectory.appendingPathComponent("notjson.json")
        try "not valid json".write(to: junkURL, atomically: true, encoding: .utf8)
        let listed = try store.listProfiles()
        try expect(listed.count == 2, "assertion 9: listProfiles returns exactly 2 profiles (P1, P2; junk skipped)")
        try expect(listed[0].id == P1, "assertion 9: listProfiles[0] == P1 (earlier createdAt)")
        try expect(listed[1].id == P2, "assertion 9: listProfiles[1] == P2 (later createdAt)")

        // --- Assertion 10: Future-schema profile is refused. ---
        let futureProfile = WorkspaceProfile(
            schemaVersion: 2,
            id: P3,
            name: "Future",
            createdAt: now2,
            captureMode: .snapshot,
            document: srcDoc
        )
        let futureData = try JSONCodec.makeEncoder().encode(futureProfile)
        try futureData.write(to: store.profileFile(id: P3))
        var caughtFutureSchema = false
        do {
            _ = try store.loadProfile(id: P3)
        } catch WorkspaceProfileApplicationError.unknownFutureSchema(_, let version, let supported) {
            caughtFutureSchema = true
            try expect(version == 2, "assertion 10: unknownFutureSchema.version == 2")
            try expect(supported == 1, "assertion 10: unknownFutureSchema.supported == 1")
        }
        try expect(caughtFutureSchema, "assertion 10: loadProfile(P3) throws unknownFutureSchema")

        // --- Assertion 11: Configurable defaults resolve. ---
        let suiteName11 = "WorkspaceProfileConfigCheck-\(UUID().uuidString)"
        let defaults11 = UserDefaults(suiteName: suiteName11)!
        defer { defaults11.removePersistentDomain(forName: suiteName11) }
        defaults11.removePersistentDomain(forName: suiteName11)
        try expect(WorkspaceProfileConfig.captureMode(defaults: defaults11) == .snapshot,
                   "assertion 11: captureMode on empty defaults == .snapshot")
        try expect(WorkspaceProfileConfig.applyMode(defaults: defaults11) == .restoreOver,
                   "assertion 11: applyMode on empty defaults == .restoreOver")
        defaults11.set(WorkspaceProfileCaptureMode.template.rawValue, forKey: WorkspaceProfileConfig.defaultCaptureModeKey)
        try expect(WorkspaceProfileConfig.captureMode(defaults: defaults11) == .template,
                   "assertion 11: captureMode override 'template' returns .template")
        defaults11.set(WorkspaceProfileApplyMode.instantiateAsNew.rawValue, forKey: WorkspaceProfileConfig.defaultApplyModeKey)
        try expect(WorkspaceProfileConfig.applyMode(defaults: defaults11) == .instantiateAsNew,
                   "assertion 11: applyMode override 'instantiateAsNew' returns .instantiateAsNew")
        defaults11.set("bogus-capture", forKey: WorkspaceProfileConfig.defaultCaptureModeKey)
        try expect(WorkspaceProfileConfig.captureMode(defaults: defaults11) == .snapshot,
                   "assertion 11: captureMode bogus string falls back to .snapshot")
        defaults11.set("bogus-apply", forKey: WorkspaceProfileConfig.defaultApplyModeKey)
        try expect(WorkspaceProfileConfig.applyMode(defaults: defaults11) == .restoreOver,
                   "assertion 11: applyMode bogus string falls back to .restoreOver")
    }
}

@MainActor
private final class FocusModeSession {
    let primaryTileId: UUID
    let companionTileId: UUID?
    let savedViewport: CanvasViewport
    let savedTiles: [Tile]
    let savedLastActiveTileId: UUID?
    let overlay = NSView(frame: .zero)
    private weak var canvasView: CanvasNSView?
    private let splitView = NSSplitView(frame: .zero)
    private let primaryPane = NSView(frame: .zero)
    private let companionPane = NSView(frame: .zero)
    private weak var primaryView: TileNSView?
    private weak var companionView: TileNSView?

    var protectedTileIds: Set<UUID> {
        var ids: Set<UUID> = [primaryTileId]
        if let companionTileId { ids.insert(companionTileId) }
        return ids
    }

    init(
        primaryTileId: UUID,
        companionTileId: UUID?,
        savedViewport: CanvasViewport,
        savedTiles: [Tile],
        savedLastActiveTileId: UUID?,
        canvasView: CanvasNSView,
        primaryView: TileNSView,
        companionView: TileNSView?
    ) {
        self.primaryTileId = primaryTileId
        self.companionTileId = companionTileId
        self.savedViewport = savedViewport
        self.savedTiles = savedTiles
        self.savedLastActiveTileId = savedLastActiveTileId
        self.canvasView = canvasView
        self.primaryView = primaryView
        self.companionView = companionView
        overlay.wantsLayer = true
        overlay.layer?.backgroundColor = NSColor.black.cgColor
        splitView.isVertical = true
        splitView.dividerStyle = .thin
        splitView.autoresizingMask = [.width, .height]
        splitView.frame = overlay.bounds
        overlay.addSubview(splitView)
        splitView.addArrangedSubview(primaryPane)
        if companionView != nil {
            splitView.addArrangedSubview(companionPane)
        }
        install(primaryView, in: primaryPane)
        if let companionView {
            install(companionView, in: companionPane)
        }
    }

    func restore() {
        overlay.removeFromSuperview()
        guard let canvasView else { return }
        if let primaryView {
            canvasView.addSubview(primaryView)
        }
        if let companionView {
            canvasView.addSubview(companionView)
        }
        canvasView.setViewport(savedViewport)
        for tile in savedTiles {
            canvasView.updateTile(tile)
        }
        if let savedLastActiveTileId {
            canvasView.markActive(tileId: savedLastActiveTileId)
        }
        canvasView.restoreTileSubviewOrder()
    }

    private func install(_ tileView: TileNSView, in pane: NSView) {
        tileView.removeFromSuperview()
        pane.addSubview(tileView)
        tileView.frame = pane.bounds
        tileView.autoresizingMask = [.width, .height]
    }
}

/// Lightweight `BrowserRuntime` spy for `--browser-note-action-check`: records
/// nav-method invocations so the A4 browser executors are observable without a
/// real `WKWebView`. No WebKit, no I/O, no first-responder games.
@MainActor
private final class SpyBrowserRuntime: BrowserRuntime {
    let id: BrowserRuntimeID = UUID()
    let tileId: TileID
    private(set) var url: String
    let title: String = ""
    let faviconURL: String? = nil
    let loadingState: BrowserLoadingState = .idle
    var onStateChange: (() -> Void)?
    var onFindResult: ((Bool) -> Void)?

    private(set) var reloadCount = 0
    private(set) var goBackCount = 0
    private(set) var goForwardCount = 0

    /// Stand-in page text: `find` reports `matchFound` when the query occurs here,
    /// letting the check drive both found and not-found without a real WKWebView.
    var findCorpus = ""

    init(tileId: TileID, initialURL: String) {
        self.tileId = tileId
        self.url = initialURL
    }

    func attach(to hostView: BrowserHostView) {}
    func detach() {}
    func loadURL(_ urlString: String) { url = urlString }
    func goBack() { goBackCount += 1 }
    func goForward() { goForwardCount += 1 }
    func reload() { reloadCount += 1 }
    func stop() {}
    var capturedInteractionState: Data? { nil }
    func restoreInteractionState(_ data: Data) {}
    func find(_ query: String, direction: BrowserFindDirection) {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        onFindResult?(findCorpus.localizedCaseInsensitiveContains(trimmed))
    }
    func focus() {}
    func blur() {}
    func isSemanticContentResponder(_ responder: NSResponder?) -> Bool { false }
    func terminate(policy: TerminationPolicy) {}
}

private extension NSView {
    func hasAncestor<T: NSView>(ofType type: T.Type) -> Bool {
        var view: NSView? = self
        while let current = view {
            if current is T { return true }
            view = current.superview
        }
        return false
    }
}

/// Ticket: docs/38-tickets/90-agent-ux/P2B.2-cross-project-walk.md
/// Gated on `--cross-project-agents-check`.
///
/// THE REAL PATH, not the walk in isolation: this drives
/// `AppDelegate.currentManagedAgentActivities()` — the exact function the
/// companion-sync `activitySnapshot` closure calls — with a registry naming
/// three projects, two of which hold one legacy `ManagedAgentSessionRecord`
/// each and one of which no longer exists on disk.
///
/// Deliberately with NO canvas and NO workspace runtime, because that is what
/// makes the assertion discriminating: the previous implementation opened with
/// `guard let canvasView … else { return [] }` and then filtered records by the
/// live canvas's managed-agent tiles, so it returned NOTHING here. It also
/// witnesses observer-independence (P2B.8) — no `ZoneRuntimeController` is
/// booted to list an agent.
extension AppDelegate {
    // A same-file extension, so the check can reach `registryStore` and
    // `currentManagedAgentActivities()` without widening either to the rest of
    // this file.
    static func runCrossProjectAgentDiscoveryChecks() throws {
    enum CheckError: Error, CustomStringConvertible {
        case failed(String)
        var description: String { switch self { case let .failed(message): return message } }
    }
    func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
        if !condition() { throw CheckError.failed(message) }
    }

    let fm = FileManager.default
    let tempRoot = fm.temporaryDirectory
        .appendingPathComponent("continuum-cross-project-agents-\(UUID().uuidString)", isDirectory: true)
    defer { try? fm.removeItem(at: tempRoot) }
    let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
    let projectARoot = tempRoot.appendingPathComponent("ProjectA", isDirectory: true)
    let projectBRoot = tempRoot.appendingPathComponent("ProjectB", isDirectory: true)
    // Never created — a registry keeps entries for projects that have been moved
    // or deleted, and one of those must not take the whole listing down.
    let projectGoneRoot = tempRoot.appendingPathComponent("ProjectGone", isDirectory: true)
    try fm.createDirectory(at: appSupport, withIntermediateDirectories: true)
    try fm.createDirectory(at: projectARoot, withIntermediateDirectories: true)
    try fm.createDirectory(at: projectBRoot, withIntermediateDirectories: true)

    let now = Date(timeIntervalSince1970: 1_900_200_000)
    let projectA = UUID(uuidString: "2B200000-0000-4000-8000-0000000000D1")!
    let projectB = UUID(uuidString: "2B200000-0000-4000-8000-0000000000D2")!
    let projectGone = UUID(uuidString: "2B200000-0000-4000-8000-0000000000D3")!
    let tileA = UUID(uuidString: "2B200000-0000-4000-8000-0000000000E1")!
    let tileB = UUID(uuidString: "2B200000-0000-4000-8000-0000000000E2")!

    try ManagedAgentSessionStore(projectRoot: projectARoot).upsert(ManagedAgentSessionRecord(
        tileId: tileA,
        agentKind: .claude,
        status: .running,
        lastSeenAt: now
    ))
    try ManagedAgentSessionStore(projectRoot: projectBRoot).upsert(ManagedAgentSessionRecord(
        tileId: tileB,
        agentKind: .codex,
        status: .stopped,
        lastSeenAt: now.addingTimeInterval(60)
    ))

    var registry = Registry.empty()
    registry.projects = [
        ProjectEntry(id: projectA, name: "Project A", rootPath: projectARoot.path, workspaceId: nil, lastOpenedAt: now, pinned: false, missing: false),
        ProjectEntry(id: projectB, name: "Project B", rootPath: projectBRoot.path, workspaceId: nil, lastOpenedAt: now, pinned: false, missing: false),
        ProjectEntry(id: projectGone, name: "Project Gone", rootPath: projectGoneRoot.path, workspaceId: nil, lastOpenedAt: now, pinned: false, missing: true),
    ]
    let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
    try registryStore.save(registry)

    let app = AppDelegate()
    app.registryStore = registryStore

    // P3.2, asserted at RUNTIME and not by reading the source: the listing must
    // REFUSE before the sweep has committed. A read that answers here is a read off
    // unswept files, and an empty answer would be indistinguishable from "no agents".
    do {
        _ = try app.currentManagedAgentActivities()
        throw CheckError.failed("cross-project discovery: the listing ANSWERED before the sweep committed — every row it returned came off unswept files")
    } catch is ReconciledManagedSessionSource.NotReady {
        // the refusal, which is the assertion
    }
    try app.reconciledManagedSessionSource.reconcile(registry: registry, reason: .continuumRestarted, now: now)

    let scan = try app.currentManagedAgentActivities()
    let activities = scan.activities
    // P2B.8: nothing live reported either of them — there is no canvas and no
    // supervised runner here, which is the whole point of the fixture.
    try expect(scan.observedAgentIds.isEmpty,
               "an agent listed off disk with no view and no runner is NOT observed — got \(scan.observedAgentIds.count) observed")
    try expect(activities.count == 2,
               "both projects' agents are published, and the project root that is gone is skipped rather than thrown — got \(activities.count)")
    guard let fromA = activities.first(where: { $0.tileId == tileA }),
          let fromB = activities.first(where: { $0.tileId == tileB })
    else {
        throw CheckError.failed("both the active-project and the NON-ACTIVE-project agent are published — got \(activities.map(\.tileId))")
    }
    // An unsupervised legacy record keys on its tile id (P2A.8's legacy identity).
    try expect(fromA.agentId == tileA && fromB.agentId == tileB,
               "an unsupervised legacy record is keyed by its tile id — got \(fromA.agentId) / \(fromB.agentId)")
    try expect(fromA.agentKind == .claude && fromB.agentKind == .codex,
               "each record's kind survives the walk — got \(fromA.agentKind) / \(fromB.agentKind)")
    // Status comes from the persisted record, since neither has a tile view here.
    // P4.14 MOVED BOTH VALUES, and this is the scan-level witness for the reported
    // bug: `A` is persisted `running` with no live view and no runner in flight, so
    // it reads IDLE — it used to read `working`, which is how a row went to "working"
    // at spawn and stayed there forever. `B` is persisted `stopped`, which reads
    // `stale` rather than `idle` so an ended session stays distinguishable from a
    // live one waiting on you.
    // P3.2: the sweep ran before this read, so A's `running` is now `cancelled` on
    // disk and both records describe the PAST. That is the point — after a restart no
    // file may claim liveness. Which of the two ways it ended is carried by
    // `endedReason` (P3.4 renders it), not by the status word at this layer.
    try expect(fromA.status == .stale && fromB.status == .stale,
               "after the sweep NEITHER persisted record claims liveness — got \(fromA.status) / \(fromB.status)")
    // …and P4.14's distinction is still a property of the pure derivation, asserted
    // where it cannot be masked by the sweep.
    try expect(AppDelegate.agentRowStatus(liveStatus: nil, hasLiveRunner: false, persisted: .running) == .idle,
               "a created-not-busy record still derives idle, distinct from an ended one")

    // And they reach the published payload, through the same fold the phone reads.
    let snapshot = DegradedDesktopActivitySnapshotSource.snapshot(
        descriptors: [],
        liveStatuses: [:],
        managedAgents: activities,
        replicaId: UUID(uuidString: "2B200000-0000-4000-8000-0000000000FF")!,
        now: now
    )
    try expect(Set(snapshot.byAgent.keys) == Set([tileA, tileB]),
               "agents from every project reach the published inventory — got \(snapshot.byAgent.keys.sorted { $0.uuidString < $1.uuidString })")
    }
}

/// Ticket: docs/38-tickets/90-agent-ux/P2B.4-feed-all-consumers.md
/// Gated on `--agent-inventory-wiring-check`.
///
/// FOUR SURFACES, ONE REBUILD. The sidebar tree, the canvas tile badges, the dock
/// attention count and the companion payload each used to derive "agent status"
/// for itself, through a different filter over a different subset — so they could
/// disagree, and did (a managed agent's raised hand reached the phone and left the
/// dock badge alone). This drives the real `AppDelegate` methods those four
/// surfaces are built from, ONCE, and asserts they all report the same thing.
///
/// Deliberately with NO workspace runtime and NO `ZoneRuntimeController`: the
/// active project's store is unreachable here, so everything comes through the
/// cross-project reads (P2B.2) and observer-independence (P2B.8) is witnessed
/// again. The canvas exists, because the tile badge is one of the four consumers.
///
/// SEVEN NEGATIVE TESTS OBSERVED RED at exit 1 with the final code, one per
/// consumer and one per input rule:
///   1. `agentStatusesByTileId` filtered to tiles with an installed view (the old
///      active-canvas filter) → `before the flip: agent …E2 is working in the
///      companion payload but nil in the sidebar` — the packet's own regression
///      witness, a status in the payload and absent from the sidebar.
///   2. the dock back on `currentAgentTileIds(status: .needsAttention).count` →
///      `the dock badge must be the snapshot's attention count — got nil`.
///   3. the supervised-record append dropped from
///      `currentManagedAgentActivities()` → `the published inventory must hold
///      every agent — got [4 ids]` (the headless agent gone).
///   4. `agentIdentities` taking every descriptor, not just the ones carrying an
///      `AgentDescriptor` → `a terminal session with no AgentDescriptor is not an
///      agent`.
///   5. the canvas filter dropped from `currentTerminalSessionDescriptors` → the
///      deleted tile's leftover descriptor (`…E9`) appears in the inventory.
///   6. `observedAgentStatuses` dropped as an input → `the terminal agent's
///      persisted status must reach the payload — got …stale`, which is also the
///      proof that a persisted terminal status is never the live one.
///   7. `applyAgentStatusesToCanvas` back on the raw observer map → `the zone
///      rollup is derived from the same statuses — got working: 0`, the managed
///      agent's status lost from the canvas surface.
///   8. one `listSessions()` call put back inside the companion closure → `the
///      companion closure must not build its own inventory — it names
///      listSessions`.
///
/// HONEST LIMIT: "from ONE rebuild" is not asserted by counting rebuilds. It
/// cannot be from here, and it is not the property that matters: the rebuild is a
/// pure recomputation, so a consumer that recomputed again would agree anyway (see
/// the invariant at `AgentActivitySurface`). What is measured is that the four
/// surfaces AGREE, and — for the one consumer whose real path needs a live sync
/// service to reach — that it holds no derivation of its own.
extension AppDelegate {
    static func runAgentInventoryWiringChecks() throws {
    enum CheckError: Error, CustomStringConvertible {
        case failed(String)
        var description: String { switch self { case let .failed(message): return message } }
    }
    func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
        if !condition() { throw CheckError.failed(message) }
    }

    let fm = FileManager.default
    let tempRoot = fm.temporaryDirectory
        .appendingPathComponent("continuum-agent-inventory-wiring-\(UUID().uuidString)", isDirectory: true)
    defer { try? fm.removeItem(at: tempRoot) }
    let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
    let agentsSupport = tempRoot.appendingPathComponent("Agents", isDirectory: true)
    let projectARoot = tempRoot.appendingPathComponent("ProjectA", isDirectory: true)
    let projectBRoot = tempRoot.appendingPathComponent("ProjectB", isDirectory: true)
    for dir in [appSupport, agentsSupport, projectARoot, projectBRoot] {
        try fm.createDirectory(at: dir, withIntermediateDirectories: true)
    }

    let now = Date(timeIntervalSince1970: 1_900_300_000)
    let workspaceId = UUID(uuidString: "2B400000-0000-4000-8000-0000000000A1")!
    let projectA = UUID(uuidString: "2B400000-0000-4000-8000-0000000000D1")!
    let projectB = UUID(uuidString: "2B400000-0000-4000-8000-0000000000D2")!
    let zoneA = UUID(uuidString: "2B400000-0000-4000-8000-0000000000C1")!
    let zoneB = UUID(uuidString: "2B400000-0000-4000-8000-0000000000C2")!
    // One terminal agent, one managed agent, one plain shell (NOT an agent), and a
    // terminal agent in a second project — the four shapes the four consumers have
    // to agree about.
    let terminalAgentTile = UUID(uuidString: "2B400000-0000-4000-8000-0000000000E1")!
    let managedAgentTile = UUID(uuidString: "2B400000-0000-4000-8000-0000000000E2")!
    let shellTile = UUID(uuidString: "2B400000-0000-4000-8000-0000000000E3")!
    let otherProjectAgentTile = UUID(uuidString: "2B400000-0000-4000-8000-0000000000E4")!
    // A FACT THIS FIXTURE IS BUILT AROUND: `ProjectStore.listSessions()` returns
    // every descriptor through `restoredForBoot()`, which forces
    // `AgentDescriptor.status` to `.stale`. A persisted terminal status is therefore
    // never the live one — which is why the runtime observer's map is an input to the
    // rebuild, and why this check flips a terminal agent's status through
    // `applyObserverStatuses`, the production entry point, rather than by rewriting a
    // file. Cross-project terminal agents legitimately read `.stale`: nothing is
    // observing them, and that is exactly what the sidebar showed for them before.

    // MARK: 1 · the fixture, all of it on disk — nothing in this process wrote it
    // through the app

    let placementA = ZonePlacement(zoneId: zoneA, projectId: projectA, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 600, height: 400), color: "blue", collapsed: false, hydrationPolicy: .automatic)
    let placementB = ZonePlacement(zoneId: zoneB, projectId: projectB, origin: ZonePoint(x: 1000, y: 0), size: ZoneSize(width: 600, height: 400), color: "green", collapsed: false, hydrationPolicy: .automatic)
    var registry = Registry.empty()
    registry.lastActiveWorkspaceId = workspaceId
    registry.workspaces = [WorkspaceEntry(id: workspaceId, name: "Default", projectIds: [projectA, projectB], createdAt: now, updatedAt: now)]
    registry.projects = [
        ProjectEntry(id: projectA, name: "Project A", rootPath: projectARoot.path, workspaceId: workspaceId, lastOpenedAt: now, pinned: false, missing: false),
        ProjectEntry(id: projectB, name: "Project B", rootPath: projectBRoot.path, workspaceId: workspaceId, lastOpenedAt: now, pinned: false, missing: false),
    ]
    let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
    try registryStore.save(registry)
    try WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport).save(
        WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [placementA, placementB],
            zoneZOrder: [zoneA, zoneB],
            lastActiveZoneId: zoneA
        )
    )

    let storeA = ProjectStore(projectRoot: projectARoot)
    let canvasA = CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [
        Tile(id: terminalAgentTile, kind: .terminal, title: "Agent · Claude", frame: TileFrame(x: 0, y: 0, width: 200, height: 120), zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata()),
        Tile(id: managedAgentTile, kind: .managedAgent, title: "Managed", frame: TileFrame(x: 220, y: 0, width: 200, height: 120), zPosition: .fromLegacyRank(2), runtimeRef: nil, metadata: TileMetadata()),
        Tile(id: shellTile, kind: .terminal, title: "Shell", frame: TileFrame(x: 440, y: 0, width: 140, height: 120), zPosition: .fromLegacyRank(3), runtimeRef: nil, metadata: TileMetadata()),
    ], groups: [], lastActiveTileId: terminalAgentTile)
    try storeA.saveCanvas(canvasA)
    func descriptor(id: UUID, tileId: UUID, root: URL, kind: AgentKind?, status: AgentStatus?) -> TerminalSessionDescriptor {
        TerminalSessionDescriptor(
            id: id, tileId: tileId, launchProfileId: "shell", command: "/bin/zsh", args: [], cwd: root.path,
            env: [:], title: "session", createdAt: now, lastStartedAt: now, lastExit: nil,
            agentDescriptor: kind.flatMap { kind in
                status.map { AgentDescriptor(agentKind: kind, worktreePath: root.path, status: $0, statusUpdatedAt: now) }
            }
        )
    }
    let terminalSessionId = UUID(uuidString: "2B400000-0000-4000-8000-0000000000F1")!
    try storeA.saveSession(descriptor(id: terminalSessionId, tileId: terminalAgentTile, root: projectARoot, kind: .claude, status: .working))
    // A plain shell. It is a terminal session with NO `AgentDescriptor`, so it is
    // not an agent on the desktop — see assertion 4.
    try storeA.saveSession(descriptor(id: UUID(uuidString: "2B400000-0000-4000-8000-0000000000F2")!, tileId: shellTile, root: projectARoot, kind: nil, status: nil))
    // Deliberately NOT on any canvas: a descriptor whose tile has been deleted is a
    // leftover file, and every one of the four surfaces dropped it before this ticket.
    try storeA.saveSession(descriptor(id: UUID(uuidString: "2B400000-0000-4000-8000-0000000000F3")!, tileId: UUID(uuidString: "2B400000-0000-4000-8000-0000000000E9")!, root: projectARoot, kind: .claude, status: .needsAttention))
    // The managed agent, as a legacy per-project record (P2A.8 keys it by tile id).
    try ManagedAgentSessionStore(projectRoot: projectARoot).upsert(ManagedAgentSessionRecord(
        tileId: managedAgentTile, agentKind: .managed, status: .running, lastSeenAt: now
    ))

    // Another project's agent, with its hand up. A managed record, because that is a
    // status that survives a read from disk. The dock badge could not see this before
    // the one-snapshot wiring: it counted tiles on the ACTIVE canvas.
    let storeB = ProjectStore(projectRoot: projectBRoot)
    try storeB.saveCanvas(CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [
        Tile(id: otherProjectAgentTile, kind: .managedAgent, title: "Agent · Codex", frame: TileFrame(x: 1000, y: 0, width: 200, height: 120), zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata()),
    ], groups: [], lastActiveTileId: nil))
    try ManagedAgentSessionStore(projectRoot: projectBRoot).upsert(ManagedAgentSessionRecord(
        tileId: otherProjectAgentTile, agentKind: .managed, status: .error, lastSeenAt: now
    ))

    // A HEADLESS supervised agent (P2A.6): no tile, in `AgentStore`, with a raised
    // hand on its recorded timeline. Before this ticket it reached no desktop
    // surface at all — `currentManagedAgentActivities()` only ever listed files.
    let headlessId = AgentID(rawValue: UUID(uuidString: "2B400000-0000-4000-8000-0000000000B1")!)
    let agentStore = AgentStore(applicationSupportDirectory: agentsSupport)
    try agentStore.upsert(AgentRecord(
        id: headlessId,
        displayName: "reviewer",
        role: "reviewer",
        model: "openai-codex/gpt-5.6-sol",
        thinking: "medium",
        cwd: projectARoot.path,
        projectId: projectA,
        createdAt: now,
        lastActivityAt: now.addingTimeInterval(10)
    ))

    let app = AppDelegate()
    app.registryStore = registryStore
    // P3.2 (design §5.9): arm the listing gate exactly as boot does.
    try app.reconciledManagedSessionSource.reconcile(registry: registry, reason: .continuumRestarted, now: now)
    // Assigned before first access, so the lazy default (which resolves the real
    // Application Support root) is never constructed.
    app.agentSupervisor = AgentSupervisor(store: agentStore, makeRunner: { _ in
        ScriptedAgentRunner(script: [])
    })
    app.agentSupervisor.restore()
    try expect(app.agentSupervisor.records[headlessId] != nil,
               "the headless agent must be adopted, or the assertions below say nothing about it")
    app.managedAgentActivityByAgent[headlessId.rawValue] = [AgentActivityEventDraft(
        agentId: headlessId.rawValue,
        tileId: nil,
        runId: nil,
        tone: .approval,
        kind: "approval.requested",
        status: .needsAttention,
        summary: "reviewer needs attention",
        occurredAt: now.addingTimeInterval(20),
        approvalRequestId: "req-1"
    )]

    let canvas = CanvasNSView(
        canvasState: canvasA,
        activeZone: placementA,
        zoneRenderModels: [CanvasNSView.ZoneRenderModel(placement: placementA, displayName: "Project A")]
    )
    for tile in canvasA.tiles where tile.kind == .terminal {
        canvas.install(tileView: TileNSView(tile: tile), for: tile)
    }
    // No view for the managed tile ON PURPOSE: a freshly built
    // `ManagedAgentTileNSView` reports `.configuring`, which would override its
    // persisted record and make the fixture describe the view instead of the store.
    app.canvasView = canvas

    // MARK: 2 · ONE rebuild — through the production observer entry point — and all
    // four surfaces read WITHOUT rebuilding again

    app.applyObserverStatuses([terminalAgentTile: .working])
    let snapshot = app.agentActivity.snapshot
    let dockLabel = NSApplication.shared.dockTile.badgeLabel
    let tree = try app.buildWorkspaceSidebarTree()

    func treeRows(_ tree: SidebarTree) -> [UUID: SidebarTileRow] {
        var rows: [UUID: SidebarTileRow] = [:]
        for workspace in tree.workspaces {
            for zone in workspace.zones {
                for tile in zone.tiles { rows[tile.tileId] = tile }
            }
        }
        return rows
    }
    var rows = treeRows(tree)
    try expect(Set(rows.keys) == Set([terminalAgentTile, managedAgentTile, shellTile, otherProjectAgentTile]),
               "the sidebar tree must hold every project's tiles, or an agreement assertion over it is vacuous — got \(rows.keys.count) row(s)")

    // The companion payload: every agent, from both projects, tiled and headless.
    try expect(Set(snapshot.byAgent.keys) == Set([terminalAgentTile, managedAgentTile, shellTile, otherProjectAgentTile, headlessId.rawValue]),
               "the published inventory must hold every agent — got \(snapshot.byAgent.keys.sorted { $0.uuidString < $1.uuidString })")
    try expect(snapshot.byAgent[terminalAgentTile]?.status == .working,
               "the terminal agent's persisted status must reach the payload — got \(String(describing: snapshot.byAgent[terminalAgentTile]?.status))")
    // P3.1/P3.2 moved this value again: the arming sweep above terminalized the
    // persisted `running` record, so the derived status is now `stale` — the session
    // did not survive the restart. (P4.14 had moved it from `working` to `idle` for a
    // related reason: created is not busy.) What the assertion is about is unchanged
    // across all three revisions — that the managed record REACHES the payload.
    try expect(snapshot.byAgent[managedAgentTile]?.status == .stale,
               "the managed agent's record status must reach the payload — got \(String(describing: snapshot.byAgent[managedAgentTile]?.status))")
    try expect(snapshot.byAgent[otherProjectAgentTile]?.status == .needsAttention,
               "the other project's agent must reach the payload with its hand up — got \(String(describing: snapshot.byAgent[otherProjectAgentTile]?.status))")

    // MARK: 3 · THE AGREEMENT. A status in the payload is a status in the sidebar,
    // on the tile, and in the dock count — no consumer may be missing one.

    func assertAgreement(_ snapshot: ActivityLogSnapshot, _ rows: [UUID: SidebarTileRow], _ label: String) throws {
        for (agentId, activity) in snapshot.byAgent
        where app.agentActivity.agentIdentities.contains(agentId) {
            guard let tileId = activity.tileId else { continue }
            guard let row = rows[tileId] else { continue }
            try expect(row.agentStatus == activity.status,
                       "\(label): agent \(agentId.uuidString) is \(activity.status) in the companion payload but \(String(describing: row.agentStatus)) in the sidebar")
            // `canvasBadgeStatus` deliberately shows no badge for configuring/idle, so
            // the tile is held to the badge the shared presenter derives from the same
            // status — not to a second opinion about what that status is.
            if let view = canvas.tileView(for: tileId) {
                try expect(view.agentStatus == AppDelegate.canvasBadgeStatus(activity.status),
                           "\(label): agent \(agentId.uuidString) is \(activity.status) in the payload but its tile badge is \(String(describing: view.agentStatus))")
            }
        }
    }
    try assertAgreement(snapshot, rows, "before the flip")
    // Vacuity guard: the agreement loop above is only worth anything if it actually
    // visited the tiled agents.
    try expect(rows[terminalAgentTile]?.agentStatus == .working && rows[otherProjectAgentTile]?.agentStatus == .needsAttention,
               "both projects' agents must carry their status in the sidebar — got \(String(describing: rows[terminalAgentTile]?.agentStatus)) / \(String(describing: rows[otherProjectAgentTile]?.agentStatus))")
    try expect(canvas.agentStatus(for: terminalAgentTile) == .working,
               "the tile badge must come from the same rebuild — got \(String(describing: canvas.agentStatus(for: terminalAgentTile)))")
    // The dock counts the OTHER project's raised hand and the HEADLESS agent's, both
    // of which the old canvas-filtered count could not see.
    try expect(AgentsBoardProjection.attentionCount(from: snapshot) == 2,
               "the attention count must include the other project's agent and the headless one — got \(AgentsBoardProjection.attentionCount(from: snapshot))")
    try expect(dockLabel == "2", "the dock badge must be the snapshot's attention count — got \(String(describing: dockLabel))")
    try expect(snapshot.byAgent[headlessId.rawValue]?.tileId == nil && rows[headlessId.rawValue] == nil,
               "a headless agent has no tile and therefore no sidebar row — it reaches the dock and the phone, which is the point of P2A.6")

    // MARK: 4 · a plain shell is IN the payload and is NOT an agent on the desktop

    try expect(app.agentActivity.agentIdentities.contains(shellTile) == false,
               "a terminal session with no AgentDescriptor is not an agent")
    try expect(snapshot.byAgent[shellTile]?.status == .idle,
               "the shell still reaches the phone as idle, exactly as it always has — got \(String(describing: snapshot.byAgent[shellTile]?.status))")
    try expect(rows[shellTile]?.agentStatus == nil,
               "a shell tile must carry NO sidebar status — every shell would otherwise roll up as unknown — got \(String(describing: rows[shellTile]?.agentStatus))")
    try expect(canvas.agentStatus(for: shellTile) == nil,
               "a shell tile must carry no badge — got \(String(describing: canvas.agentStatus(for: shellTile)))")

    // MARK: 5 · FLIP ONE STATUS. One refresh, and all four move together.

    app.applyObserverStatuses([terminalAgentTile: .needsAttention])
    let flipped = app.agentActivity.snapshot
    let flippedDockLabel = NSApplication.shared.dockTile.badgeLabel
    rows = treeRows(try app.buildWorkspaceSidebarTree())

    try expect(flipped.byAgent[terminalAgentTile]?.status == .needsAttention,
               "the flip must reach the companion payload — got \(String(describing: flipped.byAgent[terminalAgentTile]?.status))")
    try expect(rows[terminalAgentTile]?.agentStatus == .needsAttention,
               "the flip must reach the sidebar row — got \(String(describing: rows[terminalAgentTile]?.agentStatus))")
    try expect(canvas.agentStatus(for: terminalAgentTile) == .needsAttention,
               "the flip must reach the tile badge — got \(String(describing: canvas.agentStatus(for: terminalAgentTile)))")
    try expect(flippedDockLabel == "3",
               "the flip must reach the dock badge — got \(String(describing: flippedDockLabel))")
    // P4.14 moved this count from working: 1 to working: 0 — the 1 was the managed
    // agent, whose persisted `running` record read as `working` with nothing live
    // saying so. P3.1/P3.2 move it again: the arming sweep terminalizes that record,
    // so it now reads `stale` and the rollup DOES count it, in the bucket that says
    // the session ended. The zone is not less busy than it was — it was never busy,
    // and the rollup was repeating a field written once at spawn.
    try expect(canvas.zoneRenderModels.first?.agentStatusRollup == CanvasNSView.AgentStatusRollup(working: 0, needsAttention: 1, done: 0, stale: 1),
               "the zone rollup is derived from the same statuses — got \(String(describing: canvas.zoneRenderModels.first?.agentStatusRollup))")
    try assertAgreement(flipped, rows, "after the flip")

    // MARK: 6 · the COMPANION consumer holds no derivation of its own

    // A source scan, for the reason `piRunnerConstructionSites` is one: reaching the
    // real closure means standing up a `DesktopCompanionSyncService` with a transport
    // and a paired device. What can be asserted without that — and is the thing the
    // cross-review asked for — is that the closure has no inventory of its own: it
    // reads `agentActivity.snapshot` and does not list sessions or fold anything.
    let appSource = try String(
        contentsOf: URL(fileURLWithPath: FileManager.default.currentDirectoryPath, isDirectory: true)
            .appendingPathComponent("Sources/ContinuumRevived/App/ContinuumApp.swift"),
        encoding: .utf8
    )
    guard let closureStart = appSource.range(of: "activitySnapshot: { [weak self] in"),
          let closureEnd = appSource.range(of: "freshnessPublisher:", range: closureStart.upperBound..<appSource.endIndex) else {
        throw CheckError.failed("could not find the companion activitySnapshot closure — this scan is looking in the wrong place")
    }
    let closureBody = String(appSource[closureStart.upperBound..<closureEnd.lowerBound])
        .split(separator: "\n", omittingEmptySubsequences: false)
        .filter { !$0.trimmingCharacters(in: .whitespaces).hasPrefix("//") }
        .joined(separator: "\n")
    try expect(closureBody.contains("agentActivity.snapshot"),
               "the companion closure must return the one snapshot: \(closureBody)")
    for forbidden in ["DegradedDesktopActivitySnapshotSource", "listSessions", "AgentInventory.snapshot", "currentManagedAgentActivities"] {
        try expect(closureBody.contains(forbidden) == false,
                   "the companion closure must not build its own inventory — it names \(forbidden)")
    }

    // MARK: 7 · the nav-cycle order reads the same statuses

    try expect(app.currentAgentTileIds(status: .needsAttention) == [terminalAgentTile],
               "⌥-cycling over needs-attention agents must see what the badge sees — got \(app.currentAgentTileIds(status: .needsAttention))")
    // P2B.5: the managed tile is in this list. It was not before — the cycle filtered
    // `kind == .terminal` — so ⌥ stepped straight over every managed agent. Z-order,
    // so terminal (rank 1) then managed (rank 2).
    try expect(app.currentAgentTileIds(status: nil) == [terminalAgentTile, managedAgentTile],
               "⌥-cycling must reach a managed-agent tile, and the shell tile is not an agent to cycle to — got \(app.currentAgentTileIds(status: nil))")
    // …and the STATUS-FILTERED cycle selects it by its own status, not by its kind:
    // the managed agent is the only `idle` one here (the terminal agent was just
    // flipped to `needsAttention`). Without this the filtered cycle — the one the
    // packet names — would be proven only for terminal tiles.
    //
    // P4.14 changed the status this filters ON, not what it proves; P3.1/P3.2 change
    // it once more. The managed agent's persisted `running` record read `working`,
    // then `idle`, and now `stale` because the arming sweep terminalized it. The cycle
    // is still selecting a managed tile by a status, and `.working` is asserted EMPTY
    // below so the filter is not simply matching everything.
    try expect(app.currentAgentTileIds(status: .stale) == [managedAgentTile],
               "the filtered cycle must select a managed agent by its status — got \(app.currentAgentTileIds(status: .stale))")
    try expect(app.currentAgentTileIds(status: .working).isEmpty,
               "nothing is working here — an agent nobody is watching, whose record was written at spawn, is not a turn in flight — got \(app.currentAgentTileIds(status: .working))")

    NSApplication.shared.dockTile.badgeLabel = nil
    print("AgentInventoryWiring: 5 agents (2 projects, 1 managed, 1 headless, 1 shell excluded) agreed across sidebar/badge/dock/companion from one rebuild; a flipped status moved all four")
    }
}

/// P2B.6 — an observer sweep must not erase a badge it knows nothing about.
///
/// `applyAgentStatusesToCanvas` walks EVERY tile on the canvas on every refresh.
/// It used to assign `canvasBadgeStatus(statuses[tile.id])` unconditionally, so a
/// tile the inventory has no entry for got `nil` written over whatever it had —
/// including a managed tile that had just computed its own status from its own
/// ingest. The fix is one `guard`; this is its regression witness.
///
/// The fixture is the case the inventory cannot see: a managed-agent tile with a
/// LIVE `ManagedAgentTileNSView` and no `ManagedAgentSessionRecord` on disk and no
/// supervised `AgentRecord`. A vacuity guard asserts the inventory really has no
/// entry for it, or the assertion would be about nothing.
///
/// HONEST LIMIT, from the cross-review: the view is constructed and ingested into
/// DIRECTLY, not through `wireManagedAgentTile` — which always resolves or spawns a
/// supervised agent before the tile subscribes, so a tile wired that way does have
/// an entry. What is proven here is therefore the RULE ("a badge the sweep has no
/// entry for survives it"), not a claim about which production lifecycle window
/// reaches it. The production shape that does reach it is a tile that CARRIES a
/// badge while the inventory has nothing to say about it, which is now asserted on
/// the real production path in `--agent-status-check` (the shell tile there, whose
/// previously-`nil`-ed badge is the assertion this ticket reverses).
///
/// Both directions are asserted, because the packet's trap is over-correcting:
///   - NO ENTRY  → the badge is left alone (the bug);
///   - ENTRY that maps to no badge (`idle`) → the badge is still cleared, so a
///     terminal agent that genuinely went idle can still go dark.
///
/// TWO NEGATIVE TESTS OBSERVED RED at exit 1 with the final code:
///   1. the `guard` reverted to the unconditional assignment → `an observer sweep
///      with no entry for a managed tile must not erase its badge — got nil`.
///   2. the guard widened to also skip an entry whose badge is nil
///      (`guard let badge = statuses[tile.id].flatMap(Self.canvasBadgeStatus)`) →
///      `a terminal agent that went idle must still be able to clear its badge —
///      got Optional(ContinuumRevivedAgentUI.AgentStatus.working)`.
///
/// Gated on `--observer-sweep-badge-check`.
extension AppDelegate {
    static func runObserverSweepBadgeChecks() throws {
    enum CheckError: Error, CustomStringConvertible {
        case failed(String)
        var description: String { switch self { case let .failed(message): return message } }
    }
    func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
        if !condition() { throw CheckError.failed(message) }
    }

    let fm = FileManager.default
    let tempRoot = fm.temporaryDirectory
        .appendingPathComponent("continuum-observer-sweep-badge-\(UUID().uuidString)", isDirectory: true)
    defer { try? fm.removeItem(at: tempRoot) }
    let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
    let agentsSupport = tempRoot.appendingPathComponent("Agents", isDirectory: true)
    let projectRoot = tempRoot.appendingPathComponent("Project", isDirectory: true)
    for dir in [appSupport, agentsSupport, projectRoot] {
        try fm.createDirectory(at: dir, withIntermediateDirectories: true)
    }

    let now = Date(timeIntervalSince1970: 1_900_400_000)
    let workspaceId = UUID(uuidString: "2B600000-0000-4000-8000-0000000000A1")!
    let projectId = UUID(uuidString: "2B600000-0000-4000-8000-0000000000D1")!
    let zoneId = UUID(uuidString: "2B600000-0000-4000-8000-0000000000C1")!
    let terminalAgentTile = UUID(uuidString: "2B600000-0000-4000-8000-0000000000E1")!
    let managedAgentTile = UUID(uuidString: "2B600000-0000-4000-8000-0000000000E2")!

    let placement = ZonePlacement(zoneId: zoneId, projectId: projectId, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 600, height: 400), color: "blue", collapsed: false, hydrationPolicy: .automatic)
    var registry = Registry.empty()
    registry.lastActiveWorkspaceId = workspaceId
    registry.workspaces = [WorkspaceEntry(id: workspaceId, name: "Default", projectIds: [projectId], createdAt: now, updatedAt: now)]
    registry.projects = [
        ProjectEntry(id: projectId, name: "Project", rootPath: projectRoot.path, workspaceId: workspaceId, lastOpenedAt: now, pinned: false, missing: false)
    ]
    let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
    try registryStore.save(registry)
    try WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport).save(
        WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [placement],
            zoneZOrder: [zoneId],
            lastActiveZoneId: zoneId
        )
    )

    let store = ProjectStore(projectRoot: projectRoot)
    let canvasState = CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [
        Tile(id: terminalAgentTile, kind: .terminal, title: "Agent · Claude", frame: TileFrame(x: 0, y: 0, width: 200, height: 120), zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata()),
        Tile(id: managedAgentTile, kind: .managedAgent, title: "Managed", frame: TileFrame(x: 220, y: 0, width: 200, height: 120), zPosition: .fromLegacyRank(2), runtimeRef: nil, metadata: TileMetadata()),
    ], groups: [], lastActiveTileId: terminalAgentTile)
    try store.saveCanvas(canvasState)
    // The terminal agent is the one the inventory DOES have an entry for: a
    // persisted session carrying an `AgentDescriptor`, whose live status arrives
    // through `applyObserverStatuses` (a persisted status always reads `.stale`
    // after `restoredForBoot()` — see `--agent-inventory-wiring-check`).
    try store.saveSession(TerminalSessionDescriptor(
        id: UUID(uuidString: "2B600000-0000-4000-8000-0000000000F1")!,
        tileId: terminalAgentTile, launchProfileId: "shell", command: "/bin/zsh", args: [],
        cwd: projectRoot.path, env: [:], title: "session", createdAt: now, lastStartedAt: now, lastExit: nil,
        agentDescriptor: AgentDescriptor(agentKind: .claude, worktreePath: projectRoot.path, status: .working, statusUpdatedAt: now)
    ))
    // …and the managed tile deliberately has NOTHING on disk: no managed-session
    // record, no supervised agent record.

    let app = AppDelegate()
    app.registryStore = registryStore
    // P3.2 (design §5.9): arm the listing gate exactly as boot does.
    try app.reconciledManagedSessionSource.reconcile(registry: registry, reason: .continuumRestarted, now: now)
    app.agentSupervisor = AgentSupervisor(store: AgentStore(applicationSupportDirectory: agentsSupport), makeRunner: { _ in
        ScriptedAgentRunner(script: [])
    })

    let canvas = CanvasNSView(
        canvasState: canvasState,
        activeZone: placement,
        zoneRenderModels: [CanvasNSView.ZoneRenderModel(placement: placement, displayName: "Project")]
    )
    canvas.install(tileView: TileNSView(tile: canvasState.tiles[0]), for: canvasState.tiles[0])
    let managedView = ManagedAgentTileNSView(tile: canvasState.tiles[1])
    canvas.install(tileView: managedView, for: canvasState.tiles[1])
    app.canvasView = canvas

    // MARK: 1 · the managed tile computes its own status, through its own ingest

    managedView.ingest(.requestOpened(
        threadId: managedView.wiringThreadId,
        requestId: "req-1",
        kind: .commandExecutionApproval
    ))
    try expect(managedView.currentAgentStatus == .needsAttention,
               "the managed tile's own ingest must raise its hand, or this check is not about a badge the tile set — got \(managedView.currentAgentStatus)")
    try expect(canvas.agentStatus(for: managedAgentTile) == .needsAttention,
               "the managed tile must be showing the badge its ingest set — got \(String(describing: canvas.agentStatus(for: managedAgentTile)))")

    // MARK: 2 · THE WITNESS. An observer sweep for an unrelated agent leaves it alone.

    app.applyObserverStatuses([terminalAgentTile: .working])

    // Vacuity guard: the assertion below says nothing unless the sweep genuinely
    // had no entry for this tile.
    try expect(app.agentStatusesByTileId()[managedAgentTile] == nil,
               "the fixture must give the inventory NO entry for the managed tile — got \(String(describing: app.agentStatusesByTileId()[managedAgentTile]))")
    try expect(canvas.agentStatus(for: managedAgentTile) == .needsAttention,
               "an observer sweep with no entry for a managed tile must not erase its badge — got \(String(describing: canvas.agentStatus(for: managedAgentTile)))")
    // The sweep still did its job for the tile it DOES know about.
    try expect(canvas.agentStatus(for: terminalAgentTile) == .working,
               "the sweep must still drive the tile it has an entry for — got \(String(describing: canvas.agentStatus(for: terminalAgentTile)))")

    // MARK: 3 · the other direction. An entry that says idle still clears a badge.

    app.applyObserverStatuses([terminalAgentTile: .idle])
    try expect(app.agentStatusesByTileId()[terminalAgentTile] == .idle,
               "the idle flip must reach the inventory, or the assertion below is vacuous — got \(String(describing: app.agentStatusesByTileId()[terminalAgentTile]))")
    try expect(canvas.agentStatus(for: terminalAgentTile) == nil,
               "a terminal agent that went idle must still be able to clear its badge — got \(String(describing: canvas.agentStatus(for: terminalAgentTile)))")
    try expect(canvas.agentStatus(for: managedAgentTile) == .needsAttention,
               "and the managed tile's badge survives a second sweep too — got \(String(describing: canvas.agentStatus(for: managedAgentTile)))")

    NSApplication.shared.dockTile.badgeLabel = nil
    print("ObserverSweepBadge: a managed tile's self-computed badge survived two observer sweeps that had no entry for it; an entry that says idle still cleared a terminal agent's badge")
    }
}

/// Ticket: docs/38-tickets/90-agent-ux/P2B.7-incremental-refresh.md
/// Gated on `--agent-incremental-refresh-check`.
///
/// AN AGENT EVENT MUST NOT RE-READ THE DISK. `recordManagedActivity` is called per
/// streamed runtime event; it used to schedule a full `refreshAgentSurfaces()`,
/// which loads the registry, every project's canvas and every project's session
/// store. It now folds the one draft it already has into the snapshot the desktop is
/// holding (`AgentsBoardProjection.appendLocal`) and only debounces the PUSH.
///
/// HOW "WITHOUT A DISK READ" IS MEASURED, rather than asserted by inspection: the
/// whole fixture is DELETED from disk before the event is fed. A path that re-read
/// the disk would lose the terminal agent, because there is no longer a registry, a
/// canvas or a session file to find it in. That the deletion is real, and that the
/// retention therefore means something, is proven at the end by calling the
/// structural path (`refreshAgentSurfaces`) and watching that same agent VANISH —
/// the vacuity guard this check would otherwise be missing.
///
/// FIVE NEGATIVE TESTS OBSERVED RED at exit 1 with the final code, quoted verbatim:
///   1. the incremental ingest dropped, the debounced push kept (so the event only
///      ever reaches the surfaces later) → `the agent's own event must reach the
///      snapshot with no disk read — got Optional(…AgentStatus.idle)`.
///   2. the pre-ticket body in its place — a full `refreshAgentSurfaces()` on the
///      event path → `an unrelated agent must survive an agent event untouched —
///      the terminal agent is nil`. That is the disk read, caught.
///   3. `AgentsBoardProjection.appendLocal` stamping `sequence: 1` instead of
///      `snapshotSequence + 1` → the same assertion as 1 (`got
///      Optional(…AgentStatus.idle)`): the event is folded in and then ignored,
///      because the fold derives from the canonically-last event. Also red in
///      `ContinuumRevivedCoreChecks`: `P2B.7: appendLocal must move the agent's
///      summary`.
///   4. `pushAgentSurfaces` diffing against `agentActivity.snapshot` itself instead
///      of `agentActivityChangeBase` → `the first push reports every agent as ADDED
///      — got 0`.
///   5. `ingestAgentActivityIncrementally` not inserting into `agentIdentities` →
///      `a supervised agent's event must make it an agent on the desktop`.
///
///   6. the change base advanced inside `rebuildAgentActivitySnapshot` instead of on
///      the push (so what a reader's rebuild found is never reported) → `the first
///      push reports every agent as ADDED — got 0`.
///
/// TWO MORE in `ContinuumRevivedCoreChecks`, defending the two design choices in
/// `changeSet(from:to:)`:
///   7. comparing whole `AgentActivity` values instead of the row fields → `P2B.7:
///      positional renumbering alone must NOT report a row as changed — got 4
///      touched`, i.e. the whole board reported as moved because one agent was
///      created.
///   8. the oldest-event timestamp dropped from the ring witness → `P2B.7: an event
///      that evicts the oldest at the cap must still report the row as updated — got
///      0` (the cross-review's 200-cap case).
extension AppDelegate {
    static func runAgentIncrementalRefreshChecks() throws {
    enum CheckError: Error, CustomStringConvertible {
        case failed(String)
        var description: String { switch self { case let .failed(message): return message } }
    }
    func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
        if !condition() { throw CheckError.failed(message) }
    }

    let fm = FileManager.default
    let tempRoot = fm.temporaryDirectory
        .appendingPathComponent("continuum-agent-incremental-refresh-\(UUID().uuidString)", isDirectory: true)
    defer { try? fm.removeItem(at: tempRoot) }
    let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
    let agentsSupport = tempRoot.appendingPathComponent("Agents", isDirectory: true)
    let projectRoot = tempRoot.appendingPathComponent("Project", isDirectory: true)
    for dir in [appSupport, agentsSupport, projectRoot] {
        try fm.createDirectory(at: dir, withIntermediateDirectories: true)
    }

    let now = Date(timeIntervalSince1970: 1_900_500_000)
    let workspaceId = UUID(uuidString: "2B700000-0000-4000-8000-0000000000A1")!
    let projectId = UUID(uuidString: "2B700000-0000-4000-8000-0000000000D1")!
    let zoneId = UUID(uuidString: "2B700000-0000-4000-8000-0000000000C1")!
    // The BYSTANDER: a terminal agent that exists only on disk. Nothing in this
    // check ever sends it an event, so it is the thing a disk read would drop.
    let terminalAgentTile = UUID(uuidString: "2B700000-0000-4000-8000-0000000000E1")!

    let placement = ZonePlacement(zoneId: zoneId, projectId: projectId, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 600, height: 400), color: "blue", collapsed: false, hydrationPolicy: .automatic)
    var registry = Registry.empty()
    registry.lastActiveWorkspaceId = workspaceId
    registry.workspaces = [WorkspaceEntry(id: workspaceId, name: "Default", projectIds: [projectId], createdAt: now, updatedAt: now)]
    registry.projects = [
        ProjectEntry(id: projectId, name: "Project", rootPath: projectRoot.path, workspaceId: workspaceId, lastOpenedAt: now, pinned: false, missing: false)
    ]
    let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
    try registryStore.save(registry)
    try WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport).save(
        WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [placement],
            zoneZOrder: [zoneId],
            lastActiveZoneId: zoneId
        )
    )

    let store = ProjectStore(projectRoot: projectRoot)
    let canvasState = CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [
        Tile(id: terminalAgentTile, kind: .terminal, title: "Agent · Claude", frame: TileFrame(x: 0, y: 0, width: 200, height: 120), zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata()),
    ], groups: [], lastActiveTileId: terminalAgentTile)
    try store.saveCanvas(canvasState)
    try store.saveSession(TerminalSessionDescriptor(
        id: UUID(uuidString: "2B700000-0000-4000-8000-0000000000F1")!,
        tileId: terminalAgentTile, launchProfileId: "shell", command: "/bin/zsh", args: [],
        cwd: projectRoot.path, env: [:], title: "session", createdAt: now, lastStartedAt: now, lastExit: nil,
        agentDescriptor: AgentDescriptor(agentKind: .claude, worktreePath: projectRoot.path, status: .working, statusUpdatedAt: now)
    ))

    // Two HEADLESS supervised agents (P2A.6). They live in `AgentStore`, which the
    // supervisor holds in memory once restored — so they are the ones whose events
    // this check feeds, and they survive the disk deletion for a reason that is
    // stated rather than incidental (the supervisor's records, not a file).
    let agentOne = AgentID(rawValue: UUID(uuidString: "2B700000-0000-4000-8000-0000000000B1")!)
    let agentTwo = AgentID(rawValue: UUID(uuidString: "2B700000-0000-4000-8000-0000000000B2")!)
    let agentStore = AgentStore(applicationSupportDirectory: agentsSupport)
    for (agent, name) in [(agentOne, "builder"), (agentTwo, "reviewer")] {
        try agentStore.upsert(AgentRecord(
            id: agent, displayName: name, role: name, model: "openai-codex/gpt-5.6-sol",
            thinking: "medium", cwd: projectRoot.path, projectId: projectId,
            createdAt: now, lastActivityAt: now
        ))
    }

    let app = AppDelegate()
    app.registryStore = registryStore
    // P3.2 (design §5.9): arm the listing gate exactly as boot does.
    try app.reconciledManagedSessionSource.reconcile(registry: registry, reason: .continuumRestarted, now: now)
    app.agentSupervisor = AgentSupervisor(store: agentStore, makeRunner: { _ in ScriptedAgentRunner(script: []) })
    app.agentSupervisor.restore()
    try expect(app.agentSupervisor.records[agentOne] != nil && app.agentSupervisor.records[agentTwo] != nil,
               "both supervised agents must be adopted, or the assertions below say nothing about them")

    let canvas = CanvasNSView(
        canvasState: canvasState,
        activeZone: placement,
        zoneRenderModels: [CanvasNSView.ZoneRenderModel(placement: placement, displayName: "Project")]
    )
    canvas.install(tileView: TileNSView(tile: canvasState.tiles[0]), for: canvasState.tiles[0])
    app.canvasView = canvas

    // MARK: 1 · ONE structural rebuild, from disk. Every agent is added.

    app.refreshAgentSurfaces(notify: false)
    let seeded = app.agentActivity.snapshot
    try expect(seeded.byAgent[terminalAgentTile] != nil,
               "the structural rebuild must find the terminal agent on disk, or nothing below is about losing it")
    try expect(Set(app.agentActivity.lastChange.added) == Set([terminalAgentTile, agentOne.rawValue, agentTwo.rawValue]),
               "the first push reports every agent as ADDED — got \(app.agentActivity.lastChange.added.count)")
    try expect(app.agentActivity.lastChange.updated.isEmpty && app.agentActivity.lastChange.removed.isEmpty,
               "nothing was there before, so nothing is updated or removed")
    try expect(app.agentActivity.snapshot.byAgent[agentOne.rawValue]?.status == .idle,
               "a supervised agent with no recorded activity starts idle — got \(String(describing: app.agentActivity.snapshot.byAgent[agentOne.rawValue]?.status))")

    // MARK: 1b · what a READER rebuild between two pushes reports. From the
    // cross-review, which asked whether a rebuild that does not push leaves the
    // change base stale and fabricates changes.
    //
    // `currentAgentTileIds` recomputes the snapshot and does not push (a keystroke
    // reads fresh), and the base only advances on a push — so the next push reports
    // whatever that recomputation moved. MEASURED, and it is not nothing: a
    // PERSISTED TERMINAL agent moves on every single read, because
    // `AgentDescriptor.restoredForBoot` stamps `statusUpdatedAt = now` and
    // `ProjectStore.listSessions()` returns everything through it. That is a property
    // of the data source, not of this ticket — its `updatedAt` really did change, and
    // a row showing a relative time really does need re-rendering.
    //
    // What must NOT move is a supervised agent, whose activity is folded from records
    // and drafts this process holds: if a plain re-read renumbered or re-clocked
    // those, every rebuild would report the whole board and a diffing list would
    // reload exactly as it does today.
    _ = app.currentAgentTileIds(status: nil)
    app.pushAgentSurfaces(notify: false)
    let readerChange = app.agentActivity.lastChange
    try expect(readerChange.updated == Set([terminalAgentTile]),
               "a reader's rebuild must report only the agent whose timestamp the boot-restore stamp moves — got \(readerChange.updated.count) updated")
    try expect(readerChange.added.isEmpty && readerChange.removed.isEmpty,
               "a reader's rebuild must not add or remove anybody — got added \(readerChange.added.count) removed \(readerChange.removed.count)")
    try expect(readerChange.touched.contains(agentOne.rawValue) == false && readerChange.touched.contains(agentTwo.rawValue) == false,
               "a supervised agent must be STABLE across a plain re-read — otherwise every rebuild reports the whole board")

    // MARK: 2 · THE DISK GOES AWAY, and then an agent event arrives.

    // The bystander as it stands after the last read of the disk — section 1b's
    // reader rebuild re-stamped its `updatedAt`, so this is the value that must
    // survive, not `seeded`'s.
    let bystanderBeforeEvent = app.agentActivity.snapshot.byAgent[terminalAgentTile]
    try fm.removeItem(at: tempRoot)
    let sequenceBeforeEvent = app.agentActivity.snapshot.snapshotSequence
    app.recordManagedActivity(
        agentId: agentOne,
        tileId: nil,
        event: .requestOpened(threadId: "thread-1", requestId: "req-1", kind: .commandExecutionApproval),
        status: .needsAttention
    )

    let afterEvent = app.agentActivity.snapshot
    try expect(afterEvent.byAgent[agentOne.rawValue]?.status == .needsAttention,
               "the agent's own event must reach the snapshot with no disk read — got \(String(describing: afterEvent.byAgent[agentOne.rawValue]?.status))")
    try expect(afterEvent.byAgent[agentOne.rawValue]?.lastSummary == "Needs approval",
               "the event must become the agent's current state — got \(String(describing: afterEvent.byAgent[agentOne.rawValue]?.lastSummary))")
    // THE HEADLINE PROPERTY, asserted before the mechanism below it: byte-for-byte
    // the activity the disk rebuild produced. The bystander must not merely still be
    // there, it must be UNTOUCHED. (Its status reads `.stale`, not the `.working` on
    // the descriptor, because `listSessions()` returns everything through
    // `restoredForBoot()` — see `--agent-inventory-wiring-check`.)
    try expect(afterEvent.byAgent[terminalAgentTile] == bystanderBeforeEvent,
               "an unrelated agent must survive an agent event untouched — the terminal agent is \(String(describing: afterEvent.byAgent[terminalAgentTile]?.status))")
    try expect(bystanderBeforeEvent?.status == .stale,
               "…and that survival is of a real entry, not of two nils — got \(String(describing: seeded.byAgent[terminalAgentTile]?.status))")
    try expect(afterEvent.snapshotSequence == sequenceBeforeEvent + 1,
               "the local event is stamped one past the snapshot, so the fold derives from it — got \(afterEvent.snapshotSequence) after \(sequenceBeforeEvent)")
    try expect(afterEvent.byAgent[agentTwo.rawValue] != nil,
               "and so must the other supervised agent")
    try expect(app.agentActivity.agentIdentities.contains(agentOne.rawValue),
               "a supervised agent's event must make it an agent on the desktop")

    // MARK: 3 · the PUSH reports exactly what moved — and coalesces.

    app.recordManagedActivity(
        agentId: agentTwo,
        tileId: nil,
        event: .turnStarted(threadId: "thread-2", turnId: "turn-1"),
        status: .working
    )
    // A THIRD agent, spawned after the last structural rebuild: its first event
    // arrives before anything has listed it, which is the case
    // `ingestAgentActivityIncrementally` inserts into `agentIdentities` for. Without
    // that insert it would be filtered out of the sidebar and the badge sweep until
    // something unrelated moved.
    let agentThree = app.agentSupervisor.spawn(
        role: "scout", prompt: nil, cwd: projectRoot, model: "openai-codex/gpt-5.6-sol",
        thinking: "medium", projectId: projectId
    )
    try expect(app.agentActivity.snapshot.byAgent[agentThree.rawValue] == nil,
               "spawning must not itself put the agent in the snapshot, or the ADDED assertion below is vacuous")
    app.recordManagedActivity(
        agentId: agentThree,
        tileId: nil,
        event: .turnStarted(threadId: "thread-3", turnId: "turn-1"),
        status: .working
    )
    let sequenceAfterEvents = app.agentActivity.snapshot.snapshotSequence
    app.pushAgentSurfaces(notify: false)
    let change = app.agentActivity.lastChange
    try expect(change.touched == Set([agentOne.rawValue, agentTwo.rawValue, agentThree.rawValue]),
               "three coalesced events must all be reported — got added \(change.added.count) updated \(change.updated.count)")
    try expect(change.updated == Set([agentOne.rawValue, agentTwo.rawValue]),
               "the two agents that already had rows are UPDATED — got \(change.updated.count)")
    try expect(change.added == Set([agentThree.rawValue]),
               "the agent whose first event this was is ADDED — got \(change.added.count)")
    try expect(app.agentActivity.agentIdentities.contains(agentThree.rawValue),
               "a supervised agent's event must make it an agent on the desktop")
    try expect(change.removed.isEmpty,
               "no agent disappeared — got removed \(change.removed.count)")
    try expect(change.touched.contains(terminalAgentTile) == false,
               "the agent that did not move must NOT be in the change-set — that is what a diffing list consumes")
    // A real surface moved off the incremental snapshot: the dock badge counts the
    // raised hand that arrived after the disk was gone.
    try expect(NSApplication.shared.dockTile.badgeLabel == "1",
               "the dock badge must reflect the incrementally folded event — got \(String(describing: NSApplication.shared.dockTile.badgeLabel))")
    // A push with nothing new reports nothing — the base advanced with the push.
    app.pushAgentSurfaces(notify: false)
    try expect(app.agentActivity.lastChange.isEmpty,
               "a push with no new events reports an empty change-set — got \(app.agentActivity.lastChange.touched.count) touched")

    // MARK: 4 · VACUITY GUARD. The disk really is gone: the structural path loses
    // the terminal agent, which is exactly what sections 2 and 3 proved the event
    // path does not do.

    app.refreshAgentSurfaces(notify: false)
    try expect(app.agentActivity.snapshot.byAgent[terminalAgentTile] == nil,
               "the structural rebuild reads the disk, so with the fixture deleted the terminal agent must be GONE — otherwise 'without a disk read' was never tested")
    try expect(app.agentActivity.lastChange.removed == Set([terminalAgentTile]),
               "and that loss is reported as REMOVED — got \(app.agentActivity.lastChange.removed.count)")

    NSApplication.shared.dockTile.badgeLabel = nil
    print("AgentIncrementalRefresh: with the fixture deleted from disk, 3 agent events folded into the held snapshot (sequence \(sequenceBeforeEvent) → \(sequenceAfterEvents)), the bystander terminal agent survived all of them untouched, one coalesced push reported exactly the 3 agents that moved (2 updated, 1 added), and the structural rebuild then dropped the bystander")
    }
}

/// Ticket: docs/38-tickets/90-agent-ux/P2B.8-observer-independence.md
/// Gated on `--agent-observer-independence-check`.
///
/// THE INVENTORY MUST NOT DEPEND ON LIVE OBSERVERS. `ZoneRuntimeBudgetConfig`
/// `.closeOnZero` defaults true, so releasing a project's last zone reference tears
/// down its `ZoneRuntimeController` and with it that project's `SessionObserver`. An
/// inbox that spans workspaces cannot be built on live observers — it would show
/// empty or frozen state for everything you are not currently looking at.
///
/// So this drives the real `refreshAgentSurfaces()` with NO `ZoneRuntimeController`,
/// NO workspace runtime and (in section 1) NO canvas at all: every agent it finds
/// comes from a file, and each must appear with the status that file holds, MARKED as
/// something nobody has confirmed. Then a live view and a live observer sweep are
/// added, and the overlay must win and clear the mark.
///
/// Not a second AgentObservation unit test: `unobservedAgentIds` is pure and could be
/// called with hand-built arguments, which would prove nothing about whether the app
/// passes it the real observer set. What is asserted here is the WIRING — that the
/// desktop's own rebuild produces the flag from its own inputs.
///
/// WHY THE FLAG CARRIES NO AGE, measured here rather than argued: section 2 shows a
/// TERMINAL agent's persisted information reading a fraction of a second old on a
/// fixture written an hour ago, because `ProjectStore.listSessions()` returns every
/// descriptor through `AgentDescriptor.restoredForBoot()`, which stamps
/// `statusUpdatedAt = now` (see `--agent-inventory-wiring-check`). A threshold-based
/// flag would therefore exempt every terminal agent forever — the packet's
/// `## Approach` asked for one, and its own `## Verify` ("every agent … a staleness
/// flag set") is what rules against it. See `AgentObservation` for the full
/// reasoning and where the threshold went instead.
///
/// FIVE NEGATIVE TESTS OBSERVED RED at exit 1 with the final code:
///   1. `unobservedAgentIds:` dropped from the `AgentActivitySurface` the rebuild
///      writes → `an agent read off disk with no observer must be marked unobserved
///      — got 0 marked of 4 agents`.
///   2. `AgentObservation.unobservedAgentIds` aging rows past a 900s threshold — the
///      packet's literal `## Approach` → `an agent read off disk with no observer
///      must be marked unobserved — got 3 marked of 4 agents`, the terminal agent
///      exempted on an hour-old fixture. This is the measurement that removed the
///      threshold.
///   3. managed records counted as observed unconditionally (`observedAgentIds`
///      inserted regardless of `liveStatus`) → `an agent read off disk with no
///      observer must be marked unobserved — got 2 marked of 4 agents`, and
///      `--cross-project-agents-check` red too: `an agent listed off disk with no
///      view and no runner is NOT observed — got 2 observed`.
///   4. the `unobservedAgentIds.remove` dropped from
///      `ingestAgentActivityIncrementally` → `an agent's OWN event must clear the
///      mark without a rebuild — got 3 marked`.
///   5. `observedAgentIds` seeded from `liveStatuses` instead of
///      `observedAgentStatuses`, i.e. the canvas badge the app itself wrote counted
///      as an observation → `an agent whose observer went away must go BACK to
///      unobserved — got 2 marked`. Raised by the cross-review; section 4.
extension AppDelegate {
    static func runAgentObserverIndependenceChecks() throws {
    enum CheckError: Error, CustomStringConvertible {
        case failed(String)
        var description: String { switch self { case let .failed(message): return message } }
    }
    func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
        if !condition() { throw CheckError.failed(message) }
    }

    let fm = FileManager.default
    let tempRoot = fm.temporaryDirectory
        .appendingPathComponent("continuum-observer-independence-\(UUID().uuidString)", isDirectory: true)
    defer { try? fm.removeItem(at: tempRoot) }
    let appSupport = tempRoot.appendingPathComponent("AppSupport", isDirectory: true)
    let agentsSupport = tempRoot.appendingPathComponent("Agents", isDirectory: true)
    let projectARoot = tempRoot.appendingPathComponent("ProjectA", isDirectory: true)
    let projectBRoot = tempRoot.appendingPathComponent("ProjectB", isDirectory: true)
    for dir in [appSupport, agentsSupport, projectARoot, projectBRoot] {
        try fm.createDirectory(at: dir, withIntermediateDirectories: true)
    }

    // The REAL clock, not a fixed fixture one: section 2 measures how old the app
    // thinks a persisted terminal agent's information is, and `restoredForBoot()`
    // stamps `Date()`. A fixture clock parked in 2030 would make that measurement say
    // whatever the offset chose. Everything persisted here is deliberately an hour
    // old, so "the app thinks it is seconds old" can only come from the re-stamp.
    let now = Date()
    let anHourAgo = now.addingTimeInterval(-3600)
    let workspaceId = UUID(uuidString: "2B800000-0000-4000-8000-0000000000A1")!
    let projectA = UUID(uuidString: "2B800000-0000-4000-8000-0000000000D1")!
    let projectB = UUID(uuidString: "2B800000-0000-4000-8000-0000000000D2")!
    let zoneA = UUID(uuidString: "2B800000-0000-4000-8000-0000000000C1")!
    let zoneB = UUID(uuidString: "2B800000-0000-4000-8000-0000000000C2")!
    let terminalAgentTile = UUID(uuidString: "2B800000-0000-4000-8000-0000000000E1")!
    let managedTileA = UUID(uuidString: "2B800000-0000-4000-8000-0000000000E2")!
    // The agent in the OTHER project — the one whose controller is exactly what
    // `closeOnZero` releases when you look somewhere else.
    let managedTileB = UUID(uuidString: "2B800000-0000-4000-8000-0000000000E3")!
    let headlessId = AgentID(rawValue: UUID(uuidString: "2B800000-0000-4000-8000-0000000000B1")!)

    // MARK: 1 · the fixture, entirely on disk

    let placementA = ZonePlacement(zoneId: zoneA, projectId: projectA, origin: ZonePoint(x: 0, y: 0), size: ZoneSize(width: 600, height: 400), color: "blue", collapsed: false, hydrationPolicy: .automatic)
    let placementB = ZonePlacement(zoneId: zoneB, projectId: projectB, origin: ZonePoint(x: 1000, y: 0), size: ZoneSize(width: 600, height: 400), color: "green", collapsed: false, hydrationPolicy: .automatic)
    var registry = Registry.empty()
    registry.lastActiveWorkspaceId = workspaceId
    registry.workspaces = [WorkspaceEntry(id: workspaceId, name: "Default", projectIds: [projectA, projectB], createdAt: anHourAgo, updatedAt: anHourAgo)]
    registry.projects = [
        ProjectEntry(id: projectA, name: "Project A", rootPath: projectARoot.path, workspaceId: workspaceId, lastOpenedAt: anHourAgo, pinned: false, missing: false),
        ProjectEntry(id: projectB, name: "Project B", rootPath: projectBRoot.path, workspaceId: workspaceId, lastOpenedAt: anHourAgo, pinned: false, missing: false),
    ]
    let registryStore = RegistryStore(applicationSupportDirectory: appSupport)
    try registryStore.save(registry)
    try WorkspaceStore(workspaceId: workspaceId, applicationSupportDirectory: appSupport).save(
        WorkspaceDocument(
            viewport: CanvasViewport(x: 0, y: 0, zoom: 1),
            zones: [placementA, placementB],
            zoneZOrder: [zoneA, zoneB],
            lastActiveZoneId: zoneA
        )
    )

    let canvasA = CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [
        Tile(id: terminalAgentTile, kind: .terminal, title: "Agent · Claude", frame: TileFrame(x: 0, y: 0, width: 200, height: 120), zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata()),
        Tile(id: managedTileA, kind: .managedAgent, title: "Managed A", frame: TileFrame(x: 220, y: 0, width: 200, height: 120), zPosition: .fromLegacyRank(2), runtimeRef: nil, metadata: TileMetadata()),
    ], groups: [], lastActiveTileId: terminalAgentTile)
    let storeA = ProjectStore(projectRoot: projectARoot)
    try storeA.saveCanvas(canvasA)
    try storeA.saveSession(TerminalSessionDescriptor(
        id: UUID(uuidString: "2B800000-0000-4000-8000-0000000000F1")!,
        tileId: terminalAgentTile, launchProfileId: "shell", command: "/bin/zsh", args: [],
        cwd: projectARoot.path, env: [:], title: "session", createdAt: anHourAgo, lastStartedAt: anHourAgo, lastExit: nil,
        agentDescriptor: AgentDescriptor(agentKind: .claude, worktreePath: projectARoot.path, status: .working, statusUpdatedAt: anHourAgo)
    ))
    try ManagedAgentSessionStore(projectRoot: projectARoot).upsert(ManagedAgentSessionRecord(
        tileId: managedTileA, agentKind: .managed, status: .running, lastSeenAt: anHourAgo
    ))

    let canvasB = CanvasState(viewport: CanvasViewport(x: 0, y: 0, zoom: 1), tiles: [
        Tile(id: managedTileB, kind: .managedAgent, title: "Managed B", frame: TileFrame(x: 1000, y: 0, width: 200, height: 120), zPosition: .fromLegacyRank(1), runtimeRef: nil, metadata: TileMetadata()),
    ], groups: [], lastActiveTileId: nil)
    try ProjectStore(projectRoot: projectBRoot).saveCanvas(canvasB)
    try ManagedAgentSessionStore(projectRoot: projectBRoot).upsert(ManagedAgentSessionRecord(
        tileId: managedTileB, agentKind: .managed, status: .running, lastSeenAt: anHourAgo
    ))

    // A HEADLESS supervised agent, restored from its store: the supervisor HOLDS it
    // and no runner is in flight, which is precisely "we know it exists and hear
    // nothing from it".
    let agentStore = AgentStore(applicationSupportDirectory: agentsSupport)
    try agentStore.upsert(AgentRecord(
        id: headlessId,
        displayName: "reviewer",
        role: "reviewer",
        model: "openai-codex/gpt-5.6-sol",
        thinking: "medium",
        cwd: projectARoot.path,
        projectId: projectA,
        createdAt: anHourAgo,
        lastActivityAt: anHourAgo
    ))

    let app = AppDelegate()
    app.registryStore = registryStore
    // P3.2 (design §5.9): arm the listing gate exactly as boot does.
    try app.reconciledManagedSessionSource.reconcile(registry: registry, reason: .continuumRestarted, now: now)
    app.agentSupervisor = AgentSupervisor(store: agentStore, makeRunner: { _ in ScriptedAgentRunner(script: []) })
    app.agentSupervisor.restore()
    try expect(app.agentSupervisor.records[headlessId] != nil,
               "the headless agent must be adopted, or the assertions below say nothing about it")
    try expect(app.agentSupervisor.isRunning(headlessId) == false,
               "a restored agent has no runner in flight — otherwise it is legitimately observed and this fixture is not about the unobserved case")

    // MARK: 2 · NO OBSERVER ANYWHERE. Every agent still appears, from disk, marked.

    // Vacuity guards for the whole check: nothing live exists to be read, and — the
    // trap this ticket is named for — nothing starts one either.
    try expect(app.workspaceRuntime == nil && app.canvasView == nil,
               "there must be no workspace runtime and no canvas, or 'without a live observer' is not what is being measured")
    app.refreshAgentSurfaces(notify: false)
    try expect(app.workspaceRuntime == nil,
               "listing agents must not boot a ZoneRuntimeController — that would make looking at the inbox start work")

    var surface = app.agentActivity
    try expect(Set(surface.snapshot.byAgent.keys) == Set([terminalAgentTile, managedTileA, managedTileB, headlessId.rawValue]),
               "every agent must appear with no observer at all — got \(surface.snapshot.byAgent.keys.count) of 4")
    // P3.1/P3.2: `stale`, not `idle`. Both records are persisted `running`, and the
    // arming sweep terminalized them — after a restart a file describes the PAST.
    // (P4.14 had already moved this off `working`: created is not busy.) What this
    // ticket asserts is unchanged — that a disk-only agent is listed at all, with a
    // status, from a project nothing is observing.
    try expect(surface.snapshot.byAgent[managedTileA]?.status == .stale,
               "the active project's agent keeps its PERSISTED status — got \(String(describing: surface.snapshot.byAgent[managedTileA]?.status))")
    try expect(surface.snapshot.byAgent[managedTileB]?.status == .stale,
               "so does the agent in the project whose controller is gone — got \(String(describing: surface.snapshot.byAgent[managedTileB]?.status))")
    try expect(surface.snapshot.byAgent[headlessId.rawValue]?.tileId == nil,
               "the headless agent appears with no tile — got \(String(describing: surface.snapshot.byAgent[headlessId.rawValue]?.tileId))")
    // PINNED, because it is the one place the packet's "last persisted status" is not
    // literally what a human sees, and the cross-review was right to ask: a TERMINAL
    // agent's descriptor was saved as `.working`, and `restoredForBoot()` rewrites
    // both the status and its stamp on every read, so what survives the disk is
    // `.stale` + this ticket's mark. That is a property of `TerminalSessionDescriptor`
    // (recorded in `--agent-inventory-wiring-check` and P2B.7's owner note), not
    // something this ticket chose; asserted here so a fix to that stamp shows up as a
    // red gate rather than as a silent behaviour change.
    try expect(surface.snapshot.byAgent[terminalAgentTile]?.status == .stale,
               "a persisted terminal agent reads .stale after restoredForBoot, mark and all — got \(String(describing: surface.snapshot.byAgent[terminalAgentTile]?.status))")

    try expect(surface.unobservedAgentIds == Set([terminalAgentTile, managedTileA, managedTileB, headlessId.rawValue]),
               "an agent read off disk with no observer must be marked unobserved — got \(surface.unobservedAgentIds.count) marked of \(surface.snapshot.byAgent.count) agents")
    try expect(surface.unobservedAgentIds.contains(terminalAgentTile),
               "a terminal agent read off disk must be marked unobserved too — an age-based flag would exempt it forever, see the age measured below")
    // The mark is OUR ignorance, not the agent's state — and P3.1 made the ORIGINAL
    // VEHICLE for that claim unusable rather than wrong. `.stale` used to be reachable
    // only as "we do not know", so asserting `!= .stale` proved the mark had not been
    // turned into a status. The launch sweep now derives `.stale` legitimately, for a
    // record it terminalized, so one word carries both meanings until P3.4 gives the
    // unconfirmed case a word of its own.
    //
    // Re-expressed against the locked decision instead, which is both durable and
    // stronger: "An unobserved agent is unconfirmed, NEVER WORKING" (_DESIGN.md). That
    // is the claim worth protecting — the failure this guards against is a mark being
    // laundered into an assertion of liveness, and `working` is the only status that
    // asserts liveness. A swept record reading `stale` is the sweep speaking, not the
    // mark; the assertion below is what forbids the mark from ever speaking.
    try expect(surface.snapshot.byAgent[managedTileA]?.status != .working
                && surface.snapshot.byAgent[headlessId.rawValue]?.status != .working,
               "an unobserved agent must NEVER read as working — the mark is our knowledge, and it may not be laundered into a claim about the agent")

    // P3.4's propagation, at the phase where the fixture is strongest: every
    // listed agent is unobserved RIGHT NOW, so rows built through the app's own
    // seam must all carry the modifier. The overlap demand is what keeps this
    // witness honest — a fixture drift that empties the intersection must fail
    // here rather than let the equality pass over disjoint sets.
    let stampedRows = app.buildAgentInboxRows(now: Date())
    let unobservedNow = app.agentActivity.unobservedAgentIds
    try expect(stampedRows.contains { unobservedNow.contains($0.id) },
               "the propagation witness lost its subject: no built row is in the unobserved set (\(stampedRows.count) rows, \(unobservedNow.count) unobserved)")
    for row in stampedRows {
        try expect(row.isUnconfirmed == unobservedNow.contains(row.id),
                   "production propagation: row '\(row.title)' isUnconfirmed=\(row.isUnconfirmed) disagrees with the surface's unobserved set (P3.4's one stamping seam)")
    }

    // THE MEASUREMENT THAT RULED OUT A TIME THRESHOLD. Everything on disk here is an
    // hour old, and the app believes this agent's information is seconds old, because
    // `listSessions()` re-stamps it. Any threshold above a few seconds would leave
    // every terminal agent unmarked forever, so the flag carries no threshold at all.
    let terminalAge = now.timeIntervalSince(surface.snapshot.byAgent[terminalAgentTile]?.updatedAt ?? anHourAgo)
    let managedAge = now.timeIntervalSince(surface.snapshot.byAgent[managedTileB]?.updatedAt ?? now)
    try expect(terminalAge < 60,
               "a terminal agent's stamp is refreshed by restoredForBoot, so its age is unusable — measured \(terminalAge)s on an hour-old fixture")
    try expect(managedAge > 3000,
               "…while a managed record's own lastSeenAt survives the read, which is what made the difference visible — measured \(managedAge)s")

    // MARK: 3 · THE OVERLAY WINS. A live tile view beats the file, and clears the mark.

    let canvas = CanvasNSView(
        canvasState: canvasA,
        activeZone: placementA,
        zoneRenderModels: [CanvasNSView.ZoneRenderModel(placement: placementA, displayName: "Project A")]
    )
    canvas.install(tileView: TileNSView(tile: canvasA.tiles[0]), for: canvasA.tiles[0])
    let managedView = ManagedAgentTileNSView(tile: canvasA.tiles[1])
    canvas.install(tileView: managedView, for: canvasA.tiles[1])
    app.canvasView = canvas
    managedView.ingest(.requestOpened(
        threadId: managedView.wiringThreadId,
        requestId: "req-1",
        kind: .commandExecutionApproval
    ))
    try expect(managedView.currentAgentStatus == .needsAttention,
               "the live view must hold a status that differs from the file's, or 'the overlay wins' is unmeasurable — got \(managedView.currentAgentStatus)")

    app.refreshAgentSurfaces(notify: false)
    surface = app.agentActivity
    try expect(surface.snapshot.byAgent[managedTileA]?.status == .needsAttention,
               "a live view's status must override the persisted one — got \(String(describing: surface.snapshot.byAgent[managedTileA]?.status))")
    try expect(surface.unobservedAgentIds.contains(managedTileA) == false,
               "…and the agent it reports is no longer unobserved — got \(surface.unobservedAgentIds.count) marked")
    // The other project is untouched by any of that: still listed, still from disk.
    // P3.1/P3.2: `stale`, not `idle` — the sweep reaches every registry root, so the
    // other project's record describes the past too. Still listed, still marked.
    try expect(surface.snapshot.byAgent[managedTileB]?.status == .stale
                && surface.unobservedAgentIds.contains(managedTileB),
               "the agent in the other project is still listed from disk and still marked — got \(String(describing: surface.snapshot.byAgent[managedTileB]?.status))")

    // The other overlay input, through the production observer entry point: a
    // terminal agent's live status is the runtime observer's map.
    app.applyObserverStatuses([terminalAgentTile: .needsAttention])
    surface = app.agentActivity
    try expect(surface.snapshot.byAgent[terminalAgentTile]?.status == .needsAttention,
               "a runtime observer's status must override the persisted one — got \(String(describing: surface.snapshot.byAgent[terminalAgentTile]?.status))")
    try expect(surface.unobservedAgentIds == Set([managedTileB, headlessId.rawValue]),
               "only the agents nothing reported stay marked — got \(surface.unobservedAgentIds.count) marked")

    // MARK: 4 · TEARDOWN — the case the ticket is named for, raised by the
    // cross-review: a project that HAD a live observer and then loses it must go back
    // to being unobserved, not keep a status the app believes is live forever.
    //
    // `ZoneRuntimeController.close()` is what `closeOnZero` calls, and it emits an
    // EMPTY map through `onObservedAgentStatusesChanged` before it stops the observer
    // (asserted from source below, because standing up a real controller here would
    // boot a project runtime — the thing this check exists to do without; so what is
    // proven mechanically is that `close()` publishes the empty map, NOT that the
    // production wiring delivers it, which needs the GUI path). The app's
    // side of that hand-off is `applyObserverStatuses`, which REPLACES the map, so
    // that empty map is the teardown.
    let controllerSource = try String(
        contentsOf: URL(fileURLWithPath: FileManager.default.currentDirectoryPath, isDirectory: true)
            .appendingPathComponent("Sources/ContinuumRevived/App/ZoneRuntimeController.swift"),
        encoding: .utf8
    )
    guard let closeStart = controllerSource.range(of: "func close() {"),
          let closeEnd = controllerSource.range(of: "flushPendingSaves()", range: closeStart.upperBound..<controllerSource.endIndex) else {
        throw CheckError.failed("could not find ZoneRuntimeController.close() — this scan is looking in the wrong place")
    }
    try expect(controllerSource[closeStart.upperBound..<closeEnd.upperBound].contains("onObservedAgentStatusesChanged?([:])"),
               "releasing a controller must publish an EMPTY observer map, or its agents stay 'observed' with a frozen status forever")
    app.applyObserverStatuses([:])
    surface = app.agentActivity
    try expect(surface.unobservedAgentIds.contains(terminalAgentTile),
               "an agent whose observer went away must go BACK to unobserved — got \(surface.unobservedAgentIds.count) marked")
    try expect(surface.snapshot.byAgent[terminalAgentTile] != nil,
               "…and it must still be listed, from disk — losing the observer must not lose the agent")
    // The managed agent's live VIEW is still installed, so it is still observed: an
    // observer teardown is not a canvas teardown.
    try expect(surface.unobservedAgentIds.contains(managedTileA) == false,
               "the agent whose live tile view is still installed stays observed — got \(surface.unobservedAgentIds.count) marked")

    // MARK: 5 · an agent's OWN event clears the mark with no rebuild at all (P2B.7's
    // incremental path — the headless agent has no view and no file to re-read).

    try expect(surface.unobservedAgentIds.contains(headlessId.rawValue),
               "the headless agent must still be marked here, or the clear below proves nothing")
    app.recordManagedActivity(
        agentId: headlessId,
        tileId: nil,
        event: .turnStarted(threadId: "thread-1", turnId: "turn-1"),
        status: .working
    )
    try expect(app.agentActivity.unobservedAgentIds.contains(headlessId.rawValue) == false,
               "an agent's OWN event must clear the mark without a rebuild — got \(app.agentActivity.unobservedAgentIds.count) marked")
    try expect(app.agentActivity.snapshot.byAgent[headlessId.rawValue]?.status == .working,
               "…and that event is what it says it is — got \(String(describing: app.agentActivity.snapshot.byAgent[headlessId.rawValue]?.status))")
    try expect(app.agentActivity.unobservedAgentIds.contains(managedTileB),
               "the silent agent in the other project stays marked — nobody heard from it")

    NSApplication.shared.dockTile.badgeLabel = nil
    // MARK: P3.4 — the unconfirmed modifier and its frozen clock, at this seam.
    //
    // Semantics first, on the freeze value itself, with a moved clock the fixture
    // controls: the first reading is the fact, a later rebuild's bigger reading
    // must NOT replace it, and re-observation drops the memory so the live clock
    // resumes. Then the wiring: rows built through the app's own
    // buildAgentInboxRows carry the modifier for exactly the surface's set.
    var freeze = UnconfirmedElapsedFreeze()
    let frozenProbeId = UUID()
    func probeRow(elapsed: TimeInterval) -> AgentInboxRow {
        AgentInboxRow(
            id: frozenProbeId, title: "frozen probe", projectName: nil,
            state: .working, lifecycle: .active, model: "openai-codex/gpt-5.6-luna",
            branch: nil, elapsed: elapsed, createdAt: Date(timeIntervalSinceReferenceDate: 800_000_000))
    }
    let firstFrozen = freeze.apply(rows: [probeRow(elapsed: 60)], unobserved: [frozenProbeId])
    try expect(firstFrozen.first?.isUnconfirmed == true && firstFrozen.first?.elapsed == 60,
               "an unobserved row must carry the unconfirmed modifier with its last-known duration — got \(String(describing: firstFrozen.first?.elapsed))")
    let secondFrozen = freeze.apply(rows: [probeRow(elapsed: 3_660)], unobserved: [frozenProbeId])
    try expect(secondFrozen.first?.elapsed == 60,
               "an unconfirmed duration advanced across a rebuild — 60s became \(String(describing: secondFrozen.first?.elapsed)) (P3.4: a rebuild reapplies the last-known fact, it never recomputes liveness)")
    let thawed = freeze.apply(rows: [probeRow(elapsed: 3_660)], unobserved: [])
    try expect(thawed.first?.isUnconfirmed == false && thawed.first?.elapsed == 3_660,
               "a re-observed agent must shed the modifier and resume the live clock — got \(String(describing: thawed.first?.elapsed))")
    let refrozen = freeze.apply(rows: [probeRow(elapsed: 7_200)], unobserved: [frozenProbeId])
    try expect(refrozen.first?.elapsed == 7_200,
               "a NEW unobserved spell freezes at the new last-known fact, not the stale one — got \(String(describing: refrozen.first?.elapsed))")

    // P6.1 · THE SHIPPED ROW, not a helper oracle. Plant a settled record and
    // drive the same refresh path the sidebar uses. A completed-but-unseen mark
    // must remain unread without turning into a lifecycle blocker.
    let lifecycleProbeId = AgentID(rawValue: UUID(uuidString: "2B800000-0000-4000-8000-00000000F601")!)
    let lifecycleProbeSettledAt = now.addingTimeInterval(-600)
    // R2/P6.4 migration: never-visited history is now deliberately read, so this
    // planted witness carries a durable completion after an earlier visit. The
    // production row therefore remains durably unread while still testing that
    // unread is not a lifecycle blocker.
    let lifecycleProbeVisitedAt = lifecycleProbeSettledAt.addingTimeInterval(-60)
    let lifecycleProbeCompletedAt = lifecycleProbeSettledAt.addingTimeInterval(-30)
    try agentStore.upsert(AgentRecord(
        id: lifecycleProbeId,
        displayName: "Lifecycle probe",
        role: "reviewer",
        model: "openai-codex/gpt-5.6-sol",
        thinking: "medium",
        cwd: projectARoot.path,
        projectId: projectA,
        createdAt: lifecycleProbeSettledAt,
        lastActivityAt: lifecycleProbeSettledAt,
        runCompletedAt: lifecycleProbeCompletedAt,
        lastVisitedAt: lifecycleProbeVisitedAt,
        settledOverride: .settled,
        settledAt: lifecycleProbeSettledAt))
    let lifecycleProbeApp = AppDelegate()
    lifecycleProbeApp.registryStore = registryStore
    try lifecycleProbeApp.reconciledManagedSessionSource.reconcile(
        registry: registry, reason: .continuumRestarted, now: now)
    let lifecycleProbeSupervisor = AgentSupervisor(
        store: agentStore,
        makeRunner: { _ in ScriptedAgentRunner(script: []) })
    lifecycleProbeApp.agentSupervisor = lifecycleProbeSupervisor
    lifecycleProbeSupervisor.restore()
    lifecycleProbeSupervisor.focus(agentID: nil)
    lifecycleProbeSupervisor.qaDeliver(.turnCompleted(
        threadId: "lifecycle-probe", turnId: "finished",
        outcome: .completed, errorMessage: nil), to: lifecycleProbeId)
    lifecycleProbeApp.refreshAgentSurfaces(notify: false)
    let lifecycleRows = lifecycleProbeApp.buildAgentInboxRows(now: now)
    guard let lifecycleRow = lifecycleRows.first(where: { $0.id == lifecycleProbeId.rawValue }) else {
        throw CheckError.failed("P6.1 production lifecycle witness lost its planted row")
    }
    try expect(lifecycleRow.attention == .unread,
               "P6.1 production lifecycle witness must be unread before the row assertion — got \(lifecycleRow.attention.rawValue)")
    try expect(lifecycleRow.lifecycle == .settled(at: lifecycleProbeSettledAt),
               "P6.1 production lifecycle: a settled override must reach the shipped row — got \(lifecycleRow.lifecycle)")
    try expect(lifecycleRow.variant == .slim,
               "P6.1 production lifecycle: a settled shipped row must be slim — got \(lifecycleRow.variant.rawValue)")
    try expect(!lifecycleRow.settlementBlocked && !lifecycleRow.canSettle(),
               "P6.1 production lifecycle/action guard: unread is not a blocker and an already-settled row is not a target — got blocked=\(lifecycleRow.settlementBlocked) canSettle=\(lifecycleRow.canSettle())")

    // The bar and row menu consume the same row predicate, including the child
    // rollup. This is the app-level agreement witness over the three decisions
    // that used to drift: own blocker, lifecycle no-op, and child hold-open.
    let actionRows = [
        AgentInboxRow(id: UUID(uuidString: "2B800000-0000-0000-0000-00000000F611")!, title: "Ready", state: .ready, createdAt: now),
        AgentInboxRow(id: UUID(uuidString: "2B800000-0000-0000-0000-00000000F612")!, title: "Running", state: .working, createdAt: now, settlementBlocked: true),
        AgentInboxRow(id: UUID(uuidString: "2B800000-0000-0000-0000-00000000F613")!, title: "Settled", state: .ready, lifecycle: .settled(at: now.addingTimeInterval(-60)), createdAt: now),
    ]
    let actionRollups: [UUID: ChildRollup] = [
        actionRows[0].id: ChildRollup(children: 1, working: 1, needsYou: 0, failed: 0)
    ]
    for actionRow in actionRows {
        let rollup = actionRollups[actionRow.id]
        try expect(actionRow.canSettle(rollup: rollup)
                    == InboxBulkAction.settle.isAvailable(for: actionRow, rollups: actionRollups),
                   "classifier/action guard agreement for \(actionRow.title) — row \(actionRow.canSettle(rollup: rollup)), bulk \(InboxBulkAction.settle.isAvailable(for: actionRow, rollups: actionRollups))")
    }
    try expect(!InboxBulkAction.settle.isAvailable(for: actionRows[0], rollups: actionRollups),
               "ChildRollup.holdsParentOpen must withhold Settle from an otherwise active parent")
    try expect(!InboxRowAction.settle.isAvailable(for: actionRows[1], rollups: actionRollups),
               "the row menu must withhold Settle from the same explicit live-runner blocker")

    // Required source-mutation witness (run against the matrix-wired command):
    // changing the production `let lifecycle = record?.lifecycle(...) ?? .active`
    // line in AgentInboxRowBuilder.swift back to `InboxLifecycle.active` makes the
    // exact assertion above red. The harness records the command, exit 1 and
    // `FAIL: P6.1 production lifecycle: a settled override must reach the shipped
    // row — got active`; the source is restored byte-for-byte and its sha256 is
    // checked before this green run.
    NSApplication.shared.dockTile.badgeLabel = nil
    print("AgentObserverIndependence: with no ZoneRuntimeController and no canvas, 4 agents were listed from disk with their persisted statuses and all 4 marked unobserved; a live tile view and a runtime observer status each overrode the file and cleared the mark; releasing the observer put an agent back to unobserved without losing it; an agent's own event cleared the mark with no rebuild; the agent in the released project stayed listed and marked throughout; and P6.1 drove a planted unread settled record through the shipped builder to a settled slim row while the classifier, bulk action and child rollup predicates agreed (terminal age measured \(String(format: "%.1f", terminalAge))s vs managed \(String(format: "%.0f", managedAge))s on the same hour-old fixture)")
    }
}

// Ticket: docs/38-tickets/90-agent-ux/P3.6-inbox-list-view.md
//
// THE INBOX IS WHAT THE SIDEBAR SHOWS. Two halves, because the claim has two
// halves and one fixture cannot carry both:
//
//  A · THE VIEW AGAINST THE MODEL. A canned `[AgentInboxRow]` in, the rendered
